-- migrations from the top would collide with the existing objects partway
-- through. Raising here rolls back the transaction before anything changes.
do $guard$
begin
  if to_regclass('public.memories') is not null then
    raise exception using
      message = 'LoreKit schema already present: bootstrap.sql only initialises an empty database.',
      hint = 'Upgrade a database set up from this file with `supabase db push`. One set up from the older hand-written bootstrap.sql has no migration history: see docs/byod.md.';
  end if;
end
$guard$;

-- The Supabase CLI's migration-history table. `if not exists` keeps this
-- compatible with a project the CLI has already touched; the CLI adds any
-- further columns it needs on its next run.
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (
  version text not null primary key,
  statements text[],
  name text
);

-- ─────────────────────────────────────────────────────────────────────────────
-- 00001_memories.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit memories table
-- Stores agent memory/lessons with canonical scope strings, full-text search, and RLS.

create table if not exists memories (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid references auth.users on delete cascade,
  org_id       text,
  scope        text not null,
  key          text not null,
  value        text not null check (length(value) <= 65536),
  tags         text[] not null default '{}',
  source_agent text,
  trigger      text,
  -- Generated FTS column for full-text search via to_tsvector
  fts          tsvector generated always as (
    to_tsvector('english', coalesce(key, '') || ' ' || coalesce(value, ''))
  ) stored,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  -- user_id can be null for service-role writes (CI); uniqueness still holds
  constraint memories_user_scope_key_unique unique nulls not distinct (user_id, scope, key)
);

-- Indexes
create index if not exists memories_fts_idx    on memories using gin(fts);
create index if not exists memories_scope_idx  on memories (scope);
create index if not exists memories_user_idx   on memories (user_id);
create index if not exists memories_scope_key  on memories (scope, key);

-- Enable Row Level Security
alter table memories enable row level security;

-- Policy: users can read their own rows, or rows where org_id matches their JWT claim
create policy "rls_read"
  on memories for select
  using (
    user_id = auth.uid()
    or (
      org_id is not null
      and org_id = (auth.jwt() ->> 'org_id')
    )
  );

-- Policy: users can insert their own rows; service_role bypasses via superuser
create policy "rls_insert"
  on memories for insert
  with check (
    user_id = auth.uid()
    or auth.role() = 'service_role'
  );

-- Policy: users can update their own rows
create policy "rls_update"
  on memories for update
  using (
    user_id = auth.uid()
    or auth.role() = 'service_role'
  );

-- Policy: users can delete their own rows
create policy "rls_delete"
  on memories for delete
  using (
    user_id = auth.uid()
    or auth.role() = 'service_role'
  );

-- Trigger to keep updated_at current
create or replace function set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create or replace trigger memories_updated_at
  before update on memories
  for each row execute function set_updated_at();
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00001', 'memories')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00002_api_tokens.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit API tokens
-- Allows users to generate durable tokens for agent/CI authentication.
-- Tokens are NEVER stored in plain text — only as SHA-256 hashes.
-- The token prefix (first 12 chars) is stored for display/identification.
--
-- Token format: lk_{perm}_{32 random alphanumeric chars}
--   lk_rw_...  read+write  (all 5 MCP tools)
--   lk_ro_...  read-only   (memory.read, memory.list, memory.search only)

create table if not exists api_tokens (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid references auth.users on delete cascade not null,
  name         text not null check (length(name) >= 1 and length(name) <= 100),
  -- First 12 chars + "..." for display ("lk_rw_aBcD1...") — safe to store, max 16 chars
  token_prefix text not null check (length(token_prefix) <= 16),
  -- SHA-256 hex of the full token — used for lookup on every request
  token_hash   text not null unique,
  -- Array of granted permissions: 'read' | 'write'
  permissions  text[] not null default '{"read","write"}',
  last_used_at timestamptz,
  created_at   timestamptz not null default now()
);

create index if not exists api_tokens_user_idx      on api_tokens(user_id);
create index if not exists api_tokens_hash_idx      on api_tokens(token_hash);

alter table api_tokens enable row level security;

-- Users can only see and manage their own tokens
create policy "rls_api_tokens_select"
  on api_tokens for select
  using (user_id = auth.uid());

create policy "rls_api_tokens_insert"
  on api_tokens for insert
  with check (user_id = auth.uid());

create policy "rls_api_tokens_delete"
  on api_tokens for delete
  using (user_id = auth.uid());

-- Service role can look up tokens for auth validation (bypasses RLS)
-- No update policy needed — last_used_at is updated via service role
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00002', 'api_tokens')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00003_archive.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit archive / soft-delete support
--
-- Adds archived_at to memories so agents and the dashboard can soft-delete a
-- lesson (archive) instead of hard-deleting it. Archived rows are hidden from
-- all normal reads (RLS select policy, tool queries) but can be listed via the
-- memory.list_archived MCP tool or the dashboard Archive tab.
--
-- A pg_cron job (or the memory.purge RPC called by the dashboard) hard-deletes
-- rows where archived_at < now() - (retention_days * interval '1 day').

-- 1. Add the soft-delete timestamp column.
alter table memories
  add column if not exists archived_at timestamptz;

-- 2. Index for efficient purge sweeps (only touches archived rows).
create index if not exists memories_archived_at_idx
  on memories (archived_at)
  where archived_at is not null;

-- 3. Drop the old unique constraint and recreate it excluding archived rows.
--    This allows the same (user_id, scope, key) to be re-created after an archive.
alter table memories
  drop constraint if exists memories_user_scope_key_unique;

create unique index if not exists memories_user_scope_key_active_unique
  on memories (user_id, scope, key)
  where archived_at is null;

-- Nulls-not-distinct variant for rows where user_id IS NULL (service-role writes).
create unique index if not exists memories_null_user_scope_key_active_unique
  on memories (scope, key)
  where user_id is null and archived_at is null;

-- 4. Update the RLS select policy to hide archived rows from normal reads.
drop policy if exists "rls_read" on memories;

create policy "rls_read"
  on memories for select
  using (
    archived_at is null
    and (
      user_id = auth.uid()
      or (
        org_id is not null
        and org_id = (auth.jwt() ->> 'org_id')
      )
    )
  );

-- 5. RLS policy for reading archived rows (dashboard archive view).
create policy "rls_read_archived"
  on memories for select
  using (
    archived_at is not null
    and (
      user_id = auth.uid()
      or (
        org_id is not null
        and org_id = (auth.jwt() ->> 'org_id')
      )
    )
  );

-- 6. Soft-archive RPC — sets archived_at, returns the row id.
--    Called by the MCP memory.archive tool and the dashboard server action.
--    Uses SECURITY DEFINER so the RLS update policy (user_id = auth.uid())
--    still applies — the function runs as the table owner but only touches
--    the row if the caller passes their own user_id.
create or replace function archive_memory(
  p_user_id  uuid,
  p_scope    text,
  p_key      text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  update memories
     set archived_at = now()
   where user_id = p_user_id
     and scope    = p_scope
     and key      = p_key
     and archived_at is null
  returning id into v_id;

  return v_id; -- null if row not found or already archived
end;
$$;

-- 7. Restore-from-archive RPC — clears archived_at.
create or replace function restore_memory(
  p_user_id  uuid,
  p_scope    text,
  p_key      text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  update memories
     set archived_at = null
   where user_id = p_user_id
     and scope    = p_scope
     and key      = p_key
     and archived_at is not null
  returning id into v_id;

  return v_id;
end;
$$;

-- 8. Purge RPC — hard-deletes archived rows older than retention_days.
--    Returns the count of deleted rows.
--    Intended to be called by a scheduled job or the dashboard "Run purge" button.
create or replace function purge_archived_memories(
  p_user_id       uuid,
  p_retention_days integer default 30
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  delete from memories
   where user_id    = p_user_id
     and archived_at is not null
     and archived_at < now() - (p_retention_days * interval '1 day')
  ;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00003', 'archive')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00004_limits.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit abuse guardrails: per-user memory cap + request rate limiting.
--
-- Two enforcement planes sharing one config source:
--   * Cap plane (authoritative): enforce_memory_cap() BEFORE INSERT trigger on
--     memories, keyed off NEW.user_id. Counts active (non-archived) rows and
--     rejects the insert once the user's max_memories limit is reached. Upsert
--     updates (existing key) never trip this — only NEW rows go through
--     BEFORE INSERT.
--   * Rate plane (transport): lorekit_check_rate_limit() RPC, a Postgres-backed
--     fixed-window counter. Called by the app layer (Deno edge fn / Node
--     server) right after auth resolves, per request, per user.
--
-- Config source: lorekit_default_limit(key) is the single free-tier default;
-- user_limits holds nullable per-user overrides; lorekit_get_limit resolves
-- COALESCE(override, default). No numeric limit is hardcoded in app code.
--
-- Service-role (NEW.user_id / p_user_id IS NULL — CI/internal) is exempt from
-- both guardrails.

-- 1. Single source of truth for free-tier default limits.
create or replace function lorekit_default_limit(p_key text)
returns integer
language sql
immutable
as $$
  select case p_key
    when 'max_memories'         then 1000
    when 'requests_per_minute'  then 120
    else null
  end;
$$;

-- 2. Per-user override table. Absence of a row (or a null column) means the
--    user is on the free-tier default — lorekit_get_limit() never returns null.
create table if not exists user_limits (
  user_id             uuid primary key references auth.users on delete cascade,
  max_memories        integer,
  requests_per_minute integer,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

alter table user_limits enable row level security;

-- Users can see their own override row (so the dashboard/CLI can show "your
-- limit"); raising a limit is a service-role/admin upsert for now — no
-- insert/update policy for regular users.
create policy "rls_user_limits_select"
  on user_limits for select
  using (user_id = auth.uid());

create or replace trigger user_limits_updated_at
  before update on user_limits
  for each row execute function set_updated_at();

-- 3. Resolve the effective limit for a user: override if set, else the
--    free-tier default. Security definer so it can read user_limits
--    regardless of the caller's RLS visibility (needed inside the trigger).
create or replace function lorekit_get_limit(p_user_id uuid, p_key text)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_override integer;
begin
  if p_key = 'max_memories' then
    select max_memories into v_override from user_limits where user_id = p_user_id;
  elsif p_key = 'requests_per_minute' then
    select requests_per_minute into v_override from user_limits where user_id = p_user_id;
  end if;

  return coalesce(v_override, lorekit_default_limit(p_key));
end;
$$;

-- 4. Cap trigger — the authoritative guardrail. Counts NEW.user_id's active
--    (archived_at IS NULL) rows and rejects the insert at/over the limit.
--    Service-role / CI writes (NEW.user_id IS NULL) are exempt.
--    Raises a custom SQLSTATE ('LK001') so the app layer can distinguish this
--    from any other DB error and translate it into an actionable LimitError
--    (see packages/mcp-core/src/limits.ts and supabase/functions/mcp/limits.ts).
create or replace function enforce_memory_cap()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_limit integer;
  v_count integer;
begin
  if new.user_id is null then
    return new; -- service-role / CI writes are exempt from the cap
  end if;

  v_limit := lorekit_get_limit(new.user_id, 'max_memories');

  select count(*) into v_count
    from memories
   where user_id = new.user_id
     and archived_at is null;

  if v_count >= v_limit then
    raise exception using
      errcode = 'LK001',
      message = format('memory_cap_exceeded: limit=%s', v_limit);
  end if;

  return new;
end;
$$;

create or replace trigger memories_enforce_cap
  before insert on memories
  for each row execute function enforce_memory_cap();

-- 5. Rate-limit counter table — one tiny row per (user, window). Postgres-
--    backed (not in-memory) because edge isolates are stateless/short-lived.
create table if not exists rate_limit_counters (
  user_id      uuid not null,
  window_start timestamptz not null,
  count        integer not null default 0,
  primary key (user_id, window_start)
);

create index if not exists rate_limit_counters_window_idx
  on rate_limit_counters (window_start);

alter table rate_limit_counters enable row level security;
-- No policies: this table is a transport-layer implementation detail, only
-- ever touched via the security-definer RPC below (service-role / RPC path).

-- 6. Atomic fixed-window rate-limit check. Increments the current window's
--    counter and returns whether the request is allowed, plus how long until
--    the next window opens (Retry-After).
create or replace function lorekit_check_rate_limit(
  p_user_id        uuid,
  p_window_seconds integer default 60
)
returns table(
  allowed             boolean,
  current_count       integer,
  limit_value         integer,
  retry_after_seconds integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_window_start timestamptz;
  v_limit        integer;
  v_count        integer;
  v_retry_after  integer;
begin
  v_window_start := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  v_limit := lorekit_get_limit(p_user_id, 'requests_per_minute');

  insert into rate_limit_counters (user_id, window_start, count)
  values (p_user_id, v_window_start, 1)
  on conflict (user_id, window_start)
  do update set count = rate_limit_counters.count + 1
  returning rate_limit_counters.count into v_count;

  v_retry_after := ceil(extract(epoch from (v_window_start + (p_window_seconds || ' seconds')::interval - now())))::integer;
  if v_retry_after < 0 then
    v_retry_after := 0;
  end if;

  return query select (v_count <= v_limit), v_count, v_limit, v_retry_after;
end;
$$;

-- 7. Reaper for stale rate-limit windows. rate_limit_counters gains one row per
--    (user, window) on every request, but only the current window is ever read
--    — anything older is dead weight that bloats the table and its index and
--    slowly degrades the RPC above (which runs on every authenticated request).
--    Hard-delete windows older than p_older_than. Mirrors purge_archived_memories
--    in 00003_archive.sql. Returns the count of deleted rows.
create or replace function lorekit_purge_rate_limit_counters(
  p_older_than interval default interval '1 hour'
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  delete from rate_limit_counters
   where window_start < now() - p_older_than;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Schedule the reaper every 15 minutes when pg_cron is available. Guarded so
-- the migration still applies on instances without the extension — the function
-- above can then be driven by an external scheduler or the dashboard instead.
-- Idempotent: cron.schedule() upserts by job name.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule(
      'lorekit-purge-rate-limit-counters',
      '*/15 * * * *',
      $cron$select lorekit_purge_rate_limit_counters()$cron$
    );
  end if;
end;
$$;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00004', 'limits')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00005_webhook_secrets.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit webhook secrets
-- Stores per-user HMAC secrets used to verify GitHub webhook payloads.
-- Secrets are stored in plaintext because:
--   1. They are Supabase-internal (the DB itself is the trust boundary).
--   2. The edge function needs the raw value to compute HMAC-SHA256 per request.
--   3. The dashboard needs to display the value once on first setup, matching
--      the api_tokens "show once" UX pattern (except this value IS retrievable
--      because the edge function needs to read it on every webhook call).
--
-- One active secret per user. Regenerating creates a new row and soft-deletes
-- the old one (active = false) so webhook deliveries in-flight don't fail
-- immediately — GitHub retries with the old secret for a short window.

create table if not exists webhook_secrets (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid references auth.users on delete cascade not null,
  secret     text not null check (length(secret) = 64),  -- 32 raw bytes → 64 hex chars
  active     boolean not null default true,
  created_at timestamptz not null default now()
);

create index if not exists webhook_secrets_user_active_idx
  on webhook_secrets (user_id, active)
  where active = true;

alter table webhook_secrets enable row level security;

-- Users can read their own secrets (needed to display in the dashboard)
create policy "rls_webhook_secrets_select"
  on webhook_secrets for select
  using (user_id = auth.uid());

create policy "rls_webhook_secrets_insert"
  on webhook_secrets for insert
  with check (user_id = auth.uid());

create policy "rls_webhook_secrets_update"
  on webhook_secrets for update
  using (user_id = auth.uid());

-- Service role reads the active secret for HMAC verification on each webhook
-- call (bypasses RLS — no additional policy needed for service role).
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00005', 'webhook_secrets')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00006_grants.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Explicit table privileges for the Supabase API roles.
--
-- Supabase cloud projects grant DML to anon/authenticated/service_role via
-- ambient "default privileges", so this is effectively a no-op in staging and
-- production. But a fresh local `supabase start` (newer CLI) only grants
-- TRUNCATE/REFERENCES/TRIGGER to these roles, leaving them without
-- SELECT/INSERT/UPDATE/DELETE — so any service-role or api_key request fails
-- with "permission denied for table ...", and PostgREST won't expose an
-- ON CONFLICT arbiter for upserts. Granting explicitly makes the schema
-- self-contained and identical across every environment.
--
-- This grants no new *effective* access: anon/authenticated remain governed by
-- the RLS policies defined in earlier migrations; service_role bypasses RLS as
-- it already does. It only makes the underlying table privileges explicit.

grant select, insert, update, delete on all tables in schema public
  to anon, authenticated, service_role;

-- Tables created by future migrations inherit the same grants automatically.
alter default privileges in schema public
  grant select, insert, update, delete on tables
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00006', 'grants')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00007_memory_write_rpc.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Fix memory.write against the partial unique indexes introduced in 00003.
--
-- 00003 dropped the plain `memories_user_scope_key_unique` constraint and
-- replaced it with two PARTIAL unique indexes (WHERE archived_at IS NULL):
--   • memories_user_scope_key_active_unique      (user_id, scope, key)
--   • memories_null_user_scope_key_active_unique  (scope, key) WHERE user_id IS NULL
--
-- A plain `.upsert(..., { onConflict: 'user_id,scope,key' })` cannot target a
-- partial index — Postgres raises "there is no unique or exclusion constraint
-- matching the ON CONFLICT specification", so every write failed. `supabase-js`
-- can't express a partial-index arbiter, so writes go through this RPC, which
-- branches on whether user_id is null and names the matching partial index
-- predicate in ON CONFLICT.
--
-- Behaviour preserved: the BEFORE INSERT memory-cap trigger still fires on the
-- insert path (not on conflict-update); archived rows are excluded, so a
-- (user_id, scope, key) can be re-created after it is archived.

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[] default '{}',
  p_source_agent text   default null,
  p_trigger      text   default null
)
returns table (id uuid, created_at timestamptz)
language plpgsql
set search_path = public
as $$
begin
  if p_user_id is null then
    -- service-role / CI writes: (scope, key) partial index for null user_id
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, updated_at)
    values (null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger, now())
    on conflict (scope, key) where user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at;
  else
    -- user-scoped writes (api_key / user): (user_id, scope, key) partial index
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, updated_at)
    values (p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger, now())
    on conflict (user_id, scope, key) where archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00007', 'memory_write_rpc')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00008_webhook_secrets_repo.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Repo-scoped webhook secrets.
--
-- Problem: the original webhook_secrets model (00005) is one active secret
-- per user, matched at lookup time by the GitHub *owner login*. That breaks
-- for org-owned repos (repository.owner.login is the org, not the LoreKit
-- user's personal GitHub login) and requires an O(all-users) listUsers scan.
--
-- Fix: add a nullable `repo` column (canonical lowercased `owner/name`) so a
-- user can register a secret per repository, matched deterministically by
-- the delivery's `repository.full_name` — no auth.users join needed.
--
-- Existing null-`repo` rows are kept as-is (a legacy/global fallback secret)
-- for back-compat; this migration does not backfill or touch 00005.
-- Forward-only per CLAUDE.md — never edit an applied migration.

alter table webhook_secrets add column if not exists repo text;

-- Canonical owner/name, lowercased. Null = legacy/global fallback row.
alter table webhook_secrets
  add constraint webhook_secrets_repo_format
  check (repo is null or repo ~ '^[a-z0-9._-]+/[a-z0-9._-]+$');

-- One active secret per (user, repo). coalesce(repo, '') folds the legacy
-- null-repo row into a single active row per user, portably — no
-- NULLS NOT DISTINCT dependency (PG15+-only, and the repo's local Supabase
-- PostgREST predates it per the CI split note in CLAUDE.md).
drop index if exists webhook_secrets_user_active_idx;
create unique index webhook_secrets_user_repo_active_uidx
  on webhook_secrets (user_id, coalesce(repo, ''))
  where active = true;

-- Edge lookup path: match active secrets by repo directly.
create index webhook_secrets_repo_active_idx
  on webhook_secrets (repo)
  where active = true and repo is not null;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00008', 'webhook_secrets_repo')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00009_memory_write_created_at.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Allow memory.write to backdate a memory's creation date (migration support).
--
-- When importing pre-existing memories into LoreKit, the caller can pass the
-- memory's ORIGINAL creation date so the dashboard dates it correctly instead
-- of showing the migration wall-clock time. This adds an optional
-- `p_created_at timestamptz` parameter to the memory_write RPC (00007).
--
-- Semantics:
--   • p_created_at IS NULL (default / not supplied): behaviour unchanged — the
--     insert uses now() for both created_at and updated_at.
--   • p_created_at supplied: the INSERT path sets BOTH created_at AND updated_at
--     to that value, so a freshly-migrated memory presents its original date in
--     every dashboard view (some order by created_at, some by updated_at) until
--     it is next edited. The app layer validates it and rejects future dates.
--   • The ON CONFLICT (update) path is unchanged: created_at is preserved (a
--     creation date never moves on a subsequent write) and updated_at = now().
--
-- Adding a parameter changes the function signature, so CREATE OR REPLACE alone
-- would leave a stale 7-arg overload behind and make PostgREST calls ambiguous.
-- Drop the old signature first, then create the widened one. Forward-only.

drop function if exists memory_write(uuid, text, text, text, text[], text, text);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null
)
returns table (id uuid, created_at timestamptz)
language plpgsql
set search_path = public
as $$
begin
  if p_user_id is null then
    -- service-role / CI writes: (scope, key) partial index for null user_id
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at)
    values (null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()))
    on conflict (scope, key) where user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at;
  else
    -- user-scoped writes (api_key / user): (user_id, scope, key) partial index
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at)
    values (p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()))
    on conflict (user_id, scope, key) where archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00009', 'memory_write_created_at')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00010_audit_log.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit audit log — append-only trail for security/data-affecting actions.
--
-- CAPTURE MODEL: app-layer, explicit (Decision D1). Every audit row is
-- written by application code right after the primary operation succeeds
-- (packages/mcp-core/src/audit.ts + supabase/functions/mcp/audit.ts on the
-- MCP side, packages/web/src/lib/audit-log.ts on the dashboard side) — NOT by
-- a DB trigger on the data tables (memories / api_tokens / webhook_secrets).
-- App-layer capture can see the resolved actor (auth.uid() for dashboard
-- actions, the resolved token/user for MCP, null for service-role/CI) and can
-- shape a human-readable `target` + `metadata`, which a trigger on those
-- tables cannot do cleanly.
--
-- THE ONE DELIBERATE EXCEPTION: `user_limits` changes (Decision D2). No
-- app-layer path writes that table today (raising a user's limit is a raw
-- SQL upsert — see docs/limits.md), so there is no call site to instrument.
-- An AFTER INSERT OR UPDATE OR DELETE trigger (audit_user_limits(), below)
-- is the only way to capture it, mirroring the enforce_memory_cap()
-- DB-trigger precedent from 00004_limits.sql (the write-path actor is not
-- app-visible there either). If an admin server action is ever added for
-- `user_limits`, instrument it there too — the trigger is a safety net, not
-- a reason to skip app-layer capture when a call site exists.
--
-- RLS (Decision D5): append-only. Users may SELECT only their own rows.
-- A scoped INSERT policy permits the authenticated server-action client
-- (mirrors api_tokens' insert policy). NO update/delete policy — once
-- written, a row cannot be changed or removed via the API surface (only a
-- service-role/admin operating directly on the DB could, which is outside
-- RLS's scope by design).

create table if not exists audit_log (
  id            uuid primary key default gen_random_uuid(),
  -- Nullable: service-role/CI writes (memory.* via a service-role token) and
  -- JWT-authenticated MCP calls (see supabase/functions/mcp/audit.ts doc
  -- comment) don't attribute to a resolvable app user_id; RLS SELECT then
  -- never surfaces those rows to any user, mirroring the memory-cap exemption.
  user_id       uuid references auth.users on delete cascade,
  action        text not null check (action in (
    'api_key.create',
    'api_key.revoke',
    'webhook_secret.create',
    'webhook_secret.rotate',
    'webhook_secret.deactivate',
    'memory.create',
    'memory.update',
    'memory.archive',
    'memory.restore',
    'memory.delete',
    'limit.override'
  )),
  resource_type text,
  resource_id   text,
  target        text,
  metadata      jsonb,
  created_at    timestamptz not null default now()
);

-- Primary read pattern: "my recent activity", newest first.
create index if not exists audit_log_user_created_idx on audit_log (user_id, created_at desc);

-- Secondary pattern: filter by action type (the Settings → Audit Logs filter pills).
create index if not exists audit_log_action_idx on audit_log (action);

alter table audit_log enable row level security;

-- Users can see only their own audit trail.
create policy "rls_audit_log_select"
  on audit_log for select
  using (user_id = auth.uid());

-- Scoped insert for the authenticated server-action client (mirrors
-- api_tokens' insert policy exactly). Service-role writes (MCP memory
-- mutations) bypass RLS entirely, as usual.
create policy "rls_audit_log_insert"
  on audit_log for insert
  with check (user_id = auth.uid());

-- Deliberately NO update or delete policy — the log is append-only /
-- immutable via the API surface (Decision D5).

-- ── user_limits audit trigger (Decision D2 — the one exception) ────────────
--
-- Fires on every insert/update/delete against user_limits (i.e. every limit
-- override) and records a `limit.override` row. SECURITY DEFINER so it can
-- write audit_log regardless of the caller's RLS visibility, matching
-- enforce_memory_cap()'s shape in 00004_limits.sql. The acting user_id is not
-- known to this trigger (overrides are applied via raw SQL / a future admin
-- path, not a session-scoped request) — recorded as NULL, same as any other
-- service-role-attributed write.
create or replace function audit_user_limits()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row_user_id uuid;
  v_metadata    jsonb;
begin
  v_row_user_id := coalesce(new.user_id, old.user_id);

  v_metadata := jsonb_build_object(
    'op', tg_op,
    'max_memories', case when tg_op = 'DELETE' then old.max_memories else new.max_memories end,
    'requests_per_minute', case when tg_op = 'DELETE' then old.requests_per_minute else new.requests_per_minute end
  );

  -- user_limits is keyed by user_id (it IS the row's primary key), so the row
  -- identity (resource_id) and the affected subject (target) are intentionally
  -- the same value here — not a copy-paste. The actual changed limit values
  -- live in metadata, not target.
  insert into audit_log (user_id, action, resource_type, resource_id, target, metadata)
  values (null, 'limit.override', 'user_limits', v_row_user_id::text, v_row_user_id::text, v_metadata);

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create or replace trigger user_limits_audit
  after insert or update or delete on user_limits
  for each row execute function audit_user_limits();
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00010', 'audit_log')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00011_memory_write_inserted.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Distinguish memory.create from memory.update for audit logging (Decision D4).
--
-- memory_write() (00007, widened by 00009) performs an upsert — the caller
-- cannot otherwise tell whether the row was newly inserted or an existing
-- (scope, key) was updated. Postgres exposes this cheaply and atomically via
-- `xmax = 0` on the RETURNING clause: a freshly-inserted row's xmax is 0
-- (never yet updated/deleted by a transaction), while an ON CONFLICT DO
-- UPDATE path always leaves xmax set to the current transaction's id.
--
-- This is purely additive: a new `inserted boolean` column appended to the
-- RETURNS TABLE. Existing callers that read named fields (`id`, `created_at`)
-- are unaffected; packages/mcp-core/src/tools/write.ts and the edge mirror
-- (supabase/functions/mcp/tools.ts toolWrite) read the new field to record
-- `memory.create` vs `memory.update` in the audit log.
--
-- Widening the RETURNS TABLE changes the function's return signature, so
-- CREATE OR REPLACE alone is insufficient — drop the old signature first,
-- then create the widened one (same drop+recreate shape as 00009). Forward-only.

drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null
)
returns table (id uuid, created_at timestamptz, inserted boolean)
language plpgsql
set search_path = public
as $$
begin
  if p_user_id is null then
    -- service-role / CI writes: (scope, key) partial index for null user_id
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at)
    values (null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()))
    on conflict (scope, key) where user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    -- xmax is an xid; compare its text form to '0' so the insert-vs-update
    -- discriminator reads explicitly rather than relying on an implicit
    -- xid-to-integer cast (see the header comment for the idiom).
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;
  else
    -- user-scoped writes (api_key / user): (user_id, scope, key) partial index
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at)
    values (p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()))
    on conflict (user_id, scope, key) where archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    -- xmax is an xid; compare its text form to '0' so the insert-vs-update
    -- discriminator reads explicitly rather than relying on an implicit
    -- xid-to-integer cast (see the header comment for the idiom).
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00011', 'memory_write_inserted')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00012_audit_log_search.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Keyset pagination + name search support for the Settings → Audit Logs feed
-- (see packages/web/src/lib/pagination/ and the extended listAuditLog in
-- packages/web/src/lib/audit-log.ts). Forward-only, additive: no existing
-- column, constraint, or RLS policy is touched.
--
-- 1. `pg_trgm` + a GIN trigram index on `audit_log.target` so the
--    case-insensitive substring `name` search (`.ilike('target', '%…%')`)
--    stays index-backed instead of a sequential scan as the table grows.
--    A plain btree index can't serve a leading-wildcard ILIKE; trigram GIN
--    is the standard Postgres answer (mirrors the `memories_fts_idx` GIN
--    index pattern in 00001_memories.sql for full-text search).
--
-- 2. A `(user_id, created_at desc, id)` index covering the keyset seek.
--    00010's `audit_log_user_created_idx (user_id, created_at desc)` serves
--    the ORDER BY but doesn't include `id`, so the keyset predicate's
--    tiebreaker (`created_at.eq.<c>,and(id.lt.<id>)`) can't be resolved from
--    that index alone. Adding `id` makes the whole keyset seek index-only.

create extension if not exists pg_trgm;

create index if not exists audit_log_target_trgm_idx
  on audit_log using gin (target gin_trgm_ops);

create index if not exists audit_log_user_created_id_idx
  on audit_log (user_id, created_at desc, id);
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00012', 'audit_log_search')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00013_memory_keyset_index.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Keyset-pagination covering index for the Lore Explorer's server-side
-- paginated list of memories (ordered newest-first, tiebroken by id).
--
-- Mirrors the pattern established by 00012_audit_log_search.sql for
-- audit_log: the `(user_id, created_at desc, id)` index covers the keyset
-- seek used by `listMemories` (the `(created_at desc, id desc)` order +
-- the `.or()` "after cursor" predicate). The `id` tiebreaker is required so
-- the seek is deterministic when multiple rows share the same `created_at`;
-- 00001's `memories_user_idx (user_id)` lacks both `created_at` and `id`.
--
-- Also enables pg_trgm trigram search on `memories.key` and `memories.value`
-- for the key/value substring search (`ilike '%…%'`), mirroring the
-- 00012_audit_log_search.sql precedent for `audit_log.target`.
create extension if not exists pg_trgm;

create index if not exists memories_user_created_at_id_idx
  on memories (user_id, created_at desc, id desc);

create index if not exists memories_key_trgm_idx
  on memories using gin (key gin_trgm_ops);

create index if not exists memories_value_trgm_idx
  on memories using gin (value gin_trgm_ops);
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00013', 'memory_keyset_index')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00014_orgs.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit organizations: server-side org entity + membership table.
--
-- Foundational schema for shared/team lore (org-owned memories land in
-- 00013/00014; the write path itself is Phase 2 — see plan.md). `orgs` is
-- the org identity; `org_members` is the SOLE membership-truth table.
-- `.lorekit/config.json` (Phase 4, advisory-only) never substitutes for it —
-- see CLAUDE.md.
--
-- lorekit_member_org_ids() is the SINGLE tenant-visibility predicate
-- source: both the memories RLS policies (00013) and the mirrored TS helper
-- (packages/mcp-core/src/tenant-scope.ts, applyTenantScope) consume its
-- result via RPC — never a hand-copied membership check. SECURITY DEFINER +
-- STABLE, mirroring the enforce_memory_cap()/lorekit_get_limit() pattern
-- (00004_limits.sql): keyed off the authenticated identity, never a
-- client-supplied claim.

create table if not exists orgs (
  id         uuid primary key default gen_random_uuid(),
  slug       text not null unique check (slug = lower(slug)),
  name       text not null,
  created_by uuid references auth.users on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table orgs enable row level security;

create table if not exists org_members (
  org_id     uuid not null references orgs(id) on delete cascade,
  user_id    uuid not null references auth.users on delete cascade,
  role       text not null default 'member' check (role in ('owner', 'admin', 'member')),
  created_at timestamptz not null default now(),
  primary key (org_id, user_id)
);

alter table org_members enable row level security;

create index if not exists org_members_user_idx on org_members (user_id);

-- Members can read the orgs they belong to, and only their own membership
-- row. No insert/update/delete policy yet: Phase 3 (invite/accept server
-- actions, Supabase-JWT scoped) owns the membership write path — until then
-- only a service-role client can create orgs/memberships.
create policy "rls_orgs_select"
  on orgs for select
  using (
    id in (select org_id from org_members where user_id = auth.uid())
  );

create policy "rls_org_members_select"
  on org_members for select
  using (user_id = auth.uid());

create or replace trigger orgs_updated_at
  before update on orgs
  for each row execute function set_updated_at();

-- The single membership-truth function. STABLE (read-only, same result
-- within a statement) + SECURITY DEFINER so the memories RLS policy (00013)
-- can call it without granting SELECT on org_members directly, and so the
-- edge api_key path (service-role, RLS-bypass) gets identical semantics via
-- an explicit RPC call (see tenant-scope.ts). Reads ONLY org_members — never
-- memories — so it cannot recurse into the memories RLS policy that calls it.
create or replace function lorekit_member_org_ids(p_user_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select org_id from org_members where user_id = p_user_id;
$$;

-- NOT granted to `anon`: the function takes a bare p_user_id, so an
-- unauthenticated caller with EXECUTE could enumerate any user's org
-- membership via PostgREST RPC. RLS policies that call it run as the
-- querying role, and only authenticated/service_role ever read `memories`.
grant execute on function lorekit_member_org_ids(uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00014', 'orgs')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00015_memories_org_fk.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Replace the dormant, unsafe org_id scaffolding on memories with a real FK
-- and a membership-verified RLS read policy.
--
-- 00001_memories.sql introduced `org_id text` plus an RLS read policy that
-- trusted a client-asserted, single-valued JWT claim
-- (`org_id = auth.jwt() ->> 'org_id'`). That is unsafe: any caller can mint
-- a JWT (or, for the api_key path, is not even gated by RLS) asserting any
-- org_id and read that org's lore. This migration:
--   1. Drops the two policies that reference the unsafe claim (00003 widened
--      them to also gate on archived_at, so both rls_read and
--      rls_read_archived must be dropped and recreated).
--   2. Converts org_id from free-text to a nullable uuid FK -> orgs(id). The
--      column has never been written by any code path (grep-verified), so
--      `org_id::uuid` casts every existing (null) value cleanly. Pre-flight
--      safety note for whoever applies this migration to a non-fresh
--      database (dev/staging/production): run
--        select count(*) from memories where org_id is not null;
--      first. A non-zero count means the cast will fail loudly (forward-only
--      migrations do not paper over that) — investigate before proceeding.
--   3. Recreates both read policies using lorekit_member_org_ids(auth.uid())
--      (00014_orgs.sql) — the single SECURITY DEFINER membership source —
--      instead of the client-asserted claim.
--
-- Writes are untouched here: memory_write (00007/00009/00011) never sets
-- org_id, so every row stays personal-only until Phase 2. The org-aware
-- unique arbiter lands in 00014.

drop policy if exists "rls_read" on memories;
drop policy if exists "rls_read_archived" on memories;

alter table memories
  alter column org_id type uuid using org_id::uuid;

alter table memories
  add constraint memories_org_id_fkey
  foreign key (org_id) references orgs(id) on delete cascade;

create policy "rls_read"
  on memories for select
  using (
    archived_at is null
    and (
      user_id = auth.uid()
      or org_id in (select lorekit_member_org_ids(auth.uid()))
    )
  );

create policy "rls_read_archived"
  on memories for select
  using (
    archived_at is not null
    and (
      user_id = auth.uid()
      or org_id in (select lorekit_member_org_ids(auth.uid()))
    )
  );
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00015', 'memories_org_fk')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00016_memories_org_unique_arbiter.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Make org ownership a first-class partition of the (scope, key) uniqueness
-- arbiter, and re-pin memory_write's ON CONFLICT predicates to match.
--
-- 00003 introduced two partial unique indexes:
--   memories_user_scope_key_active_unique      (user_id, scope, key)
--     WHERE archived_at IS NULL
--   memories_null_user_scope_key_active_unique  (scope, key)
--     WHERE user_id IS NULL AND archived_at IS NULL
--
-- Now that org_id is a real FK (00013), those two predicates are ambiguous
-- for an org-owned row (org_id IS NOT NULL, user_id may be NULL or set to the
-- creator) — it could collide with either partition. This migration replaces
-- them with THREE mutually-exclusive partial unique indexes:
--   • org-owned  (org_id, scope, key)  WHERE org_id IS NOT NULL AND archived_at IS NULL
--   • personal   (user_id, scope, key) WHERE org_id IS NULL AND user_id IS NOT NULL AND archived_at IS NULL
--   • service    (scope, key)          WHERE org_id IS NULL AND user_id IS NULL AND archived_at IS NULL
-- An org row can never collide with (or impersonate) the cap-exempt
-- user_id IS NULL service partition, because the org index requires
-- org_id IS NOT NULL while the service index requires org_id IS NULL.
--
-- Postgres' ON CONFLICT arbiter inference requires the inference clause's
-- predicate to match the target partial index's predicate, so memory_write's
-- two ON CONFLICT ... WHERE clauses must be re-pinned in the same migration
-- or every write breaks. No signature change (still no p_org_id parameter —
-- writes stay personal-only, Requirement R7), so CREATE OR REPLACE suffices
-- (matches the "same drop+recreate shape only when the signature/return
-- changes" note in 00009/00011 — here only the body changes).

drop index if exists memories_user_scope_key_active_unique;
drop index if exists memories_null_user_scope_key_active_unique;

create unique index if not exists memories_user_scope_key_active_unique
  on memories (user_id, scope, key)
  where org_id is null and user_id is not null and archived_at is null;

create unique index if not exists memories_null_user_scope_key_active_unique
  on memories (scope, key)
  where org_id is null and user_id is null and archived_at is null;

create unique index if not exists memories_org_scope_key_active_unique
  on memories (org_id, scope, key)
  where org_id is not null and archived_at is null;

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null
)
returns table (id uuid, created_at timestamptz, inserted boolean)
language plpgsql
set search_path = public
as $$
begin
  if p_user_id is null then
    -- service-role / CI writes: (scope, key) partial index for
    -- org_id IS NULL AND user_id IS NULL.
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at)
    values (null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()))
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;
  else
    -- user-scoped writes (api_key / user): (user_id, scope, key) partial
    -- index for org_id IS NULL AND user_id IS NOT NULL. Phase 1 never sets
    -- org_id on a write, so every insert lands in this personal partition.
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at)
    values (p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()))
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00016', 'memories_org_unique_arbiter')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00017_org_roles_and_author.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Org write foundations, part 1: a `viewer` role and author attribution.
--
-- Phase 2 (org-owned writes) opens the write path Phase 1 deliberately left
-- closed. This migration lays the two pieces the write/delete RPCs (00017,
-- 00018) depend on:
--
--   1. `viewer` joins the `org_members.role` CHECK. Phase 1 only ever needed
--      owner/admin/member (nobody could write yet); Phase 2 needs a
--      read-only role so "a viewer cannot write/delete" is expressible.
--   2. `created_by` / `updated_by` land on `memories`, additive and nullable,
--      neighbour-symmetric with the existing `created_at`/`updated_at` pair
--      (created_by preserved on clobber like created_at; updated_by tracks
--      the last writer like updated_at tracks the last write time). Org rows
--      keep `user_id NULL` (see 00013/00014) so a dedicated author pair
--      records who wrote an org row without overloading `user_id` — reusing
--      `user_id` would pool org rows into the writer's personal cap count
--      and personal RLS partition.
--
-- `lorekit_org_role` / `lorekit_org_can` are the single SQL capability
-- source (mirrors the `lorekit_member_org_ids` SECURITY DEFINER shape,
-- 00012_orgs.sql): every role -> capability decision for org writes/deletes
-- routes through `lorekit_org_can`, never a hand-copied TS matrix. Reads are
-- untouched — `lorekit_member_org_ids` stays the sole read-visibility
-- predicate (R8).

alter table org_members drop constraint org_members_role_check;
alter table org_members add constraint org_members_role_check
  check (role in ('owner', 'admin', 'member', 'viewer'));

alter table memories
  add column if not exists created_by uuid references auth.users on delete set null,
  add column if not exists updated_by uuid references auth.users on delete set null;

-- Resolve a user's role within an org, or NULL if they are not a member.
-- STABLE (read-only within a statement) + SECURITY DEFINER so it can be
-- called from the memory_write/memory_delete RPCs (also SECURITY DEFINER)
-- regardless of the caller's RLS visibility into org_members.
create or replace function lorekit_org_role(p_user_id uuid, p_org_id uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select role from org_members where user_id = p_user_id and org_id = p_org_id;
$$;

grant execute on function lorekit_org_role(uuid, uuid) to anon, authenticated, service_role;

-- The single capability source for org write/delete authorization.
-- Capabilities: 'write' | 'archive' | 'restore' | 'hard_delete'.
-- Matrix: viewer -> none; member -> write/archive/restore; admin & owner ->
-- additionally hard_delete. A non-member (NULL role) is denied everything.
-- This is the ONLY place the role -> capability matrix is encoded — the
-- app-layer org-permissions.ts module translates the resulting LK002 denial,
-- it does not re-derive the matrix (see plan.md Decisions).
create or replace function lorekit_org_can(p_user_id uuid, p_org_id uuid, p_capability text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_role text := lorekit_org_role(p_user_id, p_org_id);
begin
  if v_role is null then
    return false;
  end if;

  return case p_capability
    when 'write'       then v_role in ('member', 'admin', 'owner')
    when 'archive'     then v_role in ('member', 'admin', 'owner')
    when 'restore'     then v_role in ('member', 'admin', 'owner')
    when 'hard_delete' then v_role in ('admin', 'owner')
    else false
  end;
end;
$$;

grant execute on function lorekit_org_can(uuid, uuid, text) to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00017', 'org_roles_and_author')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00018_org_limits.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Org write foundations, part 2: a tenant-keyed memory cap.
--
-- `org_limits` + `lorekit_get_org_limit` mirror `user_limits` +
-- `lorekit_get_limit` (00004_limits.sql) exactly — a nullable per-org
-- override table, COALESCEd against the same free-tier default via
-- `lorekit_default_limit`, so raising an org's cap is a single row upsert
-- (paid-tier-ready, no billing built yet). Only `max_memories` is carried —
-- rate limiting stays caller-keyed this phase (see plan.md Decisions), so an
-- org `requests_per_minute` column would be dead configuration.
--
-- `enforce_memory_cap()` gains an org branch that MUST run BEFORE the
-- `user_id IS NULL` service exemption: an org-owned row always has
-- `user_id IS NULL` (00013/00014), so without this ordering an org write
-- would silently inherit the cap-exempt service partition. Branch order is
-- now org -> service-exempt -> personal.

create table if not exists org_limits (
  org_id       uuid primary key references orgs(id) on delete cascade,
  max_memories integer,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

alter table org_limits enable row level security;

-- Members can see their org's limit row (dashboard/CLI "your org's limit");
-- raising a limit is a service-role/admin upsert for now — no insert/update
-- policy for regular members, mirroring user_limits' shape.
create policy "rls_org_limits_select"
  on org_limits for select
  using (
    org_id in (select lorekit_member_org_ids(auth.uid()))
  );

create or replace trigger org_limits_updated_at
  before update on org_limits
  for each row execute function set_updated_at();

-- Resolve the effective limit for an org: override if set, else the same
-- free-tier default lorekit_get_limit uses. Security definer so it can read
-- org_limits regardless of the caller's RLS visibility (needed inside the
-- cap trigger).
create or replace function lorekit_get_org_limit(p_org_id uuid, p_key text)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_override integer;
begin
  if p_key = 'max_memories' then
    select max_memories into v_override from org_limits where org_id = p_org_id;
  end if;

  return coalesce(v_override, lorekit_default_limit(p_key));
end;
$$;

grant execute on function lorekit_get_org_limit(uuid, text) to anon, authenticated, service_role;

-- Index backing the org branch's active-row count below
-- (`where org_id = new.org_id and archived_at is null`), which runs on every
-- org-owned INSERT. Without it large orgs seq-scan `memories` per write.
-- Partial (archived_at is null) + org_id-keyed to match the count predicate.
create index if not exists memories_org_id_active_idx
  on memories (org_id)
  where archived_at is null;

-- Tenant-keyed cap trigger. Branch order: org -> service-exempt -> personal.
-- The org branch must precede the service exemption because org rows have
-- user_id IS NULL — checking `new.user_id is null` first would silently
-- exempt every org write from any cap at all.
create or replace function enforce_memory_cap()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_limit integer;
  v_count integer;
begin
  if new.org_id is not null then
    v_limit := lorekit_get_org_limit(new.org_id, 'max_memories');

    select count(*) into v_count
      from memories
     where org_id = new.org_id
       and archived_at is null;

    if v_count >= v_limit then
      raise exception using
        errcode = 'LK001',
        message = format('memory_cap_exceeded: limit=%s', v_limit);
    end if;

    return new;
  end if;

  if new.user_id is null then
    return new; -- true service-role / CI exemption (both org_id and user_id null)
  end if;

  v_limit := lorekit_get_limit(new.user_id, 'max_memories');

  select count(*) into v_count
    from memories
   where user_id = new.user_id
     and archived_at is null;

  if v_count >= v_limit then
    raise exception using
      errcode = 'LK001',
      message = format('memory_cap_exceeded: limit=%s', v_limit);
  end if;

  return new;
end;
$$;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00018', 'org_limits')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00019_memory_write_org.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- memory_write gains org-owned writes: a trailing p_org_slug selector, author
-- attribution, and an authorization-gated org branch.
--
-- org_id is authorization-derived INSIDE the RPC, never trusted from the
-- caller (R1/R7): when p_org_slug is supplied, this resolves the slug to an
-- org_id and requires lorekit_org_can(p_user_id, org_id, 'write') — a
-- non-member or a viewer raises SQLSTATE 'LK002' (a distinct signal from the
-- memory-cap LK001) and writes no row. A caller passing any slug it is not a
-- write-capable member of is rejected regardless of what it claims.
--
-- An unresolvable slug raises a distinct 'unknown_org' error (not LK002) so
-- the caller can tell "no such org" from "not permitted" (see plan.md Edge
-- Cases).
--
-- Author attribution: every branch now sets created_by/updated_by = the
-- writer (null for the service branch, since it has no writer identity). On
-- an org upsert-clobber, created_by/created_at are preserved (matching the
-- existing personal-clobber created_at semantics) while updated_by/updated_at
-- advance to the clobbering writer.
--
-- Adding a trailing parameter changes the function signature, so
-- CREATE OR REPLACE alone would leave the old 8-arg overload behind and make
-- PostgREST calls ambiguous — drop the old signature first (same shape as
-- 00009/00011). Forward-only.

drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null,
  p_org_slug     text        default null
)
returns table (id uuid, created_at timestamptz, inserted boolean)
language plpgsql
set search_path = public
as $$
declare
  v_org_id uuid;
begin
  if p_org_slug is not null then
    -- Qualify orgs.id explicitly: the RETURNS TABLE's `id` output column
    -- would otherwise make a bare `select id` ambiguous inside this function.
    select o.id into v_org_id from orgs o where o.slug = p_org_slug;
    if v_org_id is null then
      raise exception using
        errcode = 'P0001',
        message = format('unknown_org: %s', p_org_slug);
    end if;

    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using
        errcode = 'LK002',
        message = format('org_permission_denied: org=%s', p_org_slug);
    end if;

    -- Org-owned write: (org_id, scope, key) partial index for
    -- org_id IS NOT NULL. user_id stays NULL so the row is never counted
    -- against the writer's personal cap or personal RLS partition (R3/R9);
    -- created_by/updated_by record the writer instead.
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()), p_user_id, p_user_id
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id
      -- created_by/created_at are NOT in this SET list: they are preserved
      -- from the original row on clobber, matching the existing
      -- created_at-preservation semantics (00009).
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;

  elsif p_user_id is null then
    -- service-role / CI writes: (scope, key) partial index for
    -- org_id IS NULL AND user_id IS NULL. No writer identity to attribute.
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at, created_by, updated_by)
    values (null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()), null, null)
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;
  else
    -- user-scoped writes (api_key / user): (user_id, scope, key) partial
    -- index for org_id IS NULL AND user_id IS NOT NULL.
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at, created_by, updated_by)
    values (p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()), p_user_id, p_user_id)
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00019', 'memory_write_org')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00020_memory_delete_org.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Role-gated memory_delete RPC — the org side of destructive ops.
--
-- The edge api_key path is a service-role client that bypasses RLS, so a raw
-- org-targeted `.delete()`/`.update()` would have NO gate at all. Role
-- enforcement for org rows must therefore live in a SECURITY DEFINER RPC that
-- calls lorekit_org_can (00015), mirroring memory_write's org branch.
--
-- Personal delete (p_org_slug NULL) mirrors today's raw .eq('user_id', ...)
-- behavior exactly — the well-tested personal path is intentionally left
-- untouched elsewhere (tools.ts, mcp-core delete.ts) to minimize blast radius
-- on a security-critical change; this RPC only absorbs the org-targeted case
-- plus a personal fallback so callers have one entry point.
--
-- Capability required: 'archive' for a soft-delete (p_force = false),
-- 'hard_delete' for p_force = true. A viewer is denied both; a member may
-- soft-archive but not hard-delete; admin/owner may do both. Any denial
-- raises SQLSTATE 'LK002' (same signal as memory_write's org-permission
-- denial) so the app layer translates it identically.
--
-- An unresolvable slug raises 'unknown_org', matching memory_write.

create or replace function memory_delete(
  p_user_id  uuid,
  p_org_slug text default null,
  p_scope    text default null,
  p_key      text default null,
  p_force    boolean default false
)
returns table (deleted boolean, archived boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id uuid;
  v_count  integer;
begin
  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug;
    if v_org_id is null then
      raise exception using
        errcode = 'P0001',
        message = format('unknown_org: %s', p_org_slug);
    end if;

    if p_force then
      if not lorekit_org_can(p_user_id, v_org_id, 'hard_delete') then
        raise exception using
          errcode = 'LK002',
          message = format('org_permission_denied: org=%s capability=hard_delete', p_org_slug);
      end if;

      delete from memories
       where org_id = v_org_id and scope = p_scope and key = p_key;
      get diagnostics v_count = row_count;

      return query select (v_count > 0), false;
    else
      if not lorekit_org_can(p_user_id, v_org_id, 'archive') then
        raise exception using
          errcode = 'LK002',
          message = format('org_permission_denied: org=%s capability=archive', p_org_slug);
      end if;

      update memories
         set archived_at = now()
       where org_id = v_org_id and scope = p_scope and key = p_key and archived_at is null;
      get diagnostics v_count = row_count;

      return query select false, (v_count > 0);
    end if;
  else
    -- Personal delete: mirrors the existing .eq('user_id', p_user_id) path.
    if p_force then
      delete from memories
       where user_id = p_user_id and scope = p_scope and key = p_key;
      get diagnostics v_count = row_count;

      return query select (v_count > 0), false;
    else
      update memories
         set archived_at = now()
       where user_id = p_user_id and scope = p_scope and key = p_key and archived_at is null;
      get diagnostics v_count = row_count;

      return query select false, (v_count > 0);
    end if;
  end if;
end;
$$;

grant execute on function memory_delete(uuid, text, text, text, boolean) to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00020', 'memory_delete_org')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00021_org_invites.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Org sharing Phase 3, migration 1 of 3: the `org_invites` table + its RLS
-- read policies, and widening `org_members` visibility to co-members.
--
-- `org_invites` is the identity-bound invitation entity the 00012 migration
-- comment deferred to "Phase 3": a pending invite addressed to an email OR a
-- GitHub handle (never a forwardable share-link — see plan.md Decisions).
-- `role` deliberately excludes `owner` (ownership is non-transferable in v1 —
-- see plan.md Out of Scope #2) and `status` tracks the invite's lifecycle.
-- Only ONE pending invite may exist per (org, identity) — enforced by two
-- partial unique indexes, mirroring the `webhook_secrets` partial-unique
-- pattern (00008).
--
-- NO insert/update/delete RLS policy exists on `org_invites` — every mutation
-- (invite/revoke/accept/decline) is a SECURITY DEFINER RPC (00020) that
-- authorizes via `lorekit_org_can`, exactly like `org_members`/`orgs` before
-- it. RLS here governs reads only: an org's owners/admins see all its
-- invites; an invited user sees pending invites addressed to their VERIFIED
-- JWT identity claims (`email`, `user_metadata.user_name`) — never a
-- client-supplied identity string.
--
-- Also widens `rls_org_members_select` from own-row-only (00012) to all
-- co-members of a shared org, via `lorekit_org_role` (SECURITY DEFINER, reads
-- org_members bypassing RLS — the same anti-recursion shape used throughout
-- 00012/00015). The dashboard member list needs to show co-members; this
-- supersedes the Phase 1 own-row-only assertion in migrations.test.sql §7,
-- which is updated forward in the same PR (a test file, not a shipped
-- migration — see plan.md Decisions).

create table if not exists org_invites (
  id             uuid primary key default gen_random_uuid(),
  org_id         uuid not null references orgs(id) on delete cascade,
  invitee_email  text,                                    -- lowercased
  invitee_handle text,                                    -- lowercased GitHub handle
  role           text not null default 'member' check (role in ('admin', 'member', 'viewer')),
  status         text not null default 'pending' check (status in ('pending', 'accepted', 'declined', 'revoked')),
  invited_by     uuid references auth.users on delete set null,
  created_at     timestamptz not null default now(),
  responded_at   timestamptz,
  expires_at     timestamptz,
  check (invitee_email is not null or invitee_handle is not null)  -- identity-bound
);

-- One pending invite per (org, identity) — a second pending invite for the
-- same identity would be redundant/confusing; revoke or let it resolve first.
create unique index if not exists org_invites_pending_email_idx
  on org_invites (org_id, invitee_email) where status = 'pending' and invitee_email is not null;
create unique index if not exists org_invites_pending_handle_idx
  on org_invites (org_id, invitee_handle) where status = 'pending' and invitee_handle is not null;
create index if not exists org_invites_org_idx on org_invites (org_id);

alter table org_invites enable row level security;

-- Owners/admins of the org see all its invites (single-source capability
-- check — 'invite' is a management capability an owner/admin holds).
create policy "rls_org_invites_select_manage" on org_invites for select
  using (lorekit_org_can(auth.uid(), org_id, 'invite'));

-- The invited user sees pending invites addressed to their VERIFIED identity
-- claims — never a client-supplied string. auth.jwt() reads the request's
-- verified JWT (same GUC-backed function used throughout 00012/00015).
create policy "rls_org_invites_select_invitee" on org_invites for select
  using (
    status = 'pending' and (
      invitee_email  = lower(auth.jwt() ->> 'email') or
      invitee_handle = lower(auth.jwt() -> 'user_metadata' ->> 'user_name')
    )
  );

-- Widen member visibility from own-row-only (00012) to all co-members of a
-- shared org. lorekit_org_role is SECURITY DEFINER + STABLE and reads
-- org_members bypassing RLS, so this policy cannot recurse into itself.
drop policy "rls_org_members_select" on org_members;
create policy "rls_org_members_select" on org_members for select
  using (lorekit_org_role(auth.uid(), org_id) is not null);
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00021', 'org_invites')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00022_org_management_rpcs.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Org sharing Phase 3, migration 2 of 3: the membership-truth WRITE path.
--
-- Every state transition for orgs/org_members/org_invites goes through one of
-- the 10 SECURITY DEFINER RPCs below — never a direct RLS-gated table write
-- (org_invites/org_members/orgs carry no insert/update/delete RLS policy).
-- Two problems make direct writes unsafe here (see plan.md Decisions):
--
--   1. Owner-bootstrap: the FIRST membership row can't be gated by existing
--      membership, so a self-insert-as-owner RLS policy would let any
--      authenticated user seize any org by inserting an owner row for a slug
--      they don't own. lorekit_org_create sidesteps this by being the only
--      path that can ever insert the first owner, atomically with the org
--      row, bound to auth.uid().
--   2. Non-atomic accept: inserting the membership row and flipping the
--      invite's status are two statements; RLS-gated direct writes would
--      make that two round-trips (a TOCTOU window). The RPC does both in one
--      transaction.
--
-- Every RPC below resolves the actor as `auth.uid()` — NEVER a caller-passed
-- user-id parameter — because these are dashboard actions invoked under a
-- real Supabase user JWT session (unlike memory_write/memory_delete, which
-- take an explicit p_user_id because the edge api_key path calls them from a
-- service-role client with no session JWT of its own). This is the same
-- anti-forgery property Phase 2 relies on, applied at the call boundary
-- instead of via a parameter: no argument the caller supplies can name a
-- different identity than the one the JWT authenticated.
--
-- lorekit_org_can (00015) is extended with six management capabilities —
-- never a second matrix. It stays the SOLE role -> capability source; these
-- RPCs only add capability-independent INVARIANTS (last-owner protection,
-- admin-cannot-touch-owner-or-admin, invite-addressed-to-caller) that a
-- static role matrix cannot express, since they depend on the mutation's
-- specific target/state, not just the actor's role.
create or replace function lorekit_org_can(p_user_id uuid, p_org_id uuid, p_capability text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_role text := lorekit_org_role(p_user_id, p_org_id);
begin
  if v_role is null then
    return false;
  end if;

  return case p_capability
    when 'write'         then v_role in ('member', 'admin', 'owner')
    when 'archive'       then v_role in ('member', 'admin', 'owner')
    when 'restore'       then v_role in ('member', 'admin', 'owner')
    when 'hard_delete'   then v_role in ('admin', 'owner')
    when 'invite'        then v_role in ('admin', 'owner')
    when 'revoke_invite' then v_role in ('admin', 'owner')
    when 'remove_member' then v_role in ('admin', 'owner')
    when 'change_role'   then v_role in ('admin', 'owner')
    when 'rename_org'    then v_role in ('admin', 'owner')
    when 'delete_org'    then v_role = 'owner'
    else false
  end;
end;
$$;

-- ── 1. Org lifecycle ─────────────────────────────────────────────────────────

-- Creates the org AND the creator's owner membership atomically. No
-- capability check: this is the owner-bootstrap path — anyone authenticated
-- may create an org and becomes its sole owner. A duplicate slug surfaces
-- the orgs.slug unique_violation naturally.
create or replace function lorekit_org_create(p_slug text, p_name text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id uuid := gen_random_uuid();
begin
  insert into orgs (id, slug, name, created_by)
  values (v_org_id, p_slug, p_name, auth.uid());

  insert into org_members (org_id, user_id, role)
  values (v_org_id, auth.uid(), 'owner');

  return v_org_id;
end;
$$;

grant execute on function lorekit_org_create(text, text) to authenticated, service_role;

create or replace function lorekit_org_rename(p_org_id uuid, p_name text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not lorekit_org_can(auth.uid(), p_org_id, 'rename_org') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=rename_org', p_org_id);
  end if;

  update orgs set name = p_name where id = p_org_id;
end;
$$;

grant execute on function lorekit_org_rename(uuid, text) to authenticated, service_role;

-- Owner-only. Cascades org_members/org_invites via their `on delete cascade`
-- FKs to orgs(id) — no manual cleanup needed.
create or replace function lorekit_org_delete(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not lorekit_org_can(auth.uid(), p_org_id, 'delete_org') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=delete_org', p_org_id);
  end if;

  delete from orgs where id = p_org_id;
end;
$$;

grant execute on function lorekit_org_delete(uuid) to authenticated, service_role;

-- ── 2. Invite lifecycle ──────────────────────────────────────────────────────

-- Shared identity-match check for accept/decline: true iff the invite is
-- addressed to the CALLER's verified JWT identity (email or GitHub handle).
-- Each comparison is explicitly `coalesce`d to false — `NULL = x` evaluates
-- to SQL NULL, not false, so a one-sided invite (email set, handle NULL, or
-- vice versa) would otherwise poison the `or` into NULL. `if not (NULL)` is
-- treated as `if not false` by plpgsql (the branch is skipped, no exception
-- raised) — a real privilege-escalation bug this coalesce closes, caught by
-- migrations.test.sql's AC-6 "wrong user accepts" negative assertion.
create or replace function lorekit_invite_addressed_to_caller(p_invite org_invites)
returns boolean
language sql
stable
set search_path = public
as $$
  select
    coalesce(p_invite.invitee_email = lower(auth.jwt() ->> 'email'), false)
    or coalesce(p_invite.invitee_handle = lower(auth.jwt() -> 'user_metadata' ->> 'user_name'), false);
$$;

-- Owner/admin only. The org_invites.role CHECK (00019) independently rejects
-- an attempt to invite an 'owner' — this RPC does not re-derive that guard.
create or replace function lorekit_org_invite(
  p_org_id uuid,
  p_invitee_email text default null,
  p_invitee_handle text default null,
  p_role text default 'member'
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_invite_id uuid;
begin
  if not lorekit_org_can(auth.uid(), p_org_id, 'invite') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=invite', p_org_id);
  end if;

  insert into org_invites (org_id, invitee_email, invitee_handle, role, invited_by)
  values (
    p_org_id,
    case when p_invitee_email is not null then lower(p_invitee_email) end,
    case when p_invitee_handle is not null then lower(p_invitee_handle) end,
    p_role,
    auth.uid()
  )
  returning id into v_invite_id;

  return v_invite_id;
end;
$$;

grant execute on function lorekit_org_invite(uuid, text, text, text) to authenticated, service_role;

create or replace function lorekit_org_invite_revoke(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  inv org_invites;
begin
  select * into inv from org_invites where id = p_invite_id;
  if inv.id is null then
    raise exception using errcode = 'LK002', message = 'invite not found';
  end if;

  if not lorekit_org_can(auth.uid(), inv.org_id, 'revoke_invite') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=revoke_invite', inv.org_id);
  end if;

  -- Only a still-pending invite can be revoked — guards the silent
  -- re-revoke and the revoke-of-already-accepted cases (accepted invites are
  -- undone via member removal, not revoke).
  if inv.status <> 'pending' then
    raise exception using errcode = 'LK002', message = 'invite is not pending';
  end if;

  update org_invites set status = 'revoked', responded_at = now() where id = p_invite_id;
end;
$$;

grant execute on function lorekit_org_invite_revoke(uuid) to authenticated, service_role;

-- Binds the new membership row to the CALLER (auth.uid()), NEVER the invited
-- string. Takes no user-id parameter by design (the anti-TOCTOU fix — see
-- plan.md). The invited email/handle is only ever a MATCH TARGET for "is this
-- invite addressed to me?", never the identity that gets inserted.
create or replace function lorekit_org_invite_accept(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  inv org_invites;
begin
  select * into inv from org_invites where id = p_invite_id;
  if inv.id is null or inv.status <> 'pending'
     or (inv.expires_at is not null and inv.expires_at < now()) then
    raise exception using errcode = 'LK002', message = 'invite is not open';
  end if;

  if not lorekit_invite_addressed_to_caller(inv) then
    raise exception using errcode = 'LK002', message = 'invite is not addressed to you';
  end if;

  insert into org_members (org_id, user_id, role)
  values (inv.org_id, auth.uid(), inv.role)
  on conflict (org_id, user_id) do nothing;

  update org_invites set status = 'accepted', responded_at = now() where id = inv.id;
end;
$$;

grant execute on function lorekit_org_invite_accept(uuid) to authenticated, service_role;

-- Invitee-only. Mirrors the accept RPC's identity check but flips status to
-- 'declined' and creates no membership.
create or replace function lorekit_org_invite_decline(p_invite_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  inv org_invites;
begin
  select * into inv from org_invites where id = p_invite_id;
  if inv.id is null or inv.status <> 'pending' then
    raise exception using errcode = 'LK002', message = 'invite is not open';
  end if;

  if not lorekit_invite_addressed_to_caller(inv) then
    raise exception using errcode = 'LK002', message = 'invite is not addressed to you';
  end if;

  update org_invites set status = 'declined', responded_at = now() where id = inv.id;
end;
$$;

grant execute on function lorekit_org_invite_decline(uuid) to authenticated, service_role;

-- ── 3. Member management ─────────────────────────────────────────────────────

-- Owner/admin only, plus two invariants a static role matrix cannot express:
--   - an admin actor may only act on member/viewer targets (never owner/admin)
--   - the last remaining owner can never be removed
create or replace function lorekit_org_member_remove(p_org_id uuid, p_target_user_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role  text;
  v_target_role text;
  v_owner_count int;
begin
  if not lorekit_org_can(auth.uid(), p_org_id, 'remove_member') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=remove_member', p_org_id);
  end if;

  v_actor_role  := lorekit_org_role(auth.uid(), p_org_id);
  v_target_role := lorekit_org_role(p_target_user_id, p_org_id);

  if v_target_role is null then
    raise exception using errcode = 'LK002', message = 'target is not a member of this org';
  end if;

  if v_actor_role = 'admin' and v_target_role in ('owner', 'admin') then
    raise exception using errcode = 'LK002', message = 'an admin cannot remove an owner or another admin';
  end if;

  if v_target_role = 'owner' then
    select count(*) into v_owner_count from org_members where org_id = p_org_id and role = 'owner';
    if v_owner_count <= 1 then
      raise exception using errcode = 'LK002', message = 'the last owner cannot be removed — transfer or delete the org first';
    end if;
  end if;

  delete from org_members where org_id = p_org_id and user_id = p_target_user_id;
end;
$$;

grant execute on function lorekit_org_member_remove(uuid, uuid) to authenticated, service_role;

-- Owner/admin only. Cannot assign 'owner' (ownership is non-transferable in
-- v1); cannot demote the last owner; an admin actor may only act on
-- member/viewer targets, mirroring lorekit_org_member_remove's invariant.
create or replace function lorekit_org_member_role(p_org_id uuid, p_target_user_id uuid, p_role text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor_role  text;
  v_target_role text;
  v_owner_count int;
begin
  if p_role = 'owner' then
    raise exception using errcode = 'LK002', message = 'cannot assign owner via changeMemberRole — ownership is not transferable in v1';
  end if;

  if not lorekit_org_can(auth.uid(), p_org_id, 'change_role') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=change_role', p_org_id);
  end if;

  v_actor_role  := lorekit_org_role(auth.uid(), p_org_id);
  v_target_role := lorekit_org_role(p_target_user_id, p_org_id);

  if v_target_role is null then
    raise exception using errcode = 'LK002', message = 'target is not a member of this org';
  end if;

  if v_actor_role = 'admin' and v_target_role in ('owner', 'admin') then
    raise exception using errcode = 'LK002', message = 'an admin cannot change the role of an owner or another admin';
  end if;

  if v_target_role = 'owner' then
    select count(*) into v_owner_count from org_members where org_id = p_org_id and role = 'owner';
    if v_owner_count <= 1 then
      raise exception using errcode = 'LK002', message = 'the last owner cannot be demoted — transfer or delete the org first';
    end if;
  end if;

  update org_members set role = p_role where org_id = p_org_id and user_id = p_target_user_id;
end;
$$;

grant execute on function lorekit_org_member_role(uuid, uuid, text) to authenticated, service_role;

-- Self-service: any member may remove their OWN membership (no capability
-- check — leaving is not a management action), except the last owner, who
-- must transfer ownership or delete the org first.
create or replace function lorekit_org_leave(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_role text := lorekit_org_role(auth.uid(), p_org_id);
  v_owner_count int;
begin
  if v_role is null then
    raise exception using errcode = 'LK002', message = 'you are not a member of this org';
  end if;

  if v_role = 'owner' then
    select count(*) into v_owner_count from org_members where org_id = p_org_id and role = 'owner';
    if v_owner_count <= 1 then
      raise exception using errcode = 'LK002', message = 'the last owner cannot leave — transfer or delete the org first';
    end if;
  end if;

  delete from org_members where org_id = p_org_id and user_id = auth.uid();
end;
$$;

grant execute on function lorekit_org_leave(uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00022', 'org_management_rpcs')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00023_audit_log_org_actions.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Org sharing Phase 3, migration 3 of 3: extend the audit_log `action` CHECK
-- with the 10 org-management actions so orgs.ts/org-invites.ts's
-- recordAuditEvent calls can insert them. Forward-only: drop + re-add the
-- CHECK (a constraint can't be widened in place) rather than editing the
-- shipped 00010 migration.

alter table audit_log drop constraint audit_log_action_check;

alter table audit_log add constraint audit_log_action_check check (action in (
  'api_key.create',
  'api_key.revoke',
  'webhook_secret.create',
  'webhook_secret.rotate',
  'webhook_secret.deactivate',
  'memory.create',
  'memory.update',
  'memory.archive',
  'memory.restore',
  'memory.delete',
  'limit.override',
  'org.create',
  'org.rename',
  'org.delete',
  'member.invite',
  'member.accept',
  'member.decline',
  'member.revoke',
  'member.remove',
  'member.role_change',
  'member.leave'
));
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00023', 'audit_log_org_actions')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00024_org_member_identities.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Org sharing Phase 4 addition: real member identities for the dashboard
-- member list. This REVERSES plan.md Decision D1's "web-only, no handle
-- resolution for other members" deferral — an explicit orchestrator override
-- of the Phase 4 dashboard-UX plan (see
-- .agent/claude/org-sharing-phase-4-dashboard/plan.md Decisions, D1).
--
-- `org_members` exposes only `user_id`. `auth.users.raw_user_meta_data`
-- (GitHub OAuth: `user_name` + `avatar_url` — the SAME claims 00019/00020
-- already read off the caller's own verified JWT) is otherwise only readable
-- by a service-role client, never a bare `select * from auth.users` from
-- `anon`/`authenticated`. This migration adds ONE narrow, membership-gated
-- read: a caller may resolve the handle/avatar of any user who shares an org
-- WITH them, and ONLY for that org — never a global user directory.
--
-- SECURITY DEFINER + STABLE (read-only), gated via the existing
-- `lorekit_org_role` membership-truth function (00015) — the exact same
-- "NULL role denies everything" shape used throughout 00012/00015/00020.
-- No insert/update path, no direct grant on `auth.users` to anon/authenticated.
--
-- Takes `p_org_id` (not a slug) to match every sibling Phase 3 management RPC
-- (`lorekit_org_rename`/`_delete`/`_member_remove`/`_member_role`/`_leave` all
-- take `p_org_id`) — the dashboard always already has the org's uuid in scope
-- (from `listMyOrgs()`/`listMembers()`), so a slug->id lookup would be an
-- extra, inconsistent hop for this one RPC alone.
create or replace function lorekit_org_members_list(p_org_id uuid)
returns table (
  user_id    uuid,
  handle     text,
  avatar_url text,
  role       text,
  joined_at  timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  -- Non-member (including a non-existent org — lorekit_org_role resolves to
  -- NULL either way): return an EMPTY set, never raise and never leak
  -- whether the org exists. Mirrors the "NULL role denies everything" gate
  -- shape used throughout 00012/00015/00020.
  if lorekit_org_role(auth.uid(), p_org_id) is null then
    return;
  end if;

  return query
    select
      m.user_id,
      coalesce(
        u.raw_user_meta_data ->> 'user_name',
        u.raw_user_meta_data ->> 'preferred_username'
      ) as handle,
      u.raw_user_meta_data ->> 'avatar_url' as avatar_url,
      m.role,
      m.created_at as joined_at
    from org_members m
    join auth.users u on u.id = m.user_id
    where m.org_id = p_org_id
    order by m.created_at asc;
end;
$$;

-- No `anon` grant (unlike lorekit_member_org_ids/lorekit_org_role, which
-- return only booleans/ids): this function returns PII (handle, avatar_url)
-- for other users, so it is authenticated-only, defense in depth beyond the
-- membership gate above.
grant execute on function lorekit_org_members_list(uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00024', 'org_member_identities')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00025_safe_org_deletion.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Safe org deletion — soft-delete + retention + explicit purge.
--
-- The #73 ON DELETE CASCADE discussion resolved to KEEP the cascade (an org's
-- memberships/invites/limits and its `memories.org_id` FK all cascade on a real
-- delete) and add RECOVERY one layer above it: `lorekit_org_delete` now
-- SOFT-deletes (stamps `orgs.deleted_at`), and a separate owner-only
-- `lorekit_org_purge` performs the real cascading delete as an explicit second
-- step (the permanent-delete / future grace-period-job path).
--
-- A soft-deleted org's lore disappears from every member's reads through ONE
-- change: `lorekit_member_org_ids()` (the single tenant-visibility predicate,
-- consumed by both the `memories` RLS read policies AND the mirrored TS
-- `applyTenantScope`, which reads this function's OUTPUT list) now excludes
-- soft-deleted orgs. No read-path code outside this function changes; the
-- `tenant-scope.ts` mirror and its drift guards (edge-parity / tenant-scope-usage)
-- stay green because the function's contract (a list of visible org ids) is
-- unchanged — only its result shrinks.
-- ═════════════════════════════════════════════════════════════════════════

-- 1. The soft-delete marker. Nullable; NULL = live (the overwhelming majority),
--    a timestamp = soft-deleted at that instant. Added BEFORE the function
--    recreate below so the join target exists.
alter table orgs add column if not exists deleted_at timestamptz;

-- 2. Re-create the single membership-truth function to hide soft-deleted orgs.
--    Signature / STABLE / SECURITY DEFINER / search_path all preserved verbatim
--    from 00014 — only the body gains the `orgs` join + `deleted_at is null`
--    filter. Because the memories RLS policies and the edge `applyTenantScope`
--    helper both route through this function, a soft-deleted org's memories
--    vanish from ALL reads with no other change.
create or replace function lorekit_member_org_ids(p_user_id uuid)
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select om.org_id
  from org_members om
  join orgs o on o.id = om.org_id
  where om.user_id = p_user_id
    and o.deleted_at is null;
$$;

grant execute on function lorekit_member_org_ids(uuid) to authenticated, service_role;

-- 3. The `orgs` SELECT policy (00014) uses a DIRECT org_members subquery, not
--    `lorekit_member_org_ids`, so it must be changed explicitly — otherwise a
--    soft-deleted org would still be directly readable via a `from orgs` select
--    (e.g. the org switcher). `rls_org_limits_select` (00018) DOES route through
--    the function above, so it is hidden transitively with no change here.
drop policy if exists "rls_orgs_select" on orgs;
create policy "rls_orgs_select"
  on orgs for select
  using (
    deleted_at is null
    and id in (select org_id from org_members where user_id = auth.uid())
  );

-- 4. `lorekit_org_delete` becomes a SOFT delete: stamp `deleted_at` instead of
--    removing the row. Same owner-only authorization (`delete_org` capability)
--    and `auth.uid()` actor pattern as 00022. Idempotent: a second call on an
--    already-soft-deleted org is a no-op (the `deleted_at is null` guard) and
--    still returns void.
create or replace function lorekit_org_delete(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not lorekit_org_can(auth.uid(), p_org_id, 'delete_org') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=delete_org', p_org_id);
  end if;

  update orgs set deleted_at = now() where id = p_org_id and deleted_at is null;
end;
$$;

grant execute on function lorekit_org_delete(uuid) to authenticated, service_role;

-- 5. NEW: `lorekit_org_purge` — the real, irreversible cascading delete. Same
--    owner-only gate as delete (there is no separate "purge" capability;
--    permanent removal is the owner's prerogative, identical trust level to
--    soft-delete). The `delete from orgs` cascades to org_members / org_invites
--    / org_limits and nulls/cascades `memories.org_id` per the FK definitions.
--    Not authorization-gated on `deleted_at` — an owner may purge a live org
--    directly (skip the retention window) or purge one already soft-deleted.
--    No app-layer/server-action caller ships this PR: the audit_log action
--    CHECK (00023) has no `org.purge` value, so wiring a dashboard purge button
--    would require a second CHECK migration. Shipped SQL-first as the explicit
--    permanent-delete / grace-period-job entry point; the dashboard delete flow
--    uses the soft-delete above.
create or replace function lorekit_org_purge(p_org_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not lorekit_org_can(auth.uid(), p_org_id, 'delete_org') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=purge', p_org_id);
  end if;

  delete from orgs where id = p_org_id;
end;
$$;

grant execute on function lorekit_org_purge(uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00025', 'safe_org_deletion')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00026_scope_org_bindings.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Scope → org binding: bind a scope (e.g. a repo) to an org so writes under it
-- are routed to the org automatically, without each write naming the org.
--
-- Authorization stays server-derived, never caller-trusted (the Phase 2 rule):
--   • Creating a binding requires the actor be an admin/owner of the org
--     (new `manage_scopes` capability on lorekit_org_can).
--   • A write under a bound scope is routed to the org ONLY IF the writer is a
--     write-capable member of that org. A non-member's (or viewer's) write
--     falls back to PERSONAL — never rejected, never silently lost: memory_write
--     reports the bound org's slug back so the caller can surface an actionable
--     notice ("saved personal; this scope is shared with <org>, ask an admin").
--
-- Precedence: an explicit p_org_slug on memory_write always wins; the binding
-- only applies when no org was named.
-- ═════════════════════════════════════════════════════════════════════════

-- 1. The binding table. One org per scope GLOBALLY (unique on scope) so
--    auto-routing is unambiguous — a scope can't be bound to two orgs. A
--    soft-deleted org's binding is harmless: memory_write joins orgs and skips
--    deleted ones (and the FK cascade removes the binding on a real purge).
create table org_scope_bindings (
  id         uuid primary key default gen_random_uuid(),
  org_id     uuid not null references orgs(id) on delete cascade,
  scope      text not null,
  created_by uuid,
  created_at timestamptz not null default now()
);

create unique index org_scope_bindings_scope_uniq on org_scope_bindings (scope);
create index org_scope_bindings_org_idx on org_scope_bindings (org_id);

alter table org_scope_bindings enable row level security;

-- Members of the org can see its bindings (the dashboard's "Shared scopes"
-- list). No insert/update/delete policy — all writes go through the RPCs below,
-- mirroring orgs/org_members/org_invites (Phase 3).
create policy "rls_scope_bindings_select"
  on org_scope_bindings for select
  using (org_id in (select lorekit_member_org_ids(auth.uid())));

grant select on org_scope_bindings to authenticated, service_role;

-- 2. Extend lorekit_org_can with `manage_scopes` (admin/owner) — the single
--    role→capability source, extended, never re-derived. Body is 00022's
--    verbatim plus the one new capability line.
create or replace function lorekit_org_can(p_user_id uuid, p_org_id uuid, p_capability text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_role text := lorekit_org_role(p_user_id, p_org_id);
begin
  if v_role is null then
    return false;
  end if;

  return case p_capability
    when 'write'         then v_role in ('member', 'admin', 'owner')
    when 'archive'       then v_role in ('member', 'admin', 'owner')
    when 'restore'       then v_role in ('member', 'admin', 'owner')
    when 'hard_delete'   then v_role in ('admin', 'owner')
    when 'invite'        then v_role in ('admin', 'owner')
    when 'revoke_invite' then v_role in ('admin', 'owner')
    when 'remove_member' then v_role in ('admin', 'owner')
    when 'change_role'   then v_role in ('admin', 'owner')
    when 'rename_org'    then v_role in ('admin', 'owner')
    when 'manage_scopes' then v_role in ('admin', 'owner')
    when 'delete_org'    then v_role = 'owner'
    else false
  end;
end;
$$;

-- 3. Bind / unbind RPCs. SECURITY DEFINER, actor = auth.uid() (dashboard JWT
--    session — the Phase 3 pattern; NO caller-supplied user-id). Gated on
--    `manage_scopes`. Bind is idempotent for the same (org, scope); a scope
--    already bound to a DIFFERENT org raises a distinct 'scope_bound_elsewhere'
--    so the caller can report the conflict.
create or replace function lorekit_scope_bind(p_org_id uuid, p_scope text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_existing_org uuid;
  v_id uuid;
begin
  if p_scope is null or length(trim(p_scope)) = 0 then
    raise exception using errcode = 'P0001', message = 'scope is required';
  end if;

  if not lorekit_org_can(v_actor, p_org_id, 'manage_scopes') then
    raise exception using errcode = 'LK002',
      message = format('org_permission_denied: org=%s capability=manage_scopes', p_org_id);
  end if;

  select org_id, id into v_existing_org, v_id from org_scope_bindings where scope = p_scope;
  if v_existing_org = p_org_id then
    -- Already bound to this org — idempotent no-op; return the existing id.
    return v_id;
  elsif v_existing_org is not null then
    raise exception using errcode = 'P0001',
      message = format('scope_bound_elsewhere: %s', p_scope);
  end if;

  insert into org_scope_bindings (org_id, scope, created_by)
  values (p_org_id, p_scope, v_actor)
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function lorekit_scope_unbind(p_org_id uuid, p_scope text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
begin
  if p_scope is null or length(trim(p_scope)) = 0 then
    raise exception using errcode = 'P0001', message = 'scope is required';
  end if;

  if not lorekit_org_can(v_actor, p_org_id, 'manage_scopes') then
    raise exception using errcode = 'LK002',
      message = format('org_permission_denied: org=%s capability=manage_scopes', p_org_id);
  end if;

  delete from org_scope_bindings where org_id = p_org_id and scope = p_scope;
end;
$$;

grant execute on function lorekit_scope_bind(uuid, text) to authenticated, service_role;
grant execute on function lorekit_scope_unbind(uuid, text) to authenticated, service_role;

-- 4. Recreate memory_write with scope-binding auto-routing. The return type
--    grows two additive columns — `org_routed` (did the row land in an org?)
--    and `binding_org_slug` (the bound org's slug when a binding exists for the
--    scope, regardless of routing) — so the caller can build the graceful
--    fallback notice. Changing the RETURNS TABLE shape requires a drop first.
drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz, text);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null,
  p_org_slug     text        default null
)
returns table (id uuid, created_at timestamptz, inserted boolean, org_routed boolean, binding_org_slug text)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
begin
  if p_org_slug is not null then
    -- Explicit org selector — takes precedence over any binding.
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    -- No explicit org: consult the scope binding. Resolve the bound org (if any,
    -- excluding soft-deleted orgs). Route to it only when the writer is a
    -- write-capable member; otherwise fall through to a personal/service write
    -- but still report the bound slug so the caller can surface a notice.
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    -- Org-owned write (explicit slug OR binding-routed). user_id stays NULL;
    -- created_by/updated_by record the writer. org_routed = true.
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()), p_user_id, p_user_id
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted,
              true as org_routed, v_binding_slug as binding_org_slug;

  elsif p_user_id is null then
    -- service-role / CI write.
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at, created_by, updated_by)
    values (null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()), null, null)
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now()
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted,
              false as org_routed, v_binding_slug as binding_org_slug;
  else
    -- user-scoped (api_key / user) personal write — includes the binding
    -- fallback case (a binding exists but the writer can't write to it).
    return query
    insert into memories (user_id, scope, key, value, tags, source_agent, trigger, created_at, updated_at, created_by, updated_by)
    values (p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
            coalesce(p_created_at, now()), coalesce(p_created_at, now()), p_user_id, p_user_id)
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id
    returning memories.id, memories.created_at, (xmax::text = '0') as inserted,
              false as org_routed, v_binding_slug as binding_org_slug;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00026', 'scope_org_bindings')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00027_audit_log_scope_actions.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Scope-binding UI (follow-up to 00026): extend the audit_log `action` CHECK
-- with `scope.bind` and `scope.unbind` so the dashboard's scope-bindings
-- server actions can call recordAuditEvent for bind/unbind mutations.
--
-- Forward-only: drop + re-add the CHECK (a constraint can't be widened in
-- place) — the same pattern as 00023_audit_log_org_actions.sql.

alter table audit_log drop constraint audit_log_action_check;

alter table audit_log add constraint audit_log_action_check check (action in (
  'api_key.create',
  'api_key.revoke',
  'webhook_secret.create',
  'webhook_secret.rotate',
  'webhook_secret.deactivate',
  'memory.create',
  'memory.update',
  'memory.archive',
  'memory.restore',
  'memory.delete',
  'limit.override',
  'org.create',
  'org.rename',
  'org.delete',
  'member.invite',
  'member.accept',
  'member.decline',
  'member.revoke',
  'member.remove',
  'member.role_change',
  'member.leave',
  'scope.bind',
  'scope.unbind'
));
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00027', 'audit_log_scope_actions')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00028_invite_org_details.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Invite-details modal: lets a PENDING (non-member) invitee see which org
-- invited them before accepting. `listPendingInvitesForMe`'s `orgs(name,
-- slug)` embed resolves to null for a non-member (the org read policy,
-- 00014/00025, is member-only), so today the banner falls back to the
-- literal "Someone invited you to an organization" with no name — the UX
-- problem this migration's read path fixes.
--
-- SECURITY DEFINER, gated on the EXISTING `lorekit_invite_addressed_to_caller`
-- (00022) — never re-derived, never re-widened. Returns Tier-A fields ONLY
-- (org name, slug, created_at, an aggregate member COUNT, the inviter's
-- handle/avatar) — explicitly NO per-member identity list (Tier B, declined
-- by the user in Phase 0). This migration adds NO policy and touches NO
-- existing function or policy — it is a pure, additive read path, mirroring
-- `lorekit_org_members_list`'s (00024) "gate, then join auth.users for one
-- identity" shape, applied to the ADDRESSED-INVITEE gate instead of the
-- membership gate.
create or replace function lorekit_invite_org_details(p_invite_id uuid)
returns table (
  org_name           text,
  org_slug           text,
  org_created_at     timestamptz,
  member_count       int,
  inviter_handle     text,
  inviter_avatar_url text
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  inv org_invites;
begin
  select * into inv from org_invites where id = p_invite_id;

  -- No such invite, not pending, or not addressed to the caller: return an
  -- EMPTY set, never raise and never leak whether the invite exists — the
  -- same "gate denies silently, by returning nothing" shape used throughout
  -- 00022/00024.
  if inv.id is null or inv.status <> 'pending' or not lorekit_invite_addressed_to_caller(inv) then
    return;
  end if;

  return query
    select
      o.name,
      o.slug,
      o.created_at,
      (select count(*) from org_members where org_id = inv.org_id)::int,
      coalesce(u.raw_user_meta_data ->> 'user_name', u.raw_user_meta_data ->> 'preferred_username'),
      u.raw_user_meta_data ->> 'avatar_url'
    from orgs o
    left join auth.users u on u.id = inv.invited_by
    where o.id = inv.org_id and o.deleted_at is null;
end;
$$;

-- No `anon` grant: this function returns PII (inviter handle/avatar, member
-- count) about an org the caller isn't yet a member of. Authenticated-only,
-- the same defense-in-depth posture as `lorekit_org_members_list` (00024)
-- and every other PII-bearing definer function in this schema.
grant execute on function lorekit_invite_org_details(uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00028', 'invite_org_details')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00030_memory_ttl.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Memory TTL (time-to-live) — per-row auto-expiry for transient memories.
--
-- Adds an optional `expires_at` column to the memories table. When set, the
-- row is treated as invisible by all active-memory read paths once the
-- timestamp passes, without requiring the caller to manually archive or
-- delete it. Expired rows are physically removed by the new
-- `purge_expired_memories` RPC (called by the MCP `memory.purge` tool or a
-- scheduled job) — the existing `purge_archived_memories` RPC is unchanged.
--
-- Design choices:
--   • `expires_at` is nullable — omitting it means the memory lives forever
--     (current default behaviour, fully backward-compatible).
--   • The active-read filter is extended to:
--       archived_at IS NULL AND (expires_at IS NULL OR expires_at > now())
--     NOTE: The RLS policies on the memories table perform the archived_at
--     check. The expires_at check is applied at the query layer (toolRead,
--     toolList, toolSearch, etc.) via an additional .or() filter, keeping
--     the RLS policies lean (they cannot call now() cheaply in a policy).
--   • Expired rows remain physically present until purged so the sweep is a
--     cheap index scan, not a table scan, and no data is silently lost.
--   • On UPDATE (upsert conflict): p_ttl_days IS NOT NULL → refreshes
--     expires_at; p_ttl_days IS NULL → leaves existing expires_at unchanged
--     so a value-only update never accidentally clears an existing TTL.
-- ═════════════════════════════════════════════════════════════════════════

-- 1. Add the expiry column (nullable, no default → backward-compatible).
alter table memories
  add column if not exists expires_at timestamptz;

-- 2. Partial index for fast expiry sweeps (only non-null expires_at rows).
create index if not exists memories_expires_at_idx
  on memories (expires_at)
  where expires_at is not null;

-- 3. Recreate memory_write with an optional p_ttl_days parameter.
--
--    p_ttl_days: when provided (>= 1), sets expires_at = now() + p_ttl_days * INTERVAL '1 day'.
--    On INSERT:  expires_at is computed from p_ttl_days (or left NULL if omitted).
--    On UPDATE:  expires_at is refreshed ONLY when p_ttl_days is not null —
--                omitting it on an update leaves the existing expiry unchanged.
--    The return type grows an additive `expires_at` column so callers can
--    surface the computed expiry. Changing RETURNS TABLE shape requires DROP first.
drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz, text);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null,
  p_org_slug     text        default null,
  p_ttl_days     integer     default null
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz
)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
begin
  -- Validate TTL: must be a positive integer when supplied.
  if p_ttl_days is not null then
    if p_ttl_days < 1 or p_ttl_days > 365 then
      raise exception using errcode = 'P0001',
        message = format('ttl_days must be between 1 and 365, got %s', p_ttl_days);
    end if;
    v_expires_at := now() + (p_ttl_days * interval '1 day');
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id,
      expires_at   = case when p_ttl_days is not null then v_expires_at else memories.expires_at end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      expires_at   = case when p_ttl_days is not null then v_expires_at else memories.expires_at end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id,
      expires_at   = case when p_ttl_days is not null then v_expires_at else memories.expires_at end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer)
  to anon, authenticated, service_role;

-- 4. New purge_expired_memories RPC — hard-deletes active rows whose
--    expires_at is in the past. Separate from purge_archived_memories so
--    each sweep is independently callable and narrowly indexed.
create or replace function purge_expired_memories(
  p_user_id uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  delete from memories
   where user_id     = p_user_id
     and expires_at  is not null
     and expires_at  < now()
     and archived_at is null   -- archived rows stay with purge_archived_memories
  ;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Intentionally excludes anon: an unauthenticated caller could supply any
-- p_user_id and hard-delete another user's expired rows (no auth.uid() check
-- inside the function body). Authenticated + service_role are sufficient.
grant execute on function purge_expired_memories(uuid) to authenticated, service_role;

comment on column memories.expires_at is
  'Optional timestamp after which the row is treated as invisible by active-read
   paths. NULL means the row never expires. Physically deleted by
   purge_expired_memories() or the MCP memory.purge tool.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00030', 'memory_ttl')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00031_memory_ttl_clear.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Add p_clear_ttl to memory_write so callers can explicitly remove an
-- existing expires_at (set it back to NULL → the row never expires again).
--
-- Without this, the only way to clear a TTL is a raw UPDATE, which bypasses
-- the write RPC's authorization logic (org cap, org permission checks, audit).
--
-- Design:
--   p_clear_ttl boolean default false
--   When true:  sets expires_at = NULL (clears the TTL).
--   When false: existing behaviour — p_ttl_days controls expires_at.
--   p_clear_ttl takes precedence: if both p_clear_ttl = true and
--   p_ttl_days IS NOT NULL, the clear wins.
-- ═════════════════════════════════════════════════════════════════════════

drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null,
  p_org_slug     text        default null,
  p_ttl_days     integer     default null,
  p_clear_ttl    boolean     default false
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz
)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
  -- Tri-state for the expires_at UPDATE branch:
  --   'clear'  → set to NULL
  --   'set'    → set to v_expires_at
  --   'keep'   → leave unchanged (CASE WHEN ... ELSE memories.expires_at END)
  v_ttl_action   text := 'keep';
begin
  if p_clear_ttl then
    -- Explicit clear wins over any p_ttl_days value.
    v_ttl_action := 'clear';
  elsif p_ttl_days is not null then
    if p_ttl_days < 1 or p_ttl_days > 365 then
      raise exception using errcode = 'P0001',
        message = format('ttl_days must be between 1 and 365, got %s', p_ttl_days);
    end if;
    v_expires_at  := now() + (p_ttl_days * interval '1 day');
    v_ttl_action  := 'set';
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id,
      expires_at   = case v_ttl_action
                       when 'clear' then null
                       when 'set'   then v_expires_at
                       else memories.expires_at
                     end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      expires_at   = case v_ttl_action
                       when 'clear' then null
                       when 'set'   then v_expires_at
                       else memories.expires_at
                     end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id,
      expires_at   = case v_ttl_action
                       when 'clear' then null
                       when 'set'   then v_expires_at
                       else memories.expires_at
                     end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00031', 'memory_ttl_clear')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00032_plans.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- LoreKit billing plans — Phase 1 (free plan only).
--
-- Introduces a `plan` concept without any billing integration:
--   * `user_plans` table tracks which plan a user is on (default: 'free').
--   * `lorekit_default_limit` is updated so plan-aware defaults can be read
--     from the table — a future paid tier only needs to insert a row here.
--   * The free-plan `max_memories` default rises from 1000 → 5000.
--   * A `plan_name` column is added to `user_limits` so any manual override
--     row can be annotated with its originating plan (audit trail).
--
-- Security posture:
--   * Users can read their own plan row (dashboard "you are on the free plan").
--   * Only service-role / admin can insert or update plan rows (no self-upgrade).
--   * RLS on `user_plans` mirrors `user_limits` exactly.
--
-- Existing `user_limits` per-user overrides continue to take precedence over
-- the plan default via the existing `COALESCE(override, default)` chain in
-- `lorekit_get_limit` — no change needed there. Raising a user's cap beyond
-- their plan ceiling remains a service-role upsert into `user_limits`.

-- 1. Plan definitions table — the authoritative per-plan limit defaults.
--    Adding a new plan in future is a single INSERT here.
create table if not exists plans (
  name             text primary key,           -- e.g. 'free', 'pro', 'team'
  max_memories     integer not null,
  requests_per_minute integer not null,
  description      text,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

-- Trigger to keep updated_at current on plan changes.
create or replace trigger plans_updated_at
  before update on plans
  for each row execute function set_updated_at();

-- Anyone can read plan definitions (they are public limits, not PII).
alter table plans enable row level security;
create policy "rls_plans_select"
  on plans for select
  using (true);

-- Seed the free plan. ON CONFLICT so the migration is idempotent on re-runs.
insert into plans (name, max_memories, requests_per_minute, description)
values (
  'free',
  5000,
  120,
  'Free plan: up to 5000 stored memories, 120 requests per minute.'
)
on conflict (name) do update
  set max_memories        = excluded.max_memories,
      requests_per_minute = excluded.requests_per_minute,
      description         = excluded.description,
      updated_at          = now();

-- 2. Per-user plan assignment. Absence of a row means the user is on 'free'.
create table if not exists user_plans (
  user_id    uuid primary key references auth.users on delete cascade,
  plan_name  text not null default 'free' references plans(name),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table user_plans enable row level security;

-- Users can read their own plan row.
create policy "rls_user_plans_select"
  on user_plans for select
  using (user_id = auth.uid());

create or replace trigger user_plans_updated_at
  before update on user_plans
  for each row execute function set_updated_at();

-- 3. Annotate user_limits with the plan that originated the override (optional,
--    for audit/analytics). Nullable so existing rows are unaffected.
alter table user_limits
  add column if not exists plan_name text references plans(name);

-- 4. Update lorekit_default_limit to read from the `plans` table when a
--    matching row exists, falling back to hard-coded values for safety.
--    The user-plan lookup goes through lorekit_get_limit (below) so this
--    function stays plan-agnostic — it is only the universal fallback.
create or replace function lorekit_default_limit(p_key text)
returns integer
language sql
stable   -- changed from immutable: now reads the plans table
security definer
set search_path = public
as $$
  select case p_key
    when 'max_memories'        then (select max_memories        from plans where name = 'free')
    when 'requests_per_minute' then (select requests_per_minute from plans where name = 'free')
    else null
  end;
$$;

-- 5. Plan-aware limit resolver. Replaces lorekit_get_limit with a version that
--    reads the user's plan first, then falls back to the per-user override,
--    then to the plan default. The precedence chain is:
--      user_limits override > plan default > lorekit_default_limit (free).
--
--    This ensures a pro-plan user gets their plan ceiling even without an
--    explicit user_limits row, while a user_limits override still wins
--    (needed when an admin manually caps a misbehaving user below their plan).
create or replace function lorekit_get_limit(p_user_id uuid, p_key text)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_override    integer;
  v_plan_name   text;
  v_plan_limit  integer;
begin
  -- Step 1: per-user manual override (highest precedence).
  if p_key = 'max_memories' then
    select max_memories into v_override from user_limits where user_id = p_user_id;
  elsif p_key = 'requests_per_minute' then
    select requests_per_minute into v_override from user_limits where user_id = p_user_id;
  end if;
  if v_override is not null then
    return v_override;
  end if;

  -- Step 2: plan-based limit (falls back to 'free' when no row exists).
  select coalesce(up.plan_name, 'free')
    into v_plan_name
    from user_plans up
   where up.user_id = p_user_id;

  if v_plan_name is null then
    v_plan_name := 'free';
  end if;

  if p_key = 'max_memories' then
    select max_memories into v_plan_limit from plans where name = v_plan_name;
  elsif p_key = 'requests_per_minute' then
    select requests_per_minute into v_plan_limit from plans where name = v_plan_name;
  end if;

  -- Step 3: ultimate fallback (handles unknown keys gracefully).
  return coalesce(v_plan_limit, lorekit_default_limit(p_key));
end;
$$;

-- Grant read on new tables so authenticated + anon selects work under RLS.
grant select on table plans to anon, authenticated, service_role;
grant select on table user_plans to anon, authenticated, service_role;
grant insert, update on table user_plans to service_role;
grant insert, update on table user_limits to service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00032', 'plans')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00033_performance_indexes.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Performance optimisations for the hot read paths in tools.ts.
--
-- Analysis of the three most-called query patterns:
--
-- 1. toolRead  — SELECT … FROM memories WHERE scope=? AND key=?
--               AND archived_at IS NULL AND (expires_at IS NULL OR expires_at > now())
--    Existing  : memories_scope_key (scope, key) — hits the filter, but forces
--               a heap fetch + recheck for archived_at / expires_at on every row.
--    Fix       : Replace with a PARTIAL index that pre-filters active, non-expired
--               rows and adds user_id so api_key queries can satisfy the full
--               predicate from the index alone (index-only scan).
--
-- 2. toolList  — SELECT … FROM memories WHERE scope=? AND archived_at IS NULL
--               AND (expires_at IS NULL OR expires_at > now())
--               ORDER BY updated_at DESC LIMIT ?
--    Existing  : memories_scope_idx (scope) — covers the WHERE but not the ORDER.
--               Postgres sorts in-memory; large scopes cause a filesort.
--    Fix       : Add (scope, updated_at DESC) so the planner can satisfy the
--               order from the index and stop early after LIMIT rows.
--
-- 3. toolListArchived — WHERE scope=? AND archived_at IS NOT NULL
--                       ORDER BY archived_at DESC LIMIT ?
--    Existing  : No index covering (scope, archived_at).
--    Fix       : Add a PARTIAL index (archived_at IS NOT NULL) on (scope, archived_at DESC).
--
-- 4. memberOrgIds RPC — called on every api_key read (toolRead / toolList /
--               toolSearch / toolListArchived). The RPC itself is already fast,
--               but adding a covering index on org_members (user_id, org_id)
--               means the SECURITY DEFINER function never hits the heap.
--
-- 5. rate_limit_counters — no additional index added. The existing
--               rate_limit_counters_window_idx (window_start) from 00004_limits.sql
--               already covers the reaper's DELETE. A partial index would need
--               a volatile predicate (now()), which PostgreSQL disallows.
--
-- All indexes are created with IF NOT EXISTS so they can be applied to a
-- running production database (CONCURRENTLY is not used inside migrations
-- because it cannot run inside a transaction).

-- 1. Active-memories point-read covering index.
--    Covers: toolRead, and the cap trigger's active-row count.
create index if not exists memories_scope_key_active_idx
  on memories (scope, key, user_id)
  where archived_at is null;

-- 2. List-by-scope ordered index — eliminates the filesort for toolList.
create index if not exists memories_scope_updated_at_idx
  on memories (scope, updated_at desc)
  where archived_at is null;

-- 3. Archived list ordered index — eliminates the filesort for toolListArchived.
create index if not exists memories_scope_archived_at_idx
  on memories (scope, archived_at desc)
  where archived_at is not null;

-- 4. org_members covering index — eliminates heap fetch for memberOrgIds RPC.
create index if not exists org_members_user_org_idx
  on org_members (user_id, org_id);

-- 5. rate_limit_counters — no additional index needed.
--    The existing `rate_limit_counters_window_idx (window_start)` from
--    00004_limits.sql already covers the reaper's DELETE predicate
--    (window_start < now() - interval). A partial index on this table
--    would require a volatile predicate (now()), which PostgreSQL rejects
--    for index predicates — so the existing index is the right choice.

-- 6. Schedule automatic expired-memory purge via pg_cron (when available).
--    Expired memories (expires_at < now()) are invisible to all read paths but
--    still occupy cap headroom and bloat the table. Purge them nightly.
--    lorekit_purge_all_expired_memories() is defined below.
create or replace function lorekit_purge_all_expired_memories()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  delete from memories
   where expires_at is not null
     and expires_at < now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

grant execute on function lorekit_purge_all_expired_memories() to service_role;

-- Schedule nightly at 03:00 UTC when pg_cron is available.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule(
      'lorekit-purge-expired-memories',
      '0 3 * * *',
      $cron$select lorekit_purge_all_expired_memories()$cron$
    );
  end if;
end;
$$;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00033', 'performance_indexes')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00034_usage_events.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Usage events — structured telemetry for post-processing and plan analysis.
--
-- Captures every significant MCP tool call outcome as a lightweight structured
-- row so you can answer questions like:
--   * How many writes/reads/searches per user per day? (→ plan sizing)
--   * What fraction of writes hit the cap? (→ conversion signal)
--   * What is the p50/p95 memory count at cap-hit time? (→ plan threshold)
--   * How many active memories does a median user hold? (→ free-plan ceiling)
--   * Which scope types are most used? (→ product prioritisation)
--   * What is the rate-limit hit rate per plan? (→ plan RPM calibration)
--
-- Design decisions:
--   * Append-only (no UPDATE/DELETE RLS policies). Rows age out via a pg_cron
--     job (lorekit_purge_old_usage_events) or a retention policy.
--   * user_id is stored pseudonymously (the Supabase UUID, never email/handle).
--   * No memory key/value/scope string is stored — just bounded categorical
--     attributes (tool_name, scope_type, outcome, plan_name) that are safe for
--     aggregation dashboards without privacy review.
--   * auth_type discriminates api_key vs JWT vs service writes so you can filter
--     out internal/CI traffic in analytics.
--   * duration_ms tracks wall-clock handler time for latency-percentile analysis.
--
-- RLS: users can read their own rows (self-service "my usage" views); service-
-- role writes; no user insert/update/delete.

create table if not exists usage_events (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid references auth.users on delete set null,  -- null for service-role
  org_id        uuid references orgs(id) on delete set null,    -- null for personal writes
  plan_name     text,                                            -- plan at time of event
  tool_name     text not null,                                   -- e.g. 'memory.write'
  scope_type    text,                                            -- 'global'|'project'|'repo'|'branch'|null
  auth_type     text not null,                                   -- 'api_key'|'jwt'|'service'
  outcome       text not null,                                   -- 'ok'|'cap_exceeded'|'rate_limited'|'permission_denied'|'error'
  duration_ms   integer,                                         -- wall-clock handler time
  memory_count  integer,                                         -- active memories at time of event (write path only)
  created_at    timestamptz not null default now()
);

alter table usage_events enable row level security;

-- Users can read their own usage rows (self-service dashboard).
create policy "rls_usage_events_select"
  on usage_events for select
  using (user_id = auth.uid());

-- Service-role can insert (the only write path — no user insert policy).
-- (service_role bypasses RLS by default in Supabase; this is documentation.)

-- Covering indexes for the most common analytics queries:
--   * Per-user time-series: (user_id, created_at) for daily/weekly rollups.
--   * Funnel by tool + outcome: (tool_name, outcome, created_at).
--   * Plan analysis: (plan_name, outcome, created_at).
create index if not exists usage_events_user_created_at_idx
  on usage_events (user_id, created_at desc);

create index if not exists usage_events_tool_outcome_idx
  on usage_events (tool_name, outcome, created_at desc);

create index if not exists usage_events_plan_outcome_idx
  on usage_events (plan_name, outcome, created_at desc);

-- Reaper: hard-delete usage events older than p_older_than (default 90 days).
-- Called by pg_cron. Returns the count of deleted rows.
create or replace function lorekit_purge_old_usage_events(
  p_older_than interval default interval '90 days'
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  delete from usage_events
   where created_at < now() - p_older_than;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

grant execute on function lorekit_purge_old_usage_events(interval) to service_role;

-- Schedule quarterly cleanup (retain 90 days) — runs weekly on Sundays at 02:00 UTC.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule(
      'lorekit-purge-old-usage-events',
      '0 2 * * 0',
      $cron$select lorekit_purge_old_usage_events()$cron$
    );
  end if;
end;
$$;

-- Helper RPC: record one usage event. Accepts nullable fields gracefully.
-- Called from the edge function and Node server after each tool call completes.
-- Returns the new row's id for correlation.
create or replace function lorekit_record_usage_event(
  p_user_id      uuid default null,
  p_org_id       uuid default null,
  p_plan_name    text default null,
  p_tool_name    text default null,
  p_scope_type   text default null,
  p_auth_type    text default null,
  p_outcome      text default null,
  p_duration_ms  integer default null,
  p_memory_count integer default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into usage_events (
    user_id, org_id, plan_name,
    tool_name, scope_type, auth_type,
    outcome, duration_ms, memory_count
  ) values (
    p_user_id, p_org_id, p_plan_name,
    p_tool_name, p_scope_type, p_auth_type,
    p_outcome, p_duration_ms, p_memory_count
  )
  returning id into v_id;
  return v_id;
exception
  when others then
    -- Never let telemetry writes break the primary operation.
    return null;
end;
$$;

