-- ─────────────────────────────────────────────────────────────────────────────
-- 00035_memory_count.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- lorekit_memory_count(p_user_id) — efficient active memory count for the
-- /settings/plan page usage bar.
--
-- The dashboard can't do a raw SELECT COUNT(*) per page load without either
-- bypassing RLS (service-role) or doing a full table scan under the user's
-- RLS context. This SECURITY DEFINER function does the scoped count with the
-- index-backed predicate that enforce_memory_cap() uses, so no extra full-scan
-- occurs. It reuses memories_user_idx + the archived_at IS NULL partial index
-- (memories_org_id_active_idx for the org branch).
--
-- Returns: JSONB { "count": <integer>, "limit": <integer>, "plan": <text> }
-- so the caller gets everything it needs in one round-trip.

create or replace function lorekit_memory_count(p_user_id uuid)
returns jsonb
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_count     integer;
  v_limit     integer;
  v_plan_name text;
begin
  -- Count active personal memories for this user.
  select count(*)
    into v_count
    from memories
   where user_id = p_user_id
     and archived_at is null;

  -- Resolve effective limit and plan name in the same function call.
  v_limit := lorekit_get_limit(p_user_id, 'max_memories');

  select coalesce(up.plan_name, 'free')
    into v_plan_name
    from user_plans up
   where up.user_id = p_user_id;

  if v_plan_name is null then
    v_plan_name := 'free';
  end if;

  return jsonb_build_object(
    'count',     v_count,
    'limit',     v_limit,
    'plan',      v_plan_name
  );
end;
$$;

-- Grant to authenticated so the Next.js server action can call it under the
-- user JWT (supabase-js createServerClient uses the user's JWT session).
grant execute on function lorekit_memory_count(uuid)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00035', 'memory_count')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00036_fix_memory_count.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Fix memory count consistency (bug fix).
--
-- Root cause: lorekit_memory_count (00035) only counted personal memories
-- (WHERE user_id = p_user_id AND archived_at IS NULL), while the dashboard
-- query fetched all memories visible under RLS — including org-owned rows
-- (user_id IS NULL, org_id set) and archived rows. The two numbers diverged
-- for any user who (a) belongs to an org or (b) has archived memories.
--
-- Correct definition: active (archived_at IS NULL), non-expired memories that
-- the user owns personally OR through org membership. This matches what the
-- dashboard should show and what the enforcement cap cares about (the cap is
-- per-personal-user or per-org, not a combined total, but the displayed count
-- should reflect what the user sees).
--
-- The dashboard-side fix (filter archived rows, add org memberships to the
-- count) lives in the Next.js query layer — no migration needed there.
--
-- This migration drops and recreates lorekit_memory_count with:
--   * personal count: user_id = p_user_id AND archived_at IS NULL
--   * org count: org_id IN (lorekit_member_org_ids(p_user_id)) AND archived_at IS NULL
--   * total: personal + org (what the user sees in the dashboard)
-- Both personal and org counts are returned so the UI can decide what to show.

create or replace function lorekit_memory_count(p_user_id uuid)
returns jsonb
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_personal_count integer;
  v_org_count      integer;
  v_limit          integer;
  v_plan_name      text;
  v_org_ids        uuid[];
begin
  -- Resolve org memberships once.
  select array_agg(org_id)
    into v_org_ids
    from org_members om
    join orgs o on o.id = om.org_id
   where om.user_id = p_user_id
     and o.deleted_at is null;

  -- Personal active memories.
  select count(*)
    into v_personal_count
    from memories
   where user_id = p_user_id
     and archived_at is null;

  -- Org-owned active memories across all orgs the user belongs to.
  if v_org_ids is not null and cardinality(v_org_ids) > 0 then
    select count(*)
      into v_org_count
      from memories
     where org_id = any(v_org_ids)
       and archived_at is null;
  else
    v_org_count := 0;
  end if;

  -- Resolve effective personal limit and plan name.
  v_limit := lorekit_get_limit(p_user_id, 'max_memories');

  select coalesce(up.plan_name, 'free')
    into v_plan_name
    from user_plans up
   where up.user_id = p_user_id;

  if v_plan_name is null then
    v_plan_name := 'free';
  end if;

  return jsonb_build_object(
    'count',          v_personal_count + v_org_count,
    'personal_count', v_personal_count,
    'org_count',      v_org_count,
    'limit',          v_limit,
    'plan',           v_plan_name
  );
end;
$$;

grant execute on function lorekit_memory_count(uuid)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00036', 'fix_memory_count')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00037_github_installations.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- GitHub App installation tracking.
--
-- A GitHub App installation covers one or more repositories and is identified
-- by a numeric installation_id.  When a user installs the LoreKit GitHub App,
-- GitHub delivers an `installation` event; the edge webhook handler (behind the
-- GITHUB_APP_ENABLED flag) reconciles that event here.
--
-- Authorization posture (the Phase 2 rule):
--   • The reconcile/upsert RPC is SECURITY DEFINER and is called only from the
--     edge function with the service-role key — never by an authenticated user
--     directly.  No caller-supplied user_id is trusted: the edge handler looks
--     up the GitHub account id in auth.users and supplies the resolved uuid, or
--     NULL for a pending installation.
--   • RLS on github_installations: a user reads only the rows that are linked
--     to their own auth.uid() (status='linked').  Pending rows (user_id IS NULL)
--     are invisible to authenticated users until reconciled.
--   • installation_repositories is readable only through the parent
--     github_installations row: the service role reads it; the dashboard reads
--     via a joined server action.
--
-- Fail-safe pending-identity:
--   An installation can arrive before any matching LoreKit user exists (e.g.,
--   installed from GitHub Marketplace before signing in).  Those installations
--   are stored with user_id = NULL + status = 'pending'.  A later login or
--   membership event that matches the github_account_id transitions them to
--   'linked'.  They are NEVER dropped.
--
-- Idempotency:
--   UNIQUE on installation_id + ON CONFLICT in the upsert RPC ensures that
--   redelivered `installation` events produce exactly one row.
-- ═════════════════════════════════════════════════════════════════════════

-- 1. github_installations — one row per GitHub App installation.
create table github_installations (
  id                   uuid primary key default gen_random_uuid(),
  installation_id      bigint not null,
  github_account_id    bigint not null,
  github_account_login text   not null,
  account_type         text   not null check (account_type in ('User', 'Organization')),
  user_id              uuid   references auth.users(id) on delete set null,
  status               text   not null default 'pending'
                                check (status in ('pending', 'linked', 'removed')),
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

create unique index github_installations_installation_id_uniq
  on github_installations (installation_id);

create index github_installations_github_account_id_idx
  on github_installations (github_account_id);

create index github_installations_user_id_idx
  on github_installations (user_id)
  where user_id is not null;

alter table github_installations enable row level security;

-- Users can read only their own linked installations (pending rows with
-- user_id NULL are invisible to authenticated users by this policy).
create policy "rls_github_installations_select"
  on github_installations for select
  using (user_id = auth.uid() and status = 'linked');

grant select on github_installations to authenticated, service_role;

-- 2. installation_repositories — repos covered by an installation.
create table installation_repositories (
  id              uuid primary key default gen_random_uuid(),
  installation_id bigint not null references github_installations(installation_id) on delete cascade,
  full_name       text   not null,
  active          boolean not null default true,
  added_at        timestamptz not null default now(),
  removed_at      timestamptz
);

create index installation_repositories_installation_id_idx
  on installation_repositories (installation_id);

create index installation_repositories_full_name_idx
  on installation_repositories (full_name)
  where active = true;

-- Unique: one active row per (installation_id, full_name).
create unique index installation_repositories_active_uniq
  on installation_repositories (installation_id, full_name)
  where active = true;

alter table installation_repositories enable row level security;

-- Readable only by service_role (the edge function) and by authenticated users
-- whose matching github_installations row is linked to their uid.
create policy "rls_installation_repositories_select"
  on installation_repositories for select
  using (
    installation_id in (
      select i.installation_id
        from github_installations i
       where i.user_id = auth.uid() and i.status = 'linked'
    )
  );

grant select on installation_repositories to authenticated, service_role;

-- 3. Reconcile/upsert RPC — called by the edge function (service-role key).
--    SECURITY DEFINER: operates on github_installations as the definer (bypasses
--    RLS), so the edge function cannot accidentally trigger the authenticated
--    select policy.  Caller supplies a pre-resolved p_user_id (or NULL).
--    Idempotent: ON CONFLICT (installation_id) DO UPDATE.
create or replace function lorekit_installation_upsert(
  p_installation_id      bigint,
  p_github_account_id    bigint,
  p_github_account_login text,
  p_account_type         text,
  p_user_id              uuid,     -- NULL → pending
  p_status               text,     -- 'pending' | 'linked' | 'removed'
  p_repos                text[]    -- full_names to mark active; empty = no repo changes
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  -- Upsert the installation row.
  insert into github_installations (
    installation_id, github_account_id, github_account_login, account_type,
    user_id, status, updated_at
  )
  values (
    p_installation_id, p_github_account_id, p_github_account_login, p_account_type,
    p_user_id, p_status, now()
  )
  on conflict (installation_id) do update set
    github_account_id    = excluded.github_account_id,
    github_account_login = excluded.github_account_login,
    account_type         = excluded.account_type,
    user_id              = case
                             -- Only overwrite user_id when transitioning to linked
                             -- or when updating an already-linked row.  A pending
                             -- install that re-delivers must not lose a previously
                             -- linked user_id.
                             when excluded.status = 'linked' then excluded.user_id
                             when github_installations.status = 'linked' then github_installations.user_id
                             else excluded.user_id
                           end,
    status               = case
                             -- Never regress from 'linked' to 'pending'.
                             when github_installations.status = 'linked'
                              and excluded.status = 'pending'
                             then 'linked'
                             else excluded.status
                           end,
    updated_at           = now()
  returning id into v_id;

  -- Upsert covered repos when provided.
  if array_length(p_repos, 1) is not null then
    -- Insert new active repo rows; skip if already active.
    insert into installation_repositories (installation_id, full_name, active, added_at)
    select p_installation_id, unnest(p_repos), true, now()
    on conflict (installation_id, full_name) where active = true
    do nothing;
  end if;

  return v_id;
end;
$$;

grant execute on function lorekit_installation_upsert(bigint, bigint, text, text, uuid, text, text[])
  to service_role;

-- 4. Remove repos covered by an installation (installation_repositories action='removed').
create or replace function lorekit_installation_remove_repos(
  p_installation_id bigint,
  p_repos           text[]
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update installation_repositories
  set active = false, removed_at = now()
  where installation_id = p_installation_id
    and full_name = any(p_repos)
    and active = true;
end;
$$;

grant execute on function lorekit_installation_remove_repos(bigint, text[])
  to service_role;

-- 5. Mark an installation as removed (soft-delete its repo rows too).
create or replace function lorekit_installation_remove(
  p_installation_id bigint
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  update github_installations
  set status = 'removed', updated_at = now()
  where installation_id = p_installation_id;

  update installation_repositories
  set active = false, removed_at = now()
  where installation_id = p_installation_id
    and active = true;
end;
$$;

grant execute on function lorekit_installation_remove(bigint)
  to service_role;

-- 6. Identity lookup helper — given a GitHub numeric account id (stored as
--    text in auth.identities.provider_id), return the matching auth.users.id.
--    Used by the edge webhook handler to reconcile an installation to a LoreKit
--    user without exposing the auth schema through PostgREST.
--    Returns NULL when no matching user exists (pending path).
create or replace function lorekit_find_user_by_github_id(p_github_account_id text)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select i.user_id
    from auth.identities i
   where i.provider = 'github'
     and i.provider_id = p_github_account_id
   limit 1;
$$;

grant execute on function lorekit_find_user_by_github_id(text)
  to service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00037', 'github_installations')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00038_memory_ttl_seconds.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Extend memory_write TTL to support seconds and minutes in addition to days.
--
-- Previously the RPC accepted p_ttl_days (integer days) and computed
-- expires_at = now() + p_ttl_days * INTERVAL '1 day'.
--
-- This migration replaces p_ttl_days with p_ttl_seconds (integer seconds)
-- so callers can set fine-grained expiry (e.g. 30 s, 5 min) without
-- being forced to round up to a whole day.
--
-- The application layer (mcp-core and the Deno edge function) normalises
-- all three user-visible units (ttl_days, ttl_minutes, ttl_seconds) to
-- seconds via parseTtl() before calling the RPC, so the DB only ever
-- receives an integer number of seconds.
--
-- Design:
--   p_ttl_seconds: when provided (>= 1), sets
--     expires_at = now() + p_ttl_seconds * INTERVAL '1 second'
--   On INSERT:  expires_at is computed from p_ttl_seconds (or NULL if omitted).
--   On UPDATE:  expires_at is refreshed ONLY when p_ttl_seconds is not null —
--               omitting it on an update leaves the existing expiry unchanged.
--   p_clear_ttl still wins over p_ttl_seconds when both are supplied.
--   Validation: p_ttl_seconds must be between 1 and 31 536 000 (365 days).
-- ═════════════════════════════════════════════════════════════════════════

drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean);

create or replace function memory_write(
  p_user_id      uuid,
  p_scope        text,
  p_key          text,
  p_value        text,
  p_tags         text[]      default '{}',
  p_source_agent text        default null,
  p_trigger      text        default null,
  p_created_at   timestamptz default null,
  p_org_slug     text        default null,
  p_ttl_seconds  integer     default null,
  p_clear_ttl    boolean     default false
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz
)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
  -- Tri-state for the expires_at UPDATE branch:
  --   'clear'  → set to NULL
  --   'set'    → set to v_expires_at
  --   'keep'   → leave unchanged (CASE WHEN ... ELSE memories.expires_at END)
  v_ttl_action   text := 'keep';
begin
  if p_clear_ttl then
    -- Explicit clear wins over any p_ttl_seconds value.
    v_ttl_action := 'clear';
  elsif p_ttl_seconds is not null then
    if p_ttl_seconds < 1 or p_ttl_seconds > 31536000 then
      raise exception using errcode = 'P0001',
        message = format('ttl_seconds must be between 1 and 31536000, got %s', p_ttl_seconds);
    end if;
    v_expires_at  := now() + (p_ttl_seconds * interval '1 second');
    v_ttl_action  := 'set';
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id,
      expires_at   = case v_ttl_action
                       when 'clear' then null
                       when 'set'   then v_expires_at
                       else memories.expires_at
                     end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      expires_at   = case v_ttl_action
                       when 'clear' then null
                       when 'set'   then v_expires_at
                       else memories.expires_at
                     end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value        = excluded.value,
      tags         = excluded.tags,
      source_agent = excluded.source_agent,
      trigger      = excluded.trigger,
      updated_at   = now(),
      updated_by   = p_user_id,
      expires_at   = case v_ttl_action
                       when 'clear' then null
                       when 'set'   then v_expires_at
                       else memories.expires_at
                     end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00038', 'memory_ttl_seconds')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00039_memory_scopes.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- lorekit_memory_scopes(p_user_id) — distinct visible scopes with their
-- active memory counts, for GET /memories/scopes (the REST equivalent of the
-- CLI's `listScopes()`, which returns an "unsupported" sentinel today).
--
-- Why an RPC and not a client-side dedupe: the obvious implementation is
-- `select scope from memories` followed by a Set() in TypeScript — which is
-- what packages/web/src/lib/queries/lore.ts does. That is silently wrong past
-- PostgREST's default row cap (db-max-rows): the query returns the first N
-- rows and the caller dedupes those, so a user with more memories than the cap
-- loses whole scopes with no error and no truncation signal. Aggregating in
-- Postgres is exact regardless of row count and returns one row per scope.
--
-- Visibility reuses lorekit_member_org_ids(p_user_id) — the SINGLE
-- tenant-visibility predicate source (00014_orgs.sql) — composed exactly as
-- the memories RLS read policies do (00015_memories_org_fk.sql):
--   user_id = <caller> OR org_id IN (select lorekit_member_org_ids(<caller>))
-- No hand-rolled membership check here; a soft-deleted org drops out of
-- lorekit_member_org_ids (00025) and therefore out of this result too.
--
-- The count matches what GET /memories returns by default
-- (supabase/functions/memories/handlers/list.ts): non-archived AND
-- non-expired. Archived rows are reachable via `?archived=true` and are
-- deliberately excluded from this count rather than split into a second
-- column — the endpoint answers "what can I list right now".
--
-- SECURITY DEFINER + STABLE, mirroring lorekit_memory_count (00035/00036):
-- read-only, keyed off an explicit p_user_id rather than a client-asserted
-- claim, so the api_key edge path (service-role, RLS-bypass) and the JWT path
-- get identical semantics.
--
-- The `p_user_id is null and auth.role() = 'service_role'` branch is the
-- service-role (CI) escape hatch, matching how every other read path treats
-- that credential — GET /memories applies no tenant filter for it. It is safe
-- because `auth.role()` reads the VERIFIED JWT role claim PostgREST sets, not
-- request input: an `authenticated` caller passing p_user_id => null gets
-- nothing back (user_id = null is NULL, and lorekit_member_org_ids(null) is
-- empty), so the function fails closed. Same predicate `rls_insert` (00001)
-- uses to recognise service-role.

-- plpgsql rather than a plain SQL body (unlike lorekit_member_org_ids) for one
-- specific reason: the caller contract includes the ORDER BY. A single-statement
-- SQL function is a candidate for inlining, and an inlined set-returning
-- function's internal ordering is not guaranteed to survive into the outer plan.
-- A plpgsql RETURN QUERY is never inlined, so `order by scope asc` is part of
-- the result rather than an accident of the planner. Same language choice as
-- lorekit_memory_count (00035/00036).
create or replace function lorekit_memory_scopes(p_user_id uuid)
returns table (scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
-- The RETURNS TABLE columns (scope, count) are also plpgsql OUT variables, so an
-- unqualified reference to either inside the query would be ambiguous. Every
-- reference below is table-qualified, and this directive makes the column win
-- regardless, so the body can never be mis-resolved against the OUT variables.
#variable_conflict use_column
begin
  return query
    select m.scope, count(*) as count
      from memories m
     where (
             (p_user_id is null and auth.role() = 'service_role')
             or m.user_id = p_user_id
             or m.org_id in (select lorekit_member_org_ids(p_user_id))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
     group by m.scope
     order by m.scope asc;
end;
$$;

-- NOT granted to `anon`, for the same reason lorekit_member_org_ids is not
-- (00014): the function takes a bare p_user_id, so an unauthenticated caller
-- with EXECUTE could enumerate any user's scope names — and scope names are
-- themselves sensitive (they embed repo and project names) — via a PostgREST
-- RPC call. `authenticated` is safe because the edge functions resolve
-- p_user_id from the verified credential, never from request input.
grant execute on function lorekit_memory_scopes(uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00039', 'memory_scopes')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00041_org_actor_override.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Org actor override — let the REST edge functions serve `lk_*` API tokens.
--
-- ── The problem ──────────────────────────────────────────────────────────
-- Every org management RPC (00022, plus the 00024/00025 re-definitions)
-- resolves the acting user as `auth.uid()`. That is exactly right for the
-- dashboard, which calls them under a real Supabase user JWT session.
--
-- It is unusable for `supabase/functions/orgs/`'s `api_key` auth tier. A
-- `lk_rw_*` / `lk_ro_*` token is verified by the edge function itself
-- (SHA-256 lookup in `api_tokens`), after which the function talks to
-- Postgres with the SERVICE-ROLE key. There is no end-user JWT on that
-- connection, so `auth.uid()` is NULL and every `lorekit_org_can(...)`
-- check denies. The practical consequence today is that `GET/POST/PATCH/
-- DELETE /orgs*` are registered `requires: 'jwt'` and API tokens get a 403 —
-- which is why the CLI still has to keep an MCP transport alive purely for
-- `org.create` / `org.list` / `org.rename` / `org.delete`.
--
-- ── The fix, and why it is the precedent already in this repo ────────────
-- `memory_write` (00019) and `memory_delete` (00020) hit the same wall in
-- Phase 2 and solved it the same way: take the actor as an explicit
-- parameter, because the edge api_key path calls from a service-role client
-- with no session JWT of its own. 00022's header comment names that
-- distinction explicitly. This migration extends the same treatment to the
-- org-management RPCs the REST surface actually exposes.
--
-- ── THE SECURITY INVARIANT ───────────────────────────────────────────────
-- `p_actor_user_id` is NOT a "who am I" parameter. It is a privileged
-- override that only a service-role connection can exercise:
--
--     lorekit_org_actor(p_actor_user_id) =
--       auth.role() = 'service_role'  ->  coalesce(p_actor_user_id, auth.uid())
--       otherwise                     ->  auth.uid()
--
-- 1. AN `authenticated` CALLER'S `p_actor_user_id` IS IGNORED, ENTIRELY.
--    If you are `authenticated`, the parameter never reaches the result: the
--    `else` branch returns `auth.uid()` and nothing else. A dashboard user
--    (or anyone who obtains an anon-key + user JWT and calls PostgREST
--    directly) can pass any UUID they like — their own, an owner's, a
--    stranger's — and still acts as themselves. There is no combination of
--    request input that changes this, because the discriminator is not
--    request input.
--
-- 2. THE DISCRIMINATOR IS A VERIFIED JWT CLAIM, NOT A REQUEST FIELD.
--    `auth.role()` reads the `role` claim out of `request.jwt.claims`, which
--    PostgREST sets from the JWT it has already cryptographically VERIFIED
--    against the project's JWT secret. A client cannot set it: it is not a
--    header, a query parameter, or a body field, and forging it requires the
--    signing secret. This is the SAME predicate `rls_insert` (00001) has
--    relied on since the first migration to grant service-role a bypass, and
--    the same one `lorekit_memory_scopes` (00039) uses for its CI escape
--    hatch. It is not a new trust assumption — it is the existing one.
--
-- 3. WHO ACTUALLY HOLDS SERVICE-ROLE. Only `SUPABASE_SERVICE_ROLE_KEY`
--    produces that claim, and it lives exclusively in server-side secrets
--    (the edge functions, CI). The edge function does not take the actor
--    from the request either: it resolves it from the `api_tokens` row it
--    just authenticated by token hash (`resolveRestAuth` ->
--    `auth.userId` -> `actorUserId(auth)`). So the chain is
--    "presented token -> hashed -> matched row -> that row's owner", never
--    "caller said so". A client with a `lk_*` token can only ever act as the
--    user that token belongs to.
--
-- 4. IT FAILS CLOSED. When the actor resolves to NULL (service-role with no
--    override and no `sub` claim), every capability check becomes
--    `lorekit_org_can(null, ...)`, whose `lorekit_org_role(null, ...)` is
--    NULL, whose `if v_role is null then return false` denies everything.
--    The one RPC with no capability check — `lorekit_org_create`, the
--    owner-bootstrap path — therefore gains an EXPLICIT null-actor guard
--    below; without it a service-role call with no actor would insert an org
--    with a NULL `created_by` (and then fail confusingly on the NOT NULL
--    `org_members.user_id`).
--
-- 5. IT IS BACKWARD COMPATIBLE. The new parameter is TRAILING and DEFAULTS
--    to NULL, and PostgREST resolves overloads by named arguments, so every
--    existing caller that omits it — all of `packages/web/src/lib/orgs.ts`,
--    `org-invites.ts`, `org-members.ts`, and the MCP `org.*` tools in
--    `supabase/functions/mcp/tools.ts` — keeps working unchanged and keeps
--    resolving its actor from `auth.uid()`.
--
-- ── Deliberately NOT changed: accept / decline / leave ───────────────────
-- `lorekit_org_invite_accept`, `lorekit_org_invite_decline` and
-- `lorekit_org_leave` keep their pure `auth.uid()` actor and gain no
-- override. They are not REST routes, so nothing needs it yet, and for
-- accept/decline it would be actively unsafe to bolt on: they do not merely
-- resolve an actor, they MATCH the invite's `invitee_email` /
-- `invitee_handle` against the caller's VERIFIED JWT identity claims
-- (`email`, `user_metadata.user_name`) via `lorekit_invite_addressed_to_caller`
-- (00022). A service-role connection carries no such claims, so an override
-- would have to also invent an identity to match against — i.e. re-derive
-- the anti-TOCTOU check that is the whole point of that RPC. Giving
-- service-role an identity source it can trust is a separate change with its
-- own threat model. `lorekit_org_leave` is left alone for consistency with
-- them and because `DELETE /orgs/:slug/members/:userId`'s self-removal branch
-- is the only caller; under an api_key token that branch now fails closed
-- with LK002 ("you are not a member of this org") rather than silently
-- removing the wrong row. Documented as a known gap, not an accident.
-- ═════════════════════════════════════════════════════════════════════════

-- ── 0. The actor resolver ────────────────────────────────────────────────
-- SECURITY DEFINER + STABLE, mirroring the shape of every other resolver in
-- this schema (`lorekit_org_role`, `lorekit_member_org_ids`). `stable` is
-- correct: it reads only session settings, which do not change within a
-- statement.
create or replace function lorekit_org_actor(p_actor_user_id uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select case
    when auth.role() = 'service_role' then coalesce(p_actor_user_id, auth.uid())
    else auth.uid()
  end;
$$;

-- No `anon` grant. The function returns only the caller's own resolved
-- identity (or NULL), so it leaks nothing, but there is no reason for an
-- unauthenticated role to call it — same posture as `lorekit_member_org_ids`.
--
-- THE `revoke ... from public` IS LOAD-BEARING, not belt-and-braces. Postgres
-- grants EXECUTE on a newly created function to PUBLIC by default, and `anon`
-- inherits it. Naming only `authenticated, service_role` in a GRANT therefore
-- does NOT withhold it from `anon` — it just adds two roles that already had
-- access. Every `revoke` below pairs with its `grant` for that reason.
--
-- This is not hypothetical: the assertion in `supabase/tests/migrations.test.sql`
-- ("lorekit_org_members_list must not be granted to anon") FAILED the first
-- time it ran against this migration, because 00024 created that function with
-- a grant and no revoke. It returns other members' GitHub handles and avatars.
--
-- Known remaining gap, deliberately out of scope here: the same pattern applies
-- to functions this migration does not define — `lorekit_member_org_ids`
-- (00014), `lorekit_memory_count` (00035/00036), `lorekit_memory_scopes`
-- (00039) and `lorekit_invite_org_details` (00028) are all still reachable by
-- `anon` through PUBLIC. Closing those wants one sweep across the whole schema,
-- not a half-fix smuggled into an org-actor migration.
revoke execute on function lorekit_org_actor(uuid) from public;
grant execute on function lorekit_org_actor(uuid) to authenticated, service_role;

comment on function lorekit_org_actor(uuid) is
  'Resolves the acting user for an org RPC. Returns auth.uid() for every caller '
  'except a verified service_role JWT, which may name an actor explicitly. An '
  'authenticated caller''s p_actor_user_id is always ignored.';

-- ── 1. Org lifecycle ─────────────────────────────────────────────────────

-- Bodies below are copied VERBATIM from the migration that last defined each
-- function — 00022 for create/rename/invite/invite_revoke/member_remove/
-- member_role, 00025 for delete (the soft-delete rewrite), 00024 for
-- members_list — with exactly one class of change: `auth.uid()` becomes
-- `v_actor`, resolved once at the top from `lorekit_org_actor(...)`. Starting
-- from 00022 for `delete`/`members_list` would silently revert the
-- soft-delete and the identity-resolving member list.
--
-- Each function is DROPPED first rather than `create or replace`d: adding a
-- parameter creates a new OVERLOAD instead of replacing, and two overloads
-- that differ only by a defaulted trailing argument make a named-argument
-- PostgREST call ambiguous. Dropping also drops the grants, so every one is
-- re-issued below, identical to the original.

drop function if exists lorekit_org_create(text, text);

-- Creates the org AND the creator's owner membership atomically. No
-- capability check: this is the owner-bootstrap path — anyone authenticated
-- may create an org and becomes its sole owner. A duplicate slug surfaces
-- the orgs.slug unique_violation naturally.
--
-- Unlike every sibling below, this RPC has no `lorekit_org_can` gate to fail
-- closed on a NULL actor, so it needs its OWN explicit guard (invariant 4 in
-- the header). LK002 is reused deliberately: `translateDbError` already maps
-- it to a 403, which is the honest answer to "service-role called this with
-- nobody to own the result".
create or replace function lorekit_org_create(
  p_slug text,
  p_name text,
  p_actor_user_id uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor  uuid := lorekit_org_actor(p_actor_user_id);
  v_org_id uuid := gen_random_uuid();
begin
  if v_actor is null then
    raise exception using errcode = 'LK002', message = 'org_actor_unresolved: lorekit_org_create requires an actor (an authenticated session, or an explicit p_actor_user_id from service_role)';
  end if;

  insert into orgs (id, slug, name, created_by)
  values (v_org_id, p_slug, p_name, v_actor);

  insert into org_members (org_id, user_id, role)
  values (v_org_id, v_actor, 'owner');

  return v_org_id;
end;
$$;

revoke execute on function lorekit_org_create(text, text, uuid) from public;
grant execute on function lorekit_org_create(text, text, uuid) to authenticated, service_role;

drop function if exists lorekit_org_rename(uuid, text);

create or replace function lorekit_org_rename(
  p_org_id uuid,
  p_name text,
  p_actor_user_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := lorekit_org_actor(p_actor_user_id);
begin
  if not lorekit_org_can(v_actor, p_org_id, 'rename_org') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=rename_org', p_org_id);
  end if;

  update orgs set name = p_name where id = p_org_id;
end;
$$;

revoke execute on function lorekit_org_rename(uuid, text, uuid) from public;
grant execute on function lorekit_org_rename(uuid, text, uuid) to authenticated, service_role;

drop function if exists lorekit_org_delete(uuid);

-- Body from 00025 (the SOFT delete), not 00022 (which really deleted the
-- row). Owner-only. Idempotent: a second call on an already-soft-deleted org
-- is a no-op via the `deleted_at is null` guard.
create or replace function lorekit_org_delete(
  p_org_id uuid,
  p_actor_user_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := lorekit_org_actor(p_actor_user_id);
begin
  if not lorekit_org_can(v_actor, p_org_id, 'delete_org') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=delete_org', p_org_id);
  end if;

  update orgs set deleted_at = now() where id = p_org_id and deleted_at is null;
end;
$$;

revoke execute on function lorekit_org_delete(uuid, uuid) from public;
grant execute on function lorekit_org_delete(uuid, uuid) to authenticated, service_role;

-- ── 2. Invite lifecycle ──────────────────────────────────────────────────
-- `lorekit_invite_addressed_to_caller` is untouched, as are
-- `lorekit_org_invite_accept` / `_decline` (see the header).

drop function if exists lorekit_org_invite(uuid, text, text, text);

-- Owner/admin only. The org_invites.role CHECK (00021) independently rejects
-- an attempt to invite an 'owner' — this RPC does not re-derive that guard.
create or replace function lorekit_org_invite(
  p_org_id uuid,
  p_invitee_email text default null,
  p_invitee_handle text default null,
  p_role text default 'member',
  p_actor_user_id uuid default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := lorekit_org_actor(p_actor_user_id);
  v_invite_id uuid;
begin
  if not lorekit_org_can(v_actor, p_org_id, 'invite') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=invite', p_org_id);
  end if;

  insert into org_invites (org_id, invitee_email, invitee_handle, role, invited_by)
  values (
    p_org_id,
    case when p_invitee_email is not null then lower(p_invitee_email) end,
    case when p_invitee_handle is not null then lower(p_invitee_handle) end,
    p_role,
    v_actor
  )
  returning id into v_invite_id;

  return v_invite_id;
end;
$$;

revoke execute on function lorekit_org_invite(uuid, text, text, text, uuid) from public;
grant execute on function lorekit_org_invite(uuid, text, text, text, uuid) to authenticated, service_role;

drop function if exists lorekit_org_invite_revoke(uuid);

create or replace function lorekit_org_invite_revoke(
  p_invite_id uuid,
  p_actor_user_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := lorekit_org_actor(p_actor_user_id);
  inv org_invites;
begin
  select * into inv from org_invites where id = p_invite_id;
  if inv.id is null then
    raise exception using errcode = 'LK002', message = 'invite not found';
  end if;

  if not lorekit_org_can(v_actor, inv.org_id, 'revoke_invite') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=revoke_invite', inv.org_id);
  end if;

  -- Only a still-pending invite can be revoked — guards the silent
  -- re-revoke and the revoke-of-already-accepted cases (accepted invites are
  -- undone via member removal, not revoke).
  if inv.status <> 'pending' then
    raise exception using errcode = 'LK002', message = 'invite is not pending';
  end if;

  update org_invites set status = 'revoked', responded_at = now() where id = p_invite_id;
end;
$$;

revoke execute on function lorekit_org_invite_revoke(uuid, uuid) from public;
grant execute on function lorekit_org_invite_revoke(uuid, uuid) to authenticated, service_role;

-- ── 3. Member management ─────────────────────────────────────────────────

drop function if exists lorekit_org_member_remove(uuid, uuid);

-- Owner/admin only, plus two invariants a static role matrix cannot express:
--   - an admin actor may only act on member/viewer targets (never owner/admin)
--   - the last remaining owner can never be removed
create or replace function lorekit_org_member_remove(
  p_org_id uuid,
  p_target_user_id uuid,
  p_actor_user_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor       uuid := lorekit_org_actor(p_actor_user_id);
  v_actor_role  text;
  v_target_role text;
  v_owner_count int;
begin
  if not lorekit_org_can(v_actor, p_org_id, 'remove_member') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=remove_member', p_org_id);
  end if;

  v_actor_role  := lorekit_org_role(v_actor, p_org_id);
  v_target_role := lorekit_org_role(p_target_user_id, p_org_id);

  if v_target_role is null then
    raise exception using errcode = 'LK002', message = 'target is not a member of this org';
  end if;

  if v_actor_role = 'admin' and v_target_role in ('owner', 'admin') then
    raise exception using errcode = 'LK002', message = 'an admin cannot remove an owner or another admin';
  end if;

  if v_target_role = 'owner' then
    select count(*) into v_owner_count from org_members where org_id = p_org_id and role = 'owner';
    if v_owner_count <= 1 then
      raise exception using errcode = 'LK002', message = 'the last owner cannot be removed — transfer or delete the org first';
    end if;
  end if;

  delete from org_members where org_id = p_org_id and user_id = p_target_user_id;
end;
$$;

revoke execute on function lorekit_org_member_remove(uuid, uuid, uuid) from public;
grant execute on function lorekit_org_member_remove(uuid, uuid, uuid) to authenticated, service_role;

drop function if exists lorekit_org_member_role(uuid, uuid, text);

-- Owner/admin only. Cannot assign 'owner' (ownership is non-transferable in
-- v1); cannot demote the last owner; an admin actor may only act on
-- member/viewer targets, mirroring lorekit_org_member_remove's invariant.
create or replace function lorekit_org_member_role(
  p_org_id uuid,
  p_target_user_id uuid,
  p_role text,
  p_actor_user_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor       uuid := lorekit_org_actor(p_actor_user_id);
  v_actor_role  text;
  v_target_role text;
  v_owner_count int;
begin
  if p_role = 'owner' then
    raise exception using errcode = 'LK002', message = 'cannot assign owner via changeMemberRole — ownership is not transferable in v1';
  end if;

  if not lorekit_org_can(v_actor, p_org_id, 'change_role') then
    raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s capability=change_role', p_org_id);
  end if;

  v_actor_role  := lorekit_org_role(v_actor, p_org_id);
  v_target_role := lorekit_org_role(p_target_user_id, p_org_id);

  if v_target_role is null then
    raise exception using errcode = 'LK002', message = 'target is not a member of this org';
  end if;

  if v_actor_role = 'admin' and v_target_role in ('owner', 'admin') then
    raise exception using errcode = 'LK002', message = 'an admin cannot change the role of an owner or another admin';
  end if;

  if v_target_role = 'owner' then
    select count(*) into v_owner_count from org_members where org_id = p_org_id and role = 'owner';
    if v_owner_count <= 1 then
      raise exception using errcode = 'LK002', message = 'the last owner cannot be demoted — transfer or delete the org first';
    end if;
  end if;

  update org_members set role = p_role where org_id = p_org_id and user_id = p_target_user_id;
end;
$$;

revoke execute on function lorekit_org_member_role(uuid, uuid, text, uuid) from public;
grant execute on function lorekit_org_member_role(uuid, uuid, text, uuid) to authenticated, service_role;

-- ── 4. Member identity listing (read) ────────────────────────────────────

drop function if exists lorekit_org_members_list(uuid);

-- Body from 00024. Membership-gated PII read: a caller may resolve the
-- handle/avatar of anyone who shares an org WITH them, and only for that org.
-- A non-member (or a non-existent org — `lorekit_org_role` is NULL either
-- way) gets an EMPTY set, never an error, so existence is never leaked. A
-- service-role call with no actor therefore also gets an empty set: this
-- read fails closed exactly like the write RPCs, without a special case.
create or replace function lorekit_org_members_list(
  p_org_id uuid,
  p_actor_user_id uuid default null
)
returns table (
  user_id    uuid,
  handle     text,
  avatar_url text,
  role       text,
  joined_at  timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_actor uuid := lorekit_org_actor(p_actor_user_id);
begin
  if lorekit_org_role(v_actor, p_org_id) is null then
    return;
  end if;

  return query
    select
      m.user_id,
      coalesce(
        u.raw_user_meta_data ->> 'user_name',
        u.raw_user_meta_data ->> 'preferred_username'
      ) as handle,
      u.raw_user_meta_data ->> 'avatar_url' as avatar_url,
      m.role,
      m.created_at as joined_at
    from org_members m
    join auth.users u on u.id = m.user_id
    where m.org_id = p_org_id
    order by m.created_at asc;
end;
$$;

-- No `anon` grant (unlike lorekit_member_org_ids/lorekit_org_role, which
-- return only booleans/ids): this function returns PII (handle, avatar_url)
-- for other users, so it is authenticated-only, defense in depth beyond the
-- membership gate above.
revoke execute on function lorekit_org_members_list(uuid, uuid) from public;
grant execute on function lorekit_org_members_list(uuid, uuid) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00041', 'org_actor_override')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00042_audit_log_github_app_action.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- GitHub App installation linking: extend the audit_log `action` CHECK with
-- `github_app.installation_linked` so `handleSetupReturn`
-- (packages/web/src/lib/github-installations.ts) can record the link.
--
-- WHY: that call site has been auditing `github_app.installation_linked` since
-- the GitHub App shipped, but the CHECK — last set by
-- 00027_audit_log_scope_actions.sql over 23 actions — never admitted it. The
-- insert therefore failed the constraint on EVERY App link, and because
-- `recordAuditEvent` is deliberately non-throwing (a failed audit must never
-- break the operation it audits) the failure was swallowed and logged to the
-- server console only. The result was a silent, permanent hole in the audit
-- trail: no user ever saw an error, and no `github_app.installation_linked`
-- row was ever written. Widening the CHECK is the whole fix.
--
-- The action list below is now derived from ONE source —
-- packages/schemas/src/audit.ts's `AUDIT_ACTIONS` — and
-- packages/mcp-core/src/audit-vocabulary.spec.ts parses the newest
-- `audit_log` action-CHECK migration (this file) and fails if the two sets
-- differ. A future action must be added in both places, in one commit.
--
-- Forward-only: drop + re-add the CHECK (a constraint can't be widened in
-- place) — the same pattern as 00023_audit_log_org_actions.sql and
-- 00027_audit_log_scope_actions.sql.

alter table audit_log drop constraint audit_log_action_check;

alter table audit_log add constraint audit_log_action_check check (action in (
  'api_key.create',
  'api_key.revoke',
  'webhook_secret.create',
  'webhook_secret.rotate',
  'webhook_secret.deactivate',
  'memory.create',
  'memory.update',
  'memory.archive',
  'memory.restore',
  'memory.delete',
  'limit.override',
  'org.create',
  'org.rename',
  'org.delete',
  'member.invite',
  'member.accept',
  'member.decline',
  'member.revoke',
  'member.remove',
  'member.role_change',
  'member.leave',
  'scope.bind',
  'scope.unbind',
  'github_app.installation_linked'
));
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00042', 'audit_log_github_app_action')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00043_usage_stats.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- lorekit_usage_stats(p_user_id, p_since, p_until) — aggregate usage counts a
-- caller can read back about THEIR OWN activity, for GET /memories/usage.
--
-- usage_events (00034) already captures one row per MCP tool call and one per
-- REST route (tool_name, outcome, scope_type, auth_type, duration_ms, …). What
-- was missing was any way to READ those rows back as aggregates: the table had
-- an RLS select policy but no endpoint, RPC, tool or CLI consumed it. This is
-- that read side — "how many reads/writes today, per scope, per outcome" so a
-- human or agent can judge whether LoreKit is helping.
--
-- Aggregate in Postgres, not with a select + client-side reduce, for the same
-- reason as lorekit_memory_scopes (00039): a client-side rollup is silently
-- truncated past PostgREST's row cap, dropping whole buckets with no error. One
-- grouped row per (tool_name, outcome, scope_type) is exact at any volume, and
-- the group cardinality is bounded (tool_name × outcome × scope_type are all
-- bounded categoricals).
--
-- Visibility is self-only, matching the usage_events RLS select policy
-- (user_id = auth.uid()): a caller sees only their own events. The
-- `p_user_id is null and auth.role() = 'service_role'` branch is the CI /
-- service-role escape hatch, exactly as lorekit_memory_scopes uses it and safe
-- for the same reason — auth.role() reads the VERIFIED JWT role claim PostgREST
-- sets, never request input, so an `authenticated` caller passing p_user_id =>
-- null gets nothing back (user_id = null is NULL) and the function fails closed.
--
-- The [p_since, p_until) window is half-open and both bounds are optional
-- (NULL = unbounded), so the caller controls the period: p_since = start-of-day
-- answers "today", p_since = now()-7d answers "this week", both NULL is
-- all-time. total_duration_ms is summed for latency-per-bucket analysis.
--
-- SECURITY DEFINER + STABLE (read-only, keyed on an explicit p_user_id rather
-- than a client-asserted claim) and plpgsql rather than SQL for the same
-- ordering reason as lorekit_memory_scopes: a plpgsql RETURN QUERY is never
-- inlined, so the ORDER BY is part of the contract, not an accident of the
-- planner.
create or replace function lorekit_usage_stats(
  p_user_id uuid,
  p_since   timestamptz default null,
  p_until   timestamptz default null
)
returns table (
  tool_name         text,
  outcome           text,
  scope_type        text,
  event_count       bigint,
  total_duration_ms bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
-- The RETURNS TABLE columns double as OUT variables; qualify every reference and
-- make the column win on any residual ambiguity.
#variable_conflict use_column
begin
  return query
    select
        e.tool_name,
        e.outcome,
        e.scope_type,
        count(*)                        as event_count,
        coalesce(sum(e.duration_ms), 0) as total_duration_ms
      from usage_events e
     where (
             (p_user_id is null and auth.role() = 'service_role')
             or e.user_id = p_user_id
           )
       and (p_since is null or e.created_at >= p_since)
       and (p_until is null or e.created_at <  p_until)
     group by e.tool_name, e.outcome, e.scope_type
     order by event_count desc, e.tool_name asc;
end;
$$;

-- NOT granted to `anon`, matching lorekit_memory_scopes / lorekit_member_org_ids:
-- the function takes a bare p_user_id, so an unauthenticated caller with EXECUTE
-- could read any user's usage aggregates. `authenticated` is safe because the
-- edge functions resolve p_user_id from the verified credential, never request
-- input; `service_role` is the CI escape hatch.
grant execute on function lorekit_usage_stats(uuid, timestamptz, timestamptz)
  to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00043', 'usage_stats')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00044_usage_event_dimensions.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Usage-event dimensions for G1 (real record counts) + G2 (per-PR/session
-- correlation), and the matching read-side extension of lorekit_usage_stats.
--
-- G1 — "read 600 MEMORIES today", not "600 read CALLS": usage_events counted one
-- row per tool call but never how many records that call returned. Add
-- result_count (nullable — only reads/expiry populate it) and sum it in the
-- stats RPC as record_count, distinct from the call count.
--
-- G2 — "5 memories during THIS PR": add a nullable, bounded correlation_id the
-- write paths fill from a client-supplied X-LoreKit-Correlation-Id header, and
-- let lorekit_usage_stats filter by it.
--
-- Forward-only and additive: both columns are nullable so every existing row and
-- every caller that omits them is unaffected; the two RPCs are DROPped and
-- recreated with trailing DEFAULT params so PostgREST's named-argument
-- resolution keeps every current caller working.

-- ── G1/G2 columns ───────────────────────────────────────────────────────────
alter table usage_events add column if not exists result_count integer;
alter table usage_events add column if not exists correlation_id text;

-- Bound the correlation id (cardinality + storage). char_length, not octet, is
-- fine for the printable-ASCII set the app validator (parseCorrelationId)
-- enforces; the DB check is the backstop, not the primary gate.
alter table usage_events drop constraint if exists usage_events_correlation_id_len;
alter table usage_events add constraint usage_events_correlation_id_len
  check (correlation_id is null or char_length(correlation_id) <= 200);

-- Index the grouped/filtered read: "my events for correlation X, newest first".
create index if not exists usage_events_user_correlation_idx
  on usage_events (user_id, correlation_id, created_at desc)
  where correlation_id is not null;

-- ── writer: add p_result_count + p_correlation_id ───────────────────────────
-- DROP first (not CREATE OR REPLACE): adding params changes the signature, and a
-- bare CREATE would leave the old overload behind and make calls ambiguous.
drop function if exists lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer);

create or replace function lorekit_record_usage_event(
  p_user_id        uuid    default null,
  p_org_id         uuid    default null,
  p_plan_name      text    default null,
  p_tool_name      text    default null,
  p_scope_type     text    default null,
  p_auth_type      text    default null,
  p_outcome        text    default null,
  p_duration_ms    integer default null,
  p_memory_count   integer default null,
  p_result_count   integer default null,
  p_correlation_id text    default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into usage_events (
    user_id, org_id, plan_name,
    tool_name, scope_type, auth_type,
    outcome, duration_ms, memory_count,
    result_count, correlation_id
  ) values (
    p_user_id, p_org_id, p_plan_name,
    p_tool_name, p_scope_type, p_auth_type,
    p_outcome, p_duration_ms, p_memory_count,
    p_result_count, p_correlation_id
  )
  returning id into v_id;
  return v_id;
exception
  when others then
    -- Never let telemetry writes break the primary operation.
    return null;
end;
$$;

grant execute on function lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text)
  to anon, authenticated, service_role;

-- ── reader: record_count column + correlation filter ────────────────────────
-- DROP the 00043 3-arg version and recreate with a trailing p_correlation_id and
-- an added record_count in the returned rows. Everything else — self-only
-- visibility, the service-role escape hatch, the plpgsql-not-SQL ordering
-- rationale, the grant surface — is unchanged from 00043.
drop function if exists lorekit_usage_stats(uuid, timestamptz, timestamptz);

create or replace function lorekit_usage_stats(
  p_user_id        uuid,
  p_since          timestamptz default null,
  p_until          timestamptz default null,
  p_correlation_id text        default null
)
returns table (
  tool_name         text,
  outcome           text,
  scope_type        text,
  event_count       bigint,
  record_count      bigint,
  total_duration_ms bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
begin
  return query
    select
        e.tool_name,
        e.outcome,
        e.scope_type,
        count(*)                          as event_count,
        coalesce(sum(e.result_count), 0)  as record_count,
        coalesce(sum(e.duration_ms), 0)   as total_duration_ms
      from usage_events e
     where (
             (p_user_id is null and auth.role() = 'service_role')
             or e.user_id = p_user_id
           )
       and (p_since is null or e.created_at >= p_since)
       and (p_until is null or e.created_at <  p_until)
       and (p_correlation_id is null or e.correlation_id = p_correlation_id)
     group by e.tool_name, e.outcome, e.scope_type
     order by event_count desc, e.tool_name asc;
end;
$$;

-- The `revoke ... from public` is LOAD-BEARING, not belt-and-braces — the same
-- reason 00041 pairs one with every grant. Postgres grants EXECUTE on a newly
-- created function to PUBLIC by default and `anon` inherits it, so naming only
-- `authenticated, service_role` in the GRANT does NOT withhold it from `anon`.
-- This function takes a bare p_user_id, so an `anon` caller with EXECUTE could
-- read ANY user's usage aggregates.
revoke execute on function lorekit_usage_stats(uuid, timestamptz, timestamptz, text) from public;
grant execute on function lorekit_usage_stats(uuid, timestamptz, timestamptz, text)
  to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00044', 'usage_event_dimensions')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00045_memory_expiry_events.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- G3 — make expiry OBSERVABLE ("6 lessons got expired").
--
-- Expiry was invisible to analytics: TTL'd rows are filtered out of reads
-- (expires_at in the past) but no event marks the moment, and
-- purge_expired_memories deleted them while returning only a count the caller
-- usually discarded. There is no other discrete "expired" moment to hook — a
-- lazy read never deletes, it just excludes — so the purge is the right and
-- only pattern-fitting seam: capture the count it already computes as a usage
-- event instead of throwing it away.
--
-- purge_expired_memories now records ONE usage_events row per run that deleted
-- anything, tool_name 'memory.expired', result_count = rows expired. GET
-- /memories/usage then surfaces `expired` = sum(record_count) over that bucket.
-- The signature and return value are unchanged, so every existing caller (the
-- memory.purge_expired MCP tool, POST /memories/purge-expired) is unaffected —
-- and both of those still record their own 'memory.purge_expired' CALL event, so
-- the call and its effect stay distinct.
--
-- Forward-only: CREATE OR REPLACE, same signature as 00030.

create or replace function purge_expired_memories(
  p_user_id uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
begin
  delete from memories
   where user_id     = p_user_id
     and expires_at  is not null
     and expires_at  < now()
     and archived_at is null   -- archived rows stay with purge_archived_memories
  ;
  get diagnostics v_count = row_count;

  -- Emit an expiry event so the count is tallyable per period/scope. Only when
  -- something actually expired — an empty purge is not an expiry event.
  -- lorekit_record_usage_event swallows its own errors, so this can never break
  -- the purge; auth_type 'service' marks it as a system-generated effect (it is
  -- not a caller read/write). Depends on 00044's added p_result_count param.
  if v_count > 0 then
    perform lorekit_record_usage_event(
      p_user_id      => p_user_id,
      p_tool_name    => 'memory.expired',
      p_scope_type   => null,
      p_auth_type    => 'service',
      p_outcome      => 'ok',
      p_result_count => v_count
    );
  end if;

  return v_count;
end;
$$;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00045', 'memory_expiry_events')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00046_memory_rpc_actor_guard.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Memory RPC actor guard — close a caller-supplied-user-id access-control gap.
--
-- ── The problem ──────────────────────────────────────────────────────────
-- Four SECURITY DEFINER RPCs act on a caller-supplied `p_user_id` with no
-- comparison against the authenticated caller:
--
--   archive_memory(p_user_id, scope, key)            — 00003
--   restore_memory(p_user_id, scope, key)            — 00003
--   purge_archived_memories(p_user_id, retention)    — 00003  (hard DELETE)
--   purge_expired_memories(p_user_id)                — 00030  (hard DELETE)
--
-- SECURITY DEFINER runs the body as the table owner, and no migration sets
-- FORCE ROW LEVEL SECURITY on `memories`, so the owner BYPASSES the `rls_read`
-- update/select policies entirely. The row that is touched is chosen solely by
-- the `where user_id = p_user_id` predicate — a value the caller supplies.
-- The 00003 comment ("Uses SECURITY DEFINER so the RLS update policy
-- (user_id = auth.uid()) still applies") has the mechanism backwards: DEFINER
-- is precisely the construct that stops that policy applying.
--
-- Worse, three of the four keep PostgreSQL's default `EXECUTE` grant to
-- PUBLIC (00003 never revoked it; only the org RPCs got that treatment in
-- 00041). purge_expired_memories added a grant to `authenticated` but never
-- revoked PUBLIC either, so its "intentionally excludes anon" comment did not
-- hold. Supabase exposes public-schema functions over PostgREST, so as
-- deployed any caller could:
--
--   POST /rest/v1/rpc/purge_archived_memories
--        { "p_user_id": "<victim-uuid>", "p_retention_days": 0 }
--
-- and hard-delete another user's archived rows — a textbook broken-access-
-- control (OWASP A01) IDOR. The application layer is careful everywhere
-- (the dashboard resolves user.id from the session; the MCP purge tool
-- refuses without a resolved user id) so the product path is sound; the gap
-- is at the grant boundary, which the app layer cannot close.
--
-- ── The fix, and why it is the precedent already in this repo ────────────
-- 00041_org_actor_override.sql solved the identical problem for the org
-- RPCs: resolve the actor so that a caller-supplied id is honoured ONLY on a
-- verified service-role connection and is otherwise ignored in favour of
-- `auth.uid()`. This migration applies the same rule to the four memory RPCs.
--
--     effective actor =
--       auth.role() = 'service_role'  ->  coalesce(p_user_id, auth.uid())
--       otherwise                     ->  auth.uid()
--
-- ── THE SECURITY INVARIANT (identical to lorekit_org_actor) ──────────────
-- 1. AN `authenticated` CALLER'S `p_user_id` IS IGNORED, ENTIRELY. The `else`
--    branch returns `auth.uid()` and nothing else, so a dashboard user (or
--    anyone with an anon-key + user JWT hitting PostgREST directly) can name
--    any UUID and still only ever acts on their OWN rows. No request input
--    changes this, because the discriminator is not request input.
-- 2. THE DISCRIMINATOR IS A VERIFIED JWT CLAIM, NOT A REQUEST FIELD.
--    `auth.role()` reads the `role` claim PostgREST sets from the JWT it has
--    already cryptographically verified. Forging it requires the signing
--    secret. This is the same predicate `rls_insert` (00001) and
--    `lorekit_org_actor` (00041) already rely on.
-- 3. WHO HOLDS SERVICE-ROLE: only `SUPABASE_SERVICE_ROLE_KEY`, held in
--    server-side secrets (edge functions, CI). The edge/MCP path does not take
--    the actor from the request body — it resolves it from the `api_tokens`
--    row it authenticated by hash — so the chain is "presented token ->
--    hashed -> matched row -> that row's owner", never "caller said so".
-- 4. IT FAILS CLOSED. When the actor resolves to NULL (service-role, no
--    override, no `sub`), `where user_id = NULL` matches no row, so the
--    UPDATE/DELETE touches nothing.
-- 5. IT IS BEHAVIOUR-PRESERVING FOR LEGITIMATE CALLERS. The signatures are
--    unchanged (plain `create or replace`, no new overload). The dashboard
--    already passes user.id == auth.uid(), so resolving to auth.uid() is a
--    no-op for it; the edge/MCP service-role path already passes the resolved
--    token owner, which the service-role branch honours via coalesce.
-- ═════════════════════════════════════════════════════════════════════════

-- 1. archive_memory — soft-archive the CALLER's own row.
create or replace function archive_memory(
  p_user_id  uuid,
  p_scope    text,
  p_key      text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id    uuid;
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  update memories
     set archived_at = now()
   where user_id = v_actor
     and scope    = p_scope
     and key      = p_key
     and archived_at is null
  returning id into v_id;

  return v_id; -- null if row not found or already archived
end;
$$;

-- 2. restore_memory — clear archived_at on the CALLER's own row.
create or replace function restore_memory(
  p_user_id  uuid,
  p_scope    text,
  p_key      text
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id    uuid;
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  update memories
     set archived_at = null
   where user_id = v_actor
     and scope    = p_scope
     and key      = p_key
     and archived_at is not null
  returning id into v_id;

  return v_id;
end;
$$;

-- 3. purge_archived_memories — hard-delete the CALLER's own archived rows.
create or replace function purge_archived_memories(
  p_user_id        uuid,
  p_retention_days integer default 30
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  delete from memories
   where user_id     = v_actor
     and archived_at is not null
     and archived_at < now() - (p_retention_days * interval '1 day')
  ;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- 4. purge_expired_memories — hard-delete the CALLER's own expired rows.
create or replace function purge_expired_memories(
  p_user_id uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer;
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  delete from memories
   where user_id     = v_actor
     and expires_at  is not null
     and expires_at  < now()
     and archived_at is null   -- archived rows stay with purge_archived_memories
  ;
  get diagnostics v_count = row_count;

  -- Preserve 00045's expiry-event recording (this migration is applied AFTER
  -- 00045, so its create-or-replace would otherwise silently drop it). Record
  -- for the RESOLVED actor, and only when something actually expired.
  -- lorekit_record_usage_event swallows its own errors, so it can never break
  -- the purge.
  if v_count > 0 then
    perform lorekit_record_usage_event(
      p_user_id      => v_actor,
      p_tool_name    => 'memory.expired',
      p_scope_type   => null,
      p_auth_type    => 'service',
      p_outcome      => 'ok',
      p_result_count => v_count
    );
  end if;

  return v_count;
end;
$$;

-- ── Grants ───────────────────────────────────────────────────────────────
-- `create or replace` preserves the pre-existing grants, so revoke the
-- default PUBLIC EXECUTE explicitly (00003 never did) and re-issue least-
-- privilege grants, matching the posture 00041 established for the org RPCs.
-- Now that the actor guard makes a caller-supplied id inert for anyone but a
-- service-role connection, these are safe to keep on `authenticated`.
revoke execute on function archive_memory(uuid, text, text)             from public;
revoke execute on function restore_memory(uuid, text, text)             from public;
revoke execute on function purge_archived_memories(uuid, integer)       from public;
revoke execute on function purge_expired_memories(uuid)                 from public;

grant execute on function archive_memory(uuid, text, text)             to authenticated, service_role;
grant execute on function restore_memory(uuid, text, text)             to authenticated, service_role;
grant execute on function purge_archived_memories(uuid, integer)       to authenticated, service_role;
grant execute on function purge_expired_memories(uuid)                 to authenticated, service_role;

-- Correct the record on all four functions. 00003's file comment above
-- archive_memory claimed "Uses SECURITY DEFINER so the RLS update policy
-- (user_id = auth.uid()) still applies" — backwards: DEFINER runs as the table
-- owner and, absent FORCE ROW LEVEL SECURITY, BYPASSES that policy. What
-- actually scopes each of these is the resolved actor below, not RLS. A
-- `comment on function` is the durable place to say so (a comment on a
-- superseded body in 00003 can't be edited forward-only).
comment on function archive_memory(uuid, text, text) is
  'Soft-archives the effective caller''s own row. SECURITY DEFINER BYPASSES the
   memories RLS policies (no FORCE ROW LEVEL SECURITY), so the row is scoped by
   the resolved actor, NOT by RLS — correcting 00003''s backwards note. The
   actor is resolved by the same service-role-gated rule as lorekit_org_actor
   (00041): a caller-supplied p_user_id is honoured only on a verified
   service-role connection, otherwise auth.uid() wins. Fails closed on NULL.';
comment on function restore_memory(uuid, text, text) is
  'Restores the effective caller''s own archived row. Same actor rule and same
   RLS-bypass caveat as archive_memory (see 00046 header; corrects 00003).';
comment on function purge_archived_memories(uuid, integer) is
  'Hard-deletes the effective caller''s archived rows past the retention window.
   The effective user id is resolved by the same service-role-gated rule as
   lorekit_org_actor (00041): a caller-supplied p_user_id is honoured only on a
   verified service-role connection and is otherwise ignored in favour of
   auth.uid(). SECURITY DEFINER bypasses RLS; the actor scopes the delete.
   Fails closed on a NULL actor.';
comment on function purge_expired_memories(uuid) is
  'Hard-deletes the effective caller''s expired (non-archived) rows. Same
   service-role-gated actor rule and RLS-bypass caveat as
   purge_archived_memories (see 00046 header).';

-- ═════════════════════════════════════════════════════════════════════════
-- 5. memory_delete — the omitted fifth RPC of this family.
--
-- 00020's memory_delete has the SAME caller-supplied-p_user_id flaw as the
-- four above, and it is the most dangerous: SECURITY DEFINER, granted to
-- `anon`, and it hard-DELETEs (p_force=true) or archives on a bare
-- `where user_id = p_user_id` with no auth.uid()/service-role gate. Over
-- PostgREST that is an anon-reachable, cross-tenant DESTRUCTIVE IDOR:
--   POST /rest/v1/rpc/memory_delete
--        { "p_user_id":"<victim>", "p_scope":"global", "p_key":"k", "p_force":true }
-- The org branch is exploitable too — it gates on
-- lorekit_org_can(p_user_id, ...) with the CALLER's p_user_id, so naming any
-- privileged member deletes that org's lore as a non-member. It was simply
-- omitted from this migration's original list; recreate it with the identical
-- actor guard, applied to BOTH the personal user_id filter AND the org
-- capability check, so the org path authorizes the REAL caller, never a named
-- member. Behaviour-preserving: the edge api_key path (service-role) still
-- names the token owner via coalesce; a JWT caller resolves to its own
-- auth.uid() (which the edge already passes as p_user_id).
create or replace function memory_delete(
  p_user_id  uuid,
  p_org_slug text default null,
  p_scope    text default null,
  p_key      text default null,
  p_force    boolean default false
)
returns table (deleted boolean, archived boolean)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_org_id uuid;
  v_count  integer;
  v_actor  uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug;
    if v_org_id is null then
      raise exception using
        errcode = 'P0001',
        message = format('unknown_org: %s', p_org_slug);
    end if;

    if p_force then
      if not lorekit_org_can(v_actor, v_org_id, 'hard_delete') then
        raise exception using
          errcode = 'LK002',
          message = format('org_permission_denied: org=%s capability=hard_delete', p_org_slug);
      end if;

      delete from memories
       where org_id = v_org_id and scope = p_scope and key = p_key;
      get diagnostics v_count = row_count;

      return query select (v_count > 0), false;
    else
      if not lorekit_org_can(v_actor, v_org_id, 'archive') then
        raise exception using
          errcode = 'LK002',
          message = format('org_permission_denied: org=%s capability=archive', p_org_slug);
      end if;

      update memories
         set archived_at = now()
       where org_id = v_org_id and scope = p_scope and key = p_key and archived_at is null;
      get diagnostics v_count = row_count;

      return query select false, (v_count > 0);
    end if;
  else
    -- Personal delete: scoped to the RESOLVED actor, never a named p_user_id.
    if p_force then
      delete from memories
       where user_id = v_actor and scope = p_scope and key = p_key;
      get diagnostics v_count = row_count;

      return query select (v_count > 0), false;
    else
      update memories
         set archived_at = now()
       where user_id = v_actor and scope = p_scope and key = p_key and archived_at is null;
      get diagnostics v_count = row_count;

      return query select false, (v_count > 0);
    end if;
  end if;
end;
$$;

-- 00020:92 granted memory_delete to `anon` EXPLICITLY (unlike the 00003/00030
-- RPCs, which only had the default PUBLIC grant). `revoke ... from public` does
-- NOT remove a per-role grant, so anon must be revoked by name too — otherwise
-- anon keeps EXECUTE (the actor guard makes the call inert, but least-privilege
-- means removing the grant, not just relying on the guard).
revoke execute on function memory_delete(uuid, text, text, text, boolean) from public, anon;
grant execute on function memory_delete(uuid, text, text, text, boolean) to authenticated, service_role;

comment on function memory_delete(uuid, text, text, text, boolean) is
  'Archives (p_force=false) or hard-deletes (p_force=true) the effective
   caller''s own memory, or an org''s memory when p_org_slug is given and the
   caller has the archive/hard_delete capability. The effective actor is
   resolved by the same service-role-gated rule as the rest of this family
   (00046) and lorekit_org_actor (00041): a caller-supplied p_user_id is
   honoured only on a verified service-role connection, otherwise auth.uid()
   wins — scoping BOTH the personal user_id filter and the org capability
   check to the real caller. SECURITY DEFINER bypasses RLS; the actor is the
   gate. Fails closed on a NULL actor.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00046', 'memory_rpc_actor_guard')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00047_readfn_grant_hardening.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Read-function grant hardening — the "clearly-safe" half of the deferred
-- security-review sweep (docs/tasks/security-review-deferred-findings.md).
--
-- Same root cause as 00046: PostgreSQL grants EXECUTE to PUBLIC by default, and
-- only 00041/00046 ever revoked it — so a set of SECURITY DEFINER functions
-- that take a bare `p_user_id` (or are service-role-only) stayed anon-reachable
-- over PostgREST, leaking other users' data or letting anon call service-only
-- procedures. This migration closes the CLEARLY-SAFE subset:
--
--   * lorekit_memory_scopes / lorekit_memory_count — edge-called reads that
--     trust p_user_id → get the 00046/00041 actor guard (honour p_user_id only
--     under a verified service-role connection, else auth.uid()) AND lose the
--     PUBLIC/anon grant, closing both the anon and the authenticated cross-user
--     read.
--   * lorekit_find_user_by_github_id + the three installation RPCs +
--     lorekit_purge_old_usage_events + lorekit_purge_all_expired_memories —
--     service-role / webhook / cron only → simply lose PUBLIC EXECUTE.
--
-- DELIBERATELY OUT OF SCOPE (left for a separate, carefully-tested pass):
-- functions embedded in RLS policies or the insert/rate-limit hot path
-- (lorekit_member_org_ids, lorekit_org_role/_can, lorekit_check_rate_limit,
-- lorekit_purge_rate_limit_counters, lorekit_get_limit/_org_limit/default_limit,
-- lorekit_record_usage_event) — a wrong grant/actor change there is a
-- production-availability incident. See the findings doc, "[rls/hot-path]".
-- ═════════════════════════════════════════════════════════════════════════

-- ── 1. lorekit_memory_scopes — actor guard (preserves the CI escape hatch) ──
create or replace function lorekit_memory_scopes(p_user_id uuid)
returns table (scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  -- Honour a caller-supplied p_user_id only on a verified service-role
  -- connection (the edge resolves the token owner and passes it); an
  -- authenticated caller is pinned to its own auth.uid(), closing the
  -- cross-user scope-name enumeration. A NULL actor under service-role is the
  -- CI escape hatch, preserved by the first visibility branch below.
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
    select m.scope, count(*) as count
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
     group by m.scope
     order by m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_scopes(uuid) from public, anon;
grant  execute on function lorekit_memory_scopes(uuid) to authenticated, service_role;

comment on function lorekit_memory_scopes(uuid) is
  'Per-scope active counts visible to the EFFECTIVE caller. Actor resolved by
   the 00046/00041 service-role-gated rule: a caller-supplied p_user_id is
   honoured only on a verified service-role connection, otherwise auth.uid()
   wins — so an authenticated caller can never enumerate another user''s scope
   names. p_user_id IS NULL under service-role is the CI escape hatch.';

-- ── 2. lorekit_memory_count — actor guard ───────────────────────────────────
create or replace function lorekit_memory_count(p_user_id uuid)
returns jsonb
language plpgsql
security definer
stable
set search_path = public
as $$
declare
  v_personal_count integer;
  v_org_count      integer;
  v_limit          integer;
  v_plan_name      text;
  v_org_ids        uuid[];
  v_actor          uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  -- Resolve org memberships once (for the resolved actor).
  select array_agg(org_id)
    into v_org_ids
    from org_members om
    join orgs o on o.id = om.org_id
   where om.user_id = v_actor
     and o.deleted_at is null;

  -- Personal active memories.
  select count(*)
    into v_personal_count
    from memories
   where user_id = v_actor
     and archived_at is null;

  -- Org-owned active memories across all orgs the actor belongs to.
  if v_org_ids is not null and cardinality(v_org_ids) > 0 then
    select count(*)
      into v_org_count
      from memories
     where org_id = any(v_org_ids)
       and archived_at is null;
  else
    v_org_count := 0;
  end if;

  -- Resolve effective personal limit and plan name.
  v_limit := lorekit_get_limit(v_actor, 'max_memories');

  select coalesce(up.plan_name, 'free')
    into v_plan_name
    from user_plans up
   where up.user_id = v_actor;

  if v_plan_name is null then
    v_plan_name := 'free';
  end if;

  return jsonb_build_object(
    'count',          coalesce(v_personal_count, 0) + coalesce(v_org_count, 0),
    'personal_count', coalesce(v_personal_count, 0),
    'org_count',      v_org_count,
    'limit',          v_limit,
    'plan',           v_plan_name
  );
end;
$$;

revoke execute on function lorekit_memory_count(uuid) from public, anon;
grant  execute on function lorekit_memory_count(uuid) to authenticated, service_role;

comment on function lorekit_memory_count(uuid) is
  'Personal + org memory counts, limit and plan for the EFFECTIVE caller. Same
   service-role-gated actor rule as lorekit_memory_scopes (00047) — an
   authenticated caller cannot read another user''s counts or plan tier.';

-- ── 3. Service-role / webhook / cron-only functions — drop PUBLIC EXECUTE ────
-- These take no p_user_id (or are procedures the app never calls as a normal
-- user), so no actor guard applies; they should simply not be anon-reachable.
-- They were granted `to service_role` only, but the default PUBLIC grant was
-- never revoked. `find_user_by_github_id` also loses authenticated (it maps a
-- GitHub id to an internal user UUID — a deanonymisation oracle).
revoke execute on function lorekit_find_user_by_github_id(text)                                   from public, anon, authenticated;
revoke execute on function lorekit_installation_upsert(bigint, bigint, text, text, uuid, text, text[]) from public, anon, authenticated;
revoke execute on function lorekit_installation_remove_repos(bigint, text[])                       from public, anon, authenticated;
revoke execute on function lorekit_installation_remove(bigint)                                     from public, anon, authenticated;
revoke execute on function lorekit_purge_old_usage_events(interval)                                from public, anon, authenticated;
revoke execute on function lorekit_purge_all_expired_memories()                                    from public, anon, authenticated;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00047', 'readfn_grant_hardening')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00048_memory_origin.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Memory origin (provenance): where a lesson was RECORDED FROM.
--
-- A memory's `scope` says WHERE the lesson applies. It does not say where the
-- lesson came from: a `global` lesson can be learned while reviewing a pull
-- request, and a `repo::`-scoped lesson says nothing about which branch,
-- commit, or PR taught it. The dashboard could therefore only ever render a
-- "Repo" row by string-splitting the scope — and never a branch, commit, or
-- pull-request link.
--
-- Four nullable, independently-optional columns close that gap:
--   origin_repo    owner/name of the repository the write happened in
--   origin_branch  the git branch the write happened on
--   origin_commit  the commit SHA that was checked out
--   origin_pr      the pull request number the work belonged to
--
-- Design notes:
--   * Separate typed columns, not a JSONB blob — each one is independently
--     queryable and CHECK-constrainable, and the shapes are known and stable.
--   * `origin_branch` is NOT lowercased (unlike a `branch::` scope, which is
--     canonically lowercased and therefore produces `/tree/` links that 404 on
--     a mixed-case branch). Stored verbatim so its GitHub link resolves.
--   * On UPSERT each field uses `coalesce(excluded.x, memories.x)`: the newest
--     write wins when it knows the value, and a write that does NOT know it
--     (an agent with no git context) never erases what a previous write did
--     know. "Last known origin", never a regression to unknown.
--   * The application layer validates and normalises all four before they get
--     here (packages/mcp-core/src/origin.ts, mirrored self-contained into
--     supabase/functions/_shared/provenance/origin.ts). The CHECK constraints below are
--     the backstop, deliberately looser than the app-layer regexes so a future
--     provider with a slightly different ref shape does not require a
--     migration to accept.
--   * No index: no read path filters on these columns today (they are rendered
--     from a row already fetched by `(scope, key)` or by the keyset list). Add
--     one with the feature that first filters on origin, not speculatively.
--
-- The RPC widening follows the established pattern (00009, 00030, 00031,
-- 00038): DROP the old overload FIRST — `create or replace` alone would leave
-- a stale N-arg overload and PostgREST, which resolves RPCs by ARGUMENT NAME,
-- would see an ambiguous call — then recreate with the new params appended
-- LAST and DEFAULTed, then re-issue the GRANTs against the new signature.
-- Forward-only.
-- ═════════════════════════════════════════════════════════════════════════

alter table memories add column if not exists origin_repo   text;
alter table memories add column if not exists origin_branch text;
alter table memories add column if not exists origin_commit text;
alter table memories add column if not exists origin_pr     integer;

alter table memories drop constraint if exists memories_origin_repo_check;
-- Shape-aware, not length-only. `../evil` is a well-formed "owner/name" to a
-- naive check, and the dashboard turns it into https://github.com/../evil,
-- which the browser resolves to https://github.com/evil — a link to a
-- repository the memory never came from. The regex admits exactly one
-- `owner/name` pair of [A-Za-z0-9._-] segments, and the second clause rejects
-- a segment made only of dots, so no relative path can be stored even by a
-- direct INSERT that bypasses the app-layer validator.
alter table memories add  constraint memories_origin_repo_check
  check (
    origin_repo is null
    or (
      length(origin_repo) between 3 and 140
      and origin_repo ~ '^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$'
      and origin_repo !~ '(^|/)\.+(/|$)'
    )
  );

alter table memories drop constraint if exists memories_origin_branch_check;
-- Branch names are near-freeform (git-check-ref-format is a deny list, and the
-- app layer applies it in full), so this backstop only guards the two
-- properties the render path depends on: a bounded length, and no relative
-- path segment that would retarget the /tree/ link.
alter table memories add  constraint memories_origin_branch_check
  check (
    origin_branch is null
    or (length(origin_branch) between 1 and 255 and origin_branch !~ '(^|/)\.\.(/|$)')
  );

alter table memories drop constraint if exists memories_origin_commit_check;
alter table memories add  constraint memories_origin_commit_check
  check (origin_commit is null or origin_commit ~ '^[0-9a-f]{7,40}$');

alter table memories drop constraint if exists memories_origin_pr_check;
alter table memories add  constraint memories_origin_pr_check
  check (origin_pr is null or origin_pr >= 1);

comment on column memories.origin_repo   is 'Provenance: owner/name of the repository this memory was last recorded from.';
comment on column memories.origin_branch is 'Provenance: git branch this memory was last recorded from (verbatim case).';
comment on column memories.origin_commit is 'Provenance: commit SHA checked out when this memory was last recorded.';
comment on column memories.origin_pr     is 'Provenance: pull request number this memory was last recorded from.';

drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean);

create or replace function memory_write(
  p_user_id       uuid,
  p_scope         text,
  p_key           text,
  p_value         text,
  p_tags          text[]      default '{}',
  p_source_agent  text        default null,
  p_trigger       text        default null,
  p_created_at    timestamptz default null,
  p_org_slug      text        default null,
  p_ttl_seconds   integer     default null,
  p_clear_ttl     boolean     default false,
  p_origin_repo   text        default null,
  p_origin_branch text        default null,
  p_origin_commit text        default null,
  p_origin_pr     integer     default null
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz
)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
  -- Tri-state for the expires_at UPDATE branch:
  --   'clear'  → set to NULL
  --   'set'    → set to v_expires_at
  --   'keep'   → leave unchanged (CASE WHEN ... ELSE memories.expires_at END)
  v_ttl_action   text := 'keep';
begin
  if p_clear_ttl then
    -- Explicit clear wins over any p_ttl_seconds value.
    v_ttl_action := 'clear';
  elsif p_ttl_seconds is not null then
    if p_ttl_seconds < 1 or p_ttl_seconds > 31536000 then
      raise exception using errcode = 'P0001',
        message = format('ttl_seconds must be between 1 and 31536000, got %s', p_ttl_seconds);
    end if;
    v_expires_at  := now() + (p_ttl_seconds * interval '1 second');
    v_ttl_action  := 'set';
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      -- Last KNOWN origin wins: a write that does not know a field leaves the
      -- previously recorded one intact rather than erasing it.
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean, text, text, text, integer)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00048', 'memory_origin')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00049_memory_scopes_last_activity.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_scopes — add `last_activity` to the per-scope rollup.
--
-- WHY: the dashboard's Scope Health cards show, per scope, a total and "last
-- activity". Both were derived client-side from a `select scope, created_at
-- ... limit 1000` in packages/web/src/lib/queries/dashboard.ts — the exact
-- shape 00039 exists to replace. That query is silently wrong twice over: past
-- the row cap it drops whole scopes (00039's rationale) and, because the cap
-- is applied to `created_at desc` rows, it also understates the total for
-- every scope that survives.
--
-- Returning max(created_at) alongside the count makes the endpoint answer the
-- whole question exactly, at any volume, in one round trip. It is the same
-- grouped scan — `max()` over a column already being read — so there is no new
-- cost.
--
-- Forward-only: the return type changes, so the function must be DROPped
-- first (`create or replace` cannot add a column to a RETURNS TABLE). Callers
-- that select `scope`/`count` are unaffected; the new column is additive and
-- the CLI's RemoteStore.listScopes() ignores unknown fields.
--
-- Everything else is carried over verbatim from 00047: the service-role-gated
-- actor guard, the visibility predicate composed from lorekit_member_org_ids,
-- the active-rows-only definition (non-archived AND non-expired), the
-- `order by scope asc` contract, plpgsql-not-SQL so that ordering survives, and
-- the revoked PUBLIC/anon grant.
-- ═════════════════════════════════════════════════════════════════════════

drop function if exists lorekit_memory_scopes(uuid);

create function lorekit_memory_scopes(p_user_id uuid)
returns table (scope text, count bigint, last_activity timestamptz)
language plpgsql
stable
security definer
set search_path = public
as $$
-- The RETURNS TABLE columns are also plpgsql OUT variables, so an unqualified
-- reference to any of them inside the query would be ambiguous. Every reference
-- below is table-qualified, and this directive makes the column win regardless.
#variable_conflict use_column
declare
  -- Honour a caller-supplied p_user_id only on a verified service-role
  -- connection (the edge resolves the token owner and passes it); an
  -- authenticated caller is pinned to its own auth.uid(), closing the
  -- cross-user scope-name enumeration. A NULL actor under service-role is the
  -- CI escape hatch, preserved by the first visibility branch below.
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
    select m.scope, count(*) as count, max(m.created_at) as last_activity
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
     group by m.scope
     order by m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_scopes(uuid) from public, anon;
grant  execute on function lorekit_memory_scopes(uuid) to authenticated, service_role;

comment on function lorekit_memory_scopes(uuid) is
  'Per-scope active counts and last activity visible to the EFFECTIVE caller.
   Actor resolved by the 00046/00041 service-role-gated rule: a caller-supplied
   p_user_id is honoured only on a verified service-role connection, otherwise
   auth.uid() wins — so an authenticated caller can never enumerate another
   user''s scope names. p_user_id IS NULL under service-role is the CI escape
   hatch. last_activity is max(created_at) over the same counted rows.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00049', 'memory_scopes_last_activity')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00050_memory_tags.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_tags(p_user_id, p_archived) — the label (tags) catalog, for
-- GET /memories/tags.
--
-- WHY an RPC rather than a client-side tally: this is lorekit_memory_scopes
-- (00039) applied to the second unbounded dimension. The dashboard's label
-- filter built its catalog from `select tags from memories` plus a
-- client-side reduce (packages/web/src/lib/queries/lore.ts), which is
-- truncated without warning past PostgREST's row cap — so a label used only by
-- older memories vanishes from its own filter, and every count is understated.
-- One grouped row per distinct label is exact at any volume.
--
-- WHY it is archived-aware: the catalog must describe the population it will
-- filter. The Explorer renders the bar in both the active and the archived
-- view and `GET /memories` partitions on archived_at, so a catalog pinned to
-- active rows describes the wrong population in archived mode — wrong counts,
-- and archive-only labels missing entirely. p_archived selects the partition,
-- exactly as `?archived=` does on the list route.
--
-- Expiry: the active partition additionally excludes expired rows, matching
-- lorekit_memory_scopes and the default GET /memories predicate. The archived
-- partition does NOT — an archived row is out of the active set already, and
-- `?archived=true` on the list route applies no expiry filter either, so
-- applying one here would make the catalog disagree with the list it labels.
--
-- Ordering is count desc, then tag asc: the caller renders a picker, and a bar
-- that reshuffles under the cursor for equal counts is a usability bug. As with
-- every other read RPC here, plpgsql (not SQL) so the ORDER BY cannot be lost
-- to inlining.
--
-- Actor resolution, visibility and grants are the 00046/00047 rule verbatim —
-- a caller-supplied p_user_id is honoured only on a verified service-role
-- connection, and PUBLIC/anon get no EXECUTE (label names are as sensitive as
-- scope names: they are free text written by agents).
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memory_tags(
  p_user_id  uuid,
  p_archived boolean default false
)
returns table (tag text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
    select t.tag, count(*) as count
      from memories m
      -- unnest, not a GIN-assisted filter: the catalog is a full rollup of a
      -- text[] column, so every visible row contributes each of its labels.
      cross join lateral unnest(m.tags) as t(tag)
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and t.tag is not null
       and btrim(t.tag) <> ''
     group by t.tag
     order by count(*) desc, t.tag asc;
end;
$$;

revoke execute on function lorekit_memory_tags(uuid, boolean) from public, anon;
grant  execute on function lorekit_memory_tags(uuid, boolean) to authenticated, service_role;

comment on function lorekit_memory_tags(uuid, boolean) is
  'Label (memories.tags) catalog with per-label counts, for the partition
   selected by p_archived, visible to the EFFECTIVE caller. Same
   service-role-gated actor rule and tenant predicate as
   lorekit_memory_scopes. Ordered count desc, tag asc.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00050', 'memory_tags')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00051_memory_activity.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_activity(p_user_id, p_bucket, p_since, p_until) — memories
-- created per UTC hour/day per scope, for GET /memories/activity.
--
-- WHY: the dashboard's stat cards (24h / 7d / 30d sparkbars + period-over-
-- period change) and the contribution heatmap both need "how many memories,
-- when, in which scope". Both were computed client-side from a raw
-- `select scope, created_at ... limit 1000` — truncated without warning past
-- the cap, and shipping up to 1000 rows to a browser to produce ~60 numbers.
--
-- Bucketing in Postgres is exact at any volume and the payload is bounded by
-- (buckets × active scopes) rather than by memory count. `date_trunc` anchors
-- each bucket at the START of the UTC hour/day, which is precisely where the
-- client's own bucket boundaries fall (`Math.floor(t / HOUR_MS) * HOUR_MS` and
-- `Date.UTC(y, m, d)` in packages/web/src/lib/aggregations.ts), so a client
-- tallying these rows gets the same numbers it got from raw rows.
--
-- The [p_since, p_until) window is half-open, matching lorekit_usage_stats
-- (00043). Both bounds are optional; the CALLER is responsible for choosing a
-- window, and the edge handler defaults it rather than leaving it unbounded.
--
-- p_bucket is a bounded categorical ('hour' | 'day'), validated here as well as
-- at the edge. It is passed to date_trunc as a plpgsql function ARGUMENT, not
-- interpolated into SQL text, so there is no injection surface — this function
-- builds no dynamic SQL at all (no EXECUTE, no format()). The check earns its
-- place anyway: date_trunc on an unknown field raises an opaque 22023 from
-- inside the query, so validating up front turns that into a named, testable
-- error (AC-5 in supabase/tests/migrations.test.sql). Anything else raises.
--
-- Actor resolution, visibility, grants, and plpgsql-for-ordering are the
-- 00046/00047 rule verbatim.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memory_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null
)
returns table (bucket timestamptz, scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, m.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           m.scope,
           count(*) as count
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
       and (p_since is null or m.created_at >= p_since)
       and (p_until is null or m.created_at <  p_until)
     group by 1, m.scope
     order by 1 asc, m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_activity(uuid, text, timestamptz, timestamptz) from public, anon;
grant  execute on function lorekit_memory_activity(uuid, text, timestamptz, timestamptz) to authenticated, service_role;

comment on function lorekit_memory_activity(uuid, text, timestamptz, timestamptz) is
  'Memories created per UTC hour/day per scope over the half-open
   [p_since, p_until) window, visible to the EFFECTIVE caller. Same
   service-role-gated actor rule and tenant predicate as
   lorekit_memory_scopes. p_bucket is validated against (hour, day).';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00051', 'memory_activity')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00052_memory_facets.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_facets(p_user_id, p_archived) — the value catalog for EVERY
-- filterable dimension, for GET /memories/facets.
--
-- WHY it exists: the Explorer grew from a labels-only picker into a
-- multi-dimension filter menu (labels, agent, trigger, repo, branch, pull
-- request). Each new dimension is another unbounded free-text column, so each
-- would otherwise repeat the exact bug 00039 and 00050 were written to fix —
-- `select <column> from memories` plus a browser-side tally is truncated
-- without warning past PostgREST's row cap, so a value used only by older
-- memories disappears from its own filter and every count is understated.
--
-- WHY one RPC and not six: the menu's headline affordance is cross-dimension
-- type-ahead ("type `main`, get `Branch → main`"), which needs every
-- dimension's values before the user has chosen a dimension. Six round trips
-- to render one list is six chances to render it half-populated.
--
-- WHY it overlaps lorekit_memory_tags (00050): that function is the
-- single-dimension label catalog `GET /memories/tags` serves to the CLI and to
-- older clients, and deleting it would be a breaking API change. Both read the
-- same rows under the same predicate, so their `tag` rows agree; the union
-- branch below is deliberately written in the same shape as 00050's body so
-- the agreement is visible rather than asserted.
--
-- Expiry, ordering, actor resolution, visibility and grants are 00050's rules
-- verbatim: the active partition additionally excludes expired rows and the
-- archived partition does not; ordering is count desc then value asc so a
-- picker never reshuffles under the cursor for equal counts; a caller-supplied
-- p_user_id is honoured only on a verified service-role connection; and
-- PUBLIC/anon get no EXECUTE (branch names, repo names and agent names are at
-- least as sensitive as the scope names 00039 withholds).
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memory_facets(
  p_user_id  uuid,
  p_archived boolean default false
)
returns table (facet text, value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
  with visible as (
    select m.tags, m.source_agent, m.trigger,
           m.origin_repo, m.origin_branch, m.origin_pr
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
  ), cells as (
    -- Labels: unnest, not a GIN-assisted filter — a rollup of a text[] column
    -- means every visible row contributes each of its labels (00050).
    select 'tag'::text as facet, t.tag as value
      from visible v
      cross join lateral unnest(v.tags) as t(tag)
    union all
    select 'source_agent', v.source_agent from visible v
    union all
    select 'trigger', v.trigger from visible v
    union all
    select 'origin_repo', v.origin_repo from visible v
    union all
    select 'origin_branch', v.origin_branch from visible v
    -- A pull request number is rendered and filtered as text on the wire, so
    -- it is cast once here rather than in every consumer.
    union all
    select 'origin_pr', v.origin_pr::text from visible v
  )
  select c.facet, c.value, count(*) as count
    from cells c
   -- A null column is "this memory has no branch", not a value to offer: an
   -- option that matches by absence needs an `is not set` operator, which the
   -- list route does not have yet. Blank strings are dropped for 00050's
   -- reason — they are unrenderable and unselectable.
   where c.value is not null
     and btrim(c.value) <> ''
   group by c.facet, c.value
   order by c.facet asc, count(*) desc, c.value asc;
end;
$$;

revoke execute on function lorekit_memory_facets(uuid, boolean) from public, anon;
grant  execute on function lorekit_memory_facets(uuid, boolean) to authenticated, service_role;

comment on function lorekit_memory_facets(uuid, boolean) is
  'Value catalog with counts for every filterable memory dimension (tag,
   source_agent, trigger, origin_repo, origin_branch, origin_pr) over the
   partition selected by p_archived, visible to the EFFECTIVE caller. Same
   service-role-gated actor rule, tenant predicate and ordering as
   lorekit_memory_tags.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00052', 'memory_facets')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00053_read_activity.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_read_activity(p_user_id, p_bucket, p_since, p_until) — memory
-- RECORDS read per UTC hour/day, for GET /memories/read-activity.
--
-- WHY: the Overview's third stat card claims to measure reads, but no
-- reads-over-time series existed, so it charted memories WRITTEN under a
-- "scopes active" headline — a chart whose bars measured one thing and whose
-- number measured another. Reads are already recorded: every MCP tool call and
-- every REST route writes one `usage_events` row (00034), and 00044 added
-- `result_count`, the RECORDS a call touched. Summing that over the read tools
-- is an additive metric, so the sparkbar's bars add up to the headline — the
-- property every card on that page is now held to.
--
-- Modelled on lorekit_memory_activity (00051): same bucket validation, same
-- half-open [p_since, p_until) window, same date_trunc anchoring so a JS client
-- bucketing by UTC hour/day tallies identically.
--
-- Visibility is SELF-ONLY, unlike 00051. Usage is a per-user ledger: there is
-- no org sharing of read events (a co-member's reads are not the caller's
-- activity, and usage_events has no org_id at all), so this uses the same
-- self-only predicate + service-role escape hatch as lorekit_usage_stats
-- (00043) and deliberately does NOT join lorekit_member_org_ids — that function
-- is the tenant predicate for `memories` visibility, not for usage.
--
-- The read-tool list is an inline literal, mirroring how 00045 filters
-- `memory.expired` inline. `packages/mcp-core/src/permissions.ts`'s READ_TOOLS
-- carries the same four strings, but it is the MCP permission gate, not a SQL
-- artefact, and there is no mechanism to share a TS constant with a migration.
-- Keep the two in step by hand if a read tool is ever added.
--
-- It mirrors READ_TOOLS — the memory read-FAMILY — and deliberately NOT
-- `usage-stats.ts`'s broader READ_TOOL_NAMES, which additionally classifies
-- `memory.scopes`, `memory.usage`, `org.list`, `org.get`, `member.list` and
-- `member.invite_list` as reads. Those are analytics and org listings, not
-- memory records, so `GET /usage`'s `records_read` is legitimately LARGER than
-- the sum here; a card headlined "Memories read" must not count `org.list`.
--
-- `having sum(...) > 0` keeps the payload sparse: only buckets that actually
-- read something come back, exactly as 00051's aggregate is sparse.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_read_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null
)
returns table (bucket timestamptz, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, ue.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           sum(coalesce(ue.result_count, 0))::bigint as count
      from usage_events ue
     where (
             (v_actor is null and auth.role() = 'service_role')
             or ue.user_id = v_actor
           )
       and ue.tool_name in ('memory.read', 'memory.list', 'memory.search',
                            'memory.list_archived')
       and (p_since is null or ue.created_at >= p_since)
       and (p_until is null or ue.created_at <  p_until)
     group by 1
    having sum(coalesce(ue.result_count, 0)) > 0
     order by 1 asc;
end;
$$;

revoke execute on function lorekit_read_activity(uuid, text, timestamptz, timestamptz) from public, anon;
grant  execute on function lorekit_read_activity(uuid, text, timestamptz, timestamptz) to authenticated, service_role;

comment on function lorekit_read_activity(uuid, text, timestamptz, timestamptz) is
  'Memory RECORDS read (sum of usage_events.result_count over memory.read /
   memory.list / memory.search / memory.list_archived — permissions.ts''s
   READ_TOOLS) per UTC hour/day over the half-open
   [p_since, p_until) window. Visibility is SELF-ONLY with the same
   service-role + NULL escape hatch as lorekit_usage_stats — usage is a
   per-user ledger and is never org-shared. p_bucket is validated against
   (hour, day). Buckets with no records read are omitted.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00053', 'read_activity')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00054_usage_event_client.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- usage_events.client — WHICH SURFACE made the call — and the read-activity
-- metric that stops counting the dashboard's own reads.
--
-- THE BUG: reloading the dashboard made the Overview's "Memories read" card go
-- up, every time. The dashboard is a CLIENT of LoreKit's own REST API (a
-- deliberate decision — see CLAUDE.md), so rendering the Lore Explorer issues a
-- real `GET /memories`, the router records a real `usage_events` row with a
-- real `result_count`, and `lorekit_read_activity` (00053) sums it. The card
-- was therefore measuring "records this account read INCLUDING the ones the
-- page fetched in order to draw this very card" — a metric that responds to
-- looking at it. Visualising your lore is not consuming it; the card is meant
-- to answer "how much have my agents read".
--
-- THE FIX, in two halves:
--
--   1. Record WHO called. `usage_events` already carried `auth_type` (HOW the
--      caller authenticated) and `tool_name` (WHAT they asked for) but nothing
--      for WHICH SURFACE — and neither existing column can stand in. A
--      dashboard read and an agent read over a Supabase JWT are both
--      `auth_type = 'jwt'` calling `memory.list`; distinguishing them by
--      auth tier would be a guess that silently mis-attributes the moment an
--      agent authenticates with a JWT. So: a new nullable `client` column,
--      filled from the client-supplied `X-LoreKit-Client` header at the ONE
--      recording site each surface already has (`_shared/api/router.ts`,
--      `mcp/mcp-handler.ts`) and validated against a closed vocabulary by the
--      pure `parseUsageClient` (`_shared/telemetry/usage-stats.ts`). Unattributed stays
--      NULL — the 00044 posture: a telemetry dimension can never fail the
--      call it is measuring.
--
--   2. Exclude the dashboard from the read METRIC, not from the LEDGER. The
--      events are still written in full, so `GET /memories/usage` still totals
--      every read and the exclusion is reversible with one more migration.
--      Only `lorekit_read_activity` — the series behind the "Memories read"
--      card — filters `client is distinct from 'dashboard'`.
--
-- The exclusion is inlined in the RPC rather than parameterised, mirroring how
-- 00053 inlines its read-tool list and 00045 inlines `memory.expired`: it is
-- the definition of the metric, not a caller's choice. Keep the literal in step
-- with `DASHBOARD_CLIENT` in `packages/mcp-core/src/usage-stats.ts` by hand —
-- there is no mechanism to share a TS constant with a migration.
--
-- Forward-only and additive: the column is nullable and the writer's new
-- parameter is trailing + defaulted, so every existing row and every caller
-- that omits it is unaffected.
-- ═════════════════════════════════════════════════════════════════════════

-- ── the column ──────────────────────────────────────────────────────────────
alter table usage_events add column if not exists client text;

-- Bound the value as a BACKSTOP, not as the primary gate — exactly the reason
-- 00044 gives for `usage_events_correlation_id_len`. The authoritative closed
-- vocabulary is `parseUsageClient`; a CHECK enumerating the members would turn
-- adding a surface into a migration, while an unbounded column would let a
-- malformed header inflate analytics cardinality. A short length cap gives the
-- storage/cardinality guarantee without pinning the vocabulary in SQL.
alter table usage_events drop constraint if exists usage_events_client_len;
alter table usage_events add constraint usage_events_client_len
  check (client is null or (char_length(client) between 1 and 32));

-- Index the read this exists for: "my read events, excluding one client,
-- newest first". Partial on the non-null rows because a NULL client carries no
-- information to filter on.
create index if not exists usage_events_user_client_idx
  on usage_events (user_id, client, created_at desc)
  where client is not null;

-- ── writer: add a trailing p_client ─────────────────────────────────────────
-- DROP first (not CREATE OR REPLACE): adding a parameter changes the signature,
-- and a bare CREATE would leave the 00044 overload behind and make every call
-- ambiguous. Body is 00044's verbatim plus the one column.
drop function if exists lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text);

create or replace function lorekit_record_usage_event(
  p_user_id        uuid    default null,
  p_org_id         uuid    default null,
  p_plan_name      text    default null,
  p_tool_name      text    default null,
  p_scope_type     text    default null,
  p_auth_type      text    default null,
  p_outcome        text    default null,
  p_duration_ms    integer default null,
  p_memory_count   integer default null,
  p_result_count   integer default null,
  p_correlation_id text    default null,
  p_client         text    default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into usage_events (
    user_id, org_id, plan_name,
    tool_name, scope_type, auth_type,
    outcome, duration_ms, memory_count,
    result_count, correlation_id, client
  ) values (
    p_user_id, p_org_id, p_plan_name,
    p_tool_name, p_scope_type, p_auth_type,
    p_outcome, p_duration_ms, p_memory_count,
    p_result_count, p_correlation_id, p_client
  )
  returning id into v_id;
  return v_id;
exception
  when others then
    -- Never let telemetry writes break the primary operation.
    return null;
end;
$$;

grant execute on function lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text, text)
  to anon, authenticated, service_role;

-- ── reader: the "Memories read" series stops counting the dashboard ─────────
-- CREATE OR REPLACE, not DROP: the signature is unchanged from 00053, so every
-- caller (`GET /memories/read-activity`) is untouched. Everything else — the
-- bucket validation, the half-open window, the self-only visibility with the
-- service-role escape hatch, the read-tool list, the sparse `having` — is
-- 00053's verbatim.
create or replace function lorekit_read_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null
)
returns table (bucket timestamptz, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, ue.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           sum(coalesce(ue.result_count, 0))::bigint as count
      from usage_events ue
     where (
             (v_actor is null and auth.role() = 'service_role')
             or ue.user_id = v_actor
           )
       and ue.tool_name in ('memory.read', 'memory.list', 'memory.search',
                            'memory.list_archived')
       -- The dashboard reading lore in order to DRAW this chart is not a read
       -- the chart should report. `is distinct from` (not `<>`) because the
       -- column is nullable and `null <> 'dashboard'` is null, which would
       -- silently drop every unattributed event — including every row written
       -- before this migration.
       and ue.client is distinct from 'dashboard'
       and (p_since is null or ue.created_at >= p_since)
       and (p_until is null or ue.created_at <  p_until)
     group by 1
    having sum(coalesce(ue.result_count, 0)) > 0
     order by 1 asc;
end;
$$;

revoke execute on function lorekit_read_activity(uuid, text, timestamptz, timestamptz) from public, anon;
grant  execute on function lorekit_read_activity(uuid, text, timestamptz, timestamptz) to authenticated, service_role;

comment on function lorekit_read_activity(uuid, text, timestamptz, timestamptz) is
  'Memory RECORDS read (sum of usage_events.result_count over memory.read /
   memory.list / memory.search / memory.list_archived — permissions.ts''s
   READ_TOOLS) per UTC hour/day over the half-open [p_since, p_until) window,
   EXCLUDING events attributed to the dashboard client (00054): browsing your
   own lore in the web UI is visualisation, not consumption, so it must not
   inflate the "Memories read" card it is drawing. Unattributed (NULL client)
   events are counted. Visibility is SELF-ONLY with the same service-role +
   NULL escape hatch as lorekit_usage_stats — usage is a per-user ledger and is
   never org-shared. p_bucket is validated against (hour, day). Buckets with no
   records read are omitted.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00054', 'usage_event_client')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00055_blog_post_likes.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- blog_post_likes — a public, anonymous, cumulative "like" counter for /blog.
--
-- WHY this table looks unlike every other one in this schema: the blog is a
-- PUBLIC, statically-generated surface with no auth gate, and a like
-- accumulates across ALL visitors — signed-in or not. So, uniquely here, the
-- read policy and the increment RPC are granted to `anon`. There is no
-- user_id, no tenant, no owner-scoped RLS: the counter is one global total per
-- post slug, exactly like a page-view counter.
--
-- The per-user/session cap (max 100 likes) is enforced CLIENT-side, in
-- localStorage, because an anonymous visitor has no server identity to key a
-- per-session tally on. The server's job is only to (a) accumulate the global
-- total atomically and (b) refuse an obviously abusive single call: the RPC
-- clamps p_delta to [1, 100] and validates the slug shape, so no single request
-- can inflate a counter by more than one session's worth, and no caller can
-- create junk rows under arbitrary keys. A determined client can still script
-- the endpoint — that is inherent to an anonymous public counter and accepted
-- for a blog vanity metric; the clamp bounds the per-call blast radius.
--
-- Writes go ONLY through the SECURITY DEFINER RPC (there is no insert/update
-- RLS policy), so the slug validation and delta clamp cannot be bypassed by a
-- direct PostgREST write. Reads are a plain SELECT under the public policy.
-- ═════════════════════════════════════════════════════════════════════════

create table if not exists blog_post_likes (
  slug       text primary key
             check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' and length(slug) <= 128),
  likes      bigint      not null default 0 check (likes >= 0),
  updated_at timestamptz not null default now()
);

alter table blog_post_likes enable row level security;

-- Public read: anyone (signed-in or not) can see the totals. This is the whole
-- point — the count is shown to every blog visitor.
drop policy if exists blog_post_likes_public_read on blog_post_likes;
create policy blog_post_likes_public_read
  on blog_post_likes for select
  to anon, authenticated
  using (true);

-- No insert / update / delete policy is defined on purpose: every write must go
-- through lorekit_blog_like below, so the slug CHECK and the [1,100] delta clamp
-- are always applied.

-- ── lorekit_blog_like(slug, delta) → new global total ──────────────────────
-- Atomic upsert-increment. SECURITY DEFINER so `anon` can accumulate the total
-- without any table-level write grant. Validates the slug and clamps the delta.
create or replace function lorekit_blog_like(p_slug text, p_delta int default 1)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  -- One click is +1; a batched flush of a rapid-tap burst sends its accumulated
  -- delta. Clamp to a single session's worth so no call can inflate the counter
  -- past the client-enforced cap, and floor at 1 so a stray 0/negative is a
  -- no-op increment rather than a silent decrement.
  v_delta int    := least(greatest(coalesce(p_delta, 1), 1), 100);
  v_total bigint;
begin
  if p_slug is null
     or p_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
     or length(p_slug) > 128 then
    raise exception 'invalid blog slug %', p_slug using errcode = '22023';
  end if;

  insert into blog_post_likes as l (slug, likes, updated_at)
       values (p_slug, v_delta, now())
  on conflict (slug)
    do update set likes = l.likes + v_delta, updated_at = now()
  returning l.likes into v_total;

  return v_total;
end;
$$;

revoke execute on function lorekit_blog_like(text, int) from public;
grant  execute on function lorekit_blog_like(text, int) to anon, authenticated, service_role;

comment on table blog_post_likes is
  'Public, anonymous, cumulative like counter for /blog posts — one global total
   per post slug. No user_id/tenant: reads are public and writes go only through
   lorekit_blog_like. The per-session 100-like cap is enforced client-side.';

comment on function lorekit_blog_like(text, int) is
  'Atomically add p_delta (clamped to [1,100]) likes to a blog post and return
   the new global total. SECURITY DEFINER + granted to anon so an unauthenticated
   blog visitor can like a post. Validates the slug shape (lowercase kebab, <=128)
   so no junk rows can be created.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00055', 'blog_post_likes')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00056_memory_kind_host.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- memories.kind + memories.host — the bucket TAXONOMY as first-class columns,
-- and the same two dimensions on usage_events so operations are attributable
-- to a family and an owner.
--
-- WHY: a loop's memory bucket has always encoded two facts in its tag string —
-- WHAT KIND of memory it is (a procedural `lesson`, a transient outcome `bus`,
-- or a durable per-repo `signal`) and WHICH HOST owns it (`reviewer`, `aw`, …).
-- Reading either meant parsing `loop::<host>-lessons` on the client. Promoting
-- them to columns lets a caller filter (`?kind=lesson`), lets usage analytics
-- group by kind/host, and lets the dashboard show the three families instead of
-- implying them. The authoritative vocabulary lives in agent-skills'
-- `agents/shared/rules/memory-buckets.md`.
--
-- kind is a closed 3-value vocabulary; host is open (a new host is a new agent,
-- not a migration). Following 00054's `client` precedent, neither is pinned by a
-- CHECK enumerating members — the Zod `MemoryWriteSchema` is the authoritative
-- gate for kind, and a length backstop bounds cardinality/storage without
-- turning "add a host" into a migration.
--
-- Forward-only and additive: both columns are nullable, and each RPC is DROPped
-- and recreated with its new params appended-and-defaulted, so every existing
-- row and every caller that omits them is unaffected. A memory written before
-- this migration has NULL kind/host; the app derives them from the legacy tag
-- (see tags.ts `inferKindHost`) so no data backfill is required.
-- ═════════════════════════════════════════════════════════════════════════

-- ── columns on memories ──────────────────────────────────────────────────────
alter table memories add column if not exists kind text;
alter table memories add column if not exists host text;

-- Length backstops (not the primary gate — see 00054). kind's closed vocabulary
-- is enforced by MemoryWriteSchema; host is open free-text like source_agent.
alter table memories drop constraint if exists memories_kind_len;
alter table memories add constraint memories_kind_len
  check (kind is null or (char_length(kind) between 1 and 32));
alter table memories drop constraint if exists memories_host_len;
alter table memories add constraint memories_host_len
  check (host is null or (char_length(host) between 1 and 64));

-- Index the family/owner read: "lessons for host reviewer", newest first.
create index if not exists memories_kind_host_idx
  on memories (kind, host)
  where kind is not null;

-- ── writer: memory_write gains p_kind + p_host ──────────────────────────────
-- DROP first (not CREATE OR REPLACE): adding params changes the signature, and a
-- bare CREATE would leave the 00048 15-arg overload behind and make calls
-- ambiguous. Body is 00048's verbatim plus the two columns in every branch.
-- kind/host use the origin_* "last KNOWN value wins" merge on update so a write
-- that does not know them (an older client) keeps the previously recorded value
-- rather than erasing it.
drop function if exists memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean, text, text, text, integer);

create or replace function memory_write(
  p_user_id       uuid,
  p_scope         text,
  p_key           text,
  p_value         text,
  p_tags          text[]      default '{}',
  p_source_agent  text        default null,
  p_trigger       text        default null,
  p_created_at    timestamptz default null,
  p_org_slug      text        default null,
  p_ttl_seconds   integer     default null,
  p_clear_ttl     boolean     default false,
  p_origin_repo   text        default null,
  p_origin_branch text        default null,
  p_origin_commit text        default null,
  p_origin_pr     integer     default null,
  p_kind          text        default null,
  p_host          text        default null
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz
)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
  v_ttl_action   text := 'keep';
begin
  if p_clear_ttl then
    v_ttl_action := 'clear';
  elsif p_ttl_seconds is not null then
    if p_ttl_seconds < 1 or p_ttl_seconds > 31536000 then
      raise exception using errcode = 'P0001',
        message = format('ttl_seconds must be between 1 and 31536000, got %s', p_ttl_seconds);
    end if;
    v_expires_at  := now() + (p_ttl_seconds * interval '1 second');
    v_ttl_action  := 'set';
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean, text, text, text, integer, text, text)
  to anon, authenticated, service_role;

-- ── usage_events: kind + host as tracked dimensions ─────────────────────────
alter table usage_events add column if not exists kind text;
alter table usage_events add column if not exists host text;

alter table usage_events drop constraint if exists usage_events_kind_len;
alter table usage_events add constraint usage_events_kind_len
  check (kind is null or (char_length(kind) between 1 and 32));
alter table usage_events drop constraint if exists usage_events_host_len;
alter table usage_events add constraint usage_events_host_len
  check (host is null or (char_length(host) between 1 and 64));

-- Index the family/owner analytics roll-up: "my events for kind X", newest first.
create index if not exists usage_events_user_kind_idx
  on usage_events (user_id, kind, created_at desc)
  where kind is not null;

-- ── writer: record_usage_event gains p_kind + p_host ────────────────────────
-- DROP first — adding params changes the signature (00054's 12-arg overload
-- would otherwise remain and make calls ambiguous). Body is 00054's verbatim
-- plus the two columns.
drop function if exists lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text, text);

create or replace function lorekit_record_usage_event(
  p_user_id        uuid    default null,
  p_org_id         uuid    default null,
  p_plan_name      text    default null,
  p_tool_name      text    default null,
  p_scope_type     text    default null,
  p_auth_type      text    default null,
  p_outcome        text    default null,
  p_duration_ms    integer default null,
  p_memory_count   integer default null,
  p_result_count   integer default null,
  p_correlation_id text    default null,
  p_client         text    default null,
  p_kind           text    default null,
  p_host           text    default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into usage_events (
    user_id, org_id, plan_name,
    tool_name, scope_type, auth_type,
    outcome, duration_ms, memory_count,
    result_count, correlation_id, client, kind, host
  ) values (
    p_user_id, p_org_id, p_plan_name,
    p_tool_name, p_scope_type, p_auth_type,
    p_outcome, p_duration_ms, p_memory_count,
    p_result_count, p_correlation_id, p_client, p_kind, p_host
  )
  returning id into v_id;
  return v_id;
exception
  when others then
    -- Never let telemetry writes break the primary operation.
    return null;
end;
$$;

grant execute on function lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text, text, text, text)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00056', 'memory_kind_host')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00057_memory_facets_drilldown.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_facets — drill-down (filter-aware) counts + kind/host.
--
-- WHAT CHANGES: 00052's facets were GLOBAL — every dimension's counts were the
-- total over all visible memories, ignoring whatever the user had already
-- selected. A drill-down filter menu wants the opposite: once you pick
-- `kind=lesson`, the counts shown for `host`, `source_agent`, … should narrow
-- to "how many LESSON memories also carry this host", so the numbers you see
-- are what you'd actually get by adding that filter.
--
-- THE SELF-EXCLUSION RULE (the easy thing to get wrong): when counting a
-- dimension D's values, apply every OTHER active filter but NOT D's own. If D's
-- own selection were applied to D's own counts, D would collapse to just the
-- value(s) already picked and every other value would read 0 — you could never
-- see what else you could switch to. This is "OR within a dimension, AND across
-- dimensions", the exact model ListMemoriesQuerySchema's `*_mode` filters use.
--
-- HOW: compute each dimension's match flag ONCE per row in `base` (does this row
-- satisfy that dimension's filter?), then a dimension's cells require the AND of
-- all the OTHER flags. A dimension the user has not filtered on has a flag that
-- is trivially true, so its counts fall back to the fully-filtered set — which
-- is exactly right.
--
-- ALSO: adds `kind` and `host` (migration 00056) as two new dimensions.
--
-- Forward-only. The function is DROPped and recreated with a wider signature;
-- every new parameter is optional and defaulted, and the handler is updated in
-- lockstep. With no filters supplied every flag is true and the result is
-- byte-for-byte 00052's global catalog, so callers that pass only
-- (p_user_id, p_archived) are unaffected.
-- ═════════════════════════════════════════════════════════════════════════

drop function if exists lorekit_memory_facets(uuid, boolean);

create or replace function lorekit_memory_facets(
  p_user_id            uuid,
  p_archived           boolean default false,
  -- Active filters, mirroring GET /memories' query params so the menu can pass
  -- its current filter state verbatim. All optional: null/absent = not filtered.
  p_scope              text    default null,
  p_tags               text[]  default null,
  p_tags_mode          text    default 'any',
  p_source_agent       text[]  default null,
  p_source_agent_mode  text    default 'in',
  p_trigger            text[]  default null,
  p_trigger_mode       text    default 'in',
  p_kind               text[]  default null,
  p_kind_mode          text    default 'in',
  p_host               text[]  default null,
  p_host_mode          text    default 'in',
  p_origin_repo        text[]  default null,
  p_origin_repo_mode   text    default 'in',
  p_origin_branch      text[]  default null,
  p_origin_branch_mode text    default 'in',
  p_origin_pr          text[]  default null,
  p_origin_pr_mode     text    default 'in'
)
returns table (facet text, value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  -- `origin_pr` is an INTEGER column, so it must be compared numerically, not as
  -- text: `GET /memories` sends the digits-only list bare to the integer column
  -- (`applyScalarFilter(..., { quote: false })`), where Postgres reads `007` as
  -- 7 and matches PR 7. A `m.origin_pr::text = any(...)` comparison here would
  -- match nothing for the same input, so the two routes would disagree on the
  -- same query string. Non-numeric entries are DROPPED rather than raising, and
  -- a list that reduces to empty applies no filter at all (`array_agg` over no
  -- rows is NULL) — the list route's documented behaviour, verbatim.
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
begin
  return query
  with base as (
    select
      m.tags, m.source_agent, m.trigger, m.kind, m.host,
      m.origin_repo, m.origin_branch, m.origin_pr,
      -- Per-dimension match flag: is this row kept by THIS dimension's filter?
      -- A null filter is "not filtered" → trivially true, so an untouched
      -- dimension never narrows anything.
      (p_tags is null or case coalesce(p_tags_mode, 'any')
         when 'all'  then m.tags @> p_tags
         when 'none' then not (m.tags && p_tags)
         else m.tags && p_tags
       end) as ok_tag,
      (p_source_agent is null or case coalesce(p_source_agent_mode, 'in')
         when 'nin' then (m.source_agent is not null and m.source_agent <> all(p_source_agent))
         else m.source_agent = any(p_source_agent)
       end) as ok_source_agent,
      (p_trigger is null or case coalesce(p_trigger_mode, 'in')
         when 'nin' then (m.trigger is not null and m.trigger <> all(p_trigger))
         else m.trigger = any(p_trigger)
       end) as ok_trigger,
      (p_kind is null or case coalesce(p_kind_mode, 'in')
         when 'nin' then (m.kind is not null and m.kind <> all(p_kind))
         else m.kind = any(p_kind)
       end) as ok_kind,
      (p_host is null or case coalesce(p_host_mode, 'in')
         when 'nin' then (m.host is not null and m.host <> all(p_host))
         else m.host = any(p_host)
       end) as ok_host,
      (p_origin_repo is null or case coalesce(p_origin_repo_mode, 'in')
         when 'nin' then (m.origin_repo is not null and m.origin_repo <> all(p_origin_repo))
         else m.origin_repo = any(p_origin_repo)
       end) as ok_origin_repo,
      (p_origin_branch is null or case coalesce(p_origin_branch_mode, 'in')
         when 'nin' then (m.origin_branch is not null and m.origin_branch <> all(p_origin_branch))
         else m.origin_branch = any(p_origin_branch)
       end) as ok_origin_branch,
      (v_origin_pr is null or case coalesce(p_origin_pr_mode, 'in')
         when 'nin' then (m.origin_pr is not null and m.origin_pr <> all(v_origin_pr))
         else m.origin_pr = any(v_origin_pr)
       end) as ok_origin_pr
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       -- Scope is a hard filter, not a facet dimension, so it is always applied.
       and (p_scope is null or m.scope = p_scope)
  ), cells as (
    -- Each dimension's cells are counted over rows kept by every OTHER
    -- dimension's filter (self-exclusion), so a dimension's own selection never
    -- suppresses its own alternative values.
    select 'tag'::text as facet, t.tag as value
      from base b
      cross join lateral unnest(b.tags) as t(tag)
     where b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
    union all
    select 'source_agent', b.source_agent from base b
     where b.ok_tag and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
    union all
    select 'trigger', b.trigger from base b
     where b.ok_tag and b.ok_source_agent and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
    union all
    select 'kind', b.kind from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
    union all
    select 'host', b.host from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
    union all
    select 'origin_repo', b.origin_repo from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_branch and b.ok_origin_pr
    union all
    select 'origin_branch', b.origin_branch from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_pr
    union all
    select 'origin_pr', b.origin_pr::text from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch
  )
  select c.facet, c.value, count(*) as count
    from cells c
   where c.value is not null
     and btrim(c.value) <> ''
   group by c.facet, c.value
   order by c.facet asc, count(*) desc, c.value asc;
end;
$$;

revoke execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text
) from public, anon;
grant execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text
) to authenticated, service_role;

comment on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text
) is
  'Value catalog with counts for every filterable memory dimension (tag,
   source_agent, trigger, kind, host, origin_repo, origin_branch, origin_pr)
   over the partition selected by p_archived, visible to the EFFECTIVE caller.
   Counts are DRILL-DOWN (00057): each dimension is counted with every OTHER
   active filter applied but not its own (self-exclusion), so the numbers match
   what adding that value would yield. With no filters supplied the result is
   00052''s global catalog. Same service-role-gated actor rule and ordering as
   lorekit_memory_tags.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00057', 'memory_facets_drilldown')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00058_usage_event_scope.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- usage_events.scope — WHICH SCOPE a call touched — and the read-activity
-- series grouped by it.
--
-- THE GAP: reads already carry `scope_type` (00034: `global` / `project` /
-- `repo` / `branch`), which answers "how much do I read at repo level" but not
-- "how much do I read from `repo::mthines/lorekit`". `scope_type` is a
-- deliberately low-cardinality telemetry dimension and cannot be widened into
-- the exact string without changing what it means, so per-scope read totals —
-- the number the Explorer's stats header needs beside its per-scope WRITE
-- totals (`lorekit_memory_activity`, 00051) — were simply unanswerable. Writes
-- have had the exact scope since 00051; reads have not.
--
-- THE FIX, mirroring 00054's structure exactly (that migration added `client`
-- the same way, and for the same class of reason):
--
--   1. A new nullable `scope` column on `usage_events`, filled at the ONE
--      recording site each surface already has (`_shared/api/router.ts`,
--      `mcp/mcp-handler.ts`) from the caller-supplied scope, normalised through
--      the canonical validator by the pure `safeValidateScope`. Unresolvable or
--      absent stays NULL — the 00044/00054 posture: a telemetry dimension can
--      never fail the call it is measuring.
--
--   2. `lorekit_read_activity` returns one row per `(bucket, scope)` instead of
--      one per `bucket`, exactly the shape `lorekit_memory_activity` (00051)
--      already returns for writes, plus an optional `p_scope` FILTER.
--
-- WHY A FILTER PARAMETER AND NOT A COMPANION "per-scope total" RPC: the buckets
-- are additive (a sum of `result_count`), so the filtered buckets' SUM *is* the
-- per-scope headline. A second function would be a second definition of the
-- same number, free to drift from the bars it is drawn above — the property
-- 00053 exists to protect.
--
-- BACKWARD COMPATIBILITY of the grouped shape: the sole consumer today is
-- `packages/web/src/lib/aggregations.ts`'s `computeCountTrend`, which sums
-- `row.count` into UTC time-slots and reads no other field. Splitting one row
-- per bucket into N rows per bucket therefore produces the identical trend —
-- the same argument 00051 made for the write series.
--
-- DEFERRED (R10): `purge_expired_memories` (00045) is deliberately UNTOUCHED.
-- It records one `memory.expired` event per purge run, but the run is per-USER
-- and spans every scope that user owns, so there is no single scope to
-- attribute it to — splitting that event per scope is a separate change with
-- its own shape decision, not the cheap case this migration handles.
--
-- Forward-only and additive throughout: the column is nullable, the writer's
-- new parameter is trailing + defaulted, and the reader's is trailing +
-- defaulted, so every existing row and every existing caller is unaffected.
-- ═════════════════════════════════════════════════════════════════════════

-- ── the column ──────────────────────────────────────────────────────────────
alter table usage_events add column if not exists scope text;

-- Bound the value as a BACKSTOP, not as the primary gate — the same reasoning
-- 00044 gives for `usage_events_correlation_id_len` and 00054 for
-- `usage_events_client_len`. The authoritative validator is `safeValidateScope`
-- (the canonical `validateScope` wrapped to return null instead of throwing); a
-- CHECK re-encoding the scope grammar in SQL would be a second, drift-prone
-- copy of it, while an unbounded column would let a malformed value inflate
-- analytics cardinality. 200 chars is 00044's `usage_events_correlation_id_len`
-- ceiling reused verbatim — deliberately NOT "the same ceiling `memories.scope`
-- uses", which has none: that column is plain `text not null`
-- (`00001_memories.sql:8`) with no CHECK, so a memory may legitimately be
-- written under a scope this telemetry column would refuse. That asymmetry is
-- the point of a backstop on a DIMENSION rather than on the record itself.
--
-- BACKSTOP means the recording side clamps FIRST: `safeValidateScope` returns
-- null above `USAGE_SCOPE_MAX` (= 200), so a grammatical but over-long scope is
-- recorded as unattributed instead of reaching this CHECK. It has to — the
-- violation would be raised inside `lorekit_record_usage_event`, whose `when
-- others` handler swallows it and returns null, dropping the WHOLE event rather
-- than just the scope dimension. Same clamp-then-check pairing 00044 has between
-- `parseCorrelationId` and `usage_events_correlation_id_len`.
alter table usage_events drop constraint if exists usage_events_scope_len;
alter table usage_events add constraint usage_events_scope_len
  check (scope is null or (char_length(scope) between 1 and 200));

-- Index the read this exists for: "my read events under THIS scope, newest
-- first". Partial on the non-null rows because a NULL scope carries no
-- information to filter on — the same shape as 00054's client index.
create index if not exists usage_events_user_scope_created_idx
  on usage_events (user_id, scope, created_at desc)
  where scope is not null;

-- ── writer: add a trailing p_scope ──────────────────────────────────────────
-- DROP first (not CREATE OR REPLACE): adding a parameter changes the signature,
-- and a bare CREATE would leave the previous overload behind and make every
-- call ambiguous. The signature dropped here is the FOURTEEN-argument one from
-- 00056 (which added `p_kind`/`p_host`), not 00054's twelve — a stale drop
-- target is silent, leaving both overloads live and every named-argument call
-- ambiguous at runtime. Body is 00056's verbatim plus the one column.
drop function if exists lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text, text, text, text);

create or replace function lorekit_record_usage_event(
  p_user_id        uuid    default null,
  p_org_id         uuid    default null,
  p_plan_name      text    default null,
  p_tool_name      text    default null,
  p_scope_type     text    default null,
  p_auth_type      text    default null,
  p_outcome        text    default null,
  p_duration_ms    integer default null,
  p_memory_count   integer default null,
  p_result_count   integer default null,
  p_correlation_id text    default null,
  p_client         text    default null,
  p_kind           text    default null,
  p_host           text    default null,
  p_scope          text    default null
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into usage_events (
    user_id, org_id, plan_name,
    tool_name, scope_type, auth_type,
    outcome, duration_ms, memory_count,
    result_count, correlation_id, client, kind, host,
    scope
  ) values (
    p_user_id, p_org_id, p_plan_name,
    p_tool_name, p_scope_type, p_auth_type,
    p_outcome, p_duration_ms, p_memory_count,
    p_result_count, p_correlation_id, p_client, p_kind, p_host,
    p_scope
  )
  returning id into v_id;
  return v_id;
exception
  when others then
    -- Never let telemetry writes break the primary operation.
    return null;
end;
$$;

grant execute on function lorekit_record_usage_event(uuid, uuid, text, text, text, text, text, integer, integer, integer, text, text, text, text, text)
  to anon, authenticated, service_role;

-- ── reader: one row per (bucket, scope), plus an optional scope filter ──────
-- DROP first: the RETURN TYPE gains a column, which CREATE OR REPLACE cannot
-- do ("cannot change return type of existing function"), and the parameter list
-- gains a trailing entry. Everything else — the bucket validation, the
-- half-open window, the self-only visibility with the service-role escape
-- hatch, the read-tool list, the dashboard exclusion, the sparse `having` — is
-- 00053/00054's verbatim.
drop function if exists lorekit_read_activity(uuid, text, timestamptz, timestamptz);

create or replace function lorekit_read_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null,
  p_scope   text        default null
)
returns table (bucket timestamptz, scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, ue.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           ue.scope as scope,
           sum(coalesce(ue.result_count, 0))::bigint as count
      from usage_events ue
     where (
             (v_actor is null and auth.role() = 'service_role')
             or ue.user_id = v_actor
           )
       and ue.tool_name in ('memory.read', 'memory.list', 'memory.search',
                            'memory.list_archived')
       -- The dashboard reading lore in order to DRAW this chart is not a read
       -- the chart should report. `is distinct from` (not `<>`) because the
       -- column is nullable and `null <> 'dashboard'` is null, which would
       -- silently drop every unattributed event — including every row written
       -- before this migration.
       and ue.client is distinct from 'dashboard'
       -- The optional per-scope filter. `=`, not `is not distinct from`: a
       -- caller asking for a named scope wants events attributed to it, never
       -- the unattributable NULL-scope remainder. Omitting the parameter
       -- returns every scope INCLUDING those NULL rows, so the unfiltered
       -- account total stays complete.
       and (p_scope is null or ue.scope = p_scope)
       and (p_since is null or ue.created_at >= p_since)
       and (p_until is null or ue.created_at <  p_until)
     group by 1, ue.scope
    having sum(coalesce(ue.result_count, 0)) > 0
     -- The scope tiebreak is 00051's verbatim (`order by 1 asc, m.scope asc`).
     -- Bucket alone stopped being a total order the moment a bucket could hold
     -- several scopes, and this function's header claims it mirrors that shape,
     -- so intra-bucket row order must be deterministic here too.
     order by 1 asc, ue.scope asc;
end;
$$;

revoke execute on function lorekit_read_activity(uuid, text, timestamptz, timestamptz, text) from public, anon;
grant  execute on function lorekit_read_activity(uuid, text, timestamptz, timestamptz, text) to authenticated, service_role;

comment on function lorekit_read_activity(uuid, text, timestamptz, timestamptz, text) is
  'Memory RECORDS read (sum of usage_events.result_count over memory.read /
   memory.list / memory.search / memory.list_archived — permissions.ts''s
   READ_TOOLS) per UTC hour/day AND per scope over the half-open
   [p_since, p_until) window, EXCLUDING events attributed to the dashboard
   client (00054). One row per (bucket, scope), mirroring
   lorekit_memory_activity (00051); scope is NULL for events whose scope could
   not be resolved, and those rows are counted in the unfiltered result.
   p_scope restricts the result to one exact scope, whose buckets SUM to the
   per-scope headline — the metric is additive, so no companion total function
   exists to drift from it. Visibility is SELF-ONLY with the same service-role +
   NULL escape hatch as lorekit_usage_stats — usage is a per-user ledger and is
   never org-shared. p_bucket is validated against (hour, day). Buckets with no
   records read are omitted.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00058', 'usage_event_scope')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00059_memory_seen_count.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- memories.seen_count — RECURRENCE as a real column, counted by the writer.
--
-- WHY: recurrence is already the load-bearing signal in LoreKit's own guidance.
-- `packages/cli/skill/lorekit-setup/rules/self-improvement-loops.md` gates
-- promotion on `seen_count >= 3`, `lorekit-groom`'s volatile-key rule exists
-- precisely because a per-sighting identifier in the key "never dedups and
-- leaves seen_count frozen at 1", and `lessons-view.mjs`'s LINT_RULES cites the
-- same field. None of it was ever true: the counter lived only as hand-written
-- text inside a lesson body's `<!-- meta: seen_count=1 ... -->` comment, so
-- nothing incremented it, nothing could read it, and every consumer above was
-- describing a column that did not exist.
--
-- This makes it real, and puts the increment where the recurrence actually
-- happens: the upsert. A write whose (tenant, scope, key) already resolves to a
-- live row IS the second sighting of that lesson — that is the definition the
-- skill documents ("a recurrence resolves to an UPDATE that increments
-- seen_count by 1"), so the RPC counts it rather than trusting a caller to pass
-- a number it would have to read back first.
--
-- Forward-only and additive. The column is NOT NULL DEFAULT 1 — one sighting is
-- what an existing row has demonstrably had, so the backfill is the default and
-- no data migration is required. `memory_write` keeps its 00056 signature
-- unchanged (no new parameter — the count is derived, never supplied), so every
-- existing caller is untouched and this is a CREATE OR REPLACE rather than the
-- DROP-first dance a signature change forces.
--
-- No index: no read path filters or orders on seen_count yet. Same call as
-- 00048 made for the origin_* columns — add one with the query that needs it.
-- ═════════════════════════════════════════════════════════════════════════

-- ── column on memories ──────────────────────────────────────────────────────
alter table memories add column if not exists seen_count integer not null default 1;

-- A sighting count is >= 1 by construction: the row exists because it was
-- written at least once. The backstop makes a corrupt/hand-edited 0 or negative
-- value fail loudly here rather than silently sinking a lesson's salience in
-- whatever ranks on this column later.
alter table memories drop constraint if exists memories_seen_count_positive;
alter table memories add constraint memories_seen_count_positive
  check (seen_count >= 1);

-- ── writer: memory_write counts the recurrence ──────────────────────────────
-- Body is 00056's verbatim plus `seen_count` in every branch. The signature is
-- IDENTICAL to 00056's, so CREATE OR REPLACE is safe and leaves no ambiguous
-- overload behind — unlike 00048/00056, this migration adds no parameter.
--
-- Insert branches set 1 explicitly rather than leaning on the column default,
-- so the first-sighting value is visible in the same statement that the
-- increment is, and the two cannot drift if the default is ever changed.
--
-- The increment is `memories.seen_count + 1`, NOT `excluded.seen_count + 1`:
-- `excluded` is the row the INSERT proposed, which always carries the literal 1
-- and would pin every recurrence at 2.
--
-- Reviving an ARCHIVED key is deliberately NOT a recurrence. Every conflict
-- predicate below is partial on `archived_at is null` (00016), so a write
-- against an archived key inserts a fresh row and starts at 1 — the lesson was
-- retired and is being learned again, which is the honest reading and matches
-- the existing created_at semantics on that path.
create or replace function memory_write(
  p_user_id       uuid,
  p_scope         text,
  p_key           text,
  p_value         text,
  p_tags          text[]      default '{}',
  p_source_agent  text        default null,
  p_trigger       text        default null,
  p_created_at    timestamptz default null,
  p_org_slug      text        default null,
  p_ttl_seconds   integer     default null,
  p_clear_ttl     boolean     default false,
  p_origin_repo   text        default null,
  p_origin_branch text        default null,
  p_origin_commit text        default null,
  p_origin_pr     integer     default null,
  p_kind          text        default null,
  p_host          text        default null
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz
)
language plpgsql
set search_path = public
as $$
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
  v_ttl_action   text := 'keep';
begin
  if p_clear_ttl then
    v_ttl_action := 'clear';
  elsif p_ttl_seconds is not null then
    if p_ttl_seconds < 1 or p_ttl_seconds > 31536000 then
      raise exception using errcode = 'P0001',
        message = format('ttl_seconds must be between 1 and 31536000, got %s', p_ttl_seconds);
    end if;
    v_expires_at  := now() + (p_ttl_seconds * interval '1 second');
    v_ttl_action  := 'set';
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
  else
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where b.scope = p_scope and o.deleted_at is null;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write') then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host, seen_count
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host, 1
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      seen_count    = memories.seen_count + 1,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host, seen_count
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host, 1
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      seen_count    = memories.seen_count + 1,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host, seen_count
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host, 1
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      seen_count    = memories.seen_count + 1,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at;
  end if;
end;
$$;

grant execute on function memory_write(uuid, text, text, text, text[], text, text, timestamptz, text, integer, boolean, text, text, text, integer, text, text)
  to anon, authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00059', 'memory_seen_count')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00060_memory_embeddings.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- memories.embedding — the semantic-search column, landed DORMANT.
--
-- WHY SEPARATELY, AND WHY EMPTY: nothing reads or writes this column in this
-- migration, and that is the entire point. The embedding arc has three
-- independent risks — a schema change, a provider dependency with a real cost
-- and latency, and a ranking-fusion tuning problem — and bundling them makes
-- the first impossible to review and the last impossible to abandon. Landing
-- the schema alone means the write pipeline (which needs an API key, a backfill
-- and a budget) and the search modes (which need recall tuning) can each be
-- decided on their own evidence, and either can be dropped without unpicking a
-- migration.
--
-- After this migration the database is byte-for-byte equivalent in behaviour:
-- every existing row has `embedding is null`, no handler selects the column, no
-- RPC writes it, and `MEMORY_SELECT` does not name it. The only observable
-- change is that `pgvector` is enabled and two nullable columns exist.
--
-- ── The two choices a reviewer should actually check ──────────────────────
--
-- DIMENSION 1536, and it is a constraint rather than a preference. pgvector's
-- HNSW index refuses more than 2000 dimensions on the `vector` type, so a
-- 3072-dimension model (OpenAI `text-embedding-3-large`, Gemini's large
-- embedding) cannot be ANN-indexed here at all without switching the column to
-- `halfvec` and halving precision. 1536 is `text-embedding-3-small`'s native
-- width, sits comfortably under the ceiling, and is the width every mainstream
-- provider can produce — several support Matryoshka truncation to it, so
-- choosing 1536 does NOT lock the pipeline to one vendor. Changing this later
-- is a table rewrite, which is exactly why it is being decided now, in
-- isolation, rather than discovered during the pipeline PR.
--
-- HNSW, NOT IVFFLAT, and the emptiness is the reason. An IVFFlat index
-- partitions the vector space by clustering the rows that exist AT BUILD TIME;
-- built on an empty table it produces meaningless centroids and has to be
-- dropped and rebuilt once data lands — which is a second migration and an
-- outage-shaped operation on a large table. HNSW builds a graph incrementally
-- as rows arrive, so an index created on zero rows is correct and stays correct.
-- Given this column is deliberately empty today, IVFFlat would be the wrong
-- structure by construction.
--
-- COSINE (`vector_cosine_ops`) because text embeddings from every provider
-- worth using are L2-normalised, where cosine distance and inner product rank
-- identically and cosine is the one that stays correct if a future provider is
-- not normalised.
--
-- PARTIAL (`where embedding is not null`) so the index describes only rows that
-- have one. Today that is none, so the index costs nothing; during the backfill
-- it grows with coverage instead of being sized for the whole table up front.
-- ═════════════════════════════════════════════════════════════════════════

-- Supabase provisions `vector` in the `extensions` schema on hosted projects
-- and `if not exists` makes this a no-op there; locally it is what installs it.
-- Same shape as `pg_trgm` in 00012 — no schema qualification, so it resolves
-- wherever the project already puts extensions.
create extension if not exists vector;

-- ── the column ──────────────────────────────────────────────────────────────
-- Nullable with no default: null means "not embedded yet", which is the state
-- every existing row is in and the state the backfill queries for. A default
-- would make "never embedded" indistinguishable from "embedded as zeroes".
alter table memories add column if not exists embedding vector(1536);

-- WHICH MODEL produced the vector. Not decoration: embeddings from two models
-- are not comparable, so a silent provider swap would leave the table holding
-- two incompatible vector spaces and a similarity search would return confident
-- nonsense across the boundary. Recording it is what makes a re-embed
-- targetable (`where embedding_model <> $current`) instead of a full rebuild,
-- and it is far cheaper to add now, on an empty column, than after a backfill.
alter table memories add column if not exists embedding_model text;

-- Length backstop only — the vocabulary is the pipeline's to police, exactly as
-- 00056 argued for `kind`/`host`. This bounds storage and cardinality without
-- turning "support another provider" into a migration.
alter table memories drop constraint if exists memories_embedding_model_len;
alter table memories add constraint memories_embedding_model_len
  check (embedding_model is null or (char_length(embedding_model) between 1 and 128));

-- A vector without a model is unattributable, and a model without a vector is a
-- lie about what the row holds. Both-or-neither, enforced here rather than
-- trusted to the writer, because the failure it prevents is silent.
alter table memories drop constraint if exists memories_embedding_model_pairing;
alter table memories add constraint memories_embedding_model_pairing
  check ((embedding is null) = (embedding_model is null));

-- ── the ANN index ───────────────────────────────────────────────────────────
-- `m` and `ef_construction` are pgvector's defaults, stated explicitly so the
-- build parameters are visible in the schema rather than inherited from
-- whatever version happens to be installed. Recall tuning belongs with the
-- search modes, where it can be measured.
create index if not exists memories_embedding_hnsw_idx
  on memories using hnsw (embedding vector_cosine_ops)
  with (m = 16, ef_construction = 64)
  where embedding is not null;

-- Coverage lookup for the backfill: "which rows still need embedding", newest
-- first. Without it a resumable backfill sequentially scans the whole table on
-- every batch, which is the shape that makes a backfill quadratic.
create index if not exists memories_embedding_pending_idx
  on memories (created_at desc)
  where embedding is null;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00060', 'memory_embeddings')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00061_memories_keyset_index.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Give the memories list seek its `id` tiebreaker.
--
-- `memories_scope_updated_at_idx` (00033) was designed for the query toolList
-- ran AT THE TIME:
--
--   … WHERE scope = ? AND archived_at IS NULL
--     ORDER BY updated_at DESC LIMIT ?
--
-- so `(scope, updated_at desc)` satisfied the order exactly. Keyset pagination
-- landed afterwards and changed both halves of that query. It now orders by a
-- COMPOSITE key and seeks on it:
--
--   … WHERE scope = ? AND archived_at IS NULL
--     AND (updated_at < ?ts OR (updated_at = ?ts AND id < ?id))
--     ORDER BY updated_at DESC, id DESC LIMIT ?
--
-- (`supabase/functions/mcp/tools.ts` toolList / `memories/handlers/list.ts`,
-- predicate built by `_shared/api/paginate.ts` + `mcp/cursor.ts`.)
--
-- The existing index stops at `updated_at`, so `id` is not available to the
-- scan: the tiebreaker becomes a heap recheck on every candidate row, and the
-- planner cannot stop early at LIMIT when a timestamp is not unique. This is
-- the same omission 00012 fixed for `audit_log` — 00010's
-- `(user_id, created_at desc)` lacked the same `id` column, for the same
-- keyset predicate.
--
-- The fix here is 00012's fix with ONE deliberate difference: 00012 built
-- `(user_id, created_at desc, id)`, with `id` ASC. The seek it serves orders by
-- `created_at DESC, id DESC`, and a (DESC, ASC) index yields that pair in
-- neither scan direction, so 00012 recovered the index-only tiebreaker lookup
-- but not the ordered scan. `id desc` below matches the ORDER BY exactly. The
-- corresponding correction on `audit_log_user_created_id_idx` is a separate,
-- separately-measured migration on a different table and is not made here.
--
-- Cost is concentrated where it is felt most: deep pagination over a large
-- scope, which is the shape the busiest caller actually has (37% of list calls
-- in a recent 24h window came back with `has_more`, and the deepest walk paged
-- a single scope ~a dozen times at 543–765 ms per page).
--
-- The partial predicate is carried over verbatim from 00033 so the two indexes
-- describe the same row population. The expiry filter
-- (`expires_at IS NULL OR expires_at > now()`) is deliberately NOT in the
-- predicate: `now()` is volatile and PostgreSQL rejects it in an index
-- predicate — the same reason 00033 gave for adding no `rate_limit_counters`
-- index.
--
-- Forward-only and additive. `IF NOT EXISTS` so it can be applied to a running
-- production database (`CONCURRENTLY` is not used inside migrations because it
-- cannot run in a transaction).
--
-- LOCK WINDOW: because the build is not `CONCURRENTLY`, it takes a SHARE lock
-- on `memories` for the duration — reads continue, writes BLOCK until the
-- index is built. `IF NOT EXISTS` makes re-application free but does not
-- shorten the first build. Sizing that window is a deploy-time call on the
-- live table, not something this file can assert; if it is ever too long for
-- the write path, the escape hatch is to build the index out-of-band with
-- `CREATE INDEX CONCURRENTLY` before deploying, after which this migration
-- is a no-op.
--
-- SCOPE: `sort=updated_at` only. `GET /memories` also accepts
-- `sort=created_at`, whose keyset seeks `(created_at, id)` under the same
-- `scope` filter, and no index covers that pair either. That page is
-- deliberately out of scope here: the measured cost is on the default sort
-- (`memory.list` is the most-called MCP tool and always sorts by `updated_at`),
-- and every index on `memories` is write amplification on the hottest table in
-- the product, so the second one should be justified by its own measurement
-- rather than added on symmetry. Tracked as a follow-up, not fixed here.
--
-- The superseded `memories_scope_updated_at_idx` is deliberately LEFT IN PLACE.
-- Dropping an index in the same migration that adds its replacement gives the
-- planner no fallback if the new one is not yet warm, and this is the hottest
-- read path in the product; retiring it is a separate, observable decision.

create index if not exists memories_scope_updated_at_id_idx
  on memories (scope, updated_at desc, id desc)
  where archived_at is null;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00061', 'memories_keyset_index')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00062_memory_embedding_write.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_set_embedding — the ONE authorised path for writing a
-- memory's vector.
--
-- ── WHY THIS EXISTS ──────────────────────────────────────────────────────
-- The write-path embedder (`_shared/embedding/embed-on-write.ts`) updated `memories`
-- directly, with whatever client the request happened to arrive on. That is
-- correct on two of the three auth tiers and SILENTLY wrong on the third:
--
--   * `service` and `api_key` both hold a service-role client, and `rls_update`
--     (00001) admits `auth.role() = 'service_role'`, so the update lands.
--
--   * a Supabase JWT holds an RLS-scoped client, and `rls_update` admits only
--     `user_id = auth.uid()`. The READ policies were widened for orgs in 00015
--     (`org_id in (select lorekit_member_org_ids(auth.uid()))`); `rls_update`
--     never was. An ORG-OWNED memory carries `user_id is null` (00019), so the
--     UPDATE matched ZERO ROWS — and a zero-row update is not an error in
--     PostgREST. The embedding was dropped with no signal anywhere, and the
--     row waited for a manual backfill that an operator had no reason to run.
--
-- The asymmetry is the whole bug: SELECT knows about orgs, UPDATE does not.
--
-- ── WHY NOT SIMPLY WIDEN `rls_update` ────────────────────────────────────
-- Making UPDATE symmetric with SELECT would fix the embed and open a hole:
-- every org MEMBER could then rewrite any column of any org memory straight
-- through PostgREST, with no role check at all. Org writes are gated on
-- `lorekit_org_can(…, 'write')` — a VIEWER must not write — and that gate lives
-- in RPCs precisely because RLS cannot express it. Widening the policy would
-- silently demote a role check to a membership check, on every column, for
-- every caller. The embedding is not worth that.
--
-- ── WHY NOT MIRROR `memory_write`'s BRANCHING IN THE EDGE ────────────────
-- Two copies of an ownership rule drift, and the copy in TypeScript is the one
-- no migration test ever runs. 00019's branching would have to be restated in
-- Deno and kept in step by review alone.
--
-- ── WHAT THIS DOES INSTEAD ───────────────────────────────────────────────
-- One SECURITY DEFINER function — the shape 00022/00041 established for every
-- org state transition — with authorisation derived INSIDE it from the same
-- predicates the rest of the schema already uses:
--
--   * `lorekit_org_actor`  (00041) resolves WHO is acting: a service-role
--     caller may name the user it acts for, a JWT caller is only ever itself.
--   * `lorekit_org_can`    (00017) is the ROLE gate for an org-owned row —
--     the same 'write' capability `memory_write` demanded to create it.
--   * personal rows compare against the resolved actor directly.
--
-- Nothing here re-implements an ownership rule; it composes the existing ones.
-- If the ownership model changes, it changes in those functions and this
-- inherits it.
--
-- ── IT REPORTS WHETHER IT WROTE, AND THAT IS THE OTHER HALF OF THE FIX ───
-- The original defect was not merely that the update failed — it is that it
-- failed INVISIBLY. This reports whether a row was actually written so the
-- caller can record a miss on its span. If some future ownership model escapes
-- these predicates, it surfaces as a signal instead of an empty column nobody
-- notices until a semantic search quietly comes back thin.
--
-- `returns table (written boolean)` rather than a bare `returns boolean`: it is
-- the shape `memory_delete` (00020) already uses for a did-it-land answer, and
-- the one the edge's traced client types honestly — `TracedQuery<T>` resolves to
-- `PostgrestResponse<T[]>`, so a scalar-returning function would have to be read
-- through an `unknown` cast at every call site.
--
-- ── search_path NAMES `extensions` ON PURPOSE ────────────────────────────
-- Every other function in this schema pins `set search_path = public`. This one
-- cannot: it casts to `vector(1536)`, and Supabase provisions `vector` in the
-- `extensions` schema on hosted projects (see 00060's header). Pinning `public`
-- alone would resolve locally, where the extension lands in the search path
-- already, and fail in production with `type "vector" does not exist` — inside a
-- backgrounded task whose errors are swallowed by design. Naming both schemas
-- is what makes the local run and the hosted run the same run.
-- ═════════════════════════════════════════════════════════════════════════

-- ═════════════════════════════════════════════════════════════════════════
-- PART 1 — an embedding write must not disturb `updated_at`.
--
-- `memories_updated_at` (00001) is a BEFORE UPDATE trigger that sets
-- `updated_at = now()` unconditionally. That is right for an edit and WRONG for
-- an embedding: the vector is a DERIVED artefact, not a change to what the
-- lesson says. `updated_at` is the recency signal `POST /memories/search` and
-- `GET /memories/relevant` order by, that `memory.list` keysets on
-- (`memories_scope_updated_at_id_idx`), and that `lesson-rank` scores.
--
-- On the write path the damage is nil — the row was created moments earlier.
-- A WHOLE-STORE BACKFILL is the problem: it walks `created_at desc` and would
-- restamp every row in that order, collapsing the store's real recency ordering
-- into the order the backfill happened to run in. The old values are not
-- recoverable afterwards, so this is a one-way corruption of the ranking signal
-- that nothing would report.
--
-- FIXED AT THE STORAGE LAYER, not at the two call sites. Both the RPC below and
-- the backfill's PostgREST PATCH trip the same trigger, and so would any future
-- writer — a rule each caller has to remember is a rule that gets forgotten
-- exactly once.
--
-- `set_updated_at` itself is LEFT ALONE: five other tables share it
-- (`user_limits`, `orgs`, `org_limits`, `plans`, `user_plans`), and none of them
-- has an embedding column or this problem. Only the `memories` trigger is
-- retargeted.
--
-- The predicate is "did anything OTHER than the embedding columns change?",
-- asked by masking those columns plus `updated_at` and comparing the whole rows.
-- Column-complete by construction: a column added to `memories` later is
-- included automatically, where an explicit list would silently stop covering it.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memories_set_updated_at()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
declare
  v_new memories := new;
  v_old memories := old;
  v_embedding_changed boolean;
begin
  -- The embedding columns must ACTUALLY have changed for this to be an embedding
  -- write. Without this precondition the rule reads "nothing meaningful changed
  -- → preserve", which also catches a plain NO-OP re-write — and `memory_write`
  -- upserts, so an agent re-saving an identical lesson would silently stop
  -- refreshing `updated_at`. That is a recency-contract change reaching well
  -- beyond embeddings, in a migration whose whole point is that a DERIVED column
  -- must not disturb the row. Preserve only when a vector actually moved;
  -- everything else, including a no-op, keeps the behaviour `set_updated_at`
  -- always had.
  v_embedding_changed :=
       new.embedding is distinct from old.embedding
    or new.embedding_model is distinct from old.embedding_model;

  -- Mask the derived columns and the one being decided.
  --
  -- `fts` MUST be masked too, and for a reason that is easy to get wrong:
  -- it is a GENERATED column, and Postgres computes generated columns AFTER
  -- BEFORE-row triggers run. So `new.fts` is NULL here while `old.fts` holds
  -- the stored value, and an unmasked comparison finds every update "changed"
  -- — which silently turns this whole function back into `set_updated_at`.
  -- It fails in the safe direction (a bump that should not happen, never a
  -- missing bump), which is exactly why it needs a test rather than a reading.
  -- `fts` is derived from `key || ' ' || value`, so masking it loses nothing:
  -- a real edit is already visible in those columns.
  v_new.embedding := null; v_new.embedding_model := null; v_new.updated_at := null; v_new.fts := null;
  v_old.embedding := null; v_old.embedding_model := null; v_old.updated_at := null; v_old.fts := null;

  if v_embedding_changed and v_new is not distinct from v_old then
    -- A vector moved and nothing else did: an embedding write. Preserve the
    -- row's real recency rather than restamping it.
    new.updated_at := old.updated_at;
  else
    new.updated_at := now();
  end if;

  return new;
end;
$$;

create or replace trigger memories_updated_at
  before update on memories
  for each row execute function lorekit_memories_set_updated_at();

comment on function lorekit_memories_set_updated_at() is
  'BEFORE UPDATE on memories: bumps updated_at like set_updated_at, EXCEPT when the only change is '
  'the embedding columns — a derived artefact must not rewrite the recency signal that search, '
  'relevant, the keyset index and lesson-rank all read. A whole-store backfill would otherwise '
  'restamp every row in created_at desc order, irrecoverably.';

-- ═════════════════════════════════════════════════════════════════════════
-- PART 2 — the authorised write path itself.
-- ═════════════════════════════════════════════════════════════════════════

-- Dropped first for the reason 00019/00009 give: `create or replace` cannot
-- change a function's RETURN TYPE, so amending this later (a third output
-- column, say) would fail against a database that already has it. Forward-only.
drop function if exists lorekit_memory_set_embedding(uuid, uuid, text, text);

create function lorekit_memory_set_embedding(
  p_memory_id     uuid,
  p_actor_user_id uuid,
  p_embedding     text,
  p_model         text
)
returns table (written boolean)
language plpgsql
volatile
security definer
set search_path = public, extensions
as $$
declare
  v_actor   uuid;
  v_is_svc  boolean;
  v_user_id uuid;
  v_org_id  uuid;
  v_rows    integer;
begin
  if p_memory_id is null then
    return query select false;
    return;
  end if;

  -- Both-or-neither, per the 00060 CHECK. Refused here so the caller gets a
  -- named reason rather than an opaque constraint violation surfacing from a
  -- background task. `embedOnWrite` always sends both; this is the guard for
  -- the next caller.
  if (p_embedding is null) <> (p_model is null) then
    raise exception using
      errcode = 'P0001',
      message = 'embedding and embedding_model must be set together (00060 pairing)';
  end if;

  v_actor  := lorekit_org_actor(p_actor_user_id);
  v_is_svc := auth.role() = 'service_role';

  select m.user_id, m.org_id into v_user_id, v_org_id
    from memories m
   where m.id = p_memory_id;

  -- No such row (deleted between the write and this call). Not an error: the
  -- caller's contract is "never fail a memory write because of an embedding".
  if not found then
    return query select false;
    return;
  end if;

  if v_org_id is not null then
    -- Org-owned. Membership alone is NOT enough — the same 'write' capability
    -- 00019 required to create the row is required to embed it. A null actor
    -- fails closed here (`lorekit_org_role(null, …)` is null), so the service
    -- tier is admitted by its own branch rather than by an accident of NULL
    -- comparison.
    if not (v_is_svc and v_actor is null)
       and not lorekit_org_can(v_actor, v_org_id, 'write') then
      return query select false;
      return;
    end if;

  elsif v_user_id is not null then
    -- Personal. `is distinct from` rather than `<>` so a null actor is a
    -- mismatch instead of an unknown that falls through.
    if v_actor is distinct from v_user_id then
      return query select false;
      return;
    end if;

  else
    -- Neither user- nor org-owned: written by the service tier with
    -- `p_user_id => null`. Only the service tier may touch it.
    if not v_is_svc then
      return query select false;
      return;
    end if;
  end if;

  update memories
     set embedding       = p_embedding::vector(1536),
         embedding_model = p_model
   where id = p_memory_id;

  get diagnostics v_rows = row_count;
  return query select v_rows > 0;
end;
$$;

-- THE REVOKE IS LOAD-BEARING, not belt-and-braces: Postgres grants EXECUTE on a
-- newly created function to PUBLIC by default, and `anon` inherits it. Naming
-- `authenticated, service_role` in the GRANT alone would NOT withhold it — see
-- the same note in 00041, where `migrations.test.sql`'s anon assertion caught
-- exactly this.
revoke execute on function lorekit_memory_set_embedding(uuid, uuid, text, text) from public;
grant  execute on function lorekit_memory_set_embedding(uuid, uuid, text, text)
  to authenticated, service_role;

comment on function lorekit_memory_set_embedding(uuid, uuid, text, text) is
  'Writes memories.embedding + embedding_model for one row, authorised inside the function '
  '(lorekit_org_actor + lorekit_org_can for org-owned rows, actor identity for personal rows). '
  'Returns true when a row was written, false when none matched — the write path records that '
  'miss on its span rather than dropping the embedding silently, which is what rls_update did '
  'for org-owned memories before 00062.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00062', 'memory_embedding_write')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00063_activity_filters.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_activity — filter-aware (scope + dimension filters).
--
-- WHAT CHANGES: 00051's activity counted every visible memory in the window,
-- ignoring the Explorer's filter bar. The Explorer's stat header follows a
-- scope selection AND the dimension filters (label / agent / trigger / kind /
-- host / repo / branch / PR), and its numbers have to agree with the LIST under
-- them — the list already applies exactly these predicates (GET /memories). So
-- the written/scopes cards must count the same set the list shows.
--
-- HOW: the SAME per-dimension predicate as GET /memories and lorekit_memory_facets
-- (00057) — "OR within a dimension, AND across dimensions", each `*_mode`
-- choosing `in`/`nin` (and `tags` also `all`/`none`). Unlike the facets RPC there
-- is NO self-exclusion here: a straight count applies every filter directly, so
-- the CTE-of-flags collapses to a flat WHERE. `scope` is a hard filter (00057's
-- treatment). Every parameter is optional and defaulted, so a caller passing
-- only (p_user_id, p_bucket, p_since, p_until) gets byte-for-byte 00051's result.
--
-- Read-activity is deliberately NOT widened here: usage_events carries no
-- per-memory tag/agent/repo (only `scope`, 00058), so a dimension filter is
-- unanswerable for reads — the Read card stays scope-level by design.
--
-- Forward-only. The function is DROPped and recreated with a wider signature;
-- the handler is updated in lockstep. Bucket validation, the half-open
-- [p_since, p_until) window, the active-only + tenant predicate, and the
-- date_trunc anchoring are 00051 verbatim.
-- ═════════════════════════════════════════════════════════════════════════

drop function if exists lorekit_memory_activity(uuid, text, timestamptz, timestamptz);

create or replace function lorekit_memory_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null,
  -- Active filters, mirroring GET /memories' query params so the stat header can
  -- pass its filter bar verbatim. All optional: null/absent = not filtered.
  p_scope              text   default null,
  p_tags               text[] default null,
  p_tags_mode          text   default 'any',
  p_source_agent       text[] default null,
  p_source_agent_mode  text   default 'in',
  p_trigger            text[] default null,
  p_trigger_mode       text   default 'in',
  p_kind               text[] default null,
  p_kind_mode          text   default 'in',
  p_host               text[] default null,
  p_host_mode          text   default 'in',
  p_origin_repo        text[] default null,
  p_origin_repo_mode   text   default 'in',
  p_origin_branch      text[] default null,
  p_origin_branch_mode text   default 'in',
  p_origin_pr          text[] default null,
  p_origin_pr_mode     text   default 'in'
)
returns table (bucket timestamptz, scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  -- `origin_pr` is an INTEGER column: coerce the digits-only list numerically so
  -- this route matches GET /memories on the same input (00057's rationale). A
  -- non-numeric entry is dropped; a list reducing to empty applies no filter.
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, m.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           m.scope,
           count(*) as count
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
       and (p_since is null or m.created_at >= p_since)
       and (p_until is null or m.created_at <  p_until)
       -- Scope is a hard filter, always applied (00057's treatment).
       and (p_scope is null or m.scope = p_scope)
       -- Dimension filters — every one applied (no self-exclusion for a count).
       and (p_tags is null or case coalesce(p_tags_mode, 'any')
             when 'all'  then m.tags @> p_tags
             when 'none' then not (m.tags && p_tags)
             else m.tags && p_tags
           end)
       and (p_source_agent is null or case coalesce(p_source_agent_mode, 'in')
             when 'nin' then (m.source_agent is not null and m.source_agent <> all(p_source_agent))
             else m.source_agent = any(p_source_agent)
           end)
       and (p_trigger is null or case coalesce(p_trigger_mode, 'in')
             when 'nin' then (m.trigger is not null and m.trigger <> all(p_trigger))
             else m.trigger = any(p_trigger)
           end)
       and (p_kind is null or case coalesce(p_kind_mode, 'in')
             when 'nin' then (m.kind is not null and m.kind <> all(p_kind))
             else m.kind = any(p_kind)
           end)
       and (p_host is null or case coalesce(p_host_mode, 'in')
             when 'nin' then (m.host is not null and m.host <> all(p_host))
             else m.host = any(p_host)
           end)
       and (p_origin_repo is null or case coalesce(p_origin_repo_mode, 'in')
             when 'nin' then (m.origin_repo is not null and m.origin_repo <> all(p_origin_repo))
             else m.origin_repo = any(p_origin_repo)
           end)
       and (p_origin_branch is null or case coalesce(p_origin_branch_mode, 'in')
             when 'nin' then (m.origin_branch is not null and m.origin_branch <> all(p_origin_branch))
             else m.origin_branch = any(p_origin_branch)
           end)
       and (v_origin_pr is null or case coalesce(p_origin_pr_mode, 'in')
             when 'nin' then (m.origin_pr is not null and m.origin_pr <> all(v_origin_pr))
             else m.origin_pr = any(v_origin_pr)
           end)
     group by 1, m.scope
     order by 1 asc, m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
) from public, anon;
grant execute on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
) to authenticated, service_role;

comment on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
) is
  'Memories created per UTC hour/day per scope over the half-open
   [p_since, p_until) window, visible to the EFFECTIVE caller, narrowed by the
   optional scope + dimension filters (00063) — the SAME predicate as
   GET /memories and lorekit_memory_facets, so the stat header agrees with the
   list. With no filters supplied the result is byte-for-byte 00051''s.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00063', 'activity_filters')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00064_owner_filter.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Owner as a first-class filter DIMENSION (00064).
--
-- WHAT CHANGES: ownership (personal vs a shared org) was the ONE Explorer
-- filter narrowed CLIENT-side — a separate `OwnershipFilterBar` over the loaded
-- pages, so it could not agree with the server-filtered list, the drill-down
-- facet counts, or the stat header, and it silently missed rows past the page
-- the browser happened to hold. This folds it into the SAME "OR within a
-- dimension, AND across dimensions" machinery every other dimension already
-- uses (00057 facets, 00063 activity, GET /memories), as a new `owner` facet.
--
-- THE OWNER IDENTITY of a row is `personal` when `org_id is null`, else the
-- owning org's SLUG (stable, unlike its uuid or its display name). It is
-- resolved by a LEFT JOIN to `orgs`; a personal row has no org and takes the
-- literal `personal`. Slugs resolve against the caller's member orgs ONLY —
-- which the visibility predicate already guarantees, since an org-owned row is
-- visible solely through the `lorekit_member_org_ids` branch, so its joined
-- slug is always one of the caller's own orgs.
--
-- THE OWNER PREDICATE (mirrored byte-for-byte in both functions and in the
-- GET /memories handler):
--   in  → ('personal' = any(p_owner) AND org_id is null)
--          OR (org_id is not null AND o.slug = any(p_owner))
--   nin → identity is not null AND identity <> all(p_owner)   -- identity above
-- The `nin` guard mirrors every other scalar dimension's `(col is not null AND
-- col <> all(...))` shape; the computed identity is never null in practice
-- (personal → 'personal', visible org row → its slug), but the guard keeps the
-- three-valued-logic behaviour identical to its neighbours.
--
-- SELF-EXCLUSION, as for every drill-down dimension in 00057: the `owner` facet
-- cell applies every OTHER dimension's flag but NOT `ok_owner`, so standing on
-- `owner=personal` still lists the org you could switch to; and every OTHER
-- dimension's cell now additionally requires `ok_owner`, so picking an owner
-- narrows their counts to the list's set.
--
-- Forward-only. Both functions are DROPped at their 00057 / 00063 signatures
-- and recreated with `p_owner text[]` / `p_owner_mode text` APPENDED at the end
-- (defaulted, so a positional caller passing only the earlier args is
-- unaffected, and a bare call is byte-for-byte the prior behaviour). The DROP of
-- the exact prior signature is deliberate — leaving it in place would make the
-- named-arg handler calls ambiguous between two overloads.
-- ═════════════════════════════════════════════════════════════════════════

-- ── lorekit_memory_facets ────────────────────────────────────────────────────

drop function if exists lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text
);

create or replace function lorekit_memory_facets(
  p_user_id            uuid,
  p_archived           boolean default false,
  p_scope              text    default null,
  p_tags               text[]  default null,
  p_tags_mode          text    default 'any',
  p_source_agent       text[]  default null,
  p_source_agent_mode  text    default 'in',
  p_trigger            text[]  default null,
  p_trigger_mode       text    default 'in',
  p_kind               text[]  default null,
  p_kind_mode          text    default 'in',
  p_host               text[]  default null,
  p_host_mode          text    default 'in',
  p_origin_repo        text[]  default null,
  p_origin_repo_mode   text    default 'in',
  p_origin_branch      text[]  default null,
  p_origin_branch_mode text    default 'in',
  p_origin_pr          text[]  default null,
  p_origin_pr_mode     text    default 'in',
  -- Owner dimension (00064). `personal` plus one slug per member org with
  -- visible rows. All optional: null/absent = not filtered.
  p_owner              text[]  default null,
  p_owner_mode         text    default 'in'
)
returns table (facet text, value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
begin
  return query
  with base as (
    select
      m.tags, m.source_agent, m.trigger, m.kind, m.host,
      m.origin_repo, m.origin_branch, m.origin_pr,
      m.org_id, o.slug as org_slug,
      (p_tags is null or case coalesce(p_tags_mode, 'any')
         when 'all'  then m.tags @> p_tags
         when 'none' then not (m.tags && p_tags)
         else m.tags && p_tags
       end) as ok_tag,
      (p_source_agent is null or case coalesce(p_source_agent_mode, 'in')
         when 'nin' then (m.source_agent is not null and m.source_agent <> all(p_source_agent))
         else m.source_agent = any(p_source_agent)
       end) as ok_source_agent,
      (p_trigger is null or case coalesce(p_trigger_mode, 'in')
         when 'nin' then (m.trigger is not null and m.trigger <> all(p_trigger))
         else m.trigger = any(p_trigger)
       end) as ok_trigger,
      (p_kind is null or case coalesce(p_kind_mode, 'in')
         when 'nin' then (m.kind is not null and m.kind <> all(p_kind))
         else m.kind = any(p_kind)
       end) as ok_kind,
      (p_host is null or case coalesce(p_host_mode, 'in')
         when 'nin' then (m.host is not null and m.host <> all(p_host))
         else m.host = any(p_host)
       end) as ok_host,
      (p_origin_repo is null or case coalesce(p_origin_repo_mode, 'in')
         when 'nin' then (m.origin_repo is not null and m.origin_repo <> all(p_origin_repo))
         else m.origin_repo = any(p_origin_repo)
       end) as ok_origin_repo,
      (p_origin_branch is null or case coalesce(p_origin_branch_mode, 'in')
         when 'nin' then (m.origin_branch is not null and m.origin_branch <> all(p_origin_branch))
         else m.origin_branch = any(p_origin_branch)
       end) as ok_origin_branch,
      (v_origin_pr is null or case coalesce(p_origin_pr_mode, 'in')
         when 'nin' then (m.origin_pr is not null and m.origin_pr <> all(v_origin_pr))
         else m.origin_pr = any(v_origin_pr)
       end) as ok_origin_pr,
      -- Owner: the computed identity is `personal` (org_id null) or the org slug.
      (p_owner is null or case coalesce(p_owner_mode, 'in')
         when 'nin' then (
           (case when m.org_id is null then 'personal' else o.slug end) is not null
           and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
         )
         else (
           ('personal' = any(p_owner) and m.org_id is null)
           or (m.org_id is not null and o.slug = any(p_owner))
         )
       end) as ok_owner
      from memories m
      -- A personal row has no org, so this is a LEFT join; org rows resolve to
      -- their slug. Visible org rows are always the caller's own orgs (the
      -- visibility predicate below admits them only via lorekit_member_org_ids),
      -- so `o.slug` is never a slug the caller cannot see.
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and (p_scope is null or m.scope = p_scope)
  ), cells as (
    select 'tag'::text as facet, t.tag as value
      from base b
      cross join lateral unnest(b.tags) as t(tag)
     where b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'source_agent', b.source_agent from base b
     where b.ok_tag and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'trigger', b.trigger from base b
     where b.ok_tag and b.ok_source_agent and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'kind', b.kind from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'host', b.host from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_repo', b.origin_repo from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_branch', b.origin_branch from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_pr', b.origin_pr::text from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_owner
    union all
    -- Owner is the ONE dimension self-excluded here (every other flag, NOT
    -- ok_owner), so a drilled-in owner still lists the alternative owner.
    select 'owner', case when b.org_id is null then 'personal' else b.org_slug end from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
  )
  select c.facet, c.value, count(*) as count
    from cells c
   where c.value is not null
     and btrim(c.value) <> ''
   group by c.facet, c.value
   order by c.facet asc, count(*) desc, c.value asc;
end;
$$;

revoke execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text
) from public, anon;
grant execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text
) to authenticated, service_role;

comment on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text
) is
  'Value catalog with counts for every filterable memory dimension (tag,
   source_agent, trigger, kind, host, origin_repo, origin_branch, origin_pr,
   owner) over the partition selected by p_archived, visible to the EFFECTIVE
   caller. `owner` (00064) is `personal` for org_id-null rows, else the org
   slug. Counts are DRILL-DOWN (00057): each dimension is counted with every
   OTHER active filter applied but not its own (self-exclusion), so the numbers
   match what adding that value would yield. With no filters supplied the result
   is 00052''s global catalog plus the owner dimension. Same service-role-gated
   actor rule and ordering as lorekit_memory_tags.';

-- ── lorekit_memory_activity ──────────────────────────────────────────────────

drop function if exists lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
);

create or replace function lorekit_memory_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null,
  p_scope              text   default null,
  p_tags               text[] default null,
  p_tags_mode          text   default 'any',
  p_source_agent       text[] default null,
  p_source_agent_mode  text   default 'in',
  p_trigger            text[] default null,
  p_trigger_mode       text   default 'in',
  p_kind               text[] default null,
  p_kind_mode          text   default 'in',
  p_host               text[] default null,
  p_host_mode          text   default 'in',
  p_origin_repo        text[] default null,
  p_origin_repo_mode   text   default 'in',
  p_origin_branch      text[] default null,
  p_origin_branch_mode text   default 'in',
  p_origin_pr          text[] default null,
  p_origin_pr_mode     text   default 'in',
  -- Owner dimension (00064) — the SAME predicate as lorekit_memory_facets and
  -- GET /memories, so the stat header agrees with the list under an owner pill.
  p_owner              text[] default null,
  p_owner_mode         text   default 'in'
)
returns table (bucket timestamptz, scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, m.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           m.scope,
           count(*) as count
      from memories m
      -- LEFT join for the owner predicate — a personal row has no org (00064).
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
       and (p_since is null or m.created_at >= p_since)
       and (p_until is null or m.created_at <  p_until)
       and (p_scope is null or m.scope = p_scope)
       and (p_tags is null or case coalesce(p_tags_mode, 'any')
             when 'all'  then m.tags @> p_tags
             when 'none' then not (m.tags && p_tags)
             else m.tags && p_tags
           end)
       and (p_source_agent is null or case coalesce(p_source_agent_mode, 'in')
             when 'nin' then (m.source_agent is not null and m.source_agent <> all(p_source_agent))
             else m.source_agent = any(p_source_agent)
           end)
       and (p_trigger is null or case coalesce(p_trigger_mode, 'in')
             when 'nin' then (m.trigger is not null and m.trigger <> all(p_trigger))
             else m.trigger = any(p_trigger)
           end)
       and (p_kind is null or case coalesce(p_kind_mode, 'in')
             when 'nin' then (m.kind is not null and m.kind <> all(p_kind))
             else m.kind = any(p_kind)
           end)
       and (p_host is null or case coalesce(p_host_mode, 'in')
             when 'nin' then (m.host is not null and m.host <> all(p_host))
             else m.host = any(p_host)
           end)
       and (p_origin_repo is null or case coalesce(p_origin_repo_mode, 'in')
             when 'nin' then (m.origin_repo is not null and m.origin_repo <> all(p_origin_repo))
             else m.origin_repo = any(p_origin_repo)
           end)
       and (p_origin_branch is null or case coalesce(p_origin_branch_mode, 'in')
             when 'nin' then (m.origin_branch is not null and m.origin_branch <> all(p_origin_branch))
             else m.origin_branch = any(p_origin_branch)
           end)
       and (v_origin_pr is null or case coalesce(p_origin_pr_mode, 'in')
             when 'nin' then (m.origin_pr is not null and m.origin_pr <> all(v_origin_pr))
             else m.origin_pr = any(v_origin_pr)
           end)
       -- Owner: `personal` for org_id-null rows, else the org slug (00064).
       and (p_owner is null or case coalesce(p_owner_mode, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
             )
             else (
               ('personal' = any(p_owner) and m.org_id is null)
               or (m.org_id is not null and o.slug = any(p_owner))
             )
           end)
     group by 1, m.scope
     order by 1 asc, m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
) from public, anon;
grant execute on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
) to authenticated, service_role;

comment on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text
) is
  'Memories created per UTC hour/day per scope over the half-open
   [p_since, p_until) window, visible to the EFFECTIVE caller, narrowed by the
   optional scope + dimension filters (00063) plus the owner dimension (00064,
   `personal` / org slug) — the SAME predicate as GET /memories and
   lorekit_memory_facets, so the stat header agrees with the list. With no
   filters supplied the result is byte-for-byte 00051''s.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00064', 'owner_filter')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00065_memory_scopes_order_by_count.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- lorekit_memory_scopes — order the per-scope rollup by COUNT, not scope name.
--
-- WHY: the Lore Explorer's scope chip strip renders `GET /memories/scopes` in
-- the order the endpoint returns (`fetchScopes` maps but never re-sorts), so the
-- endpoint's ORDER BY *is* the chip order. Alphabetical put a one-memory scope
-- ahead of the account's busiest one; sorting by count surfaces the scopes a
-- reader actually works in first.
--
-- This also makes the two catalog endpoints consistent: `lorekit_memory_tags`
-- (00050) already orders `count desc, label asc`. `/scopes` was the odd one out
-- at `scope asc`; both now lead with frequency and break ties by name.
--
-- Signature and return type are unchanged, so a plain `create or replace` (no
-- DROP) suffices — unlike 00049, which had to DROP to add a column. Everything
-- else is carried over verbatim from 00049: the service-role-gated actor guard,
-- the `lorekit_member_org_ids` visibility predicate, the active-rows-only
-- definition (non-archived AND non-expired), `last_activity`, plpgsql-not-SQL so
-- the ordering survives, and the revoked PUBLIC/anon grant.
--
-- `count desc` is emitted as `count(*) desc` rather than the output alias `count`
-- to stay unambiguous under `#variable_conflict use_column`; `scope asc` is the
-- deterministic tiebreaker so equal-count scopes keep a stable order.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memory_scopes(p_user_id uuid)
returns table (scope text, count bigint, last_activity timestamptz)
language plpgsql
stable
security definer
set search_path = public
as $$
-- The RETURNS TABLE columns are also plpgsql OUT variables, so an unqualified
-- reference to any of them inside the query would be ambiguous. Every reference
-- below is table-qualified, and this directive makes the column win regardless.
#variable_conflict use_column
declare
  -- Honour a caller-supplied p_user_id only on a verified service-role
  -- connection (the edge resolves the token owner and passes it); an
  -- authenticated caller is pinned to its own auth.uid(), closing the
  -- cross-user scope-name enumeration. A NULL actor under service-role is the
  -- CI escape hatch, preserved by the first visibility branch below.
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
    select m.scope, count(*) as count, max(m.created_at) as last_activity
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
     group by m.scope
     order by count(*) desc, m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_scopes(uuid) from public, anon;
grant  execute on function lorekit_memory_scopes(uuid) to authenticated, service_role;

comment on function lorekit_memory_scopes(uuid) is
  'Per-scope active counts and last activity visible to the EFFECTIVE caller,
   ordered by count desc then scope asc (matching lorekit_memory_tags). Actor
   resolved by the 00046/00041 service-role-gated rule: a caller-supplied
   p_user_id is honoured only on a verified service-role connection, otherwise
   auth.uid() wins — so an authenticated caller can never enumerate another
   user''s scope names. p_user_id IS NULL under service-role is the CI escape
   hatch. last_activity is max(created_at) over the same counted rows.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00065', 'memory_scopes_order_by_count')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00066_dimension_filter_helpers.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Reusable dimension-filter predicates — one definition of what each mode
-- means, composed by every aggregate that narrows memories by dimension.
--
-- WHY: two aggregate functions apply the SAME per-dimension predicate — the
-- facet catalog `lorekit_memory_facets` (00057) and the write series
-- `lorekit_memory_activity` (00063), both later extended with the owner
-- dimension in 00064 — and each spelled it out INLINE, once per dimension.
-- `lorekit_memory_facets` carried eight `case` flags in its base CTE;
-- `lorekit_memory_activity` carried the same eight again in a flat WHERE.
-- Sixteen near-identical copies of a rule that is easy to get subtly wrong:
--
--     `nin` means `value is not null and value <> all(filter)`
--
-- The null test is load-bearing and non-obvious. `m.source_agent <> all(...)`
-- alone is NULL for a row with no agent, which reads as false, so "agent is not
-- aw" would silently drop every memory nobody attributed — the rows most likely
-- to be the ones you are hunting for. Written out sixteen times, one copy
-- eventually loses it, and the two callers disagree about a filter neither
-- author touched.
--
-- So the predicate becomes three tiny functions and every caller composes them.
-- They are `language sql` + `immutable` + a single expression, which is what
-- makes PostgreSQL INLINE them into the calling query: the planner still sees a
-- plain boolean expression over the column and can still use an index. A
-- plpgsql helper would have been a per-row function call and a planner barrier.
--
-- ── What this migration DELIBERATELY does NOT change ────────────────────────
--
-- This is a pure refactor. `lorekit_memory_facets` and `lorekit_memory_activity`
-- keep their 00064 SIGNATURES verbatim (including `p_owner` / `p_owner_mode`)
-- and their 00064 BEHAVIOUR to the row — only the eight text/tags/int dimension
-- predicates change, from inline `case` blocks to helper calls that are
-- identical to them. The owner dimension stays INLINE: it is not a scalar
-- text/tags/int column but a LEFT JOIN-computed identity (`personal` / org
-- slug), so it is not one of the three helpers. `migrations.test.sql` §68 /
-- §69 (incl. the owner §69c) is the executable proof that behaviour did not
-- move; §80 (added here) pins the helpers directly.
--
-- `create or replace` (not drop): the signatures are unchanged, so the body is
-- swapped in place and the 00064 grants persist. The revoke/grant is re-stated
-- for the same self-documenting reason every prior migration re-states it.
-- ═════════════════════════════════════════════════════════════════════════

-- ── 1. The three predicates ─────────────────────────────────────────────────

-- A scalar text column against a value list. Covers source_agent, trigger,
-- kind, host, origin_repo and origin_branch — every single-valued text
-- dimension the filter bar offers.
--
-- `immutable`, not `stable`: the result depends only on the arguments. That is
-- also what lets the planner fold it into an index-usable expression.
create or replace function lorekit_match_text(
  p_value  text,
  p_filter text[],
  p_mode   text
)
returns boolean
language sql
immutable
parallel safe
as $$
  select coalesce(
    p_filter is null
    or case coalesce(p_mode, 'in')
         -- The null test that is the whole reason this function exists: a row
         -- with no value must NOT satisfy "is not one of these". Without it the
         -- comparison is NULL, which filters the row out — silently hiding
         -- every unattributed row from a negated filter.
         when 'nin' then (p_value is not null and p_value <> all(p_filter))
         else p_value = any(p_filter)
       end,
    false);
$$;

comment on function lorekit_match_text(text, text[], text) is
  'Does a scalar text column satisfy a value-list filter? `nin` negates and
   requires the value to be NON-NULL, so an unattributed row is excluded from a
   negated filter rather than silently dropped by NULL logic. A null filter is
   "not filtered" and matches everything. Inlinable (sql/immutable), so callers
   keep index access.';

-- A `text[]` column (memories.tags) against a label list. Three modes rather
-- than two, because a column holding MANY values admits containment: `all` is
-- @>, `any` is &&, and `none` is the negation of `any`.
create or replace function lorekit_match_tags(
  p_value  text[],
  p_filter text[],
  p_mode   text
)
returns boolean
language sql
immutable
parallel safe
as $$
  select coalesce(
    p_filter is null
    or case coalesce(p_mode, 'any')
         when 'all'  then p_value @> p_filter
         -- NOT(carries any), never NOT(carries all): the latter would also
         -- admit a row carrying all but one of the named labels.
         when 'none' then not (p_value && p_filter)
         else p_value && p_filter
       end,
    false);
$$;

comment on function lorekit_match_tags(text[], text[], text) is
  'Does a label array satisfy a label filter? `all` is containment (@>), `any`
   is overlap (&&), `none` is the negation of `any` — never the negation of
   `all`, which would admit a row carrying all but one named label. A null
   filter matches everything. Inlinable.';

-- An integer column (memories.origin_pr) against a value list.
--
-- Separate from the text helper because the column is an INTEGER and the
-- comparison must be numeric: `GET /memories` sends the digits bare to the
-- integer column, so Postgres reads `007` as 7 and matches PR 7. Comparing
-- `origin_pr::text` would match nothing for that same input and the two routes
-- would disagree about one query string. The digits-only coercion (dropping a
-- non-numeric entry, applying no filter when the list reduces to empty) happens
-- at the CALLER, so this helper only ever receives an already-numeric array.
create or replace function lorekit_match_int(
  p_value  integer,
  p_filter integer[],
  p_mode   text
)
returns boolean
language sql
immutable
parallel safe
as $$
  select coalesce(
    p_filter is null
    or case coalesce(p_mode, 'in')
         when 'nin' then (p_value is not null and p_value <> all(p_filter))
         else p_value = any(p_filter)
       end,
    false);
$$;

comment on function lorekit_match_int(integer, integer[], text) is
  'Integer counterpart of lorekit_match_text, for memories.origin_pr. Numeric
   comparison so `007` matches PR 7, exactly as GET /memories does. Inlinable.';

-- These are pure predicates that touch no data, so the default PUBLIC EXECUTE is
-- harmless — but this repo revokes PUBLIC/anon on every function it ships rather
-- than relying on the default, so match that pattern here too. It does not
-- affect inlining (which depends on the sql/immutable/single-expression shape,
-- not on the grant), and the SECURITY DEFINER callers reach them as their owner.
revoke execute on function lorekit_match_text(text, text[], text)        from public, anon;
revoke execute on function lorekit_match_tags(text[], text[], text)      from public, anon;
revoke execute on function lorekit_match_int(integer, integer[], text)   from public, anon;
grant  execute on function lorekit_match_text(text, text[], text)        to authenticated, service_role;
grant  execute on function lorekit_match_tags(text[], text[], text)      to authenticated, service_role;
grant  execute on function lorekit_match_int(integer, integer[], text)   to authenticated, service_role;

-- ── 2. lorekit_memory_facets — composes the helpers ─────────────────────────
--
-- Signature UNCHANGED from 00064 (so no caller moves) and behaviour unchanged:
-- this replaces the eight inline `case` flags in the base CTE with the helper
-- calls they are now identical to. The point is that there is one definition of
-- what `nin` means rather than two — the whole reason the helpers exist, and
-- undermined by leaving this function as the second copy. Owner stays inline:
-- it is a LEFT JOIN-computed identity, not one of the three column helpers.
--
-- Everything else — the actor rule, the tenant predicate (lorekit_member_org_ids),
-- the archived partition, the LEFT JOIN orgs, the owner predicate + owner-dimension
-- self-exclusion, the null/blank drop and the ordering — is 00064's verbatim.
create or replace function lorekit_memory_facets(
  p_user_id            uuid,
  p_archived           boolean default false,
  p_scope              text    default null,
  p_tags               text[]  default null,
  p_tags_mode          text    default 'any',
  p_source_agent       text[]  default null,
  p_source_agent_mode  text    default 'in',
  p_trigger            text[]  default null,
  p_trigger_mode       text    default 'in',
  p_kind               text[]  default null,
  p_kind_mode          text    default 'in',
  p_host               text[]  default null,
  p_host_mode          text    default 'in',
  p_origin_repo        text[]  default null,
  p_origin_repo_mode   text    default 'in',
  p_origin_branch      text[]  default null,
  p_origin_branch_mode text    default 'in',
  p_origin_pr          text[]  default null,
  p_origin_pr_mode     text    default 'in',
  -- Owner dimension (00064). `personal` plus one slug per member org with
  -- visible rows. All optional: null/absent = not filtered.
  p_owner              text[]  default null,
  p_owner_mode         text    default 'in'
)
returns table (facet text, value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
begin
  return query
  with base as (
    select
      m.tags, m.source_agent, m.trigger, m.kind, m.host,
      m.origin_repo, m.origin_branch, m.origin_pr,
      m.org_id, o.slug as org_slug,
      -- Per-dimension match flag, now from the shared predicates so it cannot
      -- drift from lorekit_memory_activity's. A null filter is "not filtered" →
      -- the helper returns true, so an untouched dimension never narrows.
      lorekit_match_tags(m.tags,          p_tags,          p_tags_mode)          as ok_tag,
      lorekit_match_text(m.source_agent,  p_source_agent,  p_source_agent_mode)  as ok_source_agent,
      lorekit_match_text(m.trigger,       p_trigger,       p_trigger_mode)       as ok_trigger,
      lorekit_match_text(m.kind,          p_kind,          p_kind_mode)          as ok_kind,
      lorekit_match_text(m.host,          p_host,          p_host_mode)          as ok_host,
      lorekit_match_text(m.origin_repo,   p_origin_repo,   p_origin_repo_mode)   as ok_origin_repo,
      lorekit_match_text(m.origin_branch, p_origin_branch, p_origin_branch_mode) as ok_origin_branch,
      lorekit_match_int (m.origin_pr,     v_origin_pr,     p_origin_pr_mode)     as ok_origin_pr,
      -- Owner: the computed identity is `personal` (org_id null) or the org slug.
      -- Stays inline — it is not one of the three column helpers (00064).
      (p_owner is null or case coalesce(p_owner_mode, 'in')
         when 'nin' then (
           (case when m.org_id is null then 'personal' else o.slug end) is not null
           and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
         )
         else (
           ('personal' = any(p_owner) and m.org_id is null)
           or (m.org_id is not null and o.slug = any(p_owner))
         )
       end) as ok_owner
      from memories m
      -- A personal row has no org, so this is a LEFT join; org rows resolve to
      -- their slug. Visible org rows are always the caller's own orgs (the
      -- visibility predicate below admits them only via lorekit_member_org_ids),
      -- so `o.slug` is never a slug the caller cannot see.
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and (p_scope is null or m.scope = p_scope)
  ), cells as (
    select 'tag'::text as facet, t.tag as value
      from base b
      cross join lateral unnest(b.tags) as t(tag)
     where b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'source_agent', b.source_agent from base b
     where b.ok_tag and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'trigger', b.trigger from base b
     where b.ok_tag and b.ok_source_agent and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'kind', b.kind from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'host', b.host from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_repo', b.origin_repo from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_branch', b.origin_branch from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_pr', b.origin_pr::text from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_owner
    union all
    -- Owner is the ONE dimension self-excluded here (every other flag, NOT
    -- ok_owner), so a drilled-in owner still lists the alternative owner.
    select 'owner', case when b.org_id is null then 'personal' else b.org_slug end from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
  )
  select c.facet, c.value, count(*) as count
    from cells c
   where c.value is not null
     and btrim(c.value) <> ''
   group by c.facet, c.value
   order by c.facet asc, count(*) desc, c.value asc;
end;
$$;

revoke execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text
) from public, anon;
grant execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text
) to authenticated, service_role;

comment on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text
) is
  'Value catalog with counts for every filterable memory dimension (tag,
   source_agent, trigger, kind, host, origin_repo, origin_branch, origin_pr,
   owner) over the partition selected by p_archived, visible to the EFFECTIVE
   caller. `owner` (00064) is `personal` for org_id-null rows, else the org
   slug. Counts are DRILL-DOWN (00057): each dimension is counted with every
   OTHER active filter applied but not its own (self-exclusion), so the numbers
   match what adding that value would yield. The eight text/tags/int dimension
   predicates come from lorekit_match_text / _tags / _int (00066) so their
   semantics cannot drift from lorekit_memory_activity; owner stays inline. With
   no filters supplied the result is 00052''s global catalog plus the owner
   dimension. Same service-role-gated actor rule and ordering as
   lorekit_memory_tags.';

-- ── 3. lorekit_memory_activity — composes the same helpers ──────────────────
--
-- Signature UNCHANGED from 00064. Unlike the facet catalog there is NO
-- self-exclusion here: a straight count applies every filter directly, so the
-- eight dimension predicates collapse to a flat WHERE. Replacing the inline
-- `case` blocks with the helper calls keeps the series byte-identical to 00064
-- and provably in step with the facet catalog. Owner stays inline. Bucket
-- validation, the half-open [p_since, p_until) window, the active-only + tenant
-- predicate, the LEFT JOIN orgs and the date_trunc anchoring are 00064 verbatim.
create or replace function lorekit_memory_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null,
  p_scope              text   default null,
  p_tags               text[] default null,
  p_tags_mode          text   default 'any',
  p_source_agent       text[] default null,
  p_source_agent_mode  text   default 'in',
  p_trigger            text[] default null,
  p_trigger_mode       text   default 'in',
  p_kind               text[] default null,
  p_kind_mode          text   default 'in',
  p_host               text[] default null,
  p_host_mode          text   default 'in',
  p_origin_repo        text[] default null,
  p_origin_repo_mode   text   default 'in',
  p_origin_branch      text[] default null,
  p_origin_branch_mode text   default 'in',
  p_origin_pr          text[] default null,
  p_origin_pr_mode     text   default 'in',
  -- Owner dimension (00064) — the SAME predicate as lorekit_memory_facets and
  -- GET /memories, so the stat header agrees with the list under an owner pill.
  p_owner              text[] default null,
  p_owner_mode         text   default 'in'
)
returns table (bucket timestamptz, scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  -- `origin_pr` is an INTEGER column: coerce the digits-only list numerically so
  -- this route matches GET /memories on the same input (00057's rationale). A
  -- non-numeric entry is dropped; a list reducing to empty applies no filter.
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, m.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           m.scope,
           count(*) as count
      from memories m
      -- LEFT join for the owner predicate — a personal row has no org (00064).
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
       and (p_since is null or m.created_at >= p_since)
       and (p_until is null or m.created_at <  p_until)
       -- Scope is a hard filter, always applied (00057's treatment).
       and (p_scope is null or m.scope = p_scope)
       -- Dimension filters — AND across, OR within, from the shared predicates
       -- (00066) so the semantics cannot drift from lorekit_memory_facets. No
       -- self-exclusion here: a straight count applies every one directly.
       and lorekit_match_tags(m.tags,          p_tags,          p_tags_mode)
       and lorekit_match_text(m.source_agent,  p_source_agent,  p_source_agent_mode)
       and lorekit_match_text(m.trigger,       p_trigger,       p_trigger_mode)
       and lorekit_match_text(m.kind,          p_kind,          p_kind_mode)
       and lorekit_match_text(m.host,          p_host,          p_host_mode)
       and lorekit_match_text(m.origin_repo,   p_origin_repo,   p_origin_repo_mode)
       and lorekit_match_text(m.origin_branch, p_origin_branch, p_origin_branch_mode)
       and lorekit_match_int (m.origin_pr,     v_origin_pr,     p_origin_pr_mode)
       -- Owner: `personal` for org_id-null rows, else the org slug (00064).
       and (p_owner is null or case coalesce(p_owner_mode, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
             )
             else (
               ('personal' = any(p_owner) and m.org_id is null)
               or (m.org_id is not null and o.slug = any(p_owner))
             )
           end)
     group by 1, m.scope
     order by 1 asc, m.scope asc;
end;
$$;

