-- ─────────────────────────────────────────────────────────────────────────────
-- 00092_list_retention_conditions.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Explorer preview of retention-policy conditions: the SAME three thresholds
-- `lorekit_groom_candidates` (00088) matches a saved policy on, added to
-- `lorekit_memory_list` (00067/00069) so the dashboard's Lore Explorer can
-- filter its list to the lessons a policy WOULD catch, before any policy is
-- ever saved. This is the "verify before you run it" gap: `groom.preview`
-- already answers "how many and which keys", but the Explorer renders full
-- lesson cards, not a bare key list, and a reader wants to see those cards
-- narrowed the same way the filter bar narrows every other dimension.
--
-- Deliberately NOT folded into `lorekit_groom_candidates` itself, and not a
-- ninth `MemoryDimensions` entry: these three are numeric THRESHOLDS against
-- `created_at`/`last_seen_at`/`seen_count`, not a categorical value-list like
-- `tags`/`kind`/`host`, so they compose with the list route's OWN predicate
-- rather than the dimension-filter helpers (00066). The predicate expression
-- is copied verbatim from `lorekit_groom_candidates` (00088) — same three
-- conditions, same "never-seen coalesces to `-infinity`" reading of
-- `unseen_days` — so a value that would match a saved policy always matches
-- here too; `groom.spec.ts`'s TypeScript mirror is unaffected, since this
-- migration adds a second SQL caller of the same rule rather than changing it.
--
-- Purely ADDITIVE: three new trailing parameters, all defaulting to `null`
-- ("not filtered"), so behaviour is unchanged for every existing caller —
-- the CLI, the MCP surface, and every caller that does not pass them see the
-- exact same rows as before. Callers use PostgREST's named-argument RPC form
-- (a JSON object, not a positional call), so appending parameters at the END
-- of the signature — rather than inserting them in reading order — needs no
-- renumbering of any `$N` placeholder already in the function body; the
-- three new placeholders are likewise appended to the end of the
-- `using (...)` list.
--
-- `create or replace` only replaces a function with the SAME argument list;
-- it cannot change a signature. The existing 35-arg overload (00069) has to
-- be dropped first, or it and this new 38-arg one coexist as two overloads —
-- PostgREST's named-argument RPC form then can't pick one and every call
-- through `lorekit_memory_list` becomes ambiguous.
drop function if exists lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[]
);

create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  -- The retention-policy preview trio (see header). All optional; `null`
  -- (the default) applies no filter, exactly like every other parameter here.
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null
)
returns table (
  id            uuid,
  scope         text,
  key           text,
  value         text,
  tags          text[],
  source_agent  text,
  trigger       text,
  created_at    timestamptz,
  updated_at    timestamptz,
  expires_at    timestamptz,
  archived_at   timestamptz,
  origin_repo   text,
  origin_branch text,
  origin_commit text,
  origin_pr     integer,
  kind          text,
  host          text,
  seen_count    integer,
  org_id        uuid,
  created_by    uuid,
  updated_by    uuid,
  org_name      text,
  org_slug      text
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       -- The retention-policy preview trio, copied verbatim from
       -- `lorekit_groom_candidates` (00088) — see header.
       and ($35 is null or m.created_at <= now() - ($35 * interval '1 day'))
       and ($36 is null or coalesce(m.last_seen_at, '-infinity'::timestamptz) <= now() - ($36 * interval '1 day'))
       and ($37 is null or m.seen_count <= $37)
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count;
end;
$$;

revoke execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
) from public, anon;
grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00092', 'list_retention_conditions')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00093_policy_dimension_filters.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Retention policies, part 3: the SAME eight dimension filters the Lore
-- Explorer's filter bar offers (label/kind/host/agent/trigger/repo/branch/PR
-- — `lib/filters.ts`'s `FILTER_FIELDS`, minus `owner`: a policy's `scope`
-- already partitions personal-vs-org lore, so a second ownership predicate
-- would either agree with it or silently fight it).
--
-- Until now a policy could only narrow by scope + the three age/activity
-- thresholds (00088). "Create retention policy" on the Explorer therefore
-- dropped every dimension filter a reader had set — the exact gap this
-- migration closes, so a policy created FROM a filtered Explorer view
-- actually reproduces that view's narrowing, not just its age conditions.
--
-- Reuses the dimension-filter helpers `lorekit_memory_facets`/
-- `lorekit_memory_list` already compose (`lorekit_match_text` /
-- `lorekit_match_tags`, migration 00066) — one definition of what `nin` /
-- `all`/`any`/`none` mean, not a third copy of it. `origin_pr` matches as
-- TEXT here (`m.origin_pr::text` against a digit-string filter), not via
-- `lorekit_match_int`: the wire and the Explorer's filter bar both speak
-- digit strings for this dimension (`ListMemoriesBodySchema.origin_pr` is a
-- string list too), and a policy's stored `origin_pr` column is `text[]` to
-- match — avoiding a second representation for the one dimension that would
-- otherwise need it.
--
-- 1. retention_policies — eight new (filter, mode) column pairs, all
--    nullable and defaulting to null/'in' — additive, so every existing row
--    reads back with every new filter "not narrowed", unchanged behaviour.
alter table retention_policies
  add column if not exists tags                text[],
  add column if not exists tags_mode           text default 'any',
  add column if not exists source_agent        text[],
  add column if not exists source_agent_mode   text default 'in',
  add column if not exists trigger             text[],
  add column if not exists trigger_mode        text default 'in',
  add column if not exists kind                text[],
  add column if not exists kind_mode           text default 'in',
  add column if not exists host                text[],
  add column if not exists host_mode           text default 'in',
  add column if not exists origin_repo         text[],
  add column if not exists origin_repo_mode    text default 'in',
  add column if not exists origin_branch       text[],
  add column if not exists origin_branch_mode  text default 'in',
  add column if not exists origin_pr           text[],
  add column if not exists origin_pr_mode      text default 'in';

-- 2. lorekit_groom_candidates — the single source of truth for "what
--    matches", extended with the eight filters. `language sql`, so the new
--    parameters are referenced by NAME in the body, not by a `$N` position —
--    unlike `lorekit_memory_list` (00092), this function has no dynamic
--    `execute format(...)` to renumber. Appended at the end of the argument
--    list so this is additive for the same reason 00092's append was: every
--    caller uses PostgREST's named-argument RPC form, so an appended,
--    defaulted parameter changes no existing caller's behaviour.
--
--    `create or replace` only replaces a function whose PARAMETER LIST
--    matches exactly — a longer list (even all-defaulted) creates a SECOND
--    overload instead, and a 5-arg call then becomes ambiguous ("not unique")
--    because both overloads can satisfy it via defaults. Drop the 00088
--    signature first so there is exactly one `lorekit_groom_candidates`.
drop function if exists lorekit_groom_candidates(uuid, text, integer, integer, integer);

create or replace function lorekit_groom_candidates(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in'
)
returns table (id uuid, scope text, key text)
language sql
stable
security definer
set search_path = public
as $$
  select m.id, m.scope, m.key
    from memories m
   where m.user_id = p_user_id
     and m.archived_at is null
     and m.protected = false
     and (
       p_scope = 'global'
       or m.scope = p_scope
       or (
         p_scope like 'repo::%'
         and starts_with(m.scope, 'branch::' || substring(p_scope from 7) || '::')
       )
     )
     and (p_min_age_days is null or m.created_at <= now() - (p_min_age_days * interval '1 day'))
     and (p_unseen_days is null or coalesce(m.last_seen_at, '-infinity'::timestamptz) <= now() - (p_unseen_days * interval '1 day'))
     and (p_max_seen_count is null or m.seen_count <= p_max_seen_count)
     and lorekit_match_tags(m.tags,               p_tags,          p_tags_mode)
     and lorekit_match_text(m.source_agent,       p_source_agent,   p_source_agent_mode)
     and lorekit_match_text(m.trigger,            p_trigger,        p_trigger_mode)
     and lorekit_match_text(m.kind,               p_kind,           p_kind_mode)
     and lorekit_match_text(m.host,               p_host,           p_host_mode)
     and lorekit_match_text(m.origin_repo,        p_origin_repo,    p_origin_repo_mode)
     and lorekit_match_text(m.origin_branch,      p_origin_branch,  p_origin_branch_mode)
     and lorekit_match_text(m.origin_pr::text,    p_origin_pr,      p_origin_pr_mode)
   order by m.scope, m.key;
$$;

grant execute on function lorekit_groom_candidates(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
) to authenticated, service_role;

-- 3. lorekit_groom_run — forwards the same eight filters to
--    lorekit_groom_candidates (never a second candidate query). Same
--    overload hazard as above — drop the 00088 5-arg signature first.
drop function if exists lorekit_groom_run(uuid, text, integer, integer, integer);

create or replace function lorekit_groom_run(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in'
)
returns table (archived integer, keys jsonb)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ids   uuid[];
  v_keys  jsonb;
  v_count integer := 0;
begin
  select coalesce(array_agg(c.id), '{}'),
         coalesce(jsonb_agg(jsonb_build_object('scope', c.scope, 'key', c.key)), '[]'::jsonb)
    into v_ids, v_keys
    from lorekit_groom_candidates(
      p_user_id, p_scope, p_min_age_days, p_unseen_days, p_max_seen_count,
      p_tags, p_tags_mode, p_source_agent, p_source_agent_mode,
      p_trigger, p_trigger_mode, p_kind, p_kind_mode, p_host, p_host_mode,
      p_origin_repo, p_origin_repo_mode, p_origin_branch, p_origin_branch_mode,
      p_origin_pr, p_origin_pr_mode
    ) c;

  if array_length(v_ids, 1) is null then
    return query select 0, '[]'::jsonb;
    return;
  end if;

  update memories m
     set archived_at = now()
   where m.id = any(v_ids)
     and m.archived_at is null;
  get diagnostics v_count = row_count;

  return query select v_count, v_keys;
end;
$$;

grant execute on function lorekit_groom_run(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
) to authenticated, service_role;

-- 4. lorekit_groom_sweep — passes a swept policy's new filter columns
--    through to lorekit_groom_run, unchanged shape otherwise.
create or replace function lorekit_groom_sweep()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_policy retention_policies%rowtype;
  v_result record;
  v_total  integer := 0;
begin
  for v_policy in
    select * from retention_policies where mode = 'auto' and enabled = true
  loop
    select * into v_result
      from lorekit_groom_run(
        v_policy.user_id, v_policy.scope,
        v_policy.min_age_days, v_policy.unseen_days, v_policy.max_seen_count,
        v_policy.tags, v_policy.tags_mode,
        v_policy.source_agent, v_policy.source_agent_mode,
        v_policy.trigger, v_policy.trigger_mode,
        v_policy.kind, v_policy.kind_mode,
        v_policy.host, v_policy.host_mode,
        v_policy.origin_repo, v_policy.origin_repo_mode,
        v_policy.origin_branch, v_policy.origin_branch_mode,
        v_policy.origin_pr, v_policy.origin_pr_mode
      );
    v_total := v_total + coalesce(v_result.archived, 0);
  end loop;

  return v_total;
end;
$$;

grant execute on function lorekit_groom_sweep() to service_role;

-- 5. lorekit_policy_create — the eight filters, appended. Same overload
--    hazard as `lorekit_groom_candidates` above — drop the 00088 8-arg
--    signature first.
drop function if exists lorekit_policy_create(uuid, text, text, text, boolean, integer, integer, integer);

create or replace function lorekit_policy_create(
  p_user_id             uuid,
  p_scope               text,
  p_name                text,
  p_mode                text    default 'review',
  p_enabled             boolean default false,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in'
)
returns setof retention_policies
language sql
security definer
set search_path = public
as $$
  insert into retention_policies (
    user_id, scope, name, mode, enabled, min_age_days, unseen_days, max_seen_count,
    tags, tags_mode, source_agent, source_agent_mode, trigger, trigger_mode,
    kind, kind_mode, host, host_mode, origin_repo, origin_repo_mode,
    origin_branch, origin_branch_mode, origin_pr, origin_pr_mode
  )
  values (
    p_user_id, p_scope, p_name, p_mode, p_enabled, p_min_age_days, p_unseen_days, p_max_seen_count,
    p_tags, p_tags_mode, p_source_agent, p_source_agent_mode, p_trigger, p_trigger_mode,
    p_kind, p_kind_mode, p_host, p_host_mode, p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode, p_origin_pr, p_origin_pr_mode
  )
  returning *;
$$;

grant execute on function lorekit_policy_create(
  uuid, text, text, text, boolean, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
) to authenticated, service_role;

-- 6. lorekit_policy_update — the same has-key / json-null-clears JSONB patch
--    convention as 00088, extended to the eight new array + mode columns. An
--    array column's clear needs its own branch (`p_patch->'tags' = 'null'::jsonb`)
--    because `jsonb_array_elements_text` raises on a JSON null rather than
--    returning zero rows.
create or replace function lorekit_policy_update(
  p_user_id uuid,
  p_id      uuid,
  p_patch   jsonb
)
returns setof retention_policies
language sql
security definer
set search_path = public
as $$
  update retention_policies
     set name                = case when p_patch ? 'name'                then p_patch ->> 'name'                          else name end,
         mode                 = case when p_patch ? 'mode'                then p_patch ->> 'mode'                          else mode end,
         enabled              = case when p_patch ? 'enabled'             then (p_patch ->> 'enabled')::boolean            else enabled end,
         min_age_days         = case when p_patch ? 'min_age_days'        then (p_patch ->> 'min_age_days')::integer       else min_age_days end,
         unseen_days          = case when p_patch ? 'unseen_days'         then (p_patch ->> 'unseen_days')::integer        else unseen_days end,
         max_seen_count       = case when p_patch ? 'max_seen_count'      then (p_patch ->> 'max_seen_count')::integer     else max_seen_count end,
         tags                 = case when p_patch ? 'tags'                then (case when p_patch -> 'tags'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'tags')) end)                else tags end,
         tags_mode            = case when p_patch ? 'tags_mode'           then p_patch ->> 'tags_mode'                     else tags_mode end,
         source_agent         = case when p_patch ? 'source_agent'        then (case when p_patch -> 'source_agent'        = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'source_agent')) end)         else source_agent end,
         source_agent_mode    = case when p_patch ? 'source_agent_mode'   then p_patch ->> 'source_agent_mode'             else source_agent_mode end,
         trigger              = case when p_patch ? 'trigger'             then (case when p_patch -> 'trigger'             = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'trigger')) end)              else trigger end,
         trigger_mode         = case when p_patch ? 'trigger_mode'        then p_patch ->> 'trigger_mode'                  else trigger_mode end,
         kind                 = case when p_patch ? 'kind'                then (case when p_patch -> 'kind'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'kind')) end)                 else kind end,
         kind_mode            = case when p_patch ? 'kind_mode'           then p_patch ->> 'kind_mode'                     else kind_mode end,
         host                 = case when p_patch ? 'host'                then (case when p_patch -> 'host'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'host')) end)                 else host end,
         host_mode            = case when p_patch ? 'host_mode'           then p_patch ->> 'host_mode'                     else host_mode end,
         origin_repo          = case when p_patch ? 'origin_repo'         then (case when p_patch -> 'origin_repo'         = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_repo')) end)          else origin_repo end,
         origin_repo_mode     = case when p_patch ? 'origin_repo_mode'    then p_patch ->> 'origin_repo_mode'              else origin_repo_mode end,
         origin_branch        = case when p_patch ? 'origin_branch'       then (case when p_patch -> 'origin_branch'       = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_branch')) end)        else origin_branch end,
         origin_branch_mode   = case when p_patch ? 'origin_branch_mode'  then p_patch ->> 'origin_branch_mode'            else origin_branch_mode end,
         origin_pr            = case when p_patch ? 'origin_pr'           then (case when p_patch -> 'origin_pr'           = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_pr')) end)            else origin_pr end,
         origin_pr_mode       = case when p_patch ? 'origin_pr_mode'      then p_patch ->> 'origin_pr_mode'                else origin_pr_mode end
   where id = p_id and user_id = p_user_id
  returning *;
$$;

grant execute on function lorekit_policy_update(uuid, uuid, jsonb) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00093', 'policy_dimension_filters')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00094_memory_list_total_count.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- The Lore Explorer's header shows how many memories a scope/search/filter/
-- retention view actually matches ("12 of 128"), but `lorekit_memory_list`
-- (00067/00069/00092) only ever returned a PAGE — `limit + 1` rows, so the
-- REST handler could tell "is there another page" but not "how many rows
-- match in total". The dashboard was filling that gap with how many rows it
-- had LOADED so far, which understates the true match for any view spanning
-- more than one page (a "50+ of 2897" that never resolves past 50 for an
-- account with thousands of matches) — a floor pretending to be a fact.
--
-- Adds ONE extra output column, `total_count`, computed with
-- `count(*) over ()` — a window function evaluated over every row the WHERE
-- clause matched, BEFORE the `limit` in the same query cuts it down to a page.
-- This is the standard "exact total alongside a LIMITed page" technique and
-- costs no second round trip: every row of the page carries the same
-- `total_count`, so the caller reads it off the first row (or 0 for an empty
-- page) rather than issuing a companion COUNT query.
--
-- Purely ADDITIVE to behaviour: the WHERE clause, its 38 parameters and their
-- defaults are UNCHANGED, so the CLI, the MCP surface and every existing
-- caller see the exact same rows in the exact same order — only the returned
-- ROW SHAPE gains one column. `create or replace` cannot change a return
-- type, so the existing 38-arg overload has to be dropped first, exactly as
-- 00092 dropped the 35-arg one it replaced.
drop function if exists lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
);

create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null
)
returns table (
  id            uuid,
  scope         text,
  key           text,
  value         text,
  tags          text[],
  source_agent  text,
  trigger       text,
  created_at    timestamptz,
  updated_at    timestamptz,
  expires_at    timestamptz,
  archived_at   timestamptz,
  origin_repo   text,
  origin_branch text,
  origin_commit text,
  origin_pr     integer,
  kind          text,
  host          text,
  seen_count    integer,
  org_id        uuid,
  created_by    uuid,
  updated_by    uuid,
  org_name      text,
  org_slug      text,
  -- Exact count of every row the WHERE clause matched, ignoring `limit` —
  -- see header. Identical on every row of the result; a caller reads it off
  -- the first row (or treats an empty result as 0).
  total_count   integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug,
      (count(*) over ())::integer as total_count
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       and ($35 is null or m.created_at <= now() - ($35 * interval '1 day'))
       and ($36 is null or coalesce(m.last_seen_at, '-infinity'::timestamptz) <= now() - ($36 * interval '1 day'))
       and ($37 is null or m.seen_count <= $37)
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count;
end;
$$;

revoke execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
) from public, anon;
grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00094', 'memory_list_total_count')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00095_groom_sweep_telemetry.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Retention-policy sweep telemetry.
--
-- `lorekit_groom_sweep()` (00088, re-created in 00093) is the nightly
-- auto-archive pass — and it has ALWAYS been invisible end-to-end. pg_cron
-- calls it directly as a raw SQL statement, entirely inside Postgres: no
-- span, no metric, nothing distinguishes "ran and archived nothing" from
-- "did not run at all" from "failed silently". An operator staring at
-- unchanged data has no telemetry to tell those apart from here — the exact
-- report this migration exists to fix.
--
-- Mirrors the ALREADY-SOLVED identical problem one migration family over:
-- `lorekit_export_db_query_stats()` / the `profiling` Edge Function (00074,
-- docs/otel.md "Query-level profiling"). Same shape, applied to the sweep
-- instead of the stats scrape:
--
--   pg_cron (nightly, 03:17 UTC)
--     └── lorekit_export_groom_sweep()       ← inert without vault secrets
--           └── pg_net → POST /functions/v1/groom-sweep
--                 └── lorekit_groom_sweep_and_record()  ← THIS migration
--                       └── lorekit_groom_sweep()         ← UNCHANGED (00093)
--
-- `lorekit_groom_sweep_and_record()` does not touch `lorekit_groom_sweep()`'s
-- tested behaviour at all — it calls it exactly as pg_cron always has, then
-- records the result into a persistent counter row so the Edge Function can
-- export TRUE cumulative sums (matching db-query-metrics.ts's convention)
-- instead of a per-run delta needing its own reset-detection.

-- 1. groom_sweep_stats — a SINGLETON counter row. `id` is fixed to TRUE by
--    the check constraint so there is exactly one row, ever; every sweep
--    UPDATEs it rather than INSERTing a new one, the same "one row, updated
--    forever" shape pg_stat_statements itself uses for its own counters.
--    `started_at` is set once, at row creation, and becomes every exported
--    datapoint's `startTimeUnixNano` — the series start a cumulative counter
--    needs for a backend to read a reset (this table dropped and recreated)
--    as a new series rather than as negative traffic.
create table if not exists groom_sweep_stats (
  id                 boolean primary key default true check (id),
  runs_total         bigint not null default 0,
  archived_total     bigint not null default 0,
  policies_evaluated integer not null default 0,
  started_at         timestamptz not null default now(),
  last_run_at        timestamptz
);

insert into groom_sweep_stats (id) values (true) on conflict (id) do nothing;

comment on table groom_sweep_stats is
  'Singleton cumulative counters for the nightly retention-policy sweep — '
  'updated by lorekit_groom_sweep_and_record, read by the groom-sweep Edge '
  'Function to export lorekit.groom.sweep.{runs,archived} to Dash0.';

alter table groom_sweep_stats enable row level security;
-- No policy is created: this is an operator/service-role surface exactly
-- like retention_policies' RPCs are for CRUD, but here there is no owning
-- user at all (the sweep spans every user's auto+enabled policies), so no
-- `authenticated`-reachable policy is correct — only the SECURITY DEFINER
-- function below (and the service role, which bypasses RLS) may touch it.

-- 2. lorekit_groom_sweep_and_record — runs the existing, unchanged
--    `lorekit_groom_sweep()`, then atomically records this run's result into
--    `groom_sweep_stats` and returns the accumulated totals PLUS this run's
--    own snapshot (archived_this_run, policies_evaluated) for the Edge
--    Function's span attributes. The snapshot fields are deliberately NOT
--    part of the exported metrics (see groom-sweep-metrics.ts) — they are
--    per-run values, not cumulative counters, and mixing the two shapes in
--    one Sum metric would misread a run-over-run drop as a counter reset.
create or replace function lorekit_groom_sweep_and_record()
returns table (
  runs_total         bigint,
  archived_total     bigint,
  archived_this_run  integer,
  policies_evaluated integer,
  started_at         timestamptz,
  last_run_at        timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_archived  integer;
  v_policies  integer;
begin
  select lorekit_groom_sweep() into v_archived;

  select count(*) into v_policies
    from retention_policies where mode = 'auto' and enabled = true;

  return query
    update groom_sweep_stats
       set runs_total         = groom_sweep_stats.runs_total + 1,
           archived_total     = groom_sweep_stats.archived_total + coalesce(v_archived, 0),
           policies_evaluated = v_policies,
           last_run_at        = now()
     where id = true
    returning
      groom_sweep_stats.runs_total,
      groom_sweep_stats.archived_total,
      coalesce(v_archived, 0),
      v_policies,
      groom_sweep_stats.started_at,
      groom_sweep_stats.last_run_at;
end;
$$;

comment on function lorekit_groom_sweep_and_record() is
  'Runs lorekit_groom_sweep() unchanged, then records the result into '
  'groom_sweep_stats. Called by the groom-sweep Edge Function so every '
  'nightly sweep produces a span + cumulative Dash0 metrics.';

revoke all on function lorekit_groom_sweep_and_record() from public;
revoke all on function lorekit_groom_sweep_and_record() from anon, authenticated;
grant execute on function lorekit_groom_sweep_and_record() to service_role;

-- 3. lorekit_export_groom_sweep — pokes the `groom-sweep` Edge Function
--    through pg_net, IDENTICAL gating and shape to
--    lorekit_export_db_query_stats (00074): OFF by default until an operator
--    provisions two Vault secrets, so this migration turns nothing on by
--    itself and adds no new secret-handling code path to audit.
--
--   select vault.create_secret('https://<ref>.supabase.co/functions/v1/groom-sweep', 'lorekit_groom_sweep_url');
--   select vault.create_secret('<service-role-key>', 'lorekit_groom_sweep_key');
create or replace function lorekit_export_groom_sweep()
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_url text;
  v_key text;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_net') then
    return 'skipped: pg_net not installed';
  end if;

  if to_regclass('vault.decrypted_secrets') is null then
    return 'disabled: vault unavailable';
  end if;

  select decrypted_secret into v_url
    from vault.decrypted_secrets where name = 'lorekit_groom_sweep_url';
  select decrypted_secret into v_key
    from vault.decrypted_secrets where name = 'lorekit_groom_sweep_key';

  if v_url is null or v_key is null then
    return 'disabled: set the lorekit_groom_sweep_url and lorekit_groom_sweep_key vault secrets to enable';
  end if;

  -- Fire-and-forget, same reasoning as the query-stats poke: pg_net queues
  -- the request and returns immediately, so a cron tick never blocks on
  -- Dash0 being slow or unreachable. A dropped tick here loses one night's
  -- run count, never data — the cumulative counters keep going from wherever
  -- they last landed.
  perform net.http_post(
    url     := v_url,
    body    := '{}'::jsonb,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_key
    ),
    timeout_milliseconds := 30000
  );

  return 'posted';
end;
$$;

comment on function lorekit_export_groom_sweep() is
  'Pokes the groom-sweep Edge Function to run the nightly retention sweep '
  'and export its telemetry to Dash0. Inert until the '
  'lorekit_groom_sweep_url + lorekit_groom_sweep_key vault secrets exist.';

revoke all on function lorekit_export_groom_sweep() from public;
revoke all on function lorekit_export_groom_sweep() from anon, authenticated;
grant execute on function lorekit_export_groom_sweep() to service_role;

-- 4. Reschedule the nightly job to call the new, observable entry point.
--    `cron.schedule()` upserts by job name (same name, same time as 00088:
--    'lorekit-groom-sweep', 03:17 UTC) so this REPLACES the command in
--    place — no unschedule step needed, and no gap in the schedule.
--    Guarded identically to 00088 so this migration still applies on an
--    instance without pg_cron.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule(
      'lorekit-groom-sweep',
      '17 3 * * *',
      $cron$select lorekit_export_groom_sweep()$cron$
    );
  end if;
end;
$$;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00095', 'groom_sweep_telemetry')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00096_memories_user_updated_at_id_idx.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Covering index for the one memories read that has NO scope predicate:
-- `GET /memories/clusters` run without `?scope=` (`handlers/clusters.ts`).
--
-- Every other hot read on this table filters `scope = ?` first and is served
-- by `memories_scope_key_active_idx` / `memories_scope_updated_at_id_idx`
-- (00033, 00061). The unscoped clusters query has no such leading column:
--
--   SELECT scope,key,value,seen_count,updated_at FROM memories
--   WHERE archived_at IS NULL
--     AND (expires_at IS NULL OR expires_at > now())
--   ORDER BY updated_at DESC, id DESC
--   LIMIT 150
--
-- For a JWT caller this reaches Postgres under RLS's `rls_read` predicate
-- (`user_id = auth.uid() OR org_id = jwt org_id`, 00001); for an api_key
-- caller with no org membership, `applyRestTenantScope` adds an explicit
-- `.eq('user_id', userId)` (`_shared/api/tenant.ts`). Either way the query is
-- effectively scoped to ONE user's rows, but the only index covering
-- `user_id` is the bare `memories_user_idx (user_id)` from 00001 — it has no
-- `archived_at` predicate and no `updated_at`/`id` ordering, so the planner
-- has to choose between an index scan on `user_id` followed by a heap
-- recheck + filesort, or a sequential scan filtered on `archived_at IS
-- NULL`. Neither is stable: which one the planner picks (and how many rows
-- of the OTHER tenants' data it has to skip past to find this user's 150
-- newest) depends on live statistics, so the SAME query with the SAME
-- 150-row result swings from ~150ms to several seconds run to run — the
-- p95 latency alert on the `api` service (`lorekit` namespace) fired on
-- exactly this variance, not on a change in traffic or row count.
--
-- The fix mirrors 00061's `(scope, updated_at desc, id desc)` index one
-- column over: replace the leading `scope` with `user_id`, so the ONE
-- unscoped query gets the same shape of covering, order-satisfying index
-- every scoped query already has. `IF NOT EXISTS` so it applies safely to a
-- running production database; not `CONCURRENTLY` because migrations run
-- inside a transaction (matches every prior index migration on this table).
--
-- The expiry filter (`expires_at IS NULL OR expires_at > now()`) is
-- deliberately NOT in the predicate, for the same reason 00061 left it out
-- of its own index: `now()` is volatile and PostgreSQL rejects a volatile
-- expression in an index predicate.
create index if not exists memories_user_updated_at_id_idx
  on memories (user_id, updated_at desc, id desc)
  where archived_at is null;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00096', 'memories_user_updated_at_id_idx')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00098_groom_unseen_days_last_read_at.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Fix: `unseen_days` was checking a column nothing ever wrote.
--
-- 00088 introduced `memories.last_seen_at` for the `unseen_days` retention
-- condition, but its own header said so explicitly: "nothing sets it yet...
-- wiring memory.read/list/search to bump it is deliberately left as a
-- follow-up." That follow-up never landed — `last_seen_at` has no writer
-- anywhere in this codebase, so it is permanently NULL for every row,
-- including rows read constantly. `coalesce(last_seen_at, '-infinity')` then
-- evaluates to true for EVERY memory regardless of actual read activity, so
-- `unseen_days` has been a silent no-op since it shipped: `min_age_days` and
-- `max_seen_count` narrowed a retention view, `unseen_days` narrowed nothing.
--
-- 00084 (which predates 00088) already ships the real signal:
-- `memories.last_read_at`, bumped by `lorekit_record_memory_reads` on every
-- `memory.read`/`list`/`search`/`list_archived` call that actually returns
-- the row. This migration repoints `unseen_days` at that column instead of
-- the dead one, in both callers that evaluate it — `lorekit_groom_candidates`
-- (00088/00093) and `lorekit_memory_list` (00092/00094) — so a saved policy's
-- preview, a run, the nightly sweep, and the Explorer's retention-conditions
-- filter all agree, exactly as they did before this fix, just against a
-- column that is actually written.
--
-- The "never-seen matches any threshold" reading is unchanged: `last_read_at`
-- is NULL until a row is first read (or if it predates 00084's cutover), and
-- `coalesce(last_read_at, '-infinity')` treats that the same way the dead
-- column's NULL always did — this is a data-source fix, not a semantics
-- change, and `grooming.mdx`'s documented contract ("a lesson that has never
-- been read matches at ANY threshold") was already written for this reading.
--
-- `last_seen_at` has no remaining reader or writer after this migration —
-- dropped rather than left as inert dead weight for a future reader to trip
-- over again.
--
-- Both functions keep their EXISTING signatures (no parameter added, removed,
-- or reordered), so `create or replace` is safe here without a preceding
-- `drop function` — unlike 00093/00094, which changed the argument or return
-- shape and had to drop the old overload first.

-- ── lorekit_groom_candidates (00088, extended by 00093) ─────────────────────
create or replace function lorekit_groom_candidates(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in'
)
returns table (id uuid, scope text, key text)
language sql
stable
security definer
set search_path = public
as $$
  select m.id, m.scope, m.key
    from memories m
   where m.user_id = p_user_id
     and m.archived_at is null
     and m.protected = false
     and (
       p_scope = 'global'
       or m.scope = p_scope
       or (
         p_scope like 'repo::%'
         and starts_with(m.scope, 'branch::' || substring(p_scope from 7) || '::')
       )
     )
     and (p_min_age_days is null or m.created_at <= now() - (p_min_age_days * interval '1 day'))
     and (p_unseen_days is null or coalesce(m.last_read_at, '-infinity'::timestamptz) <= now() - (p_unseen_days * interval '1 day'))
     and (p_max_seen_count is null or m.seen_count <= p_max_seen_count)
     and lorekit_match_tags(m.tags,               p_tags,          p_tags_mode)
     and lorekit_match_text(m.source_agent,       p_source_agent,   p_source_agent_mode)
     and lorekit_match_text(m.trigger,            p_trigger,        p_trigger_mode)
     and lorekit_match_text(m.kind,               p_kind,           p_kind_mode)
     and lorekit_match_text(m.host,               p_host,           p_host_mode)
     and lorekit_match_text(m.origin_repo,        p_origin_repo,    p_origin_repo_mode)
     and lorekit_match_text(m.origin_branch,      p_origin_branch,  p_origin_branch_mode)
     and lorekit_match_text(m.origin_pr::text,    p_origin_pr,      p_origin_pr_mode)
   order by m.scope, m.key;
$$;

grant execute on function lorekit_groom_candidates(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
) to authenticated, service_role;

-- ── lorekit_memory_list (00067/00069/00092/00094) ───────────────────────────
create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null
)
returns table (
  id            uuid,
  scope         text,
  key           text,
  value         text,
  tags          text[],
  source_agent  text,
  trigger       text,
  created_at    timestamptz,
  updated_at    timestamptz,
  expires_at    timestamptz,
  archived_at   timestamptz,
  origin_repo   text,
  origin_branch text,
  origin_commit text,
  origin_pr     integer,
  kind          text,
  host          text,
  seen_count    integer,
  org_id        uuid,
  created_by    uuid,
  updated_by    uuid,
  org_name      text,
  org_slug      text,
  total_count   integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug,
      (count(*) over ())::integer as total_count
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       and ($35 is null or m.created_at <= now() - ($35 * interval '1 day'))
       and ($36 is null or coalesce(m.last_read_at, '-infinity'::timestamptz) <= now() - ($36 * interval '1 day'))
       and ($37 is null or m.seen_count <= $37)
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count;
end;
$$;

grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
) to authenticated, service_role;

-- ── drop the dead column ─────────────────────────────────────────────────
-- No function, view, index, or RLS policy reads or writes `last_seen_at`
-- after the two replacements above — it was never wired to anything in the
-- first place. Dropping it rather than leaving it as inert dead weight.
alter table memories drop column if exists last_seen_at;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00098', 'groom_unseen_days_last_read_at')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00099_last_opened_at_targeted_agent_reads.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- `unseen_days` should mean "no agent has deliberately opened this lesson in
-- N days" — not "nothing touched this row", which is what `last_read_at`
-- (repointed here from the dead `last_seen_at` by 00098) actually measures.
--
-- THE GAP 00098 LEFT: `last_read_at` is bumped by `lorekit_record_memory_reads`
-- for EVERY read that returns a row, `targeted` (`memory.read` / `GET /:id`)
-- OR `bulk` (`memory.list` / `.search` / `.list_archived`) — and `GET /:id` is
-- the SAME route the web dashboard's LessonDetailSheet calls to render a
-- lesson for a human, plus whatever the CLI's remote `read`/`show` command
-- calls. So `last_read_at` moves when: an agent asks for this exact lesson
-- (the signal `unseen_days` wants), a bulk `list`/`search` happens to include
-- it (no one "saw" it — it rode along in a results page), or a human opens the
-- dashboard's detail sheet (browsing your own lore is not consuming it — the
-- same reasoning migration 00054 already applied to `lorekit_read_activity`).
-- A policy set to "unseen 90d" was therefore satisfied by the Explorer being
-- opened, not by an agent reading the lesson back.
--
-- THE FIX: a new, narrower column — `memories.last_opened_at` — bumped ONLY
-- when a read is BOTH `read_kind = 'targeted'` AND attributed to an agent
-- surface (`client` = `mcp` or `cli`, the `X-LoreKit-Client` / MCP-transport
-- vocabulary from migration 00054). `unseen_days` in both
-- `lorekit_groom_candidates` and `lorekit_memory_list` now reads THIS column
-- instead of `last_read_at`.
--
-- `last_read_at`/`read_count` are UNTOUCHED and keep their existing, broader
-- meaning (any read, from any surface, targeted or bulk) — that is the
-- dashboard's "Consumption" row, and it stays useful precisely because it
-- answers a different question ("has this been read at all") than
-- `last_opened_at` ("has an agent deliberately reached for this one lesson").
-- Both are worth keeping: a lesson can ride along in list pages constantly
-- while never once being individually opened, or vice versa.
--
-- `lorekit_record_memory_reads` gains a trailing `p_client text default null`
-- — additive, so every existing caller that omits it is unaffected and keeps
-- recording `read_count`/`last_read_at`/`memory_read_daily` exactly as before.
-- Adding a parameter changes the signature, so the old overload is DROPped
-- first, matching 00093/00094/00054's precedent.

-- ── the column ──────────────────────────────────────────────────────────────
alter table memories add column if not exists last_opened_at timestamptz;

comment on column memories.last_opened_at is
  'Last time this exact memory was individually retrieved by an agent over
   MCP or the CLI (read_kind = targeted, client in (mcp, cli)) — migration
   00099. NULL means never targeted-opened by an agent. Distinct from
   last_read_at (migration 00084/00098), which also moves on a bulk
   list/search appearance or a human viewing the web dashboard.';

-- ── writer: add a trailing p_client, gate last_opened_at on it ─────────────
drop function if exists lorekit_record_memory_reads(uuid[], text);

create or replace function lorekit_record_memory_reads(
  p_memory_ids uuid[],
  p_read_kind  text,
  p_client     text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_memory_ids is null or array_length(p_memory_ids, 1) is null then
    return;
  end if;

  -- ONE statement for every id, not one per id — the hot-path requirement a
  -- bulk `list` returning 31 rows imposes. `unnest` turns the array into a rowset
  -- the UPDATE can join against directly.
  update memories m
     set read_count = m.read_count + 1,
         last_read_at = now(),
         -- Narrower than the two columns above: only a TARGETED read
         -- attributed to an agent surface counts as "opened". `p_client` is
         -- validated app-side (`parseUsageClient`) before it reaches here, so
         -- this is a closed two-value check, not a free-text comparison.
         last_opened_at = case
           when p_read_kind = 'targeted' and p_client in ('mcp', 'cli')
             then now()
           else m.last_opened_at
         end
    from unnest(p_memory_ids) as ids(id)
   where m.id = ids.id;

  -- Upsert today's rollup row per memory — one INSERT, conflict-aggregated,
  -- same shape as the update above. `current_date` is UTC-anchored the same
  -- way `usage_events`' other date_trunc'd reads are (`at time zone 'UTC'`),
  -- so a rollup day boundary agrees with every other UTC-bucketed series in
  -- this schema.
  insert into memory_read_daily (memory_id, day, read_kind, count)
  select ids.id, (now() at time zone 'UTC')::date, p_read_kind, 1
    from unnest(p_memory_ids) as ids(id)
  on conflict (memory_id, day, read_kind)
  do update set count = memory_read_daily.count + 1;
exception
  when others then
    -- Never let a counter write break the read it is measuring.
    return;
end;
$$;

