    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count;
end;
$$;

grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00100', 'unseen_days_never_opened_uses_created_at')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00101_max_read_count_condition.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- 00101_max_read_count_condition.sql
--
-- A fourth retention condition: `max_read_count` — match only lessons READ at
-- most N times.
--
-- WHY IT IS NOT max_seen_count. `seen_count` (00059) counts WRITES: a
-- `memory.write` against an existing key bumps it, so it measures how often a
-- lesson RECURRED, not whether anyone used it. "Written once and never
-- consumed" is the classic dead-lore shape and no existing condition could
-- express it — `max_seen_count: 1` catches every one-off write, useful and
-- useless lore alike.
--
-- WHICH COUNTER. `memories.read_count` (00084) — the BROAD one, incremented on
-- every read including a bulk `memory.list`/`memory.search` appearance. It is
-- deliberately NOT the narrow targeted-open signal `unseen_days` uses
-- (`last_opened_at`, 00099): there is no targeted-only counter, and inventing
-- one would restart every lesson at zero. Every surface must therefore SAY
-- that bulk reads count, rather than labelling both conditions "seen" — the
-- mismatch 00100 was written to clean up.
--
-- CUTOVER, inherited from 00084. `read_count` starts at 0 for a memory created
-- before that migration, so a low count can mean "not read" or "not counted
-- yet". Unlike `unseen_days` (00100) there is no second column to fall back
-- to, so this condition is honestly conservative in the OPPOSITE direction: it
-- over-matches on old rows rather than under-matching. `lorekit_memory_read_ranking`
-- (00085) already carries the same caveat as `counting_since`, and the docs
-- repeat it wherever this condition is offered.
--
-- SIGNATURES. `p_max_read_count` is APPENDED to every parameter list rather
-- than slotted beside `p_max_seen_count`, so existing positional callers keep
-- working. Adding a parameter changes the signature, so each function is
-- DROPPED first — `create or replace` would leave a second overload behind and
-- make every call ambiguous. `lorekit_policy_update` takes a jsonb patch and
-- so needs no drop.
--
-- The index that serves it already exists: `memories_user_read_count_idx`
-- on `(user_id, read_count) where archived_at is null` (00085).

-- ── the policy column ─────────────────────────────────────────────────────
alter table retention_policies add column if not exists max_read_count integer;

alter table retention_policies drop constraint if exists retention_policies_max_read_count_non_negative;
alter table retention_policies add constraint retention_policies_max_read_count_non_negative
  check (max_read_count is null or max_read_count >= 0);

comment on column retention_policies.max_read_count is
  'Match only lessons read at most this many times (memories.read_count, 00084 --
   counts bulk list/search appearances too, unlike unseen_days). NULL = unconstrained.';

-- ── 1. lorekit_groom_candidates ───────────────────────────────────────────
drop function if exists lorekit_groom_candidates(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
);

create or replace function lorekit_groom_candidates(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in',
  p_max_read_count      integer default null
)
returns table (id uuid, scope text, key text)
language sql
stable
security definer
set search_path = public
as $$
  select m.id, m.scope, m.key
    from memories m
   where m.user_id = p_user_id
     and m.archived_at is null
     and m.protected = false
     and (
       p_scope = 'global'
       or m.scope = p_scope
       or (
         p_scope like 'repo::%'
         and starts_with(m.scope, 'branch::' || substring(p_scope from 7) || '::')
       )
     )
     and (p_min_age_days is null or m.created_at <= now() - (p_min_age_days * interval '1 day'))
     and (p_unseen_days is null or coalesce(m.last_opened_at, m.created_at) <= now() - (p_unseen_days * interval '1 day'))
     and (p_max_seen_count is null or m.seen_count <= p_max_seen_count)
     and (p_max_read_count is null or m.read_count <= p_max_read_count)
     and lorekit_match_tags(m.tags,               p_tags,          p_tags_mode)
     and lorekit_match_text(m.source_agent,       p_source_agent,   p_source_agent_mode)
     and lorekit_match_text(m.trigger,            p_trigger,        p_trigger_mode)
     and lorekit_match_text(m.kind,               p_kind,           p_kind_mode)
     and lorekit_match_text(m.host,               p_host,           p_host_mode)
     and lorekit_match_text(m.origin_repo,        p_origin_repo,    p_origin_repo_mode)
     and lorekit_match_text(m.origin_branch,      p_origin_branch,  p_origin_branch_mode)
     and lorekit_match_text(m.origin_pr::text,    p_origin_pr,      p_origin_pr_mode)
   order by m.scope, m.key;
$$;

grant execute on function lorekit_groom_candidates(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer
) to authenticated, service_role;

-- ── 2. lorekit_groom_run ──────────────────────────────────────────────────
drop function if exists lorekit_groom_run(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
);

create or replace function lorekit_groom_run(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in',
  p_max_read_count      integer default null
)
returns table (archived integer, keys jsonb)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ids   uuid[];
  v_keys  jsonb;
  v_count integer := 0;
begin
  select coalesce(array_agg(c.id), '{}'),
         coalesce(jsonb_agg(jsonb_build_object('scope', c.scope, 'key', c.key)), '[]'::jsonb)
    into v_ids, v_keys
    from lorekit_groom_candidates(
      p_user_id, p_scope, p_min_age_days, p_unseen_days, p_max_seen_count,
      p_tags, p_tags_mode, p_source_agent, p_source_agent_mode,
      p_trigger, p_trigger_mode, p_kind, p_kind_mode, p_host, p_host_mode,
      p_origin_repo, p_origin_repo_mode, p_origin_branch, p_origin_branch_mode,
      p_origin_pr, p_origin_pr_mode, p_max_read_count
    ) c;

  if array_length(v_ids, 1) is null then
    return query select 0, '[]'::jsonb;
    return;
  end if;

  update memories m
     set archived_at = now()
   where m.id = any(v_ids)
     and m.archived_at is null;
  get diagnostics v_count = row_count;

  return query select v_count, v_keys;
end;
$$;

grant execute on function lorekit_groom_run(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer
) to authenticated, service_role;

-- ── 3. lorekit_groom_sweep ────────────────────────────────────────
create or replace function lorekit_groom_sweep()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_policy retention_policies%rowtype;
  v_result record;
  v_total  integer := 0;
begin
  for v_policy in
    select * from retention_policies where mode = 'auto' and enabled = true
  loop
    select * into v_result
      from lorekit_groom_run(
        v_policy.user_id, v_policy.scope,
        v_policy.min_age_days, v_policy.unseen_days, v_policy.max_seen_count,
        v_policy.tags, v_policy.tags_mode,
        v_policy.source_agent, v_policy.source_agent_mode,
        v_policy.trigger, v_policy.trigger_mode,
        v_policy.kind, v_policy.kind_mode,
        v_policy.host, v_policy.host_mode,
        v_policy.origin_repo, v_policy.origin_repo_mode,
        v_policy.origin_branch, v_policy.origin_branch_mode,
        v_policy.origin_pr, v_policy.origin_pr_mode,
        v_policy.max_read_count
      );
    v_total := v_total + coalesce(v_result.archived, 0);
  end loop;

  return v_total;
end;
$$;

grant execute on function lorekit_groom_sweep() to service_role;

-- ── 4. lorekit_policy_create ──────────────────────────────────────────────
drop function if exists lorekit_policy_create(
  uuid, text, text, text, boolean, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text
);

create or replace function lorekit_policy_create(
  p_user_id             uuid,
  p_scope               text,
  p_name                text,
  p_mode                text    default 'review',
  p_enabled             boolean default false,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in',
  p_max_read_count      integer default null
)
returns setof retention_policies
language sql
security definer
set search_path = public
as $$
  insert into retention_policies (
    user_id, scope, name, mode, enabled, min_age_days, unseen_days, max_seen_count,
    max_read_count,
    tags, tags_mode, source_agent, source_agent_mode, trigger, trigger_mode,
    kind, kind_mode, host, host_mode, origin_repo, origin_repo_mode,
    origin_branch, origin_branch_mode, origin_pr, origin_pr_mode
  )
  values (
    p_user_id, p_scope, p_name, p_mode, p_enabled, p_min_age_days, p_unseen_days, p_max_seen_count,
    p_max_read_count,
    p_tags, p_tags_mode, p_source_agent, p_source_agent_mode, p_trigger, p_trigger_mode,
    p_kind, p_kind_mode, p_host, p_host_mode, p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode, p_origin_pr, p_origin_pr_mode
  )
  returning *;
$$;

grant execute on function lorekit_policy_create(
  uuid, text, text, text, boolean, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer
) to authenticated, service_role;

-- ── 5. lorekit_policy_update ───────────────────────────────────
create or replace function lorekit_policy_update(
  p_user_id uuid,
  p_id      uuid,
  p_patch   jsonb
)
returns setof retention_policies
language sql
security definer
set search_path = public
as $$
  update retention_policies
     set name                = case when p_patch ? 'name'                then p_patch ->> 'name'                          else name end,
         mode                 = case when p_patch ? 'mode'                then p_patch ->> 'mode'                          else mode end,
         enabled              = case when p_patch ? 'enabled'             then (p_patch ->> 'enabled')::boolean            else enabled end,
         min_age_days         = case when p_patch ? 'min_age_days'        then (p_patch ->> 'min_age_days')::integer       else min_age_days end,
         unseen_days          = case when p_patch ? 'unseen_days'         then (p_patch ->> 'unseen_days')::integer        else unseen_days end,
         max_seen_count       = case when p_patch ? 'max_seen_count'      then (p_patch ->> 'max_seen_count')::integer     else max_seen_count end,
         max_read_count       = case when p_patch ? 'max_read_count'      then (p_patch ->> 'max_read_count')::integer     else max_read_count end,
         tags                 = case when p_patch ? 'tags'                then (case when p_patch -> 'tags'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'tags')) end)                else tags end,
         tags_mode            = case when p_patch ? 'tags_mode'           then p_patch ->> 'tags_mode'                     else tags_mode end,
         source_agent         = case when p_patch ? 'source_agent'        then (case when p_patch -> 'source_agent'        = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'source_agent')) end)         else source_agent end,
         source_agent_mode    = case when p_patch ? 'source_agent_mode'   then p_patch ->> 'source_agent_mode'             else source_agent_mode end,
         trigger              = case when p_patch ? 'trigger'             then (case when p_patch -> 'trigger'             = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'trigger')) end)              else trigger end,
         trigger_mode         = case when p_patch ? 'trigger_mode'        then p_patch ->> 'trigger_mode'                  else trigger_mode end,
         kind                 = case when p_patch ? 'kind'                then (case when p_patch -> 'kind'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'kind')) end)                 else kind end,
         kind_mode            = case when p_patch ? 'kind_mode'           then p_patch ->> 'kind_mode'                     else kind_mode end,
         host                 = case when p_patch ? 'host'                then (case when p_patch -> 'host'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'host')) end)                 else host end,
         host_mode            = case when p_patch ? 'host_mode'           then p_patch ->> 'host_mode'                     else host_mode end,
         origin_repo          = case when p_patch ? 'origin_repo'         then (case when p_patch -> 'origin_repo'         = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_repo')) end)          else origin_repo end,
         origin_repo_mode     = case when p_patch ? 'origin_repo_mode'    then p_patch ->> 'origin_repo_mode'              else origin_repo_mode end,
         origin_branch        = case when p_patch ? 'origin_branch'       then (case when p_patch -> 'origin_branch'       = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_branch')) end)        else origin_branch end,
         origin_branch_mode   = case when p_patch ? 'origin_branch_mode'  then p_patch ->> 'origin_branch_mode'            else origin_branch_mode end,
         origin_pr            = case when p_patch ? 'origin_pr'           then (case when p_patch -> 'origin_pr'           = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_pr')) end)            else origin_pr end,
         origin_pr_mode       = case when p_patch ? 'origin_pr_mode'      then p_patch ->> 'origin_pr_mode'                else origin_pr_mode end
   where id = p_id and user_id = p_user_id
  returning *;
$$;

grant execute on function lorekit_policy_update(uuid, uuid, jsonb) to authenticated, service_role;

-- ── 6. lorekit_memory_list ────────────────────────────────────────────────
drop function if exists lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer
);

create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null,
  p_max_read_count       integer     default null
)
returns table (
  id            uuid,
  scope         text,
  key           text,
  value         text,
  tags          text[],
  source_agent  text,
  trigger       text,
  created_at    timestamptz,
  updated_at    timestamptz,
  expires_at    timestamptz,
  archived_at   timestamptz,
  origin_repo   text,
  origin_branch text,
  origin_commit text,
  origin_pr     integer,
  kind          text,
  host          text,
  seen_count    integer,
  org_id        uuid,
  created_by    uuid,
  updated_by    uuid,
  org_name      text,
  org_slug      text,
  total_count   integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug,
      (count(*) over ())::integer as total_count
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       and ($35 is null or m.created_at <= now() - ($35 * interval '1 day'))
       and ($36 is null or coalesce(m.last_opened_at, m.created_at) <= now() - ($36 * interval '1 day'))
       and ($37 is null or m.seen_count <= $37)
       and ($38 is null or m.read_count <= $38)
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count, p_max_read_count;
end;
$$;

grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer,
  integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00101', 'max_read_count_condition')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00102_github_relevance_configs.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Server-side review-comment relevance classification — per-installation
-- configuration.
--
-- WHAT THIS ENABLES
--   A review agent posts findings as PR review comments.  Later, the thread is
--   resolved, declined, or merged still open.  That outcome is the only honest
--   signal about whether the finding was worth posting, and until now capturing
--   it required every consumer repository to install a GitHub Actions workflow
--   plus a LOREKIT_API_KEY secret.  The GitHub App already receives the same
--   deliveries, so the classification can run server-side and a consumer gets
--   it by installing the App — no workflow, no secret.
--
-- WHY IT NEEDS CONFIGURATION AT ALL
--   LoreKit must NOT learn any particular agent's vocabulary.  It does not know
--   what a "finder", a "defect class", or a fingerprint is, and it must never
--   have to.  So the account that installed the App declares, once, three
--   things about its own review agent:
--
--     • marker_open / marker_close — the literal delimiters the agent wraps its
--       per-finding identifier in, inside the comment body.
--     • bucket_tag                 — the LoreKit tag the outcome is filed under.
--     • key_prefix                 — the key namespace the outcome is filed in.
--     • agent_name                 — what to record as the finding's author.
--
--   `agent_name` exists because the consuming reader filters on it: another
--   bot's declined finding and a human's incidental comment have their own
--   false-positive profiles and must never train this agent's suppressor.  The
--   account is the only party that can name its agent, and a comment carrying
--   the account's own marker is by definition from it — so the marker is the
--   attribution and this column is what it attributes to.  LoreKit does not
--   otherwise use the value.
--
--   The identifier between the delimiters is copied VERBATIM and treated as an
--   opaque string.  LoreKit never parses it, never splits it, never derives
--   meaning from it.  That is the whole separation: LoreKit owns the mechanism
--   (receive, read, classify, write); the account owns the vocabulary.
--
-- WHY LITERAL DELIMITERS AND NOT A REGEX
--   A caller-supplied regex compiled inside an edge function is a
--   catastrophic-backtracking vector, and "reject the dangerous patterns" is
--   not a check anyone can write soundly.  Two literal delimiters answer the
--   same question in linear time with nothing to validate beyond length, and a
--   human can read the stored config and know exactly what it matches.
--
-- SECURITY POSTURE — the config IS the boundary
--   Anyone who can comment on a PR in a covered repository can cause a write.
--   That is already true of the `source::pr-webhook` candidate feed, but a
--   classified record is filed under a DERIVED key, so an unbounded key would
--   let a commenter address — and overwrite — an arbitrary existing record.
--   Three things bound it:
--     a) The account, not the comment, supplies `key_prefix` and `bucket_tag`.
--        A commenter can only ever influence the suffix, inside a namespace the
--        account itself declared.
--     b) The extracted identifier must pass a strict charset + length check
--        (`isSafeMarkerValue`, comment-relevance.ts) or nothing is written.
--     c) The write is scoped to `repo::<full_name>` of the delivery, which is
--        HMAC-verified before any of this runs.
--
-- WHY THE ROW CARRIES NO user_id
--   Ownership comes from the installation, resolved at write time through
--   `github_installations.user_id`.  Storing it here too would let the two
--   disagree after an installation is transferred, and the installation row is
--   the one the reconcile path already keeps correct.
--
-- Authorization posture (matches 00037 and the Phase 3 org rule):
--   • RLS grants SELECT on rows whose installation is linked to auth.uid().
--   • There is NO insert/update/delete policy.  Every state transition goes
--     through a SECURITY DEFINER RPC that checks installation ownership.
--   • The edge function reads through `lorekit_relevance_config_for_repo`,
--     service-role only, which resolves repo → installation → owner → config
--     in one round trip.
-- ═════════════════════════════════════════════════════════════════════════

-- 1. github_relevance_configs — one row per (installation, bucket).
create table github_relevance_configs (
  id              uuid primary key default gen_random_uuid(),
  installation_id bigint not null
                    references github_installations(installation_id) on delete cascade,

  -- Literal delimiters around the agent's opaque per-finding identifier.
  -- `marker_open` is at least 4 characters so a config cannot be written that
  -- matches near-arbitrary prose; `marker_close` may be short (`-->`).
  marker_open     text not null check (length(marker_open) between 4 and 120),
  marker_close    text not null check (length(marker_close) between 1 and 120),

  -- Where the outcome is filed. Both are the account's vocabulary, never a
  -- commenter's — see the security posture above.
  bucket_tag      text not null check (bucket_tag ~ '^[a-z0-9]+(::[a-z0-9._-]+)+$'),
  key_prefix      text not null check (length(key_prefix) between 1 and 200),
  agent_name      text not null check (length(agent_name) between 1 and 60),

  -- Taxonomy applied to the written record. LoreKit infers kind/host only from
  -- a `loop::` tag, so a `ci::`-tagged bucket must state them explicitly.
  record_kind     text not null default 'signal'
                    check (record_kind in ('lesson', 'bus', 'signal')),
  record_host     text check (record_host is null or length(record_host) between 1 and 60),

  ttl_days        int not null default 60 check (ttl_days between 1 and 365),
  active          boolean not null default true,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

-- One active config per (installation, bucket): an account can classify into
-- more than one bucket, but never twice into the same one with two different
-- markers, which would make the write order decide the record.
create unique index github_relevance_configs_active_uniq
  on github_relevance_configs (installation_id, bucket_tag)
  where active = true;

create index github_relevance_configs_installation_id_idx
  on github_relevance_configs (installation_id)
  where active = true;

alter table github_relevance_configs enable row level security;

-- Readable by the owner of the installation, and by the service role.
create policy "rls_github_relevance_configs_select"
  on github_relevance_configs for select
  using (
    installation_id in (
      select i.installation_id
        from github_installations i
       where i.user_id = auth.uid() and i.status = 'linked'
    )
  );

grant select on github_relevance_configs to authenticated, service_role;

-- 2. Edge lookup — repo full_name → the configs to classify with, plus the
--    LoreKit user the resulting records belong to.
--
--    Returns ZERO rows for every honest no-op, and the caller treats them
--    identically: the repo is not covered by any installation, the installation
--    is still `pending` (nobody to attribute the write to), or the account has
--    declared no marker.  None of those is an error.
--
--    `status = 'linked'` is load-bearing rather than cosmetic: a webhook write
--    with a null user_id lands in the service-role partition, which no user
--    token can read back (see `applyTenantScope`), so classifying for a pending
--    installation would produce records that exist and are unreachable.
create or replace function lorekit_relevance_config_for_repo(p_repo text)
returns table (
  installation_id bigint,
  user_id         uuid,
  marker_open     text,
  marker_close    text,
  bucket_tag      text,
  key_prefix      text,
  agent_name      text,
  record_kind     text,
  record_host     text,
  ttl_days        int
)
language sql
stable
security definer
set search_path = public
as $$
  select c.installation_id,
         i.user_id,
         c.marker_open,
         c.marker_close,
         c.bucket_tag,
         c.key_prefix,
         c.agent_name,
         c.record_kind,
         c.record_host,
         c.ttl_days
    from installation_repositories r
    join github_installations i
      on i.installation_id = r.installation_id
    join github_relevance_configs c
      on c.installation_id = r.installation_id
   where r.full_name = lower(p_repo)
     and r.active = true
     and i.status = 'linked'
     and i.user_id is not null
     and c.active = true;
$$;

-- Service-role only, and the revoke is not optional. This function takes an
-- ARBITRARY `p_repo` and returns another account's installation owner plus its
-- whole declared vocabulary, with no `auth.uid()` gate in the body — the
-- table's select-RLS does not apply inside a `security definer` function. A
-- newly CREATEd function in `public` carries PostgreSQL's default PUBLIC
-- EXECUTE, and on this project's Supabase image ALSO a direct default-privilege
-- grant to `anon` that `revoke ... from public` does not touch (00077's whole
-- subject). Granting to `service_role` without revoking first therefore leaves
-- the function callable by every `anon`/`authenticated` caller through
-- PostgREST. Same three statements as `lorekit_db_query_stats` (00074) and
-- `lorekit_groom_sweep_and_record` (00095).
revoke all on function lorekit_relevance_config_for_repo(text) from public;
revoke all on function lorekit_relevance_config_for_repo(text) from anon, authenticated;
grant execute on function lorekit_relevance_config_for_repo(text) to service_role;

-- 3. Owner-only upsert. The caller proves ownership by owning the installation;
--    no caller-supplied user_id is trusted and there is no UPDATE policy to
--    reach the table any other way.
create or replace function lorekit_relevance_config_set(
  p_installation_id bigint,
  p_marker_open     text,
  p_marker_close    text,
  p_bucket_tag      text,
  p_key_prefix      text,
  p_agent_name      text,
  p_record_kind     text default 'signal',
  p_record_host     text default null,
  p_ttl_days        int  default 60
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  if not exists (
    select 1
      from github_installations i
     where i.installation_id = p_installation_id
       and i.user_id = auth.uid()
       and i.status = 'linked'
  ) then
    raise exception 'installation not found or not linked to caller';
  end if;

  insert into github_relevance_configs (
    installation_id, marker_open, marker_close, bucket_tag, key_prefix, agent_name,
    record_kind, record_host, ttl_days, active, updated_at
  )
  values (
    p_installation_id, p_marker_open, p_marker_close, p_bucket_tag, p_key_prefix, p_agent_name,
    coalesce(p_record_kind, 'signal'), p_record_host, coalesce(p_ttl_days, 60), true, now()
  )
  on conflict (installation_id, bucket_tag) where active = true
  do update set
    marker_open  = excluded.marker_open,
    marker_close = excluded.marker_close,
    key_prefix   = excluded.key_prefix,
    agent_name   = excluded.agent_name,
    record_kind  = excluded.record_kind,
    record_host  = excluded.record_host,
    ttl_days     = excluded.ttl_days,
    updated_at   = now()
  returning id into v_id;

  return v_id;
end;
$$;

-- `anon` is named explicitly for the reason 00077 exists: the default-privilege
-- grant to `anon` survives a bare `revoke ... from public`. The body's
-- `auth.uid()` gate already denies an anonymous caller, so this is defence in
-- depth — but leaving the function on PostgREST's anonymous surface is the
-- exposure this schema closes by policy, not case by case.
revoke execute on function lorekit_relevance_config_set(bigint, text, text, text, text, text, text, text, int)
  from public, anon;
grant execute on function lorekit_relevance_config_set(bigint, text, text, text, text, text, text, text, int)
  to authenticated;

-- 4. Owner-only deactivate. Soft, so the unique index frees up for a new
--    config while the history of what was configured stays readable.
create or replace function lorekit_relevance_config_deactivate(
  p_installation_id bigint,
  p_bucket_tag      text
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (
    select 1
      from github_installations i
     where i.installation_id = p_installation_id
       and i.user_id = auth.uid()
       and i.status = 'linked'
  ) then
    raise exception 'installation not found or not linked to caller';
  end if;

  update github_relevance_configs
     set active = false, updated_at = now()
   where installation_id = p_installation_id
     and bucket_tag = p_bucket_tag
     and active = true;
end;
$$;

revoke execute on function lorekit_relevance_config_deactivate(bigint, text)
  from public, anon;
grant execute on function lorekit_relevance_config_deactivate(bigint, text)
  to authenticated;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00102', 'github_relevance_configs')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00103_reads_must_not_restamp_updated_at.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00103 — a READ must not rewrite `updated_at`.
--
-- THE BUG, observed in production on 2026-09-03:
--
--     BEFORE  updated_at = 2026-09-03T17:49:09.236723+00:00
--     GET     /memories?scope=repo::mthines/agent-skills&limit=100
--     AFTER   updated_at = 2026-09-03T17:50:04.978342+00:00
--
-- No write of any kind was issued. `lorekit_record_memory_reads` (00099) does
--
--     update memories m set read_count = m.read_count + 1, last_read_at = now()
--
-- to record that a read happened, and that UPDATE fires the BEFORE-row trigger
-- `lorekit_memories_set_updated_at`, which stamps `updated_at = now()`. Because
-- a single `memory.list` page carries ~55 rows and every one of them gets the
-- counter bump, ONE bulk read restamps ~55 memories.
--
-- WHAT IT COST, measured on the same account the day this was written:
--   * 0 of 2,475 sampled memories had an `updated_at` older than 14 days,
--     against a median row age of 22 days and a maximum of 77 — freshness was
--     unreadable because every row looked touched-just-now.
--   * `updated_at` is the DEFAULT SORT for both the dashboard Explorer and
--     `memory.list order=recency`, so the ordering agents receive lore in was
--     being driven by which rows happened to be read most recently — that is,
--     by nothing.
--   * The detail sheet's "Last updated" field was showing a last-READ time
--     under a last-WRITTEN label.
--
-- THE FIX is the one migration 00062 already established for the embedding
-- columns, applied to the read counters: a DERIVED column must not rewrite the
-- recency signal that search, `relevant`, the keyset index and lesson-rank all
-- read. 00062's function is EXTENDED rather than replaced, so `memories` keeps
-- exactly one BEFORE UPDATE trigger and the two exemptions are stated in one
-- place instead of racing each other.
--
-- The predicate keeps 00062's shape for the reason its comment gives: mask the
-- derived columns plus `updated_at`, then compare the WHOLE rows, so a column
-- added to `memories` later is covered automatically where an explicit
-- "did any real column change" list would silently stop covering it.
--
-- The `v_*_changed` preconditions are equally load-bearing, and for 00062's
-- reason: without them the rule degrades to "nothing meaningful changed →
-- preserve", which also catches a plain NO-OP re-write — and `memory_write`
-- upserts, so an agent re-saving an identical lesson would stop refreshing
-- `updated_at`. Preserve only when a derived column ACTUALLY moved and nothing
-- else did.
--
-- `set_updated_at` itself is still LEFT ALONE — six other tables share it
-- (`user_limits`, `orgs`, `org_limits`, `plans`, `user_plans`,
-- `retention_policies`) and none of them has counters or this problem.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memories_set_updated_at()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
declare
  v_new memories := new;
  v_old memories := old;
  v_embedding_changed boolean;
  v_counters_changed  boolean;
begin
  -- 00062's exemption: an embedding write.
  v_embedding_changed :=
       new.embedding is distinct from old.embedding
    or new.embedding_model is distinct from old.embedding_model;

  -- This migration's exemption: a read-counter write from
  -- `lorekit_record_memory_reads`. `last_opened_at` is included because a
  -- TARGETED read moves it in the same statement as `read_count`; leaving it
  -- unmasked would make every targeted read look like a real edit.
  v_counters_changed :=
       new.read_count     is distinct from old.read_count
    or new.last_read_at   is distinct from old.last_read_at
    or new.last_opened_at is distinct from old.last_opened_at;

  -- Mask the derived columns and the one being decided.
  --
  -- `fts` MUST be masked too, for 00062's reason: it is a GENERATED column and
  -- Postgres computes generated columns AFTER BEFORE-row triggers run, so
  -- `new.fts` is NULL here while `old.fts` holds the stored value. An unmasked
  -- comparison finds every update "changed", which silently turns this whole
  -- function back into `set_updated_at`. It fails in the safe direction (a bump
  -- that should not happen, never a missing bump), which is exactly why it
  -- needs a test rather than a reading — see migrations.test.sql §101.
  v_new.embedding := null; v_new.embedding_model := null;
  v_new.read_count := null; v_new.last_read_at := null; v_new.last_opened_at := null;
  v_new.updated_at := null; v_new.fts := null;

  v_old.embedding := null; v_old.embedding_model := null;
  v_old.read_count := null; v_old.last_read_at := null; v_old.last_opened_at := null;
  v_old.updated_at := null; v_old.fts := null;

  if (v_embedding_changed or v_counters_changed)
     and v_new is not distinct from v_old then
    -- A derived column moved and nothing else did. Preserve the row's real
    -- recency rather than restamping it.
    new.updated_at := old.updated_at;
  else
    new.updated_at := now();
  end if;

  return new;
end;
$$;

-- The trigger already points here (00062); recreated so a fresh database and a
-- migrated one land in the same state regardless of which migrations ran.
create or replace trigger memories_updated_at
  before update on memories
  for each row execute function lorekit_memories_set_updated_at();

comment on function lorekit_memories_set_updated_at() is
  'BEFORE UPDATE on memories: bumps updated_at like set_updated_at, EXCEPT when the only change is '
  'a DERIVED column — the embedding pair (00062) or the read counters read_count/last_read_at/'
  'last_opened_at (00103). Neither may rewrite the recency signal that search, relevant, the keyset '
  'index, lesson-rank and BOTH default sorts (Explorer, memory.list order=recency) all read. Before '
  '00103 a single bulk memory.list restamped every row on the page, so updated_at reported '
  'last-READ under a last-WRITTEN name and recency ordering was effectively arbitrary.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00103', 'reads_must_not_restamp_updated_at')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00104_opened_count_pull_through.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00104 — `opened_count`: the numerator that makes lore value comparable.
--
-- THE PROBLEM. All three counters a memory carries are ABSOLUTE COUNTS ON THE
-- SUPPLY SIDE — how often the system produced this lesson:
--
--   seen_count     (00059) how many times it was WRITTEN.  88.4% of a live
--                          2,475-row sample sit at exactly 1, so it has almost
--                          no variance to rank by.
--   read_count     (00084) how many times it was READ — but 99.80% of recorded
--                          reads are BULK ride-alongs in a list/search page, so
--                          this ranks SCOPE BREADTH, not usefulness. A `global`
--                          lesson is delivered on every session; a `branch`
--                          lesson almost never. Sorting by it puts every global
--                          lesson on top whether or not anything used it.
--   last_opened_at (00099) when an agent last deliberately fetched THIS lesson.
--                          The honest signal — and a bare timestamp, with no
--                          count and no denominator to compare rows by.
--
-- Value lives on the DEMAND side: given that a lesson was offered, did anything
-- take it up? That is a RATIO, and a ratio cancels the confound — scope breadth
-- appears in both numerator and denominator and divides away. A `global` lesson
-- delivered 1,300 times and opened twice scores 0.15%; a `branch` lesson
-- delivered 3 times and opened twice scores 67%. For the first time those two
-- numbers are comparable, and the second is obviously the more valuable.
--
-- PULL-THROUGH is defined here as `opened_count / read_count` — targeted opens
-- over TOTAL reads, not over bulk reads. A proper fraction in [0, 1]: bounded,
-- so it sorts; and defined for a lesson that has only ever been fetched
-- deliberately (which `targeted / bulk` would divide by zero on).
--
-- WHY A COLUMN, when `memory_read_daily(memory_id, day, read_kind, count)`
-- (00084) has stored the split since the counters shipped:
--
--   1. It has to be FILTERABLE at scale. `max_opened_count` (00105) is a
--      retention condition, and `lorekit_groom_candidates` runs it over a whole
--      scope. A per-memory aggregate over the rollup cannot be indexed; a
--      column can, and gets `memories_user_opened_count_idx` below, mirroring
--      00085's index on `read_count`.
--   2. It cannot DISAGREE with `last_opened_at`. Both move in the SAME
--      statement under the SAME gate inside `lorekit_record_memory_reads`, so
--      "opened 4 times" and "last opened on ..." are always the same event
--      stream. Deriving one from the rollup and reading the other from the row
--      is two sources for one fact.
--
-- The rollup is still the authority on HISTORY, which is what the backfill
-- below reads: every targeted read ever recorded, so the column ships exact
-- rather than starting every lesson at zero.
--
-- ORDER IS LOAD-BEARING IN THIS FILE. The trigger is taught to mask
-- `opened_count` BEFORE the backfill runs. Reversed, the backfill's UPDATE
-- would restamp `updated_at` on every memory that has ever been opened — the
-- exact whole-store recency wipe 00103 was written to stop, and unrecoverable
-- once done.
-- ═════════════════════════════════════════════════════════════════════════

-- ── 1. the column ─────────────────────────────────────────────────────────
alter table memories add column if not exists opened_count integer not null default 0;

comment on column memories.opened_count is
  'How many times an agent DELIBERATELY fetched this exact lesson -- the count
   whose timestamp is last_opened_at (00099), moved by the same gate in the same
   statement: read_kind = targeted AND client in (mcp, cli). Never moved by a
   bulk list/search ride-along or by a human browsing the dashboard. Divided by
   read_count (00084, which counts every read) it gives PULL-THROUGH: of all the
   times this lesson was surfaced, how often was it a deliberate fetch. That
   ratio is comparable across scopes where the raw counts are not, because scope
   breadth cancels. Not null, defaults to 0; backfilled from memory_read_daily
   by 00104.';

-- ── 2. teach the trigger to mask it — BEFORE the backfill ─────────────────
-- 00103 exempted read_count/last_read_at/last_opened_at from restamping
-- `updated_at`; opened_count is the fourth column of that same derived set and
-- moves in the same statement, so omitting it here would defeat 00103 for every
-- TARGETED read. Asserted by migrations.test.sql §101 AC-2b, which does exactly
-- that read and checks the stamp did not move.
create or replace function lorekit_memories_set_updated_at()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
declare
  v_new memories := new;
  v_old memories := old;
  v_embedding_changed boolean;
  v_counters_changed  boolean;
begin
  -- 00062's exemption: an embedding write.
  v_embedding_changed :=
       new.embedding is distinct from old.embedding
    or new.embedding_model is distinct from old.embedding_model;

  -- 00103's exemption, extended by 00104 with opened_count: a read-counter
  -- write from `lorekit_record_memory_reads`.
  v_counters_changed :=
       new.read_count     is distinct from old.read_count
    or new.last_read_at   is distinct from old.last_read_at
    or new.last_opened_at is distinct from old.last_opened_at
    or new.opened_count   is distinct from old.opened_count;

  -- Mask the derived columns and the one being decided.
  --
  -- `fts` MUST be masked too, for 00062's reason: it is a GENERATED column and
  -- Postgres computes generated columns AFTER BEFORE-row triggers, so
  -- `new.fts` is NULL here while `old.fts` holds the stored value. An unmasked
  -- comparison finds every update "changed", which silently turns this whole
  -- function back into `set_updated_at`. It fails in the safe direction (a bump
  -- that should not happen, never a missing bump), which is exactly why it
  -- needs a test rather than a reading — see migrations.test.sql §101.
  v_new.embedding := null; v_new.embedding_model := null;
  v_new.read_count := null; v_new.last_read_at := null; v_new.last_opened_at := null;
  v_new.opened_count := null;
  v_new.updated_at := null; v_new.fts := null;

  v_old.embedding := null; v_old.embedding_model := null;
  v_old.read_count := null; v_old.last_read_at := null; v_old.last_opened_at := null;
  v_old.opened_count := null;
  v_old.updated_at := null; v_old.fts := null;

  if (v_embedding_changed or v_counters_changed)
     and v_new is not distinct from v_old then
    -- A derived column moved and nothing else did. Preserve the row's real
    -- recency rather than restamping it.
    new.updated_at := old.updated_at;
  else
    new.updated_at := now();
  end if;

  return new;
end;
$$;

comment on function lorekit_memories_set_updated_at() is
  'BEFORE UPDATE on memories: bumps updated_at like set_updated_at, EXCEPT when the only change is '
  'a DERIVED column — the embedding pair (00062) or the read counters read_count/last_read_at/'
  'last_opened_at (00103) and opened_count (00104). None may rewrite the recency signal that '
  'search, relevant, the keyset index, lesson-rank and BOTH default sorts (Explorer, memory.list '
  'order=recency) all read. Before 00103 a single bulk memory.list restamped every row on the page, '
  'so updated_at reported last-READ under a last-WRITTEN name and recency ordering was arbitrary.';

-- ── 3. backfill from the rollup ───────────────────────────────────────────
-- Every targeted read `memory_read_daily` has ever recorded, so the column is
-- exact from day one instead of restarting the whole store at zero — the
-- cutover problem 00101 had to document for `read_count` and this one does not.
-- Runs AFTER the trigger above, so it preserves `updated_at` (see the header).
update memories m
   set opened_count = t.n
  from (
    select memory_id, sum(count)::integer as n
      from memory_read_daily
     where read_kind = 'targeted'
     group by memory_id
  ) t
 where m.id = t.memory_id
   and m.opened_count is distinct from t.n;

-- ── 4. the index the retention condition and the ranking need ─────────────
-- Mirrors `memories_user_read_count_idx` (00085) so `max_opened_count` (00105)
-- and any "never chosen" query are served the same way `max_read_count` is.
create index if not exists memories_user_opened_count_idx
  on memories (user_id, opened_count)
  where archived_at is null;

-- ── 5. the writer ─────────────────────────────────────────────────────────
-- Same signature, so `create or replace` is enough — no drop needed. The
-- increment is gated on EXACTLY the condition that sets `last_opened_at`,
-- written as one shared `case` so the pair cannot drift apart.
create or replace function lorekit_record_memory_reads(
  p_memory_ids uuid[],
  p_read_kind  text,
  p_client     text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  -- Resolved ONCE, outside the statement: `p_read_kind`/`p_client` are call
  -- arguments, not per-row values, so "is this a targeted agent open" is one
  -- boolean for the whole batch rather than a predicate re-evaluated per row —
  -- and, more importantly, the count and the timestamp below cannot be gated
  -- on two expressions that drift.
  v_opened boolean := p_read_kind = 'targeted' and p_client in ('mcp', 'cli');
begin
  if p_memory_ids is null or array_length(p_memory_ids, 1) is null then
    return;
  end if;

  -- ONE statement for every id, not one per id — the hot-path requirement a
  -- bulk `list` returning 31 rows imposes. `unnest` turns the array into a rowset
  -- the UPDATE can join against directly.
  update memories m
     set read_count = m.read_count + 1,
         last_read_at = now(),
         -- Narrower than the two columns above: only a TARGETED read
         -- attributed to an agent surface counts as "opened". `p_client` is
         -- validated app-side (`parseUsageClient`) before it reaches here, so
         -- this is a closed two-value check, not a free-text comparison.
         last_opened_at = case when v_opened then now() else m.last_opened_at end,
         opened_count   = m.opened_count + case when v_opened then 1 else 0 end
    from unnest(p_memory_ids) as ids(id)
   where m.id = ids.id;

  -- Upsert today's rollup row per memory — one INSERT, conflict-aggregated,
  -- same shape as the update above. `current_date` is UTC-anchored the same
  -- way `usage_events`' other date_trunc'd reads are (`at time zone 'UTC'`),
  -- so a rollup day boundary agrees with every other UTC-bucketed series in
  -- this schema.
  insert into memory_read_daily (memory_id, day, read_kind, count)
  select ids.id, (now() at time zone 'UTC')::date, p_read_kind, 1
    from unnest(p_memory_ids) as ids(id)
  on conflict (memory_id, day, read_kind)
  do update set count = memory_read_daily.count + 1;
exception
  when others then
    -- Never let a counter write break the read it is measuring.
    return;
end;
$$;

comment on function lorekit_record_memory_reads(uuid[], text, text) is
  'Increments memories.read_count/.last_read_at and today''s memory_read_daily
   row (UTC day, keyed by read_kind) for every memory id a read call actually
   returned, in ONE statement regardless of array size. Also sets
   memories.last_opened_at (00099) and increments memories.opened_count (00104)
   when read_kind = targeted AND client in (mcp, cli) -- an agent deliberately
   reaching for this one lesson, as opposed to it riding along in a page. Those
   two move together off one shared gate so a count and its timestamp can never
   disagree. Swallows its own errors: a counter must never break the read it is
   measuring.';

-- ── 6. surface the counters on the list RPC ───────────────────────────────
-- `lorekit_memory_list` returned NONE of the four read counters, so the lesson
-- CARD could not show any of them and comparing two lessons meant opening two
-- detail sheets. Adding them to `returns table` is a return-TYPE change, so the
-- function must be dropped first; the parameter list is unchanged, so the drop
-- signature is 00101's verbatim.
drop function if exists lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer,
  integer
);

create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null,
  p_max_read_count       integer     default null
)
returns table (
  id             uuid,
  scope          text,
  key            text,
  value          text,
  tags           text[],
  source_agent   text,
  trigger        text,
  created_at     timestamptz,
  updated_at     timestamptz,
  expires_at     timestamptz,
  archived_at    timestamptz,
  origin_repo    text,
  origin_branch  text,
  origin_commit  text,
  origin_pr      integer,
  kind           text,
  host           text,
  seen_count     integer,
  read_count     integer,
  opened_count   integer,
  last_read_at   timestamptz,
  last_opened_at timestamptz,
  org_id         uuid,
  created_by     uuid,
  updated_by     uuid,
  org_name       text,
  org_slug       text,
  total_count    integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.read_count, m.opened_count, m.last_read_at, m.last_opened_at,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug,
      (count(*) over ())::integer as total_count
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       and ($35 is null or m.created_at <= now() - ($35 * interval '1 day'))
       and ($36 is null or coalesce(m.last_opened_at, m.created_at) <= now() - ($36 * interval '1 day'))
       and ($37 is null or m.seen_count <= $37)
       and ($38 is null or m.read_count <= $38)
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count, p_max_read_count;
end;
$$;

grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer,
  integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00104', 'opened_count_pull_through')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00105_max_opened_count_condition.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00105 — `max_opened_count`: the retention condition whose 0 means something.
--
-- WHY max_read_count IS NOT ENOUGH. 00101 added `max_read_count` over
-- `read_count`, which counts EVERY read including bulk list/search
-- ride-alongs. Measured on a live 2,772-memory store the day this was written,
-- that makes the filter almost unusable at the low end:
--
--     max_read_count <= 5     ->     0 memories
--     max_read_count <= 26    ->     the first non-empty result
--     max_read_count <= 50    ->     roughly half the store
--     max_read_count <= 400   ->     essentially everything
--
-- Its whole usable range is a narrow band in the middle, and the grooming UI
-- suggests `0` — a value that can never match anything a `memory.list` has ever
-- paged over, which is every lesson in an active scope. Worse, what it ranks on
-- is SCOPE BREADTH: a `global` lesson rides along in every session and a
-- `branch` lesson almost never, so "read at most N times" selects narrow scopes
-- and calls them unused.
--
-- `opened_count` (00104) counts ONLY a deliberate agent fetch of this exact
-- lesson. `max_opened_count => 0` therefore means exactly what a reader
-- expects — "no agent has ever reached for this" — and it means the same thing
-- for a `global` lesson as for a `branch` one. It is the condition
-- `max_read_count` was reaching for.
--
-- BOTH ARE KEPT, and `max_read_count` is not deprecated here. It answers a real
-- and different question — "what is this lesson COSTING me in context" — which
-- is the other axis of the delivered x chosen grid. Pairing them is what makes
-- the interesting quadrant expressible for the first time:
--
--     max_opened_count => 0            "nothing ever chose it"
--     (with no max_read_count)         ... at any delivery volume
--
-- and, for the prune list that actually saves context, a policy that leaves
-- `max_read_count` unset while setting `max_opened_count => 0` catches the
-- heavily-delivered, never-chosen lessons that `max_read_count` structurally
-- cannot reach.
--
-- NO CUTOVER CAVEAT, unlike 00101. `max_read_count` had to warn that a
-- long-lived lesson can show a low count it never earned, because `read_count`
-- started at 0 when 00084 shipped. `opened_count` was BACKFILLED from
-- `memory_read_daily` in 00104, so it is exact over the whole history the
-- rollup holds and no lesson looks falsely unopened.
--
-- SIGNATURES follow 00101 exactly: `p_max_opened_count` is APPENDED last so
-- positional callers keep working, and every function whose signature changes
-- is DROPPED first — `create or replace` would leave a second overload behind
-- and make every call ambiguous. `lorekit_policy_update` takes a jsonb patch,
-- so it needs no drop; `lorekit_groom_sweep` takes no arguments.
--
-- The index it needs already exists: `memories_user_opened_count_idx` (00104).
-- ═════════════════════════════════════════════════════════════════════════

-- ── the policy column ─────────────────────────────────────────────────────
alter table retention_policies add column if not exists max_opened_count integer;

alter table retention_policies drop constraint if exists retention_policies_max_opened_count_non_negative;
alter table retention_policies add constraint retention_policies_max_opened_count_non_negative
  check (max_opened_count is null or max_opened_count >= 0);

comment on column retention_policies.max_opened_count is
  'Match only lessons an agent has DELIBERATELY fetched at most this many times
   (memories.opened_count, 00104). Unlike max_read_count (00101) a bulk
   list/search ride-along does not count, so 0 means "nothing ever chose this"
   rather than "this lesson happens to live in a narrow scope". NULL =
   unconstrained.';

-- ── 1. lorekit_groom_candidates ───────────────────────────────────────────
drop function if exists lorekit_groom_candidates(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer
);

create or replace function lorekit_groom_candidates(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in',
  p_max_read_count      integer default null,
  p_max_opened_count    integer default null
)
returns table (id uuid, scope text, key text)
language sql
stable
security definer
set search_path = public
as $$
  select m.id, m.scope, m.key
    from memories m
   where m.user_id = p_user_id
     and m.archived_at is null
     and m.protected = false
     and (
       p_scope = 'global'
       or m.scope = p_scope
       or (
         p_scope like 'repo::%'
         and starts_with(m.scope, 'branch::' || substring(p_scope from 7) || '::')
       )
     )
     and (p_min_age_days is null or m.created_at <= now() - (p_min_age_days * interval '1 day'))
     and (p_unseen_days is null or coalesce(m.last_opened_at, m.created_at) <= now() - (p_unseen_days * interval '1 day'))
     and (p_max_seen_count is null or m.seen_count <= p_max_seen_count)
     and (p_max_read_count is null or m.read_count <= p_max_read_count)
     and (p_max_opened_count is null or m.opened_count <= p_max_opened_count)
     and lorekit_match_tags(m.tags,               p_tags,          p_tags_mode)
     and lorekit_match_text(m.source_agent,       p_source_agent,   p_source_agent_mode)
     and lorekit_match_text(m.trigger,            p_trigger,        p_trigger_mode)
     and lorekit_match_text(m.kind,               p_kind,           p_kind_mode)
     and lorekit_match_text(m.host,               p_host,           p_host_mode)
     and lorekit_match_text(m.origin_repo,        p_origin_repo,    p_origin_repo_mode)
     and lorekit_match_text(m.origin_branch,      p_origin_branch,  p_origin_branch_mode)
     and lorekit_match_text(m.origin_pr::text,    p_origin_pr,      p_origin_pr_mode)
   order by m.scope, m.key;
$$;

grant execute on function lorekit_groom_candidates(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer, integer
) to authenticated, service_role;

-- ── 2. lorekit_groom_run ──────────────────────────────────────────────────
drop function if exists lorekit_groom_run(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer
);

create or replace function lorekit_groom_run(
  p_user_id             uuid,
  p_scope               text,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in',
  p_max_read_count      integer default null,
  p_max_opened_count    integer default null
)
returns table (archived integer, keys jsonb)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ids   uuid[];
  v_keys  jsonb;
  v_count integer := 0;
begin
  select coalesce(array_agg(c.id), '{}'),
         coalesce(jsonb_agg(jsonb_build_object('scope', c.scope, 'key', c.key)), '[]'::jsonb)
    into v_ids, v_keys
    from lorekit_groom_candidates(
      p_user_id, p_scope, p_min_age_days, p_unseen_days, p_max_seen_count,
      p_tags, p_tags_mode, p_source_agent, p_source_agent_mode,
      p_trigger, p_trigger_mode, p_kind, p_kind_mode, p_host, p_host_mode,
      p_origin_repo, p_origin_repo_mode, p_origin_branch, p_origin_branch_mode,
      p_origin_pr, p_origin_pr_mode, p_max_read_count, p_max_opened_count
    ) c;

  if array_length(v_ids, 1) is null then
    return query select 0, '[]'::jsonb;
    return;
  end if;

  update memories m
     set archived_at = now()
   where m.id = any(v_ids)
     and m.archived_at is null;
  get diagnostics v_count = row_count;

  return query select v_count, v_keys;
end;
$$;

grant execute on function lorekit_groom_run(
  uuid, text, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer, integer
) to authenticated, service_role;

-- ── 3. lorekit_groom_sweep ────────────────────────────────────────────────
-- No signature change; recreated only to pass the new policy column through.
create or replace function lorekit_groom_sweep()
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_policy retention_policies%rowtype;
  v_result record;
  v_total  integer := 0;
begin
  for v_policy in
    select * from retention_policies where mode = 'auto' and enabled = true
  loop
    select * into v_result
      from lorekit_groom_run(
        v_policy.user_id, v_policy.scope,
        v_policy.min_age_days, v_policy.unseen_days, v_policy.max_seen_count,
        v_policy.tags, v_policy.tags_mode,
        v_policy.source_agent, v_policy.source_agent_mode,
        v_policy.trigger, v_policy.trigger_mode,
        v_policy.kind, v_policy.kind_mode,
        v_policy.host, v_policy.host_mode,
        v_policy.origin_repo, v_policy.origin_repo_mode,
        v_policy.origin_branch, v_policy.origin_branch_mode,
        v_policy.origin_pr, v_policy.origin_pr_mode,
        v_policy.max_read_count, v_policy.max_opened_count
      );
    v_total := v_total + coalesce(v_result.archived, 0);
  end loop;

  return v_total;
end;
$$;

grant execute on function lorekit_groom_sweep() to service_role;

-- ── 4. lorekit_policy_create ──────────────────────────────────────────────
drop function if exists lorekit_policy_create(
  uuid, text, text, text, boolean, integer, integer, integer,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, integer
);

create or replace function lorekit_policy_create(
  p_user_id             uuid,
  p_scope               text,
  p_name                text,
  p_mode                text    default 'review',
  p_enabled             boolean default false,
  p_min_age_days        integer default null,
  p_unseen_days         integer default null,
  p_max_seen_count      integer default null,
  p_tags                text[]  default null,
  p_tags_mode           text    default 'any',
  p_source_agent        text[]  default null,
  p_source_agent_mode   text    default 'in',
  p_trigger             text[]  default null,
  p_trigger_mode        text    default 'in',
  p_kind                text[]  default null,
  p_kind_mode           text    default 'in',
  p_host                text[]  default null,
  p_host_mode           text    default 'in',
  p_origin_repo         text[]  default null,
  p_origin_repo_mode    text    default 'in',
  p_origin_branch       text[]  default null,
  p_origin_branch_mode  text    default 'in',
  p_origin_pr           text[]  default null,
  p_origin_pr_mode      text    default 'in',
  p_max_read_count      integer default null,
  p_max_opened_count    integer default null
)
returns setof retention_policies
language sql
security definer
set search_path = public
as $$
  insert into retention_policies (
    user_id, scope, name, mode, enabled, min_age_days, unseen_days, max_seen_count,
    max_read_count, max_opened_count,
    tags, tags_mode, source_agent, source_agent_mode, trigger, trigger_mode,
    kind, kind_mode, host, host_mode, origin_repo, origin_repo_mode,
    origin_branch, origin_branch_mode, origin_pr, origin_pr_mode
  )
  values (
    p_user_id, p_scope, p_name, p_mode, p_enabled, p_min_age_days, p_unseen_days, p_max_seen_count,
    p_max_read_count, p_max_opened_count,
    p_tags, p_tags_mode, p_source_agent, p_source_agent_mode, p_trigger, p_trigger_mode,
    p_kind, p_kind_mode, p_host, p_host_mode, p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode, p_origin_pr, p_origin_pr_mode
  )
  returning *;
$$;

grant execute on function lorekit_policy_create(
