-- ── 5. lorekit_policy_update ──────────────────────────────────────────────
-- jsonb patch, so the signature is unchanged and no drop is needed. One more
-- `case when p_patch ? ...` line, matching every other condition: an absent key
-- leaves the column alone, an explicit null clears it.
create or replace function lorekit_policy_update(
  p_user_id uuid,
  p_id      uuid,
  p_patch   jsonb
)
returns setof retention_policies
language sql
security definer
set search_path = public
as $$
  update retention_policies
     set name                = case when p_patch ? 'name'                then p_patch ->> 'name'                          else name end,
         mode                 = case when p_patch ? 'mode'                then p_patch ->> 'mode'                          else mode end,
         enabled              = case when p_patch ? 'enabled'             then (p_patch ->> 'enabled')::boolean            else enabled end,
         min_age_days         = case when p_patch ? 'min_age_days'        then (p_patch ->> 'min_age_days')::integer       else min_age_days end,
         unseen_days          = case when p_patch ? 'unseen_days'         then (p_patch ->> 'unseen_days')::integer        else unseen_days end,
         max_seen_count       = case when p_patch ? 'max_seen_count'      then (p_patch ->> 'max_seen_count')::integer     else max_seen_count end,
         max_read_count       = case when p_patch ? 'max_read_count'      then (p_patch ->> 'max_read_count')::integer     else max_read_count end,
         max_opened_count     = case when p_patch ? 'max_opened_count'    then (p_patch ->> 'max_opened_count')::integer   else max_opened_count end,
         tags                 = case when p_patch ? 'tags'                then (case when p_patch -> 'tags'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'tags')) end)                else tags end,
         tags_mode            = case when p_patch ? 'tags_mode'           then p_patch ->> 'tags_mode'                     else tags_mode end,
         source_agent         = case when p_patch ? 'source_agent'        then (case when p_patch -> 'source_agent'        = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'source_agent')) end)         else source_agent end,
         source_agent_mode    = case when p_patch ? 'source_agent_mode'   then p_patch ->> 'source_agent_mode'             else source_agent_mode end,
         trigger              = case when p_patch ? 'trigger'             then (case when p_patch -> 'trigger'             = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'trigger')) end)              else trigger end,
         trigger_mode         = case when p_patch ? 'trigger_mode'        then p_patch ->> 'trigger_mode'                  else trigger_mode end,
         kind                 = case when p_patch ? 'kind'                then (case when p_patch -> 'kind'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'kind')) end)                 else kind end,
         kind_mode            = case when p_patch ? 'kind_mode'           then p_patch ->> 'kind_mode'                     else kind_mode end,
         host                 = case when p_patch ? 'host'                then (case when p_patch -> 'host'                = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'host')) end)                 else host end,
         host_mode            = case when p_patch ? 'host_mode'           then p_patch ->> 'host_mode'                     else host_mode end,
         origin_repo          = case when p_patch ? 'origin_repo'         then (case when p_patch -> 'origin_repo'         = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_repo')) end)          else origin_repo end,
         origin_repo_mode     = case when p_patch ? 'origin_repo_mode'    then p_patch ->> 'origin_repo_mode'              else origin_repo_mode end,
         origin_branch        = case when p_patch ? 'origin_branch'       then (case when p_patch -> 'origin_branch'       = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_branch')) end)        else origin_branch end,
         origin_branch_mode   = case when p_patch ? 'origin_branch_mode'  then p_patch ->> 'origin_branch_mode'            else origin_branch_mode end,
         origin_pr            = case when p_patch ? 'origin_pr'           then (case when p_patch -> 'origin_pr'           = 'null'::jsonb then null else array(select jsonb_array_elements_text(p_patch -> 'origin_pr')) end)            else origin_pr end,
         origin_pr_mode       = case when p_patch ? 'origin_pr_mode'      then p_patch ->> 'origin_pr_mode'                else origin_pr_mode end
   where id = p_id and user_id = p_user_id
  returning *;
$$;

grant execute on function lorekit_policy_update(uuid, uuid, jsonb) to authenticated, service_role;

-- ── 6. lorekit_memory_list ────────────────────────────────────────────────
-- The Explorer's retention filter bar reads through this, so the condition has
-- to exist on both surfaces or the preview and the policy disagree. Parameter
-- change, so the 00104 definition is dropped by its exact argument list first.
drop function if exists lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer,
  integer
);

create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null,
  p_max_read_count       integer     default null,
  p_max_opened_count     integer     default null
)
returns table (
  id             uuid,
  scope          text,
  key            text,
  value          text,
  tags           text[],
  source_agent   text,
  trigger        text,
  created_at     timestamptz,
  updated_at     timestamptz,
  expires_at     timestamptz,
  archived_at    timestamptz,
  origin_repo    text,
  origin_branch  text,
  origin_commit  text,
  origin_pr      integer,
  kind           text,
  host           text,
  seen_count     integer,
  read_count     integer,
  opened_count   integer,
  last_read_at   timestamptz,
  last_opened_at timestamptz,
  org_id         uuid,
  created_by     uuid,
  updated_by     uuid,
  org_name       text,
  org_slug       text,
  total_count    integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.read_count, m.opened_count, m.last_read_at, m.last_opened_at,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug,
      (count(*) over ())::integer as total_count
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       and ($35 is null or m.created_at <= now() - ($35 * interval '1 day'))
       and ($36 is null or coalesce(m.last_opened_at, m.created_at) <= now() - ($36 * interval '1 day'))
       and ($37 is null or m.seen_count <= $37)
       and ($38 is null or m.read_count <= $38)
       and ($39 is null or m.opened_count <= $39)
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    p_min_age_days, p_unseen_days, p_max_seen_count, p_max_read_count,
    p_max_opened_count;
end;
$$;

grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer,
  integer, integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00105', 'max_opened_count_condition')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00106_memory_utility_grid.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00106 — the delivered × chosen grid, and what delivery costs.
--
-- WHAT THIS REPLACES. `lorekit_memory_read_ranking` (00085) ranks by
-- `read_count` alone, and 99.80% of recorded reads are bulk ride-alongs in a
-- `memory.list`/`memory.search` page. So the "cold" end of that ranking — the
-- end the Insights page nominates for pruning — is populated by NARROW SCOPES,
-- not by unused lore: a `branch` lesson is delivered a handful of times however
-- useful it is, while a `global` one is delivered on every session however
-- useless. Ranking two lessons by a number that mostly encodes their scope is
-- the defect; dividing by the deliveries cancels it, because scope breadth
-- appears in both halves.
--
-- 00085 IS NOT DROPPED. `/read-ranking` still answers "what is read most", a
-- real question, and it is a live REST route. This adds the grid beside it.
--
-- TWO FUNCTIONS, TWO WINDOWS, DELIBERATELY.
--
--   `lorekit_memory_utility_census` counts, per quadrant, over the LIFETIME
--   counters on `memories`. It must agree with the per-lesson chip the
--   dashboard renders from those same two columns, so it reads the same source.
--
--   `lorekit_memory_delivery_cost` sums over `memory_read_daily`, which is the
--   only source that can be WINDOWED ("this month"). It reports reads and an
--   estimated token volume.
--
-- Mixing them would produce a page where the headline and the grid silently
-- describe different periods. Each caller captions its own.
--
-- NO THRESHOLD IS HARDCODED HERE. `p_min_deliveries` / `p_min_age_days` /
-- `p_chosen_pull_through` / `p_broad_reach` arrive as parameters from
-- `LESSON_UTILITY_THRESHOLDS` in `@lorekit/schemas`, which is also what the
-- TypeScript chip reads. This is the `lorekit_get_limit` posture: the numbers
-- live in ONE place and the SQL encodes only the SHAPE of the rule (four
-- quadrants from two booleans, plus an evidence floor). A SQL default is
-- supplied so a hand-run query is not unusable, but it is a fallback, never
-- the authority — a drift between the two would put a lesson in one quadrant
-- on the card and another in the census.
--
-- TOKENS ARE ESTIMATED, never tokenized: `length(value) / 4`. The headline is
-- an order of magnitude, and shipping a BPE tokenizer into an edge function to
-- sharpen a number nobody acts on to the digit is the wrong trade. Every
-- surface that renders it says "estimated".
--
-- VISIBILITY is the same org-shared + own-rows predicate every per-user
-- analytics RPC in this family uses (`lorekit_memory_scopes`,
-- `lorekit_memory_read_ranking`, `lorekit_read_activity`), with the same
-- service-role + NULL-actor escape hatch and the same
-- `lorekit_api_token_scope_allowed` narrowing for a scoped key (00068/00069).
--
-- INDEXES: `memories_user_read_count_idx` (00085) and
-- `memories_user_opened_count_idx` (00104) already cover the census scan;
-- `memory_read_daily`'s primary key covers the cost sum's join.
-- ═════════════════════════════════════════════════════════════════════════

-- ── the quadrant expression, in ONE place ────────────────────────────────
--
-- Both functions below need "which quadrant is this row in", and the census
-- needs it twice (count and filter). An immutable helper keeps the rule from
-- being written out three times and drifting between them — the same reason
-- `isGroomCandidate` is one pure function rather than a predicate inlined per
-- caller.
--
-- Returns the SAME five names `LessonUtilitySchema` declares, so a rename on
-- either side is caught by `migrations.test.sql` §104 rather than silently
-- producing a quadrant no client knows how to render.
create or replace function lorekit_lesson_utility(
  p_read_count          integer,
  p_opened_count        integer,
  p_created_at          timestamptz,
  p_min_deliveries      integer     default 10,
  p_min_age_days        integer     default 7,
  p_chosen_pull_through numeric     default 0.02,
  p_broad_reach         integer     default 100,
  p_now                 timestamptz default now()
)
returns text
language sql
immutable
as $$
  select case
    -- The evidence floor comes FIRST, and both halves of it are needed: a
    -- lesson delivered 5,000 times in its first day has volume but no chance
    -- to have been chosen, and a 400-day-old lesson delivered 3 times has age
    -- but no denominator. Either alone would hand out a confident verdict the
    -- data cannot support.
    when p_created_at > p_now - make_interval(days => p_min_age_days) then 'unproven'
    when coalesce(p_read_count, 0) < p_min_deliveries then 'unproven'
    when coalesce(p_opened_count, 0)::numeric / nullif(p_read_count, 0) >= p_chosen_pull_through then
      case when p_read_count >= p_broad_reach then 'load-bearing' else 'specialist' end
    else
      case when p_read_count >= p_broad_reach then 'noise-tax' else 'dormant' end
  end;
$$;

comment on function lorekit_lesson_utility(integer, integer, timestamptz, integer, integer, numeric, integer, timestamptz) is
  'Where one lesson sits on the delivered x chosen grid: load-bearing /
   specialist / noise-tax / dormant / unproven. Pull-through is
   opened_count / read_count -- a proper fraction, so scope breadth cancels.
   Thresholds are PARAMETERS (LESSON_UTILITY_THRESHOLDS in @lorekit/schemas is
   the authority); the defaults here are a fallback for a hand-run query, not
   a second source of truth.';

-- ── the census ───────────────────────────────────────────────────────────
create or replace function lorekit_memory_utility_census(
  p_user_id             uuid,
  p_scope               text    default null,
  p_key_scopes          text[]  default '{}',
  p_min_deliveries      integer default 10,
  p_min_age_days        integer default 7,
  p_chosen_pull_through numeric default 0.02,
  p_broad_reach         integer default 100
)
returns table (
  utility text,
  n       bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
    -- LEFT JOIN off the five names rather than grouping the rows: a quadrant
    -- with no members must come back as 0, not be absent. An absent key reads
    -- to a client as "not measured", and "you have no noise tax" is a very
    -- different answer from "we did not look".
    select q.utility, coalesce(c.n, 0)::bigint
      from unnest(array['load-bearing', 'specialist', 'noise-tax', 'dormant', 'unproven']) as q(utility)
      left join (
        select lorekit_lesson_utility(
                 m.read_count, m.opened_count, m.created_at,
                 p_min_deliveries, p_min_age_days, p_chosen_pull_through, p_broad_reach, now()
               ) as utility,
               count(*) as n
          from memories m
         where (
                 (v_actor is null and auth.role() = 'service_role')
                 or m.user_id = v_actor
                 or m.org_id in (select lorekit_member_org_ids(v_actor))
               )
           and m.archived_at is null
           and (m.expires_at is null or m.expires_at > now())
           and (p_scope is null or m.scope = p_scope)
           and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
         group by 1
      ) c on c.utility = q.utility;
end;
$$;

revoke execute on function lorekit_memory_utility_census(uuid, text, text[], integer, integer, numeric, integer) from public, anon;
grant  execute on function lorekit_memory_utility_census(uuid, text, text[], integer, integer, numeric, integer) to authenticated, service_role;

comment on function lorekit_memory_utility_census(uuid, text, text[], integer, integer, numeric, integer) is
  'How many active lessons sit in each quadrant of the delivered x chosen grid,
   account-wide and ALL-TIME (the lifetime counters on memories, the same two
   columns the per-lesson chip reads, so the two cannot disagree). Every one of
   the five names is always returned, 0 included -- an absent key would read as
   "not measured".';

-- ── the rows for one quadrant ────────────────────────────────────────────
create or replace function lorekit_memory_utility_rows(
  p_user_id             uuid,
  p_utility             text,
  p_scope               text    default null,
  p_limit               integer default 20,
  p_key_scopes          text[]  default '{}',
  p_min_deliveries      integer default 10,
  p_min_age_days        integer default 7,
  p_chosen_pull_through numeric default 0.02,
  p_broad_reach         integer default 100
)
returns table (
  id             uuid,
  scope          text,
  key            text,
  read_count     integer,
  opened_count   integer,
  last_opened_at timestamptz,
  created_at     timestamptz
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 100);
begin
  if p_utility is null
     or p_utility not in ('load-bearing', 'specialist', 'noise-tax', 'dormant', 'unproven') then
    raise exception 'invalid utility %, expected one of load-bearing, specialist, noise-tax, dormant, unproven', p_utility
      using errcode = '22023';
  end if;

  return query
    select m.id, m.scope, m.key, m.read_count, m.opened_count, m.last_opened_at, m.created_at
      from memories m
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
       and (p_scope is null or m.scope = p_scope)
       and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
       and lorekit_lesson_utility(
             m.read_count, m.opened_count, m.created_at,
             p_min_deliveries, p_min_age_days, p_chosen_pull_through, p_broad_reach, now()
           ) = p_utility
     -- Most-delivered first WITHIN a quadrant, because that is the order the
     -- action wants: the noise-tax row costing the most context is the one to
     -- prune first, and the load-bearing row reaching the most sessions is the
     -- one to promote first. `id desc` is the stable tiebreak every other
     -- ranked read in this family uses.
     order by m.read_count desc, m.opened_count desc, m.id desc
     limit v_limit;
end;
$$;

revoke execute on function lorekit_memory_utility_rows(uuid, text, text, integer, text[], integer, integer, numeric, integer) from public, anon;
grant  execute on function lorekit_memory_utility_rows(uuid, text, text, integer, text[], integer, integer, numeric, integer) to authenticated, service_role;

comment on function lorekit_memory_utility_rows(uuid, text, text, integer, text[], integer, integer, numeric, integer) is
  'The active lessons in one quadrant of the delivered x chosen grid, most-
   delivered first. Same visibility and scoped-key narrowing as
   lorekit_memory_read_ranking. p_limit is clamped to [1, 100]; an unknown
   quadrant name raises 22023 rather than returning nothing.';

-- ── what delivery cost, over a window ────────────────────────────────────
create or replace function lorekit_memory_delivery_cost(
  p_user_id    uuid,
  p_since      timestamptz default null,
  p_until      timestamptz default null,
  p_scope      text        default null,
  p_key_scopes text[]      default '{}'
)
returns table (
  delivered_reads  bigint,
  chosen_reads     bigint,
  delivered_tokens bigint,
  chosen_tokens    bigint
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
begin
  return query
    -- `coalesce` on the aggregates, not on the row: `sum` over no rows is
    -- NULL, and a client reading `delivered_tokens: null` as 0 is the kind of
    -- accidental agreement that breaks the first time a caller is stricter.
    -- An account with no recorded reads gets four honest zeroes.
    select
      coalesce(sum(d.count), 0)::bigint,
      coalesce(sum(d.count) filter (where d.read_kind = 'targeted'), 0)::bigint,
      coalesce(sum(d.count * ceil(length(m.value) / 4.0)), 0)::bigint,
      coalesce(sum(d.count * ceil(length(m.value) / 4.0)) filter (where d.read_kind = 'targeted'), 0)::bigint
      from memory_read_daily d
      join memories m on m.id = d.memory_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       -- Archived lore is deliberately INCLUDED: it was delivered while it was
       -- live, and the point of this figure is what the reads actually cost.
       -- Excluding it would make the bill drop retroactively every time
       -- something is pruned, which is exactly backwards as a feedback signal.
       and (p_scope is null or m.scope = p_scope)
       and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
       -- HALF-OPEN `[since, until)`, the same asymmetry `/activity` and
       -- `/read-activity` use, so two adjacent windows partition the reads
       -- instead of both claiming the boundary day. The comparison is at DAY
       -- grain because `memory_read_daily` is a daily rollup and no finer
       -- answer exists — which makes `until` exclusive of the whole day it
       -- names. A caller wanting "through right now" therefore passes NO
       -- `until` (the default) rather than `now()`, which would drop today.
       and (p_since is null or d.day >= p_since::date)
       and (p_until is null or d.day <  p_until::date);
end;
$$;

revoke execute on function lorekit_memory_delivery_cost(uuid, timestamptz, timestamptz, text, text[]) from public, anon;
grant  execute on function lorekit_memory_delivery_cost(uuid, timestamptz, timestamptz, text, text[]) to authenticated, service_role;

comment on function lorekit_memory_delivery_cost(uuid, timestamptz, timestamptz, text, text[]) is
  'Reads and ESTIMATED tokens of lore delivered over a window, and how much of
   that was a deliberate (targeted) fetch. Windowed over memory_read_daily --
   a DIFFERENT source from lorekit_memory_utility_census, which reads the
   lifetime counters; each caller must caption its own window. The window is
   half-open [since, until) at DAY grain, so p_until excludes the whole day it
   names -- pass NULL, not now(), for "through right now". Tokens are
   length(value)/4, never tokenized: render them as estimates. Archived lore is
   included, because it cost context while it was live.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00106', 'memory_utility_grid')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00107_memory_citations.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00107 — citations: the signal pull-through cannot give.
--
-- WHAT IS STILL MISSING AFTER 00104. `opened_count / read_count` measures
-- SELECTION — of all the times a lesson was surfaced, how often did something
-- deliberately reach for it. That is a real signal and it is the best one
-- available from read telemetry alone, but it systematically under-counts the
-- path lore is mostly consumed by: a lesson INJECTED at SessionStart is already
-- in the agent's context and never needs a second fetch to change what the
-- agent does. Its pull-through can be 0% while it is the single most
-- influential lesson in the store.
--
-- Every surface built on pull-through says so out loud (the Insights cost line
-- prints "this measures whether lore is looked up on purpose, not whether it
-- changed an outcome"). This migration is the other half: a way for the only
-- party that KNOWS whether a lesson was applied — the agent — to say so.
--
-- THE SHAPE. `memory.write` gains an optional `cited: string[]` of `scope::key`
-- references. The retrospective write an agent already makes at the end of a
-- run names the lessons that shaped it, and each name becomes a citation row
-- joined to the memory it cites, the memory it was written from, and the
-- `correlation_id` that groups the run (`usage_events` already carries that
-- key, and `/usage/runs` already enumerates it). One new optional field on an
-- existing verb, not a new tool: every entry in `tools/list` is context the
-- model pays for in every session, and this one has nothing to dispatch.
--
-- WHY A TABLE AND NOT JUST A COUNTER. The counter (`memories.cited_count`) is
-- what the dashboard reads and what a `max_cited_count` retention condition
-- would read, and it could have been the whole feature. The rows earn their
-- keep by answering the two questions a counter cannot: WHICH lesson credited
-- this one (so a load-bearing rule can be traced to the retrospectives that
-- kept invoking it) and WHICH RUN (so a citation joins to the same
-- `correlation_id` grouping `/usage/runs` already shows). A bare counter also
-- has no idempotency key, which is the next paragraph.
--
-- IDEMPOTENCY, AND WHY IT LEANS TOWARD UNDER-COUNTING. The unique key is
-- `(cited_memory_id, citing_memory_id, coalesce(correlation_id, ''))`: one
-- citation per cited lesson per citing lesson per run. A retried write inside
-- one run does not double-count. Two genuinely separate runs each count, which
-- is right — a lesson applied on Monday and again on Friday was applied twice.
-- A caller that sends NO correlation id collapses to a single citation for that
-- pair forever, which under-counts; that is the deliberate direction, because
-- an inflated influence number is worse than a conservative one on a surface
-- whose entire argument is that the existing numbers overstate.
--
-- THE `updated_at` EXEMPTION IS LOAD-BEARING (00103/00104). `cited_count` and
-- `last_cited_at` are the fifth and sixth columns of the derived set a READ-ish
-- path writes. Without adding them to the trigger's mask, recording a citation
-- would restamp the cited lesson's `updated_at` — reintroducing exactly the
-- bug 00103 fixed, on a new path, and making the freshness column lie again.
-- migrations.test.sql §105 AC-2 is that assertion.
-- ═════════════════════════════════════════════════════════════════════════

-- ── 1. the counters on `memories` ─────────────────────────────────────────
alter table memories add column if not exists cited_count integer not null default 0;
alter table memories add column if not exists last_cited_at timestamptz;

alter table memories drop constraint if exists memories_cited_count_non_negative;
alter table memories add constraint memories_cited_count_non_negative
  check (cited_count >= 0);

comment on column memories.cited_count is
  'How many times an agent has explicitly CREDITED this lesson for shaping a run,
   via memory.write''s `cited` array (00107). Distinct from opened_count (00104),
   which counts deliberate FETCHES: a lesson injected at session start is already
   in context and can be applied without ever being fetched, so a lesson can have
   opened_count = 0 and a high cited_count. Never moved by any read. Not null,
   defaults to 0.';

comment on column memories.last_cited_at is
  'When this lesson was last explicitly credited by an agent (00107). Null until
   the first citation. Moved in the same statement as cited_count, off the same
   gate, so a count and its timestamp cannot disagree.';

-- ── 2. teach the trigger to mask them — BEFORE anything writes them ───────
-- 00103 exempted read_count/last_read_at/last_opened_at; 00104 added
-- opened_count. These are the fifth and sixth columns of the same derived set:
-- a citation is recorded ABOUT a lesson by a write to a DIFFERENT lesson, so
-- letting it restamp the cited row's `updated_at` would say "this lesson was
-- edited" when nobody touched its content. Asserted by §105 AC-2.
create or replace function lorekit_memories_set_updated_at()
returns trigger
language plpgsql
set search_path = public, extensions
as $$
declare
  v_new memories := new;
  v_old memories := old;
  v_embedding_changed boolean;
  v_counters_changed  boolean;
begin
  -- 00062's exemption: an embedding write.
  v_embedding_changed :=
       new.embedding is distinct from old.embedding
    or new.embedding_model is distinct from old.embedding_model;

  -- 00103's exemption, extended by 00104 (opened_count) and 00107
  -- (cited_count/last_cited_at): a derived-counter write that is not an edit.
  v_counters_changed :=
       new.read_count     is distinct from old.read_count
    or new.last_read_at   is distinct from old.last_read_at
    or new.last_opened_at is distinct from old.last_opened_at
    or new.opened_count   is distinct from old.opened_count
    or new.cited_count    is distinct from old.cited_count
    or new.last_cited_at  is distinct from old.last_cited_at;

  -- Mask the derived columns and the one being decided.
  --
  -- `fts` MUST be masked too, for 00062's reason: it is a GENERATED column and
  -- Postgres computes generated columns AFTER BEFORE-row triggers, so
  -- `new.fts` is NULL here while `old.fts` holds the stored value. An unmasked
  -- comparison finds every update "changed", which silently turns this whole
  -- function back into `set_updated_at`. It fails in the safe direction (a bump
  -- that should not happen, never a missing bump), which is exactly why it
  -- needs a test rather than a reading — see migrations.test.sql §101/§105.
  v_new.embedding := null; v_new.embedding_model := null;
  v_new.read_count := null; v_new.last_read_at := null; v_new.last_opened_at := null;
  v_new.opened_count := null;
  v_new.cited_count := null; v_new.last_cited_at := null;
  v_new.updated_at := null; v_new.fts := null;

  v_old.embedding := null; v_old.embedding_model := null;
  v_old.read_count := null; v_old.last_read_at := null; v_old.last_opened_at := null;
  v_old.opened_count := null;
  v_old.cited_count := null; v_old.last_cited_at := null;
  v_old.updated_at := null; v_old.fts := null;

  if (v_embedding_changed or v_counters_changed)
     and v_new is not distinct from v_old then
    new.updated_at := old.updated_at;
  else
    new.updated_at := now();
  end if;

  return new;
end;
$$;

comment on function lorekit_memories_set_updated_at() is
  'BEFORE UPDATE trigger on memories. Stamps updated_at = now() for a real
   content edit, and LEAVES IT ALONE for a write that only moves derived
   columns: the embedding pair (00062), the four read counters (00099/00103/
   00104) and the two citation counters (00107). Compares NEW to OLD with every
   derived column plus the generated `fts` masked out, so the exemption is a
   property of the whole row rather than a list of allowed callers.';

-- ── 3. the citation ledger ────────────────────────────────────────────────
create table if not exists memory_citations (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null,
  cited_memory_id   uuid not null references memories(id) on delete cascade,
  -- SET NULL, not CASCADE: purging the retrospective that credited a lesson
  -- must not erase the evidence that the lesson was credited. The counter on
  -- `memories` would then disagree with the ledger, and the counter is the one
  -- the product reads.
  citing_memory_id  uuid references memories(id) on delete set null,
  correlation_id    text,
  created_at        timestamptz not null default now()
);

-- Same ceiling `usage_events.correlation_id` carries (00058), so a value that
-- groups a run there can always be stored here.
alter table memory_citations drop constraint if exists memory_citations_correlation_id_len;
alter table memory_citations add constraint memory_citations_correlation_id_len
  check (correlation_id is null or char_length(correlation_id) <= 200);

-- The idempotency key. `coalesce` because a NULL never equals a NULL in a
-- unique index, so without it an uncorrelated retry would insert a second row.
-- See the header for why collapsing the uncorrelated case is the deliberate
-- direction.
create unique index if not exists memory_citations_once_per_run_idx
  on memory_citations (cited_memory_id, citing_memory_id, coalesce(correlation_id, ''));

-- The two reads this table exists for: "who credited this lesson" and "what did
-- this run credit".
create index if not exists memory_citations_cited_idx
  on memory_citations (cited_memory_id, created_at desc);
create index if not exists memory_citations_user_correlation_idx
  on memory_citations (user_id, correlation_id)
  where correlation_id is not null;

alter table memory_citations enable row level security;
-- No policies, and the `memory_read_daily`/`usage_events` reasoning verbatim:
-- every access is through the SECURITY DEFINER function below. RLS on with zero
-- policies denies every direct PostgREST request, which is the backstop against
-- the one path that is neither service-role nor SECURITY DEFINER — an
-- anon/authenticated key querying the table directly.
revoke all on memory_citations from anon, authenticated;
grant select, insert on memory_citations to service_role;

comment on table memory_citations is
  'One row per (cited lesson, citing lesson, run): an agent explicitly crediting
   a lesson for shaping the run it just finished, recorded from memory.write''s
   `cited` array (00107). The influence signal pull-through (00104) cannot give,
   because a lesson injected at session start is applied without ever being
   fetched. Unique on (cited_memory_id, citing_memory_id, coalesce(correlation_id,
   '''')) so a retry inside one run counts once. Never read through PostgREST.';

-- ── 4. the writer ─────────────────────────────────────────────────────────
-- Takes the references as two PARALLEL ARRAYS rather than an array of composite
-- types, for the reason every other array-taking RPC here does: PostgREST maps
-- `text[]` cleanly from JSON and a composite type would need a matching
-- declared type on both sides of the wire.
create or replace function lorekit_record_memory_citations(
  p_user_id          uuid,
  p_citing_memory_id uuid,
  p_cited_scopes     text[],
  p_cited_keys       text[],
  p_correlation_id   text default null
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_inserted integer := 0;
begin
  if p_user_id is null
     or p_cited_scopes is null
     or array_length(p_cited_scopes, 1) is null
     or coalesce(array_length(p_cited_scopes, 1), 0) <> coalesce(array_length(p_cited_keys, 1), 0)
  then
    return 0;
  end if;

  -- Resolve refs → ids under the CALLER'S OWN tenancy, and nothing wider. This
  -- runs SECURITY DEFINER on a service-role connection where `auth.uid()` is
  -- NULL for the api_key tier, so the `user_id` predicate is the only thing
  -- standing between a citation and someone else's lore. A ref that resolves to
  -- nothing is silently skipped: it names a lesson this account cannot see, or
  -- one that has since been deleted, and neither is the write's problem.
  --
  -- Org-owned lore is deliberately NOT resolvable here yet. `memories.user_id`
  -- is the row's owner, and widening to `lorekit_member_org_ids` would let one
  -- member's retrospective move a counter on a shared lesson that other members
  -- read — a decision about shared state that belongs in its own change, with
  -- its own audit story. Under-counting again, deliberately.
  with refs as (
    select trim(s.scope) as scope, trim(k.key) as key
      from unnest(p_cited_scopes) with ordinality as s(scope, n)
      join unnest(p_cited_keys)   with ordinality as k(key, n) using (n)
     where trim(s.scope) <> '' and trim(k.key) <> ''
  ),
  resolved as (
    select distinct m.id
      from refs r
      join memories m
        on m.scope = r.scope
       and m.key = r.key
       and m.user_id = p_user_id
       and m.archived_at is null
     -- A lesson cannot cite itself. A retrospective that names its own key is
     -- a model echoing the write it is making, not evidence of anything.
     where p_citing_memory_id is null or m.id <> p_citing_memory_id
  ),
  ins as (
    insert into memory_citations (user_id, cited_memory_id, citing_memory_id, correlation_id)
    select p_user_id, resolved.id, p_citing_memory_id, p_correlation_id
      from resolved
    on conflict do nothing
    returning cited_memory_id
  ),
  bumped as (
    -- Only the rows that ACTUALLY inserted move a counter, which is what makes
    -- the counter and the ledger agree after a retry.
    select cited_memory_id, count(*)::integer as n from ins group by cited_memory_id
  ),
  upd as (
    update memories m
       set cited_count = m.cited_count + b.n,
           last_cited_at = now()
      from bumped b
     where m.id = b.cited_memory_id
    returning b.n
  )
  select coalesce(sum(n), 0)::integer into v_inserted from upd;

  return v_inserted;
exception
  when others then
    -- Never let a citation break the write it accompanies. Same posture as
    -- `lorekit_record_memory_reads` and `lorekit_record_usage_event`.
    return 0;
end;
$$;

comment on function lorekit_record_memory_citations(uuid, uuid, text[], text[], text) is
  'Records that the write identified by p_citing_memory_id credited each
   (p_cited_scopes[i], p_cited_keys[i]) lesson for shaping the run p_correlation_id
   groups, and bumps memories.cited_count/.last_cited_at for each citation that
   was actually new. Resolves references ONLY within p_user_id''s own active lore
   -- an unresolvable ref is skipped, and a self-citation is dropped. Returns how
   many citations were newly recorded (0 on a duplicate run, 0 on any error).
   Swallows its own errors: a citation must never break the write carrying it.';

grant execute on function lorekit_record_memory_citations(uuid, uuid, text[], text[], text)
  to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00107', 'memory_citations')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00108_retention_conditions_on_aggregates.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00108 — the retention conditions reach the AGGREGATE reads, not just the list.
--
-- THE BUG. `lorekit_memory_list` has accepted the five retention thresholds
-- since 00105 (`p_min_age_days`, `p_unseen_days`, `p_max_seen_count`,
-- `p_max_read_count`, `p_max_opened_count`). The three functions that COUNT the
-- same population did not:
--
--     lorekit_memory_facets     the filter menu's per-value counts
--     lorekit_memory_activity   the Explorer's five stat cards
--     lorekit_memory_pivot      the Explorer's matrix
--
-- So setting any threshold moved the list and left every number describing it
-- unchanged. A user filtering to "never opened, older than 5 days" saw a short
-- list above a menu still offering `source::manual 150` — a count for a
-- population that filter had already excluded. The dimension filters were
-- always mirrored (00057/00064/00069), which is why the discrepancy read as a
-- facet bug rather than a missing parameter: a label pill moved the counts, a
-- threshold did not.
--
-- The `created_since`/`created_until` window had the identical gap and is fixed
-- with it. `lorekit_memory_activity` needs no new window — its own
-- `p_since`/`p_until` already bound `created_at`.
--
-- `q`, `p_key` and `expiring_within_days` stay unmirrored, for the reason
-- `ListFacetsQuerySchema` records: mirroring `q` means a second LIKE-escaper
-- inside plpgsql and mirroring `expiring_within_days` a second `now`-relative
-- boundary. A filter value is encoded exactly one way in this repo. The
-- thresholds carry no such cost — see the helper below.
--
-- ── DESIGN ───────────────────────────────────────────────────────────────
--
-- ONE HELPER, `lorekit_match_retention`, in 00066's inlinable-predicate family
-- (`lorekit_match_text` / `_tags` / `_int`). Four callers had five nearly
-- identical `and (p_x is null or …)` lines each; they now have one call each,
-- and migration 00100's never-opened rule — `coalesce(last_opened_at,
-- created_at)`, so a lesson nobody has EVER opened ages from its creation
-- rather than being immune — lives in exactly one place instead of four.
--
-- IT TAKES CUTOFF TIMESTAMPS, NOT DAY COUNTS. `now() - (n * interval '1 day')`
-- inside the helper would make it `stable` rather than `immutable`, costing the
-- inlining that keeps callers on index access, and would read the clock once
-- per ROW instead of once per call. Each caller resolves its own cutoffs in its
-- declare block, so the `now`-relative boundary is still computed exactly once
-- per query — the same discipline the unmirrored `expiring_within_days`
-- argument above is protecting.
--
-- IN THE `base` CTE's WHERE, NEVER AN `ok_*` SELF-EXCLUSION FLAG. `facets` and
-- `pivot` count each dimension with every OTHER filter applied but not its own,
-- so that a value's count is what selecting it would yield. That trick is
-- meaningful only for a dimension the caller can select a value FROM. A
-- threshold has no value catalog — "count this threshold with every filter but
-- itself" describes nothing — so it belongs in the row-visibility predicate
-- every facet value is derived from, alongside `p_scope` and `p_archived`.
--
-- ── SIGNATURES ───────────────────────────────────────────────────────────
--
-- The new parameters are APPENDED, null-defaulted, following 00101/00105. That
-- changes each function's signature, and `create or replace` CANNOT change a
-- signature — it would leave the old overload in place beside the new one, and
-- two overloads make every PostgREST named-argument call to that name fail as
-- ambiguous (the footgun 00092's header documents). So each of the three is
-- dropped at its EXACT old signature first.
--
-- `lorekit_memory_list` keeps its 00105 signature verbatim — only its body
-- changes, to compose the helper in place of its five inline lines — so it is a
-- true `create or replace` with no drop and its grants persist.
--
-- §108 in `migrations.test.sql` is the executable proof, including the case
-- that motivated the whole change: a threshold that narrows the list must
-- narrow the facet counts by the same rows.
-- ═════════════════════════════════════════════════════════════════════════

-- ── 1. The predicate ────────────────────────────────────────────────────────

-- The five retention thresholds as one row-level test.
--
-- Every parameter is independently optional: a null threshold is "not
-- filtered" and matches everything, so an untouched condition never narrows.
-- All five null (the overwhelmingly common case) is a constant `true` the
-- planner discards.
--
-- `immutable` + `parallel safe` + `language sql`, exactly as 00066's three
-- helpers, and for the same two reasons: the result depends only on the
-- arguments, and that is what lets the planner fold the call into an
-- index-usable expression rather than treating it as an opaque filter.
create or replace function lorekit_match_retention(
  -- The row's own counters.
  p_created_at        timestamptz,
  p_last_opened_at    timestamptz,
  p_seen_count        integer,
  p_read_count        integer,
  p_opened_count      integer,
  -- The filter, with both day counts already resolved to absolute instants by
  -- the caller. Null = that condition is not applied.
  p_created_cutoff    timestamptz,
  p_unseen_cutoff     timestamptz,
  p_max_seen_count    integer,
  p_max_read_count    integer,
  p_max_opened_count  integer
)
returns boolean
language sql
immutable
parallel safe
as $$
  select coalesce(
    (p_created_cutoff is null or p_created_at <= p_created_cutoff)
    -- 00100: a lesson NEVER opened ages from its creation date. Without the
    -- coalesce a null `last_opened_at` makes the comparison NULL, which
    -- excludes the row — so the lore nothing has ever opened would be the one
    -- lore an "unopened for N days" filter could never find.
    and (p_unseen_cutoff is null or coalesce(p_last_opened_at, p_created_at) <= p_unseen_cutoff)
    -- `<=`, so a threshold of 0 is meaningful: `max_opened_count => 0` is
    -- "nothing ever chose to open it" (00105), not "no filter".
    and (p_max_seen_count   is null or p_seen_count   <= p_max_seen_count)
    and (p_max_read_count   is null or p_read_count   <= p_max_read_count)
    and (p_max_opened_count is null or p_opened_count <= p_max_opened_count),
    false);
$$;

comment on function lorekit_match_retention(
  timestamptz, timestamptz, integer, integer, integer,
  timestamptz, timestamptz, integer, integer, integer
) is
  'Does a memory satisfy a retention-policy condition set? The five thresholds
   of GroomConditionsSchema, as one inlinable row test shared by
   lorekit_memory_list, _facets, _activity and _pivot so a count cannot
   disagree with the list it describes (00108). Takes CUTOFF INSTANTS rather
   than day counts so it stays immutable and reads no clock: the caller
   resolves now()-relative bounds once per query. A null threshold is "not
   filtered". Holds migration 00100''s never-opened rule
   (coalesce(last_opened_at, created_at)) in one place.';

-- The same revoke/grant pair 00066's three helpers carry. A `create or replace`
-- of a NEW function starts from the default ACL, which is EXECUTE to public —
-- so without this line the helper would be the one member of the
-- `lorekit_match_*` family reachable by `anon`. It reads no table and would
-- leak nothing, but a predicate helper with a different ACL from its three
-- siblings is a difference someone has to re-derive later.
revoke execute on function lorekit_match_retention(
  timestamptz, timestamptz, integer, integer, integer,
  timestamptz, timestamptz, integer, integer, integer
) from public, anon;
grant  execute on function lorekit_match_retention(
  timestamptz, timestamptz, integer, integer, integer,
  timestamptz, timestamptz, integer, integer, integer
) to authenticated, service_role;

-- ── 2. lorekit_memory_facets ────────────────────────────────────────────────

drop function if exists lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[]
);

create or replace function lorekit_memory_facets(
  p_user_id            uuid,
  p_archived           boolean default false,
  p_scope              text    default null,
  p_tags               text[]  default null,
  p_tags_mode          text    default 'any',
  p_source_agent       text[]  default null,
  p_source_agent_mode  text    default 'in',
  p_trigger            text[]  default null,
  p_trigger_mode       text    default 'in',
  p_kind               text[]  default null,
  p_kind_mode          text    default 'in',
  p_host               text[]  default null,
  p_host_mode          text    default 'in',
  p_origin_repo        text[]  default null,
  p_origin_repo_mode   text    default 'in',
  p_origin_branch      text[]  default null,
  p_origin_branch_mode text    default 'in',
  p_origin_pr          text[]  default null,
  p_origin_pr_mode     text    default 'in',
  -- Owner dimension (00064). `personal` plus one slug per member org with
  -- visible rows. All optional: null/absent = not filtered.
  p_owner              text[]  default null,
  p_owner_mode         text    default 'in',
  -- The CALLING KEY's restriction (00068), defaulted to unrestricted.
  p_key_scopes         text[]  default '{}',
  p_key_org_access     text    default 'all',
  p_key_org_ids        uuid[]  default '{}',
  -- 00108: the created_at window and the five retention thresholds, so a count
  -- describes the same rows the list shows. Appended, null-defaulted.
  p_created_since      timestamptz default null,
  p_created_until      timestamptz default null,
  p_min_age_days       integer default null,
  p_unseen_days        integer default null,
  p_max_seen_count     integer default null,
  p_max_read_count     integer default null,
  p_max_opened_count   integer default null
)
returns table (facet text, value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
  -- Resolved ONCE per call, so lorekit_match_retention can stay immutable and
  -- the clock is read once rather than once per row (00108).
  v_created_cutoff timestamptz := case
    when p_min_age_days is null then null else now() - (p_min_age_days * interval '1 day')
  end;
  v_unseen_cutoff timestamptz := case
    when p_unseen_days is null then null else now() - (p_unseen_days * interval '1 day')
  end;
begin
  return query
  with base as (
    select
      m.tags, m.source_agent, m.trigger, m.kind, m.host,
      m.origin_repo, m.origin_branch, m.origin_pr,
      m.org_id, o.slug as org_slug,
      -- Per-dimension match flag, now from the shared predicates so it cannot
      -- drift from lorekit_memory_activity's. A null filter is "not filtered" →
      -- the helper returns true, so an untouched dimension never narrows.
      lorekit_match_tags(m.tags,          p_tags,          p_tags_mode)          as ok_tag,
      lorekit_match_text(m.source_agent,  p_source_agent,  p_source_agent_mode)  as ok_source_agent,
      lorekit_match_text(m.trigger,       p_trigger,       p_trigger_mode)       as ok_trigger,
      lorekit_match_text(m.kind,          p_kind,          p_kind_mode)          as ok_kind,
      lorekit_match_text(m.host,          p_host,          p_host_mode)          as ok_host,
      lorekit_match_text(m.origin_repo,   p_origin_repo,   p_origin_repo_mode)   as ok_origin_repo,
      lorekit_match_text(m.origin_branch, p_origin_branch, p_origin_branch_mode) as ok_origin_branch,
      lorekit_match_int (m.origin_pr,     v_origin_pr,     p_origin_pr_mode)     as ok_origin_pr,
      -- Owner: the computed identity is `personal` (org_id null) or the org slug.
      -- Stays inline — it is not one of the three column helpers (00064).
      (p_owner is null or case coalesce(p_owner_mode, 'in')
         when 'nin' then (
           (case when m.org_id is null then 'personal' else o.slug end) is not null
           and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
         )
         else (
           ('personal' = any(p_owner) and m.org_id is null)
           or (m.org_id is not null and o.slug = any(p_owner))
         )
       end) as ok_owner
      from memories m
      -- A personal row has no org, so this is a LEFT join; org rows resolve to
      -- their slug. Visible org rows are always the caller's own orgs (the
      -- visibility predicate below admits them only via lorekit_member_org_ids),
      -- so `o.slug` is never a slug the caller cannot see.
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       -- The calling key's restriction, applied ONCE here in the row-visibility
       -- predicate every emitted facet value is derived from — `origin_repo` is
       -- a repository name by construction, so an unnarrowed facet list leaks
       -- exactly what the scope catalog hides.
       and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
       and lorekit_api_token_org_allowed(p_key_org_access, p_key_org_ids, m.org_id)
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and (p_scope is null or m.scope = p_scope)
       -- 00108. Here rather than as an `ok_*` flag: these narrow the population
       -- every facet value is drawn from, they are not a dimension that can be
       -- self-excluded. Half-open window, matching lorekit_memory_list.
       and (p_created_since is null or m.created_at >= p_created_since)
       and (p_created_until is null or m.created_at <  p_created_until)
       and lorekit_match_retention(
             m.created_at, m.last_opened_at, m.seen_count, m.read_count, m.opened_count,
             v_created_cutoff, v_unseen_cutoff, p_max_seen_count, p_max_read_count, p_max_opened_count
           )
  ), cells as (
    select 'tag'::text as facet, t.tag as value
      from base b
      cross join lateral unnest(b.tags) as t(tag)
     where b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'source_agent', b.source_agent from base b
     where b.ok_tag and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'trigger', b.trigger from base b
     where b.ok_tag and b.ok_source_agent and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'kind', b.kind from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'host', b.host from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_repo', b.origin_repo from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_branch', b.origin_branch from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_pr and b.ok_owner
    union all
    select 'origin_pr', b.origin_pr::text from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_owner
    union all
    -- Owner is the ONE dimension self-excluded here (every other flag, NOT
    -- ok_owner), so a drilled-in owner still lists the alternative owner.
    select 'owner', case when b.org_id is null then 'personal' else b.org_slug end from base b
     where b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
       and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr
  )
  select c.facet, c.value, count(*) as count
    from cells c
   where c.value is not null
     and btrim(c.value) <> ''
   group by c.facet, c.value
   order by c.facet asc, count(*) desc, c.value asc;
end;
$$;

revoke execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) from public, anon;
grant execute on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) to authenticated, service_role;

comment on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) is
  'Value catalog with counts for every filterable memory dimension (tag,
   source_agent, trigger, kind, host, origin_repo, origin_branch, origin_pr,
   owner) over the partition selected by p_archived, visible to the EFFECTIVE
   caller and narrowed by the calling key''s own scope/org restriction. Each
   dimension is counted with every OTHER dimension filter applied but not its
   own (drill-down self-exclusion, 00057). The created_at window and the five
   retention thresholds (00108) are NOT self-excluded: they narrow the
   population every facet value is drawn from, so a count matches the list
   under the same parameters. q/key/expiring_within_days remain unmirrored, so
   with those active a count is an upper bound.';

-- ── 3. lorekit_memory_activity ──────────────────────────────────────────────

drop function if exists lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[]
);

create or replace function lorekit_memory_activity(
  p_user_id uuid,
  p_bucket  text        default 'day',
  p_since   timestamptz default null,
  p_until   timestamptz default null,
  p_scope              text   default null,
  p_tags               text[] default null,
  p_tags_mode          text   default 'any',
  p_source_agent       text[] default null,
  p_source_agent_mode  text   default 'in',
  p_trigger            text[] default null,
  p_trigger_mode       text   default 'in',
  p_kind               text[] default null,
  p_kind_mode          text   default 'in',
  p_host               text[] default null,
  p_host_mode          text   default 'in',
  p_origin_repo        text[] default null,
  p_origin_repo_mode   text   default 'in',
  p_origin_branch      text[] default null,
  p_origin_branch_mode text   default 'in',
  p_origin_pr          text[] default null,
  p_origin_pr_mode     text   default 'in',
  p_owner              text[] default null,
  p_owner_mode         text   default 'in',
  -- The CALLING KEY's restriction (00068), defaulted to unrestricted.
  p_key_scopes         text[] default '{}',
  p_key_org_access     text   default 'all',
  p_key_org_ids        uuid[] default '{}',
  -- 00108: the five retention thresholds. No created_at window is added — this
  -- function's own p_since/p_until already bound created_at, and a second
  -- window would be two ways to say one thing.
  p_min_age_days       integer default null,
  p_unseen_days        integer default null,
  p_max_seen_count     integer default null,
  p_max_read_count     integer default null,
  p_max_opened_count   integer default null
)
returns table (bucket timestamptz, scope text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  -- `origin_pr` is an INTEGER column: coerce the digits-only list numerically so
  -- this route matches GET /memories on the same input (00057's rationale). A
  -- non-numeric entry is dropped; a list reducing to empty applies no filter.
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
  v_created_cutoff timestamptz := case
    when p_min_age_days is null then null else now() - (p_min_age_days * interval '1 day')
  end;
  v_unseen_cutoff timestamptz := case
    when p_unseen_days is null then null else now() - (p_unseen_days * interval '1 day')
  end;
begin
  if p_bucket is null or p_bucket not in ('hour', 'day') then
    raise exception 'invalid bucket %, expected hour or day', p_bucket
      using errcode = '22023';
  end if;

  return query
    select date_trunc(p_bucket, m.created_at at time zone 'UTC') at time zone 'UTC' as bucket,
           m.scope,
           count(*) as count
      from memories m
      -- LEFT join for the owner predicate — a personal row has no org (00064).
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       -- The calling key's own restriction, ANDed on top of the caller's
       -- visibility and never instead of it (the lorekit_memory_scopes rule).
       and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
       and lorekit_api_token_org_allowed(p_key_org_access, p_key_org_ids, m.org_id)
       and m.archived_at is null
       and (m.expires_at is null or m.expires_at > now())
       and (p_since is null or m.created_at >= p_since)
       and (p_until is null or m.created_at <  p_until)
       -- Scope is a hard filter, always applied (00057's treatment).
       and (p_scope is null or m.scope = p_scope)
       -- Dimension filters — AND across, OR within, from the shared predicates
       -- (00066) so the semantics cannot drift from lorekit_memory_facets. No
       -- self-exclusion here: a straight count applies every one directly.
       and lorekit_match_tags(m.tags,          p_tags,          p_tags_mode)
       and lorekit_match_text(m.source_agent,  p_source_agent,  p_source_agent_mode)
       and lorekit_match_text(m.trigger,       p_trigger,       p_trigger_mode)
       and lorekit_match_text(m.kind,          p_kind,          p_kind_mode)
       and lorekit_match_text(m.host,          p_host,          p_host_mode)
       and lorekit_match_text(m.origin_repo,   p_origin_repo,   p_origin_repo_mode)
       and lorekit_match_text(m.origin_branch, p_origin_branch, p_origin_branch_mode)
       and lorekit_match_int (m.origin_pr,     v_origin_pr,     p_origin_pr_mode)
       -- 00108: the same thresholds the list applies, so the Explorer's stat
       -- cards describe the rows underneath them.
       and lorekit_match_retention(
             m.created_at, m.last_opened_at, m.seen_count, m.read_count, m.opened_count,
             v_created_cutoff, v_unseen_cutoff, p_max_seen_count, p_max_read_count, p_max_opened_count
           )
       -- Owner: `personal` for org_id-null rows, else the org slug (00064).
       and (p_owner is null or case coalesce(p_owner_mode, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
             )
             else (
               ('personal' = any(p_owner) and m.org_id is null)
               or (m.org_id is not null and o.slug = any(p_owner))
             )
           end)
     group by 1, m.scope
     order by 1 asc, m.scope asc;
end;
$$;

revoke execute on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], integer, integer, integer, integer, integer
) from public, anon;
grant execute on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], integer, integer, integer, integer, integer
) to authenticated, service_role;

comment on function lorekit_memory_activity(
  uuid, text, timestamptz, timestamptz, text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], integer, integer, integer, integer, integer
) is
  'Memories created per UTC hour/day per scope, visible to the EFFECTIVE caller
   and narrowed by the calling key''s own scope/org restriction. Applies every
   dimension filter directly (no self-exclusion — this is a straight count) and,
   since 00108, the same five retention thresholds lorekit_memory_list applies,
   so the Explorer''s stat cards describe the list beneath them. p_since/p_until
   already bound created_at, so no separate window parameter exists.';

-- ── 4. lorekit_memory_pivot ─────────────────────────────────────────────────

drop function if exists lorekit_memory_pivot(
  text, text, uuid, boolean, text, integer, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[]
);

create or replace function lorekit_memory_pivot(
  p_row_facet          text,
  p_col_facet          text,
  p_user_id            uuid    default null,
  p_archived           boolean default false,
  p_scope              text    default null,
  p_limit              integer default 400,
  p_tags               text[]  default null,
  p_tags_mode          text    default 'any',
  p_source_agent       text[]  default null,
  p_source_agent_mode  text    default 'in',
  p_trigger            text[]  default null,
  p_trigger_mode       text    default 'in',
  p_kind               text[]  default null,
  p_kind_mode          text    default 'in',
  p_host               text[]  default null,
  p_host_mode          text    default 'in',
  p_origin_repo        text[]  default null,
  p_origin_repo_mode   text    default 'in',
  p_origin_branch      text[]  default null,
  p_origin_branch_mode text    default 'in',
  p_origin_pr          text[]  default null,
  p_origin_pr_mode     text    default 'in',
  p_owner              text[]  default null,
  p_owner_mode         text    default 'in',
  -- The CALLING KEY's restriction (00068), defaulted to unrestricted.
  p_key_scopes         text[]  default '{}',
  p_key_org_access     text    default 'all',
  p_key_org_ids        uuid[]  default '{}',
  -- 00108: the created_at window and the five retention thresholds.
  p_created_since      timestamptz default null,
  p_created_until      timestamptz default null,
  p_min_age_days       integer default null,
  p_unseen_days        integer default null,
  p_max_seen_count     integer default null,
  p_max_read_count     integer default null,
  p_max_opened_count   integer default null
)
returns table (row_value text, col_value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
  v_created_cutoff timestamptz := case
    when p_min_age_days is null then null else now() - (p_min_age_days * interval '1 day')
  end;
  v_unseen_cutoff timestamptz := case
    when p_unseen_days is null then null else now() - (p_unseen_days * interval '1 day')
  end;
begin
  return query
  with base as (
    select
      m.tags, m.source_agent, m.trigger, m.kind, m.host,
      m.origin_repo, m.origin_branch, m.origin_pr,
      m.org_id, o.slug as org_slug,
      lorekit_match_tags(m.tags,          p_tags,          p_tags_mode)          as ok_tag,
      lorekit_match_text(m.source_agent,  p_source_agent,  p_source_agent_mode)  as ok_source_agent,
      lorekit_match_text(m.trigger,       p_trigger,       p_trigger_mode)       as ok_trigger,
      lorekit_match_text(m.kind,          p_kind,          p_kind_mode)          as ok_kind,
      lorekit_match_text(m.host,          p_host,          p_host_mode)          as ok_host,
      lorekit_match_text(m.origin_repo,   p_origin_repo,   p_origin_repo_mode)   as ok_origin_repo,
      lorekit_match_text(m.origin_branch, p_origin_branch, p_origin_branch_mode) as ok_origin_branch,
      lorekit_match_int (m.origin_pr,     v_origin_pr,     p_origin_pr_mode)     as ok_origin_pr,
      -- Owner stays inline for lorekit_memory_facets' reason: it is a
      -- LEFT JOIN-computed identity, not one of the three column helpers.
      (p_owner is null or case coalesce(p_owner_mode, 'in')
         when 'nin' then (
           (case when m.org_id is null then 'personal' else o.slug end) is not null
           and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
         )
         else (
           ('personal' = any(p_owner) and m.org_id is null)
           or (m.org_id is not null and o.slug = any(p_owner))
         )
       end) as ok_owner
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
       and lorekit_api_token_org_allowed(p_key_org_access, p_key_org_ids, m.org_id)
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and (p_scope is null or m.scope = p_scope)
       -- 00108. Row-visibility, not an `ok_*` flag — see lorekit_memory_facets.
       and (p_created_since is null or m.created_at >= p_created_since)
       and (p_created_until is null or m.created_at <  p_created_until)
       and lorekit_match_retention(
             m.created_at, m.last_opened_at, m.seen_count, m.read_count, m.opened_count,
             v_created_cutoff, v_unseen_cutoff, p_max_seen_count, p_max_read_count, p_max_opened_count
           )
  )
  select rv.value, cv.value, count(*)::bigint
    from base b
    cross join lateral lorekit_memory_facet_value(
      p_row_facet, b.tags, b.source_agent, b.trigger, b.kind, b.host,
      b.origin_repo, b.origin_branch, b.origin_pr, b.org_id, b.org_slug
    ) as rv(value)
    cross join lateral lorekit_memory_facet_value(
      p_col_facet, b.tags, b.source_agent, b.trigger, b.kind, b.host,
      b.origin_repo, b.origin_branch, b.origin_pr, b.org_id, b.org_slug
    ) as cv(value)
   -- Each dimension's own filter applies UNLESS it is one of the two axes —
   -- see the self-exclusion note at the top. One line per dimension so adding
   -- a tenth is one line here, not a re-derivation.
   where (p_row_facet = 'tag'           or p_col_facet = 'tag'           or b.ok_tag)
     and (p_row_facet = 'source_agent'  or p_col_facet = 'source_agent'  or b.ok_source_agent)
     and (p_row_facet = 'trigger'       or p_col_facet = 'trigger'       or b.ok_trigger)
     and (p_row_facet = 'kind'          or p_col_facet = 'kind'          or b.ok_kind)
     and (p_row_facet = 'host'          or p_col_facet = 'host'          or b.ok_host)
     and (p_row_facet = 'origin_repo'   or p_col_facet = 'origin_repo'   or b.ok_origin_repo)
     and (p_row_facet = 'origin_branch' or p_col_facet = 'origin_branch' or b.ok_origin_branch)
     and (p_row_facet = 'origin_pr'     or p_col_facet = 'origin_pr'     or b.ok_origin_pr)
     and (p_row_facet = 'owner'         or p_col_facet = 'owner'         or b.ok_owner)
     -- A null column value yields no cell, matching lorekit_memory_facets.
     and rv.value is not null
     and cv.value is not null
   group by rv.value, cv.value
   -- Densest cells first, so a caller that has to truncate keeps the ones
   -- worth drawing. Deterministic tie-break so a page boundary is stable.
   order by count(*) desc, rv.value asc, cv.value asc
   limit greatest(p_limit, 0);
end;
$$;

revoke execute on function lorekit_memory_pivot(
  text, text, uuid, boolean, text, integer, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) from public, anon;
grant execute on function lorekit_memory_pivot(
  text, text, uuid, boolean, text, integer, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) to authenticated, service_role;

comment on function lorekit_memory_pivot(
  text, text, uuid, boolean, text, integer, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) is
  'Cross-tabulation of two facet dimensions with a count per cell, visible to
   the EFFECTIVE caller and narrowed by the calling key''s own scope/org
   restriction. BOTH axes are self-excluded from the dimension filters, so a
   caller that turns a cell into a filter still gets every other cell back. The
   created_at window and the five retention thresholds (00108) are not
   self-excluded — they narrow the population, matching lorekit_memory_facets.';

-- ── 5. lorekit_memory_list — compose the helper, signature unchanged ────────
--
-- A true `create or replace`: the 00105 signature is kept VERBATIM, so no drop
-- is needed and the 00105 grants persist. Only the five inline threshold lines
-- change, into one call, which is what puts 00100's never-opened rule in one
-- place across all four functions. `$35`/`$36` now carry resolved CUTOFFS
-- rather than day counts — the parameter list and every position are
-- unchanged, so no caller moves.
create or replace function lorekit_memory_list(
  p_user_id              uuid,
  p_archived             boolean     default false,
  p_scope                text        default null,
  p_key                  text        default null,
  p_key_prefix           text        default null,
  p_q                    text        default null,
  p_created_since        timestamptz default null,
  p_created_until        timestamptz default null,
  p_expires_after        timestamptz default null,
  p_expires_on_or_before timestamptz default null,
  p_tags                 text[]      default null,
  p_tags_mode            text        default 'any',
  p_source_agent         text[]      default null,
  p_source_agent_mode    text        default 'in',
  p_trigger              text[]      default null,
  p_trigger_mode         text        default 'in',
  p_kind                 text[]      default null,
  p_kind_mode            text        default 'in',
  p_host                 text[]      default null,
  p_host_mode            text        default 'in',
  p_origin_repo          text[]      default null,
  p_origin_repo_mode     text        default 'in',
  p_origin_branch        text[]      default null,
  p_origin_branch_mode   text        default 'in',
  p_origin_pr            text[]      default null,
  p_origin_pr_mode       text        default 'in',
  p_owner                text[]      default null,
  p_owner_mode           text        default 'in',
  p_sort                 text        default 'updated_at',
  p_cursor_ts            timestamptz default null,
  p_cursor_id            uuid        default null,
  p_limit                integer     default 51,
  p_key_scopes           text[]      default '{}',
  p_key_org_access       text        default 'all',
  p_key_org_ids          uuid[]      default '{}',
  p_min_age_days         integer     default null,
  p_unseen_days          integer     default null,
  p_max_seen_count       integer     default null,
  p_max_read_count       integer     default null,
  p_max_opened_count     integer     default null
)
returns table (
  id             uuid,
  scope          text,
  key            text,
  value          text,
  tags           text[],
  source_agent   text,
  trigger        text,
  created_at     timestamptz,
  updated_at     timestamptz,
  expires_at     timestamptz,
  archived_at    timestamptz,
  origin_repo    text,
  origin_branch  text,
  origin_commit  text,
  origin_pr      integer,
  kind           text,
  host           text,
  seen_count     integer,
  read_count     integer,
  opened_count   integer,
  last_read_at   timestamptz,
  last_opened_at timestamptz,
  org_id         uuid,
  created_by     uuid,
  updated_by     uuid,
  org_name       text,
  org_slug       text,
  total_count    integer
)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^0*[0-9]{1,9}$'
  );
  v_sort text := case when p_sort = 'created_at' then 'created_at' else 'updated_at' end;
  -- Resolved once per call so lorekit_match_retention stays immutable (00108).
  v_created_cutoff timestamptz := case
    when p_min_age_days is null then null else now() - (p_min_age_days * interval '1 day')
  end;
  v_unseen_cutoff timestamptz := case
    when p_unseen_days is null then null else now() - (p_unseen_days * interval '1 day')
  end;
begin
  return query execute format($q$
    select
      m.id, m.scope, m.key, m.value, m.tags, m.source_agent, m.trigger,
      m.created_at, m.updated_at, m.expires_at, m.archived_at,
      m.origin_repo, m.origin_branch, m.origin_commit, m.origin_pr,
      m.kind, m.host, m.seen_count,
      m.read_count, m.opened_count, m.last_read_at, m.last_opened_at,
      m.org_id, m.created_by, m.updated_by,
      o.name as org_name, o.slug as org_slug,
      (count(*) over ())::integer as total_count
      from memories m
      left join orgs o on o.id = m.org_id
     where (
             ($1 is null and auth.role() = 'service_role')
             or m.user_id = $1
             or m.org_id in (select lorekit_member_org_ids($1))
           )
       and lorekit_api_token_scope_allowed($32, m.scope)
       and lorekit_api_token_org_allowed($33, $34, m.org_id)
       and (
             case
               when $2 then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and ($3 is null or m.scope = $3)
       and ($4 is null or m.key = $4)
       and ($5 is null or m.key ilike $5 || '%%')
       and ($6 is null or m.key ilike '%%' || $6 || '%%' or m.value ilike '%%' || $6 || '%%')
       and ($7 is null or m.created_at >= $7)
       and ($8 is null or m.created_at < $8)
       and ($9  is null or m.expires_at > $9)
       and ($10 is null or m.expires_at <= $10)
       and lorekit_match_tags(m.tags,          $11, $12)
       and lorekit_match_text(m.source_agent,  $13, $14)
       and lorekit_match_text(m.trigger,       $15, $16)
       and lorekit_match_text(m.kind,          $17, $18)
       and lorekit_match_text(m.host,          $19, $20)
       and lorekit_match_text(m.origin_repo,   $21, $22)
       and lorekit_match_text(m.origin_branch, $23, $24)
       and lorekit_match_int (m.origin_pr,     $25, $26)
       and ($27 is null or case coalesce($28, 'in')
             when 'nin' then (
               (case when m.org_id is null then 'personal' else o.slug end) is not null
               and (case when m.org_id is null then 'personal' else o.slug end) <> all($27)
             )
             else (
               ('personal' = any($27) and m.org_id is null)
               or (m.org_id is not null and o.slug = any($27))
             )
           end)
       and lorekit_match_retention(
             m.created_at, m.last_opened_at, m.seen_count, m.read_count, m.opened_count,
             $35, $36, $37, $38, $39
           )
       and (
             $29 is null
             or m.%1$I < $29
             or (m.%1$I = $29 and m.id < $30)
           )
     order by m.%1$I desc, m.id desc
     limit $31
  $q$, v_sort)
  using
    v_actor, coalesce(p_archived, false), p_scope, p_key, p_key_prefix, p_q,
    p_created_since, p_created_until, p_expires_after, p_expires_on_or_before,
    p_tags, p_tags_mode,
    p_source_agent, p_source_agent_mode,
    p_trigger, p_trigger_mode,
    p_kind, p_kind_mode,
    p_host, p_host_mode,
    p_origin_repo, p_origin_repo_mode,
    p_origin_branch, p_origin_branch_mode,
    v_origin_pr, p_origin_pr_mode,
    p_owner, p_owner_mode,
    p_cursor_ts, p_cursor_id,
    greatest(coalesce(p_limit, 51), 1),
    coalesce(p_key_scopes, '{}'::text[]),
    coalesce(p_key_org_access, 'all'),
    coalesce(p_key_org_ids, '{}'::uuid[]),
    v_created_cutoff, v_unseen_cutoff, p_max_seen_count, p_max_read_count,
    p_max_opened_count;
end;
$$;

grant execute on function lorekit_memory_list(
  uuid, boolean, text, text, text, text, timestamptz, timestamptz, timestamptz,
  timestamptz, text[], text, text[], text, text[], text, text[], text, text[],
  text, text[], text, text[], text, text[], text, text[], text, text,
  timestamptz, uuid, integer, text[], text, uuid[], integer, integer, integer,
  integer, integer
) to authenticated, service_role;
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00108', 'retention_conditions_on_aggregates')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00109_usage_events_read_activity_idx.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00109 — a covering index for lorekit_read_activity's own predicate.
--
-- THE BUG. `lorekit_read_activity` (00080) filters `usage_events` on
-- `user_id = v_actor AND tool_name IN ('memory.read', 'memory.list',
-- 'memory.search', 'memory.list_archived') AND created_at >= p_since AND
-- created_at < p_until` — and `GET /memories/read-activity` defaults that
-- window to 200 days when the caller passes no `since`/`until`
-- (`DEFAULT_WINDOW_DAYS`, read-activity.ts).
--
-- The only index that can serve that query is `usage_events_user_created_at_idx`
-- (00034) on `(user_id, created_at desc)` — it carries no `tool_name`, so
-- Postgres range-scans EVERY row the user wrote in the window and filters
-- `tool_name` afterward. `usage_events` is this schema's highest-volume table
-- by construction (00080's own comment: a single SessionStart hook can write
-- ~31 rows per call, ~16,000 times, in a 30-day sample) — so for an active
-- account a 200-day scan routinely touches hundreds of thousands of rows that
-- are never in the 4-tool read family at all (writes, org calls, etc.), all to
-- return a handful of read-family rows.
--
-- Observed in production: `GET /memories/read-activity` canceling with
-- "statement timeout" after ~20s of pure DB wait
-- (`lorekit.io.wait_ms` == the request's full duration), concentrated on
-- heavier accounts — exactly the profile a full per-user scan predicts.
--
-- THE FIX. A partial index scoped to the same 4-tool read family this
-- function already hardcodes, so Postgres can seek straight to the
-- `(user_id, created_at)` range within JUST those rows instead of scanning
-- the account's entire event history. Partial (not a plain 3-column index)
-- because the read family is a small, fixed slice of `tool_name`'s domain —
-- indexing the other tool names would bloat the index for no query that uses
-- them via this predicate.
-- ═════════════════════════════════════════════════════════════════════════

create index if not exists usage_events_user_tool_created_idx
  on usage_events (user_id, tool_name, created_at desc)
  where tool_name in ('memory.read', 'memory.list', 'memory.search', 'memory.list_archived');

comment on index usage_events_user_tool_created_idx is
  'Covers lorekit_read_activity''s (user_id, tool_name IN (4 read tools), created_at)
   predicate (00080) so the 200-day default window (read-activity.ts) does not
   force a full per-user scan of usage_events, this schema''s highest-volume
   table. Fixes production statement-timeout cancellations on
   GET /memories/read-activity for heavier accounts.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00109', 'usage_events_read_activity_idx')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00110_facets_within_group_cooccurrence.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- 00110 — within-group facet counting: co-occurrence for AND mode, and a
-- stable (zero-stays) value set for every dimension.
--
-- THE BUG (two, related). `lorekit_memory_facets` (00108) counts each
-- dimension against every OTHER dimension's filter, self-excluding its own —
-- the drill-down convention that lets you widen or switch within the
-- dimension you are standing in. Two consequences of doing this
-- unconditionally:
--
--   1. Selecting a `label` in `all` (AND / "includes all") mode still
--      self-excluded the tag dimension, so every OTHER label's count ignored
--      the selection entirely rather than answering "how many memories carry
--      BOTH the selected label(s) AND this one" — the question an AND
--      selection actually poses.
--   2. A value that had ZERO matching rows under the active filters simply
--      never appeared: the old `cells` CTE filtered rows to the matching set
--      BEFORE grouping, so a value only visible on now-excluded rows vanished
--      from the menu instead of reading as `count: 0`. A vanishing option
--      reads as "this value no longer exists"; a `0` reads as "not with your
--      current selection" — the honest answer.
--
-- ── DESIGN (Decision D5) ─────────────────────────────────────────────────
--
-- `v_tag_cooccur := (p_tags_mode = 'all')` — co-occurrence is gated on AND
-- mode. It is meaningless for a scalar column (`host = X` intersected with
-- `host = Y` is always empty — a memory has one host) and wrong for OR
-- multi-select (there you want what ADDING a value yields, i.e. the current
-- self-exclusion), so every scalar dimension and every non-`all` tag mode
-- keep self-exclusion exactly as 00108 left it. Only the tag branch's OWN
-- flag (`b.ok_tag`) is conditionally folded back in.
--
-- Every branch now enumerates its full candidate set from `base` — the
-- unfiltered-by-dimension population `base` already restricts to
-- visibility / archived / tenant-scope / created-window / retention — and
-- computes its count with `count(*) filter (where <predicate>)`, so a value
-- with zero matching rows still gets a `group by` row (via the `cells` CTE's
-- unconditional membership) with `count = 0`, instead of being absent.
--
-- Response shape, RPC signature and grants are UNCHANGED (Decision D6) — only
-- the `cells` CTE's body and the final aggregation change from
-- "filter-then-group" to "group-then-filter-count". `migrations.test.sql`
-- §110 is the executable proof, including the AND vs. OR distinction and the
-- cross-group AND that must still narrow every dimension's counts.
-- ═════════════════════════════════════════════════════════════════════════

create or replace function lorekit_memory_facets(
  p_user_id            uuid,
  p_archived           boolean default false,
  p_scope              text    default null,
  p_tags               text[]  default null,
  p_tags_mode          text    default 'any',
  p_source_agent       text[]  default null,
  p_source_agent_mode  text    default 'in',
  p_trigger            text[]  default null,
  p_trigger_mode       text    default 'in',
  p_kind               text[]  default null,
  p_kind_mode          text    default 'in',
  p_host               text[]  default null,
  p_host_mode          text    default 'in',
  p_origin_repo        text[]  default null,
  p_origin_repo_mode   text    default 'in',
  p_origin_branch      text[]  default null,
  p_origin_branch_mode text    default 'in',
  p_origin_pr          text[]  default null,
  p_origin_pr_mode     text    default 'in',
  -- Owner dimension (00064). `personal` plus one slug per member org with
  -- visible rows. All optional: null/absent = not filtered.
  p_owner              text[]  default null,
  p_owner_mode         text    default 'in',
  -- The CALLING KEY's restriction (00068), defaulted to unrestricted.
  p_key_scopes         text[]  default '{}',
  p_key_org_access     text    default 'all',
  p_key_org_ids        uuid[]  default '{}',
  -- 00108: the created_at window and the five retention thresholds, so a count
  -- describes the same rows the list shows. Appended, null-defaulted.
  p_created_since      timestamptz default null,
  p_created_until      timestamptz default null,
  p_min_age_days       integer default null,
  p_unseen_days        integer default null,
  p_max_seen_count     integer default null,
  p_max_read_count     integer default null,
  p_max_opened_count   integer default null
)
returns table (facet text, value text, count bigint)
language plpgsql
stable
security definer
set search_path = public
as $$
#variable_conflict use_column
declare
  v_actor uuid := case
    when auth.role() = 'service_role' then coalesce(p_user_id, auth.uid())
    else auth.uid()
  end;
  v_origin_pr integer[] := (
    select array_agg(x::integer)
      from unnest(coalesce(p_origin_pr, '{}'::text[])) as x
     where x ~ '^[0-9]+$'
  );
  v_created_cutoff timestamptz := case
    when p_min_age_days is null then null else now() - (p_min_age_days * interval '1 day')
  end;
  v_unseen_cutoff timestamptz := case
    when p_unseen_days is null then null else now() - (p_unseen_days * interval '1 day')
  end;
  -- 00110: only `label`/tag has an `all` (AND / set-containment) mode — see
  -- the module header. Every other dimension, and the tag facet in `in`/`nin`
  -- mode, keep self-exclusion (unchanged).
  v_tag_cooccur boolean := (p_tags_mode = 'all');
begin
  return query
  with base as (
    select
      m.tags, m.source_agent, m.trigger, m.kind, m.host,
      m.origin_repo, m.origin_branch, m.origin_pr,
      m.org_id, o.slug as org_slug,
      -- Per-dimension match flag, from the shared predicates so it cannot
      -- drift from lorekit_memory_activity's. A null filter is "not filtered" →
      -- the helper returns true, so an untouched dimension never narrows.
      lorekit_match_tags(m.tags,          p_tags,          p_tags_mode)          as ok_tag,
      lorekit_match_text(m.source_agent,  p_source_agent,  p_source_agent_mode)  as ok_source_agent,
      lorekit_match_text(m.trigger,       p_trigger,       p_trigger_mode)       as ok_trigger,
      lorekit_match_text(m.kind,          p_kind,          p_kind_mode)          as ok_kind,
      lorekit_match_text(m.host,          p_host,          p_host_mode)          as ok_host,
      lorekit_match_text(m.origin_repo,   p_origin_repo,   p_origin_repo_mode)   as ok_origin_repo,
      lorekit_match_text(m.origin_branch, p_origin_branch, p_origin_branch_mode) as ok_origin_branch,
      lorekit_match_int (m.origin_pr,     v_origin_pr,     p_origin_pr_mode)     as ok_origin_pr,
      -- Owner: the computed identity is `personal` (org_id null) or the org slug.
      -- Stays inline — it is not one of the three column helpers (00064).
      (p_owner is null or case coalesce(p_owner_mode, 'in')
         when 'nin' then (
           (case when m.org_id is null then 'personal' else o.slug end) is not null
           and (case when m.org_id is null then 'personal' else o.slug end) <> all(p_owner)
         )
         else (
           ('personal' = any(p_owner) and m.org_id is null)
           or (m.org_id is not null and o.slug = any(p_owner))
         )
       end) as ok_owner
      from memories m
      -- A personal row has no org, so this is a LEFT join; org rows resolve to
      -- their slug. Visible org rows are always the caller's own orgs (the
      -- visibility predicate below admits them only via lorekit_member_org_ids),
      -- so `o.slug` is never a slug the caller cannot see.
      left join orgs o on o.id = m.org_id
     where (
             (v_actor is null and auth.role() = 'service_role')
             or m.user_id = v_actor
             or m.org_id in (select lorekit_member_org_ids(v_actor))
           )
       -- The calling key's restriction, applied ONCE here in the row-visibility
       -- predicate every emitted facet value is derived from — `origin_repo` is
       -- a repository name by construction, so an unnarrowed facet list leaks
       -- exactly what the scope catalog hides.
       and lorekit_api_token_scope_allowed(p_key_scopes, m.scope)
       and lorekit_api_token_org_allowed(p_key_org_access, p_key_org_ids, m.org_id)
       and (
             case
               when p_archived then m.archived_at is not null
               else m.archived_at is null
                    and (m.expires_at is null or m.expires_at > now())
             end
           )
       and (p_scope is null or m.scope = p_scope)
       -- 00108. Here rather than as an `ok_*` flag: these narrow the population
       -- every facet value is drawn from, they are not a dimension that can be
       -- self-excluded. Half-open window, matching lorekit_memory_list.
       and (p_created_since is null or m.created_at >= p_created_since)
       and (p_created_until is null or m.created_at <  p_created_until)
       and lorekit_match_retention(
             m.created_at, m.last_opened_at, m.seen_count, m.read_count, m.opened_count,
             v_created_cutoff, v_unseen_cutoff, p_max_seen_count, p_max_read_count, p_max_opened_count
           )
  ), cells as (
    -- 00110: every branch now scans the FULL `base` population (not just rows
    -- that already satisfy the other flags) and carries a `matched` boolean
    -- instead of a row-level WHERE — the `group by` below therefore enumerates
    -- every value the dimension has, and the final `count` reflects only the
    -- ones actually matching. This is what keeps a non-matching value at
    -- `count = 0` instead of dropping it.
    select 'tag'::text as facet, t.tag as value,
           (b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner
            -- Co-occurrence: fold the tag dimension's OWN flag back in only in
            -- `all` mode, so another label's count becomes "carries the
            -- selection AND this label" rather than the plain self-excluded
            -- total. `not v_tag_cooccur` keeps `in`/`nin` mode's existing
            -- self-exclusion untouched.
            and (not v_tag_cooccur or b.ok_tag)) as matched
      from base b
      cross join lateral unnest(b.tags) as t(tag)
    union all
    select 'source_agent', b.source_agent,
           (b.ok_tag and b.ok_trigger and b.ok_kind and b.ok_host
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner)
      from base b
     where b.source_agent is not null
    union all
    select 'trigger', b.trigger,
           (b.ok_tag and b.ok_source_agent and b.ok_kind and b.ok_host
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner)
      from base b
     where b.trigger is not null
    union all
    select 'kind', b.kind,
           (b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_host
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner)
      from base b
     where b.kind is not null
    union all
    select 'host', b.host,
           (b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner)
      from base b
     where b.host is not null
    union all
    select 'origin_repo', b.origin_repo,
           (b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
            and b.ok_origin_branch and b.ok_origin_pr and b.ok_owner)
      from base b
     where b.origin_repo is not null
    union all
    select 'origin_branch', b.origin_branch,
           (b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
            and b.ok_origin_repo and b.ok_origin_pr and b.ok_owner)
      from base b
     where b.origin_branch is not null
    union all
    select 'origin_pr', b.origin_pr::text,
           (b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_owner)
      from base b
     where b.origin_pr is not null
    union all
    -- Owner is the ONE dimension self-excluded here (every other flag, NOT
    -- ok_owner), so a drilled-in owner still lists the alternative owner.
    select 'owner', case when b.org_id is null then 'personal' else b.org_slug end,
           (b.ok_tag and b.ok_source_agent and b.ok_trigger and b.ok_kind and b.ok_host
            and b.ok_origin_repo and b.ok_origin_branch and b.ok_origin_pr)
      from base b
  )
  select c.facet, c.value, count(*) filter (where c.matched) as count
    from cells c
   where c.value is not null
     and btrim(c.value) <> ''
   group by c.facet, c.value
   order by c.facet asc, count(*) filter (where c.matched) desc, c.value asc;
end;
$$;

-- Signature is IDENTICAL to 00108's — a true `create or replace`, no drop
-- needed, and the 00108 grants persist untouched. Comment refreshed to
-- describe the new within-group semantics.
comment on function lorekit_memory_facets(
  uuid, boolean, text, text[], text, text[], text, text[], text, text[], text,
  text[], text, text[], text, text[], text, text[], text, text[], text,
  text[], text, uuid[], timestamptz, timestamptz, integer, integer, integer,
  integer, integer
) is
  'Value catalog with counts for every filterable memory dimension (tag,
   source_agent, trigger, kind, host, origin_repo, origin_branch, origin_pr,
   owner) over the partition selected by p_archived, visible to the EFFECTIVE
   caller and narrowed by the calling key''s own scope/org restriction. Each
   dimension is counted with every OTHER dimension filter applied (cross-group
   AND). WITHIN a dimension: self-exclusion (drill-down, 00057) for every
   scalar dimension and for label/tag in `in`/`nin` (OR) mode; CO-OCCURRENCE
   (intersection with the tag selection) for label/tag in `all` (AND) mode
   (00110). Every dimension enumerates its FULL value set so a value with zero
   matches under the active filters still returns `count = 0` instead of being
   omitted (00110). The created_at window and the five retention thresholds
   (00108) are NOT self-excluded: they narrow the population every facet value
   is drawn from, so a count matches the list under the same parameters.
   q/key/expiring_within_days remain unmirrored, so with those active a count
   is an upper bound.';
;
insert into supabase_migrations.schema_migrations (version, name)
values ('00110', 'facets_within_group_cooccurrence')
on conflict (version) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 00111_wildcard_scope_org_bindings.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════
-- Wildcard scope → org bindings: bind a WHOLE prefix (`repo::owner/*`,
-- `branch::owner/repo::*`) to an org instead of one concrete scope at a time,
-- and resolve writes under a MOST-SPECIFIC-WINS rule when several bindings
-- could match.
--
-- ── What changes, and why ───────────────────────────────────────────────
--
-- 1. `lorekit_scope_bind` gains a SQL-side grammar gate: the pattern must
--    satisfy `lorekit_api_token_scopes_valid` (00068) — the SAME charset and
--    wildcard-position rule already enforced for API-token scope allowlists,
--    reused rather than forked so the two authorities can never drift. The
--    gate sits AFTER the `manage_scopes` authorization check, so an
--    authorized owner submitting a malformed pattern is refused by the
--    grammar, not the auth layer — and a non-admin is still refused by auth
--    first, unchanged. `lorekit_scope_unbind` needs no grammar gate: deleting
--    a row by its exact stored string can't insert a bad one.
--
-- 2. `memory_write`'s no-explicit-org branch changes from a single-row
--    equijoin (`where b.scope = p_scope`) to a wildcard-aware match:
--
--      where o.deleted_at is null
--        and (b.scope = p_scope
--             or (right(b.scope, 1) = '*'
--                 and p_scope like replace(left(b.scope, -1), '_', '\_') || '%'))
--      order by (right(b.scope, 1) = '*') asc, length(b.scope) desc, b.scope asc
--      limit 1
--
--    Precedence, in the ORDER BY: an EXACT string always beats ANY wildcard
--    (`false < true` on the first key); among wildcards, the LONGER literal
--    prefix wins (more specific); ties break on the scope string itself,
--    ascending, purely for determinism — two distinct wildcard prefixes of
--    EQUAL length cannot both match one `p_scope` (prefix containment forces
--    different lengths), and two identical exact strings can't coexist (the
--    unique index on `scope`), so the third key is a documented safeguard,
--    never a reachable branch. The LIKE escaping mirrors
--    `lorekit_api_token_scope_allowed` (00068) byte-for-byte — the pattern's
--    own CHECK already excludes `%` and `\`, so the escape only neutralises a
--    literal `_`.
--
--    Every other branch of `memory_write` (explicit `p_org_slug`, the
--    service-role write, the personal fallback, the returned columns) is
--    copied VERBATIM from 00075 — the current definition (confirmed by
--    grepping every `memory_write` definer) — so this migration's diff is
--    exactly the matcher above.
--
-- 3. Overlapping bindings are ALLOWED — an exact scope and a wildcard, or two
--    wildcards of different depth, may coexist, even bound to different
--    orgs. Only an IDENTICAL pattern STRING bound to a second org still
--    raises `scope_bound_elsewhere` (the existing unique index on `scope` is
--    unchanged — it was never a uniqueness-of-match constraint, only a
--    uniqueness-of-literal-row one).
--
-- No REST route, OpenAPI path, `rest-tool-name` mapping, or new audit action
-- is added — bindings stay the dashboard-RPC-only exempt surface, and
-- wildcards reuse the existing `scope.bind` / `scope.unbind` audit actions.
-- ═════════════════════════════════════════════════════════════════════════

-- 0. `org_scope_bindings.scope` gets the SAME shape gate at the table level,
--    not only inside `lorekit_scope_bind`. Without this, a row inserted
--    before this migration under the old (non-empty-only) validation — or by
--    any future direct INSERT that bypasses the RPC — could hold a scope
--    string ending in `*` with no charset guarantee, and the LIKE-escaping in
--    `memory_write`'s matcher below is only injection-safe because it relies
--    on this exact shape (no `%`/`\` in a valid pattern). A CHECK makes any
--    such row fail this migration LOUDLY at deploy time instead of silently
--    starting to behave as a live wildcard the moment 00111 ships.
alter table org_scope_bindings
  drop constraint if exists org_scope_bindings_scope_shape;
alter table org_scope_bindings
  add constraint org_scope_bindings_scope_shape
  check (lorekit_api_token_scopes_valid(array[scope]));

-- 1. `lorekit_scope_bind` — add the grammar gate after the auth gate.
create or replace function lorekit_scope_bind(p_org_id uuid, p_scope text)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_actor uuid := auth.uid();
  v_existing_org uuid;
  v_id uuid;
begin
  if p_scope is null or length(trim(p_scope)) = 0 then
    raise exception using errcode = 'P0001', message = 'scope is required';
  end if;

  if not lorekit_org_can(v_actor, p_org_id, 'manage_scopes') then
    raise exception using errcode = 'LK002',
      message = format('org_permission_denied: org=%s capability=manage_scopes', p_org_id);
  end if;

  -- Grammar gate, deliberately AFTER the authorization gate above so the two
  -- layers are independently provable: an unauthorized actor is refused by
  -- auth regardless of pattern shape, and an authorized actor with a bad
  -- pattern is refused here. Reuses 00068's shape validator verbatim — this
  -- is a SHAPE check (charset + wildcard position), not full canonical-scope
  -- validation; the dashboard's `validateScopeBindingPattern` does the
  -- stronger check for a non-wildcard string before this RPC is ever called.
  if not lorekit_api_token_scopes_valid(array[p_scope]) then
    raise exception using errcode = 'P0001',
      message = format('invalid_scope_pattern: %s', p_scope);
  end if;

  select org_id, id into v_existing_org, v_id from org_scope_bindings where scope = p_scope;
  if v_existing_org = p_org_id then
    -- Already bound to this org — idempotent no-op; return the existing id.
    return v_id;
  elsif v_existing_org is not null then
    raise exception using errcode = 'P0001',
      message = format('scope_bound_elsewhere: %s', p_scope);
  end if;

  insert into org_scope_bindings (org_id, scope, created_by)
  values (p_org_id, p_scope, v_actor)
  returning id into v_id;
  return v_id;
end;
$$;

comment on function lorekit_scope_bind(uuid, text) is
  'Bind a scope pattern (exact or owner wildcard, e.g. repo::owner/*) to an '
  'org. Admin/owner only (manage_scopes); pattern must pass '
  'lorekit_api_token_scopes_valid or raises invalid_scope_pattern.';

-- 2. `memory_write` — wildcard-aware most-specific-wins binding resolution.
-- Signature and RETURNS TABLE shape are UNCHANGED from 00075, so no `drop`.
create or replace function memory_write(
  p_user_id       uuid,
  p_scope         text,
  p_key           text,
  p_value         text,
  p_tags          text[]      default '{}',
  p_source_agent  text        default null,
  p_trigger       text        default null,
  p_created_at    timestamptz default null,
  p_org_slug      text        default null,
  p_ttl_seconds   integer     default null,
  p_clear_ttl     boolean     default false,
  p_origin_repo   text        default null,
  p_origin_branch text        default null,
  p_origin_commit text        default null,
  p_origin_pr     integer     default null,
  p_kind          text        default null,
  p_host          text        default null,
  p_key_scopes     text[]     default '{}',
  p_key_org_access text       default 'all',
  p_key_org_ids    uuid[]     default '{}'
)
returns table (
  id               uuid,
  created_at       timestamptz,
  inserted         boolean,
  org_routed       boolean,
  binding_org_slug text,
  expires_at       timestamptz,
  scope            text,
  key              text,
  value            text,
  tags             text[],
  source_agent     text,
  trigger          text,
  updated_at       timestamptz,
  archived_at      timestamptz,
  origin_repo      text,
  origin_branch    text,
  origin_commit    text,
  origin_pr        integer,
  kind             text,
  host             text,
  seen_count       integer
)
language plpgsql
security definer
set search_path = public
as $$
-- See 00075's comment for why this directive is required (the OUT columns
-- `scope`/`key` collide with the bare column names in the `on conflict`
-- arbiter lists below).
#variable_conflict use_column
declare
  v_org_id       uuid;
  v_binding_org  uuid;
  v_binding_slug text;
  v_expires_at   timestamptz;
  v_ttl_action   text := 'keep';
begin
  if not lorekit_api_token_scope_allowed(p_key_scopes, p_scope) then
    raise exception using errcode = 'LK002',
      message = format('key_scope_denied: scope=%s', p_scope);
  end if;

  if p_clear_ttl then
    v_ttl_action := 'clear';
  elsif p_ttl_seconds is not null then
    if p_ttl_seconds < 1 or p_ttl_seconds > 31536000 then
      raise exception using errcode = 'P0001',
        message = format('ttl_seconds must be between 1 and 31536000, got %s', p_ttl_seconds);
    end if;
    v_expires_at  := now() + (p_ttl_seconds * interval '1 second');
    v_ttl_action  := 'set';
  end if;

  if p_org_slug is not null then
    select o.id into v_org_id from orgs o where o.slug = p_org_slug and o.deleted_at is null;
    if v_org_id is null then
      raise exception using errcode = 'P0001', message = format('unknown_org: %s', p_org_slug);
    end if;
    if not lorekit_org_can(p_user_id, v_org_id, 'write') then
      raise exception using errcode = 'LK002', message = format('org_permission_denied: org=%s', p_org_slug);
    end if;
    if not lorekit_api_token_org_allowed(p_key_org_access, p_key_org_ids, v_org_id) then
      raise exception using errcode = 'LK002',
        message = format('key_org_denied: org=%s', p_org_slug);
    end if;
  else
    -- Wildcard-aware, most-specific-wins resolution. A binding matches
    -- p_scope either by exact string equality, or — when it ends in '*' — as
    -- an owner-wildcard prefix (the same LIKE-escaping `lorekit_api_token_
    -- scope_allowed` (00068) uses, since `%` and `\` cannot occur in a
    -- pattern that already passed the grammar gate above). Among matches:
    -- exact (is-wildcard = false) always sorts before any wildcard; among
    -- wildcards, the LONGER literal prefix (length desc) sorts first as the
    -- more specific match; the trailing `scope asc` is a determinism
    -- safeguard for a tie that provably cannot occur (see the header
    -- comment), not a reachable precedence branch.
    select b.org_id, o.slug into v_binding_org, v_binding_slug
    from org_scope_bindings b
    join orgs o on o.id = b.org_id
    where o.deleted_at is null
      and (
        b.scope = p_scope
        or (
          right(b.scope, 1) = '*'
          and p_scope like replace(left(b.scope, -1), '_', '\_') || '%'
        )
      )
    order by (right(b.scope, 1) = '*') asc, length(b.scope) desc, b.scope asc
    limit 1;

    if v_binding_org is not null
       and p_user_id is not null
       and lorekit_org_can(p_user_id, v_binding_org, 'write')
       and lorekit_api_token_org_allowed(p_key_org_access, p_key_org_ids, v_binding_org) then
      v_org_id := v_binding_org;
    end if;
  end if;

  if v_org_id is not null then
    return query
    insert into memories (
      user_id, org_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host, seen_count
    )
    values (
      null, v_org_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host, 1
    )
    on conflict (org_id, scope, key) where org_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      seen_count    = memories.seen_count + 1,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      true as org_routed, v_binding_slug as binding_org_slug, memories.expires_at,
      memories.scope, memories.key, memories.value, memories.tags,
      memories.source_agent, memories.trigger, memories.updated_at, memories.archived_at,
      memories.origin_repo, memories.origin_branch, memories.origin_commit, memories.origin_pr,
      memories.kind, memories.host, memories.seen_count;

  elsif p_user_id is null then
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host, seen_count
    )
    values (
      null, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      null, null, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host, 1
    )
    on conflict (scope, key) where org_id is null and user_id is null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      seen_count    = memories.seen_count + 1,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at,
      memories.scope, memories.key, memories.value, memories.tags,
      memories.source_agent, memories.trigger, memories.updated_at, memories.archived_at,
      memories.origin_repo, memories.origin_branch, memories.origin_commit, memories.origin_pr,
      memories.kind, memories.host, memories.seen_count;

  else
    return query
    insert into memories (
      user_id, scope, key, value, tags, source_agent, trigger,
      created_at, updated_at, created_by, updated_by, expires_at,
      origin_repo, origin_branch, origin_commit, origin_pr, kind, host, seen_count
    )
    values (
      p_user_id, p_scope, p_key, p_value, p_tags, p_source_agent, p_trigger,
      coalesce(p_created_at, now()), coalesce(p_created_at, now()),
      p_user_id, p_user_id, v_expires_at,
      p_origin_repo, p_origin_branch, p_origin_commit, p_origin_pr, p_kind, p_host, 1
    )
    on conflict (user_id, scope, key) where org_id is null and user_id is not null and archived_at is null
    do update set
      value         = excluded.value,
      tags          = excluded.tags,
      source_agent  = excluded.source_agent,
      trigger       = excluded.trigger,
      updated_at    = now(),
      updated_by    = p_user_id,
      seen_count    = memories.seen_count + 1,
      origin_repo   = coalesce(excluded.origin_repo,   memories.origin_repo),
      origin_branch = coalesce(excluded.origin_branch, memories.origin_branch),
      origin_commit = coalesce(excluded.origin_commit, memories.origin_commit),
      origin_pr     = coalesce(excluded.origin_pr,     memories.origin_pr),
      kind          = coalesce(excluded.kind,          memories.kind),
      host          = coalesce(excluded.host,          memories.host),
      expires_at    = case v_ttl_action
                        when 'clear' then null
                        when 'set'   then v_expires_at
                        else memories.expires_at
                      end
    returning
      memories.id, memories.created_at, (xmax::text = '0') as inserted,
      false as org_routed, v_binding_slug as binding_org_slug, memories.expires_at,
      memories.scope, memories.key, memories.value, memories.tags,
      memories.source_agent, memories.trigger, memories.updated_at, memories.archived_at,
      memories.origin_repo, memories.origin_branch, memories.origin_commit, memories.origin_pr,
      memories.kind, memories.host, memories.seen_count;
  end if;
end;
$$;

grant execute on function memory_write(
  uuid, text, text, text, text[], text, text, timestamptz, text,
